import { Injectable } from '@angular/core';
import { ToastController } from '@ionic/angular';
import { IMagToastOptions } from './interface';

@Injectable({
  providedIn: 'root', // optional if provided in module
})
export class ToastService {
  private activeToast: any;
  private isCreating = false;

  constructor(private toastController: ToastController) {}

  async create(options: IMagToastOptions): Promise<void> {
    // Validate options
    if (!options) {
      console.error('Toast options are required');
      return;
    }

    if (!options.message || options.message.trim() === '') {
      console.error('Toast message is required');
      return;
    }

    if (!options.type || !['success', 'error'].includes(options.type)) {
      console.error('Invalid toast type. Must be "success" or "error"');
      return;
    }

    // Prevent multiple simultaneous toast creations
    if (this.isCreating) {
      console.warn('Toast creation already in progress');
      return;
    }

    this.isCreating = true;

    try {
      // Dismiss existing toast if any
      if (this.activeToast) {
        try {
          await this.activeToast.dismiss();
        } catch (e) {
          console.warn('Failed to dismiss existing toast', e);
        }
        this.activeToast = null;
      }

      // Create new toast
      this.activeToast = await this.toastController.create({
        message: options.message.trim(),
        duration: options?.duration || 2500,
        icon: this.getDefaultIcon(options.type),
        color: options.type,
        cssClass: `toast-${options.type}`,
      });

      // Reset activeToast after it disappears
      this.activeToast.onDidDismiss().then(() => {
        this.activeToast = null;
      });

      await this.activeToast.present();
    } catch (error) {
      console.error('Failed to create toast:', error);
      this.activeToast = null;
    } finally {
      this.isCreating = false;
    }
  }

  private getDefaultIcon(type: string): string {
    switch (type) {
      case 'success':
        return 'checkmark-circle';
      case 'error':
        return 'close-circle';
      default:
        return 'checkmark-circle';
    }
  }
}
