import { Injectable } from '@angular/core';
import { CanActivate, ActivatedRouteSnapshot, RouterStateSnapshot } from '@angular/router';
import { NavController } from '@ionic/angular/common';

@Injectable({ providedIn: 'root' })
export class RecipeRedirectGuard implements CanActivate {
  constructor(private navCtrl: NavController) {}

  canActivate(route: ActivatedRouteSnapshot, state: RouterStateSnapshot): boolean {
    const currentUrl = state.url;
    if (currentUrl.startsWith('/recipe')) {
      const newUrl = currentUrl.replace(/^\/recipe/, '/tabs/recipe');
      this.navCtrl.navigateForward(newUrl);
      return false;
    }
    return true;
  }
}
