import { FirebaseService } from './core/firebase/firebase.service';
import { Firestore } from 'firebase/firestore';
import { iosSmooth } from './animations/route-animation';
export function getToken(appLoadService: AppLoadService) {
  return () => appLoadService.getToken();
}
const AppComponentTarget = AppComponent;

export function createTranslateLoader(http: HttpClient) {
  return new TranslateHttpLoader(http, './assets/locales/', '.json');
}

// Factory function for APP_INITIALIZER
export function initializeAppEnvironment(
  environmentService: EnvironmentService,
  firebaseService: FirebaseService,
  faroService: FaroService
) {
  return async () => {
    try {
      await firstValueFrom(environmentService.loadEnvironment());
      firebaseService.initializeFirebase();
      // Initialize Grafana Faro after env is loaded
      faroService.init();
    } catch (error) {
      console.warn('Error in initializeAppEnvironment:', error);
      throw error;
    }
  };
}

@NgModule({
  declarations: [AppComponentTarget, AppLoadingComponent],
  imports: [
    IonicModule.forRoot({
      mode: 'ios',
      scrollAssist: true,
      scrollPadding: false,
      innerHTMLTemplatesEnabled: true,
      navAnimation: iosSmooth,
    }),
    IonicStorageModule.forRoot({
      name: '__rsdb',
      driverOrder: [Drivers.IndexedDB, Drivers.LocalStorage],
    }),
    CommonModule,
    HttpClientModule,
    CacheModule.forRoot({ keyPrefix: 'rs-' }),
    AppRoutingModule,
    NgxPubSubModule,
    CoreModule,
    BrowserModule,
    BrowserAnimationsModule,
    SharedComponentModule,
    MembershipModule,
    NgxGpAutocompleteModule,
    ShoppingListServiceModule,
    ProductServiceModule,
    // AngularFireAnalyticsModule,
    NgxMatomoTrackerModule.forRoot({ mode: MatomoInitializationMode.AUTO_DEFERRED }),
    TranslateModule.forRoot({
      loader: {
        provide: TranslateLoader,
        useFactory: createTranslateLoader,
        deps: [HttpClient],
      },
    }),
  ],
  providers: [
    AppLoadService,
    EnvironmentService,
    InAppBrowser,
    {
      provide: APP_INITIALIZER,
      useFactory: initializeAppEnvironment,
      deps: [EnvironmentService, FirebaseService, FaroService],
      multi: true,
    },
    { provide: APP_INITIALIZER, useFactory: getToken, deps: [AppLoadService], multi: true },
    {
      provide: FirebaseApp,
      useFactory: (firebaseService: FirebaseService) => firebaseService.getApp(),
      deps: [FirebaseService],
    },
    {
      provide: Firestore,
      useFactory: (firebaseService: FirebaseService) => firebaseService.getFirestore(),
      deps: [FirebaseService],
    },
    {
      provide: Analytics,
      useFactory: (firebaseService: FirebaseService) => firebaseService.getAnalytics(),
      deps: [FirebaseService],
    },
    UserTrackingService,
    NotificationService,
    // {
    //   provide: Loader,
    //   useValue: new Loader({
    //     apiKey: ENV.GOOGLE_MAPS_BROWSER_API_KEY,
    //     version: 'weekly',
    //     libraries: ['places'],
    //   }),
    // },
    { provide: RouteReuseStrategy, useClass: IonicRouteStrategy },
    { provide: HTTP_INTERCEPTORS, useClass: CacheInterceptor, multi: true },
    { provide: HTTP_INTERCEPTORS, useClass: AuthInterceptor, multi: true },
    {
      provide: CONFIG,
      useValue: {
        send_page_view: false,
        allow_ad_personalization_signals: false,
        anonymize_ip: true,
      },
    },
  ],
  schemas: [CUSTOM_ELEMENTS_SCHEMA],
  bootstrap: [AppComponentTarget],
})
export class AppModule {}
