import { Component, Input, OnInit, Output, EventEmitter, Optional } from '@angular/core';
import { ModalController } from '@ionic/angular';
import { IWidgetLayout, IZoneInfo } from '@rsApp/modules/interfaces/widget-layout.interface';
import { firstValueFrom } from 'rxjs';
import { DxpComponentService } from '../../providers/dxp.component.service';
import { WidgetLayoutService } from '../../providers/widget-layout.service';
import { WidgetLayoutCenterModalComponent } from '../widget-layout-center-modal/widget-layout-center-modal.component';
import { DXPTracker } from '../../providers/dxp-tracker.service';
import { PerformanceLoggerService } from '@rsApp/modules/utils/providers/performance-logger.service';
import { RouteTrackerService } from '../../providers/route-tracker.service';

export enum ZoneLayoutType {
  FIXED_TOP = 'Fixed Top',
  FIXED_CENTER = 'Fixed Center',
  STICKY = 'Sticky',
  TOP = 'Top',
  BOTTOM = 'Bottom',
}

@Component({
  selector: 'widget-layout',
  templateUrl: 'widget-layout.component.html',
  styleUrls: ['widget-layout.component.scss'],
})
export class WidgetLayoutComponent implements OnInit {
  @Input() public type?: string;
  @Input() public objectId?: string;
  @Input() public slug?: string;
  @Input() public zoneName?: string;
  @Output() public widgetReady = new EventEmitter<void>();

  public ZoneLayoutType = ZoneLayoutType;
  public dataWidget: { key: number; value: string }[] = [];

  constructor(
    public widgetLayoutService: WidgetLayoutService,
    public dxpComponentService: DxpComponentService,
    private dxpTracker: DXPTracker,
    private modalCtrl: ModalController,
    private routeTracker: RouteTrackerService,
    @Optional() private perfLogger?: PerformanceLoggerService
  ) {}
  async ngOnInit() {
    const widgetStartTime = performance.now();
    const widgetMarker = `WIDGET_${this.zoneName}_START`;
    this.perfLogger?.mark(widgetMarker);
    this.perfLogger?.log(`📦 WidgetLayout init - Zone: ${this.zoneName}, Type: ${this.type}`);

    if (!this.type) {
      this.widgetReady.emit();
      return;
    }

    try {
      const slug = this.getSlug();
      this.perfLogger?.log(`🔍 Fetching layout for slug: ${slug}`);

      const layoutConfig: IWidgetLayout = await firstValueFrom(
        this.widgetLayoutService.getLayout(slug, this.objectId, this.type)
      );
      
      if (layoutConfig && this.zoneName == ZoneLayoutType.TOP) {
        this.trackingPageViewOnPage(layoutConfig);
      }
      this.perfLogger?.measure(`Layout fetched for ${this.zoneName}`, widgetMarker);

      // Wait for DXP component to be connected
      this.perfLogger?.log(`⏳ Waiting for DXP component connection...`);
      await this.dxpComponentService.onConnected();
      this.perfLogger?.log(`✅ DXP component connected`);

      const zone: IZoneInfo | undefined = layoutConfig?.ZoneInfoValue?.find((s) => s.Name === this.zoneName);

      // If zone not found, emit ready and return
      if (!zone) {
        this.perfLogger?.log(`⚠️ Zone not found: ${this.zoneName}`);
        this.widgetReady.emit();
        return;
      }

      // Init DXP widget (it will emit ready event when done)
      await this.initDXPWidget(zone);
      const widgetLoadTime = performance.now() - widgetStartTime;
      this.perfLogger?.log(`✅ Widget ${this.zoneName} fully loaded - ${widgetLoadTime.toFixed(2)}ms`);
    } catch (error) {
      console.error('Error fetching widget layout:', error);
      this.perfLogger?.log(`❌ Error loading widget ${this.zoneName}`, error);
      // Emit ready even on error to prevent skeleton from staying forever
      this.widgetReady.emit();
    }
  }

  async refresh() {
    this.perfLogger?.log(`🔄 Refreshing widget: ${this.zoneName}`);
    this.dataWidget = []; // Clear existing widgets

    if (!this.type) {
      this.widgetReady.emit();
      return;
    }

    try {
      const slug = this.getSlug();
      // Force refresh by passing a refresher object
      const refresher = { timestamp: Date.now() };

      const layoutConfig: IWidgetLayout = await firstValueFrom(
        this.widgetLayoutService.getLayout(slug, this.objectId, this.type, refresher)
      );

      await this.dxpComponentService.onConnected();

      const zone: IZoneInfo | undefined = layoutConfig?.ZoneInfoValue?.find((s) => s.Name === this.zoneName);

      if (!zone) {
        this.widgetReady.emit();
        return;
      }

      await this.initDXPWidget(zone);
      this.perfLogger?.log(`✅ Widget ${this.zoneName} refreshed`);
    } catch (error) {
      console.error('Error refreshing widget layout:', error);
      this.perfLogger?.log(`❌ Error refreshing widget ${this.zoneName}`, error);
      this.widgetReady.emit();
    }
  }

  async initDXPWidget(zone: IZoneInfo) {
    if (!zone.Widgets || zone.Widgets.length === 0) {
      this.widgetReady.emit();
      return;
    }

    if (
      (zone.Name === ZoneLayoutType.FIXED_TOP && sessionStorage.getItem('hideFixedTopZone')) ||
      (zone.Name === ZoneLayoutType.FIXED_CENTER && sessionStorage.getItem('hideFixedCenterZone'))
    ) {
      this.widgetReady.emit();
      return;
    }

    const data = zone.Widgets.map((widget) => {
      if (!widget || !widget.Id) {
        return null;
      }

      return {
        key: widget.Id,
        value: escape(JSON.stringify(widget)),
      };
    });

    this.dataWidget = [...data];

    if (this.dataWidget && zone.Name == ZoneLayoutType.FIXED_CENTER) {
      const modal = await this.modalCtrl.create({
        cssClass: 'center-modal',
        component: WidgetLayoutCenterModalComponent,
        componentProps: {
          dataWidget: this.dataWidget,
        },
      });

      modal.onDidDismiss().then(() => {
        sessionStorage.setItem('hideFixedCenterZone', 'true');
      });

      await modal.present();
      this.widgetReady.emit();
      return;
    }

    // For other zones, emit ready after dataWidget is set
    this.widgetReady.emit();
  }

  getSlug() {
    return this.slug?.startsWith('/') ? this.slug.substring(1) : this.slug;
  }

  closeFixedTopZone() {
    document.getElementsByClassName('widget-fixed-top')[0].remove();
    sessionStorage.setItem('hideFixedTopZone', 'true');
  }

  async trackingPageViewOnPage(layoutConfig: IWidgetLayout) {
    const widgetsWithValidFlag = await Promise.all(
      layoutConfig.ZoneInfoValue.flatMap((zone) =>
        (zone.Widgets || []).map(async (widget) => {
          const widgetData = await this.widgetLayoutService.setWidget(widget, zone.Name);

          return widgetData?.IsValid ? { ...widget } : null;
        })
      )
    );

    const data = widgetsWithValidFlag.filter(Boolean);
    this.dxpTracker.handlePushDxpTracking('trackPageViewAllWidget', { data, previousPage: this.routeTracker.getPreviousPage() });
  }
}
