import { inject } from '@angular/core';
import { ResolveFn, Router } from '@angular/router';

export interface IExtrasStateData {
  extrasStateResolver: Record<string, any>;
}

export const extrasStateResolver: ResolveFn<IExtrasStateData['extrasStateResolver']> = () => {
  return inject(Router).getCurrentNavigation()?.extras.state ?? {};
};
