export const envParser = (base64String: string, name: string) => {
  try {
    if (!base64String) {
      console.warn(`No base64 string found: ${name}`);
      return null;
    }
    const base64 = atob(base64String.replace(/-/g, '+').replace(/_/g, '/'));
    return JSON.parse(base64);
  } catch (error) {
    console.error(error);
  }
};
