import { Component, OnInit, OnDestroy } from '@angular/core';
import { Subscription } from 'rxjs';
import { CurrentStore } from '../../../../modules/store/providers/current-store.service';
import { IStore } from '@rsApp/modules/interfaces/store.interface';
import { Router } from '@angular/router';

@Component({
  selector: 'mag-store-accordion',
  templateUrl: './mag-store-accordion.html',
  styleUrls: ['./mag-store-accordion.scss'],
})
export class MagStoreAccordionComponent implements OnInit, OnDestroy {
  public store: IStore;
  private store$: Subscription;

  constructor(
    private currentStore: CurrentStore,
    private router: Router
  ) {}

  ngOnInit() {
    this.store$ = this.currentStore.storeState().subscribe((store) => {
      this.store = store;
    });
  }

  ngOnDestroy() {
    if (this.store$) {
      this.store$.unsubscribe();
    }
  }

  formatPhone(phone: string | null | undefined): string {
    if (!phone) return '';
    const digits = phone.replace(/\D/g, '').slice(0, 10);
    if (digits.length < 10) return phone;

    return `(${digits.slice(0, 3)}) ${digits.slice(3, 6)}-${digits.slice(6, 10)}`;
  }

  handleNavigate() {
    this.router.navigate(['/tabs/store/result-find'], {
      queryParams: { backRoute: 'tabs/my-account' },
    });
  }
}
