import { Injectable } from '@angular/core';
import { IWidgetLayout, IZoneInfo } from '@rsApp/modules/interfaces/widget-layout.interface';

@Injectable({
  providedIn: 'root',
})
export class WidgetPrerenderService {
  private layoutConfig: IWidgetLayout;
  private zoneIds = [];

  setLayoutConfig(config: IWidgetLayout) {
    this.layoutConfig = config;
    console.log('Set the layout config');
  }

  async preloadStencilComponent(): Promise<void> {
    console.log('Preload stencil component');
    if (!this.layoutConfig || !this.layoutConfig.ZoneInfoValue) {
      console.warn('No layout config or ZoneInfoValue available');
      return;
    }
    this.zoneIds.push(`zone-prerender-loading`);
    const container = document.createElement('div');
    container.id = `zone-prerender-loading`;
    container.style.position = 'fixed';
    container.style.top = '0';
    container.style.left = '0';
    container.style.width = '100%';
    container.style.height = '100%';
    container.style.display = 'flex';
    container.style.justifyContent = 'center';
    container.style.alignItems = 'center';
    container.style.zIndex = '9999';
    const spinner = document.createElement('ion-spinner');
    spinner.setAttribute('name', 'crescent');
    container.appendChild(spinner);
    document.body.prepend(container);

    const processWidgets = async (zone: IZoneInfo) => {
      if (!zone || !zone.Widgets || zone.Widgets.length === 0) return;
      const container = document.createElement('div');
      const zoneId = `zone-${zone.Name}-prerender-container`;
      this.zoneIds.push(zoneId);
      container.id = zoneId;
      container.style.position = 'fixed';
      container.style.visibility = 'hidden';
      container.style.top = '0';
      container.style.left = '0';
      document.body.appendChild(container);

      for (const widget of zone?.Widgets || []) {
        const stencilComponent = document.createElement('dxp-widget');
        stencilComponent.setAttribute('widgetid', widget.Id.toString());
        stencilComponent.setAttribute('viewmode', 'Mobile');
        container.appendChild(stencilComponent);
      }
    };

    for (const zone of this.layoutConfig.ZoneInfoValue) {
      processWidgets(zone);
    }
  }

  async clearPrerenderStencilComponent(): Promise<void> {
    console.log('Clear prerender stencil component');
    for (const zoneId of this.zoneIds) {
      const container = document.getElementById(zoneId);
      if (container) {
        container.remove();
      }
    }
    this.zoneIds = [];
  }
}
