import { Injectable } from '@angular/core';
import { ENV } from '@app/env';
import {
  type Faro,
  initializeFaro,
  getWebInstrumentations,
  LogLevel,
  ConsoleInstrumentation,
  WebVitalsInstrumentation,
  ErrorsInstrumentation,
  PerformanceInstrumentation,
} from '@grafana/faro-web-sdk';
import { TracingInstrumentation } from '@grafana/faro-web-tracing';
import { FetchInstrumentation } from '@opentelemetry/instrumentation-fetch';
import { XMLHttpRequestInstrumentation } from '@opentelemetry/instrumentation-xml-http-request';

@Injectable({ providedIn: 'root' })
export class FaroService {
  private faroInstance: Faro | undefined;

  public init(): void {
    if (this.faroInstance || !ENV.FaroEnabled) return;

    if (!ENV.FaroUrl || !ENV.FaroApiKey) {
      console.warn('Faro config missing FARO_URL or FARO_RUM_KEY');
      return;
    }

    const instrumentationOptions = {
      propagateTraceHeaderCorsUrls: [new RegExp('https://uat-api-dxpro.mercatus.com/*')], // This is a list of specific URIs or regular exprressions
      ignoreUrls: [ENV.FaroUrl, /\.(?:png|jpe?g|gif|svg|webp|ico)(?:\?.*)?$/i, /\/assets\//i, /google-analytics\.com/i],
    };
    this.faroInstance = initializeFaro({
      url: ENV.FaroUrl,
      apiKey: ENV.FaroApiKey,
      app: {
        name: ENV.FaroAppName || 'nextmobile',
        namespace: ENV.FaroAppNamespace || 'nextmobile',
        version: '1.0.0',
        environment: ENV.production ? 'production' : 'development',
      },
      isolate: true,
      batching: {
        itemLimit: 50,
        sendTimeout: 1000,
      },
      sessionTracking: {
        samplingRate: ENV.FaroSessionTrackingSamplingRate,
      },
      instrumentations: [
        ...getWebInstrumentations({
          captureConsole: true,
          captureConsoleDisabledLevels: [LogLevel.DEBUG, LogLevel.INFO, LogLevel.LOG],
          enablePerformanceInstrumentation: true,
        }),
        new ErrorsInstrumentation(), // Error tracking
        new WebVitalsInstrumentation(), // Core Web Vitals
        new PerformanceInstrumentation(), // Page load timing (DOMContentLoaded, load event)
        new ConsoleInstrumentation(), // Console logging

        // API calls (XHR/fetch + timing)
        new TracingInstrumentation({
          instrumentations: [
            new FetchInstrumentation(instrumentationOptions),
            new XMLHttpRequestInstrumentation(instrumentationOptions),
          ],
        }),
      ],
    });

    // Optional test error
    setTimeout(() => {
      this.faroInstance?.api?.pushError(new Error('Test error'));
    }, 3000);
  }
}
