import { HttpClient, HttpContext, HttpHandler, HttpHeaders, HttpParams, HttpRequest } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { Observable, firstValueFrom, from } from 'rxjs';
import { switchMap } from 'rxjs/operators';
import { ENV } from '@app/env';
import { Credential } from '@rsApp/modules/auth-v2/providers/credential.service';
import { EnvironmentService } from '../../../environments/environment.service';
export type HttpObserve = 'body' | 'events' | 'response';
/** reference 
  https://medium.com/@admin_87321/extending-angular-httpclient-episode-2-144b58494db4
  https://github.com/bbogdanov/ExtendAngularHttpClient/blob/master/extendHttpClient/src/app/http-client.ts 
  https://github.com/angular/angular/issues/20203
**/

@Injectable({
  providedIn: 'root',
})
export class RelationshopCoreHttpClient extends HttpClient {
  protected api = ENV.DXPCoreAPI;
  protected identityAPIUrl = ENV.IdentityAPIUrl;

  constructor(
    handler: HttpHandler,
    private cre: Credential,
    private http: HttpClient,
    private environmentService: EnvironmentService
  ) {
    super(handler);
  }

  private async loadDynamicEnvironment() {
    try {
      await firstValueFrom(this.environmentService.getDynamicEnvironment());
    } catch (error) {
      console.warn('Failed to load dynamic environment in RelationshopCore service:', error);
    }
  }

  request(
    first: string | HttpRequest<any>,
    url?: string,
    options: {
      body?: any;
      headers?: HttpHeaders | { [header: string]: string | string[] };
      context?: HttpContext;
      observe?: HttpObserve;
      params?:
        | HttpParams
        | {
            [param: string]: string | number | boolean | ReadonlyArray<string | number | boolean>;
          };
      reportProgress?: boolean;
      responseType?: 'arraybuffer' | 'blob' | 'json' | 'text';
      withCredentials?: boolean;
    } = {}
  ): Observable<any> {
    // Ensure dynamic environment is loaded before making request
    if (!(window as any).TenantId) {
      return from(this.loadDynamicEnvironment()).pipe(switchMap(() => this.makeRequest(first, url, options)));
    }

    return this.makeRequest(first, url, options);
  }

  private makeRequest(first: string | HttpRequest<any>, url?: string, options: any = {}): Observable<any> {
    if (!options) {
      options = {};
    }
    // end point url
    // url =  ENV.APIUrl+ url;
    url = this.api + url;

    // token
    let headers: HttpHeaders | undefined = undefined;
    if (options.headers instanceof HttpHeaders) {
      headers = options.headers;
    } else {
      headers = new HttpHeaders(options.headers);
    }
    headers = headers.set('Content-Type', 'application/json; charset=utf-8');
    headers = headers.set('X-MCMAccessToken', this.cre.rsApiToken || '');
    headers = headers.set('TrackingCode', ENV.TrackingCode || '');
    headers = headers.set('Authorization', `Bearer ${this.cre.rsApiToken}` || '');
    headers = headers.set('X-ShoppingMode', (this.cre.extras && this.cre.extras.ShoppingModeId) || '');
    headers = headers.set('TenantIdentify', `${(window as any).TenantId}` || '');
    headers = headers.set(
      'AccessToken',
      (this.cre.extras && this.cre.extras.mi9v8 && this.cre.extras.mi9v8.token) || ''
    );
    headers = headers.set(
      'X-Device-Info',
      JSON.stringify({
        Source: 'app',
        SourceVersion: ENV.AppVersion,
        SourceBuildNumber: ENV.BuildNumber,
      })
    );
    options.headers = headers;

    // cache params
    // let params: HttpParams|undefined = undefined;
    // if (!!options.params) {
    //     if (options.params instanceof HttpParams) {
    //       params = options.params;
    //     } else {
    //       params = new HttpParams({ fromObject: options.params } as HttpParamsOptions);
    //     }
    // }

    const req = super.request(first as string, url, options as any);
    return req;
  }

  requestAccessToken() {
    // Ensure dynamic environment is loaded before making request
    if (!(window as any).TenantId) {
      return from(this.loadDynamicEnvironment()).pipe(switchMap(() => this.makeAccessTokenRequest()));
    }

    return this.makeAccessTokenRequest();
  }

  private makeAccessTokenRequest(): Observable<any> {
    const url = this.identityAPIUrl + `/login/guest`;
    let headers = new HttpHeaders();
    headers = headers.set('Content-Type', 'application/json; charset=utf-8');
    headers = headers.set('TrackingCode', ENV.TrackingCode || '');
    headers = headers.set('TenantIdentify', `${(window as any).TenantId}` || '');
    headers = headers.set(
      'X-Device-Info',
      JSON.stringify({
        Source: 'app',
        SourceVersion: ENV.AppVersion,
        SourceBuildNumber: ENV.BuildNumber,
      })
    );
    return this.http.post(url, null, { headers });
  }
}
