import { Injectable } from '@angular/core';
import { CanActivate, Router, UrlTree } from '@angular/router';
import { Observable, of } from 'rxjs';
import { switchMap, take } from 'rxjs/operators';
import { AuthService } from '../providers/auth-v2.service';
import { Credential } from '@rsApp/modules/auth-v2/providers/credential.service';

@Injectable({
  providedIn: 'root',
})
export class VerifiedEmailGuardService implements CanActivate {
  constructor(
    public authServcie: AuthService,
    public router: Router,
    public cre: Credential
  ) {}
  canActivate(): Observable<boolean | UrlTree> {
    return this.authServcie.getCurrentUser().pipe(
      take(1),
      switchMap((user) => {
        if (user && !user.IsVerifiedEmail) {
          if (user?.IsForceVerifyEmail) {
            return of(this.router.createUrlTree(['/verify-otp']));
          }
        }
        return of(true);
      })
    );
  }
}
