import { NgModule } from '@angular/core';
import { RouterModule, Routes } from '@angular/router';
import { RecipeRedirectGuard } from '../auth-v2/guards/recipe-redirect-guard';
import { AppGuardsWithoutAuth } from '../utils/guard';
import { TabsPageComponent } from './tabs.page';
import { extrasStateResolver } from '../utils/providers/navExtrasStateResolve.service';

const routes: Routes = [
  {
    path: 'tabs',
    component: TabsPageComponent,
    children: [
      {
        path: 'home',
        children: [
          {
            path: '',
            loadChildren: () => import('../home/home.router.module').then((m) => m.HomePageRoutingModule),
            resolve: {
              extrasStateResolver,
            },
          },
        ],
      },
      {
        path: 'browse',
        loadChildren: () => import('../browse/browse.router.module').then((m) => m.BrowsePageRoutingModule),
      },
      {
        path: 'membership',
        loadChildren: () =>
          import('../membership/membership-routing.module').then((m) => m.MembershipPageRoutingModule),
        data: {},
      },
      {
        path: 'more',
        loadChildren: () => import('../more/more.module').then((m) => m.MoreModule),
      },
      {
        path: 'deals',
        loadChildren: () => import('../ecom-v2/offer/offer-routing.module').then((m) => m.OfferRoutingModule),
      },
      {
        path: 'weekly-ad',
        loadChildren: () =>
          import('../ecom-v2/weekly-ad/weekly-ad-routing.module').then((m) => m.WeeklyAdRoutingModule),
      },
      {
        path: 'recipe',
        loadChildren: () => import('../ecom-v2/recipe/recipe-routing.module').then((m) => m.RecipeRoutingModule),
        canActivate: [...AppGuardsWithoutAuth, RecipeRedirectGuard],
      },
      {
        path: 'store',
        loadChildren: () => import('../store/store.module').then((m) => m.StoreModule),
        canActivate: AppGuardsWithoutAuth,
        data: {
          hideTab: true,
        },
      },
      {
        path: 'my-account',
        loadChildren: () => import('../account-v2/account-v2.module').then((m) => m.AccountV2Module),
        data: {
          hideTab: true,
        },
      },
    ],
    canActivate: AppGuardsWithoutAuth,
  },
  {
    path: '',
    redirectTo: 'tabs/home',
    pathMatch: 'full',
  },
];

@NgModule({
  imports: [RouterModule.forChild(routes)],
  exports: [RouterModule],
  declarations: [],
})
export class TabsPageRoutingModule {}
