import { Component, OnDestroy, ViewChild, OnInit } from '@angular/core';
import { Router } from '@angular/router';
import { AuthService } from '../../providers/auth-v2.service';
import { firstValueFrom } from 'rxjs';
import { ForgotPasswordStep } from '../../utils/enum';
import { MagAppDialogComponent } from '@rsApp/components/mag-app-dialog/mag-app-dialog';
import { User } from '@rsApp/modules/account-v2/providers/user.service';
import { TenantSettingsStore } from '@rsApp/modules/utils/providers/tenant-settings.service';
import { ITenantSettings } from '@rsApp/modules/utils/models/app-settings.model';

@Component({
  selector: 'forgot-password',
  templateUrl: 'forgot-password.html',
  styleUrls: ['./forgot-password.scss'],
})
export class ForgotPasswordPageComponent implements OnDestroy, OnInit {
  email: string;
  step: ForgotPasswordStep = ForgotPasswordStep.PRE_SEND_RESET_LINK;
  countdown: number = 0;
  alertConfig = {
    title: 'Failed to Send Reset Link',
    message:
      'Something went wrong. Please try again or contact <a class="alert-support">Customer Support</a> for help.',
    actionText: 'Close',
  };
  tenantSettings: ITenantSettings;
  private intervalId: any;

  constructor(
    public router: Router,
    private authService: AuthService,
    private userService: User,
    private tenantSettingsStore: TenantSettingsStore
  ) {
    this.email = this.router.getCurrentNavigation().extras.state?.email;
  }
  @ViewChild('dialogModal') dialogComponent!: MagAppDialogComponent;

  async ngOnInit() {
    this.tenantSettings = await this.tenantSettingsStore.getTenantSettings();
  }

  ngOnDestroy() {
    if (this.intervalId) {
      clearInterval(this.intervalId);
    }
  }

  backToSignIn(action: string) {
    this.router.navigate(['/sign-in']);
    if (action == 'closeForgotPW') return this.userService.setterEmail(this.email, 'forgot-password');
    this.userService.setterEmail(null, null);
  }

  async sendResetLink() {
    const response = await this.pushSendResetLink();
    if (!response) {
      this.dialogComponent.openDialog();
      console.warn('Failed to send reset link');
      return;
    }
    this.step = ForgotPasswordStep.SEND_RESET_LINK;
    this.initCountdown();
  }

  async resendLink() {
    const response = await this.pushSendResetLink();
    if (!response) {
      console.warn('Failed to send reset link');
      return;
    }
    this.initCountdown();
  }

  initCountdown() {
    this.countdown = 30;
    if (this.intervalId) {
      clearInterval(this.intervalId);
    }
    this.intervalId = setInterval(() => {
      this.countdown--;
      if (this.countdown <= 0) {
        clearInterval(this.intervalId);
      }
    }, 1000);
  }

  async pushSendResetLink() {
    try {
      const res = await firstValueFrom(this.authService.sendResetLink(this.email, this.tenantSettings?.bannerId));
      if (!res) {
        console.error('Failed to send reset link');
        return null;
      }
      return res;
    } catch (error) {
      console.error('Failed to send reset link', error);
      return null;
    }
  }

  closeAlert() {
    this.dialogComponent.closeDialog();
  }
}
