  init() {
    if (this.analytics) {
      console.log('Analytics initialized:', this.analytics.app.name);
    } else {
      console.error('Analytics not initialized');
    }
  }

  private trackEventWithCookieConsent(eventName: string, data: any) {
    const cookieConsent = CookieConsentManager.getInstance();

    if (!cookieConsent) return;

    cookieConsent.hasConsent('C0002', null, (hasConsent) => {
      if (hasConsent) {
        try {
          (window as any).dxp_at.push(['trackGtagEvent', eventName, data]);
          window.postMessage(
            { action: 'MagPushTrackingFirebase', payload: { eventName, payload: data } },
            window.location.origin
          ); // Push tracking Firebase library
        } catch (error) {
          console.error(`Error in ${eventName}:`, error);
        }
      }
    });
  }

  async getCurrent() {
    this.currentUser = await this.cri.getCurrentUser();
    this.userId = this.currentUser && this.currentUser.UserId ? this.currentUser.userID : '';
    this.currentService = '';
    this.currentStore = await this.cStore.getStore();
  }

