  convertIBagData(items: IBag) {
    try {
      if (!items.Items || items.Items.length <= 0) {
        return { result: [], value: 0 };
      }

      const result = [];
      let value = 0;

      Array.from(items.Items).forEach((item, index) => {
        const discount = item.ShoppingOfferDetails
          ? item.ShoppingOfferDetails.reduce((accumulator, current) => {
              return accumulator + current.DiscountAmount;
            }, 0)
          : 0;
        const coupon =
          (item.ShoppingOfferDetails &&
            item.ShoppingOfferDetails.length > 0 &&
            item.ShoppingOfferDetails[0].OfferCode) ||
          '';
        const data: IItemTrack = {
          item_id: item.Upc,
          item_name: item.ProductName,
          affiliation: this.currentService,
          coupon: coupon,
          discount: discount,
          index: index,
          item_brand: item.BrandName,
          item_category: item.CategoryNames && item.CategoryNames[0] ? item.CategoryNames[0] : '',
          item_category2: item.CategoryNames && item.CategoryNames[1] ? item.CategoryNames[1] : '',
          item_category3: item.CategoryNames && item.CategoryNames[2] ? item.CategoryNames[2] : '',
          item_category4: item.CategoryNames && item.CategoryNames[3] ? item.CategoryNames[3] : '',
          item_category5: item.CategoryNames && item.CategoryNames[4] ? item.CategoryNames[4] : '',
          item_list_id: items.ListId ? items.ListId.toString() : '',
          item_list_name: '',
          item_variant: '',
          location_id: '',
          price: item.Price,
          quantity: item.Quantity,
        };
        value += data.price * data.quantity;
        result.push(data);
      });

      return { result, value: items.TotalAmount || value };
    } catch (error) {
      console.error('Error in convertIBagData:', error);
    }
  }

  convertIBagItemData(item: IBagItem) {
    try {
      const discount = item.ShoppingOfferDetails
        ? item.ShoppingOfferDetails.reduce((accumulator, current) => {
            return accumulator + current.DiscountAmount;
          }, 0)
        : 0;
      const coupon =
        (item.ShoppingOfferDetails && item.ShoppingOfferDetails.length > 0 && item.ShoppingOfferDetails[0].OfferCode) ||
        '';
      const data: IItemTrack = {
        item_id: item.Upc,
        item_name: item.ProductName,
        affiliation: item.ServiceId && item.ServiceId.toString(),
        coupon: coupon,
        discount: discount,
        index: 0,
        item_brand: item.BrandName,
        item_category: item.CategoryNames && item.CategoryNames[0] ? item.CategoryNames[0] : '',
        item_category2: item.CategoryNames && item.CategoryNames[1] ? item.CategoryNames[1] : '',
        item_category3: item.CategoryNames && item.CategoryNames[2] ? item.CategoryNames[2] : '',
        item_category4: item.CategoryNames && item.CategoryNames[3] ? item.CategoryNames[3] : '',
        item_category5: item.CategoryNames && item.CategoryNames[4] ? item.CategoryNames[4] : '',
        item_list_id: '',
        item_list_name: '',
        item_variant: '',
        location_id: '',
        price: item.Price || this.getPriceText(item.DisplayPrice),
        quantity: 1,
      };

      return data;
      this.trackEventWithCookieConsent('sign_up', data);
    } catch (error) {
      console.error('Error in convertIBagItemData:', error);
    }
  }

  convertIProductVariantListArrayData(items?: IProductVariantList[]) {
    try {
      if (!items || items.length <= 0) {
        return { result: [], value: 0 };
      }

      const result = [];
      let value = 0;

      Array.from(items).forEach((item, index) => {
        const productVariant =
          item.ProductVariant || (item.ProductVariants && item.ProductVariants.length > 0 && item.ProductVariants[0]);
        const data: IItemTrack = {
          item_id: item.Upc,
          item_name: item.ProductName || item.Name,
          affiliation: this.currentService,
          coupon: '',
          discount: 0,
          index: index,
          item_brand: '',
          item_category: item.Categories && item.Categories[0] ? item.Categories[0].Name : '',
          item_category2: item.Categories && item.Categories[1] ? item.Categories[1].Name : '',
          item_category3: item.Categories && item.Categories[2] ? item.Categories[2].Name : '',
          item_category4: item.Categories && item.Categories[3] ? item.Categories[3].Name : '',
          item_category5: item.Categories && item.Categories[4] ? item.Categories[4].Name : '',
          item_list_id: '',
          item_list_name: '',
          item_variant: (productVariant && productVariant.Name) || '',
          location_id: '',
          price: this.getPriceFromProductVariant(productVariant),
          quantity: 1,
        };
        value += data.price;
        result.push(data);
      });

      return { result, value };
    } catch (error) {
      console.error('Error in convertIProductVariantListArrayData:', error);
    }
  }

