  convertProductData(item) {
    const price = this.getPriceFromProduct(item);

    try {
      const data: IItemTrack = {
        item_id: item.Upc || '',
        item_name: item.Name['En'] || '',
        affiliation: this.currentService || '',
        coupon: '',
        discount: 0,
        index: 0,
        item_brand: item.BrandName?.BrandName || '',
        item_category: item.Categories && item.Categories[0] ? item.Categories[0].CategoryName : '',
        item_category2: item.Categories && item.Categories[1] ? item.Categories[1].CategoryName : '',
        item_category3: item.Categories && item.Categories[2] ? item.Categories[2].CategoryName : '',
        item_category4: item.Categories && item.Categories[3] ? item.Categories[3].CategoryName : '',
        item_category5: item.Categories && item.Categories[4] ? item.Categories[4].CategoryName : '',
        item_list_id: '',
        item_list_name: '',
        item_variant: item.Name['En'] || '',
        location_id: this.currentStore?.StoreCode?.toString() || '',
        price: Number.parseFloat(price.price.replace('$', '')) || 0,
        salePrice: Number.parseFloat(price.salePrice.replace('$', '')) || 0,
        quantity: 1,
      };

      return data;
      this.trackEventWithCookieConsent('sign_up', data);
    } catch (error) {
      console.error('Error in convertProductData:', error);
    }
  }

  convertListProductsData(items: any) {
    try {
      if (!items || items.length <= 0) {
        return { result: [], value: 0 };
      }

      const result = [];
      let value = 0;

      Array.from(items).forEach((item: any, index) => {
        const data: IItemTrack = {
          item_id: item.UPC,
          item_name: item.Name,
          affiliation: this.currentService,
          coupon: '',
          discount: 0,
          index: index,
          item_brand: item.ProductBrand,
          item_category:
            item.ProductCategories && item.ProductCategories[0]
              ? item.ProductCategories[0].CategoryName
              : item.CategoryName || '',
          item_category2:
            item.ProductCategories && item.ProductCategories[1] ? item.ProductCategories[1].CategoryName : '',
          item_category3:
            item.ProductCategories && item.ProductCategories[2] ? item.ProductCategories[2].CategoryName : '',
          item_category4:
            item.ProductCategories && item.ProductCategories[3] ? item.ProductCategories[3].CategoryName : '',
          item_category5:
            item.ProductCategories && item.ProductCategories[4] ? item.ProductCategories[4].CategoryName : '',
          item_list_id: '',
          item_list_name: '',
          item_variant: item.ProductVariantName,
          location_id: '',
          price: item.PriceText ? Number.parseFloat(item.PriceText.replace('$', '')) : 0,
          quantity: 1,
        };
        value += data.price * data.quantity;
        result.push(data);
      });

      return { result, value };
    } catch (error) {
      console.error('Error in convertListProductsData:', error);
    }
  }

