  async createAccount(accountInfo: ISignupPayload) {
    try {
      const response = await firstValueFrom(this.user.createAccount(accountInfo));
      if (!response) return null;
      return response;
    } catch (error) {
      const errorCode = error?.error?.InternalCode;
      if (errorCode) {
        this.handlErrorMsg(errorCode);
      }
      return null;
    }
  }

  onContentScroll(event: any) {
    if (this.signupStep !== SignupStep.SIGNUP) return;
    const threshold = 60;
    const scrollTop = event.detail?.scrollTop ?? 0;

    if (!this.ionContent || typeof this.ionContent.getScrollElement !== 'function') {
      console.warn('ionContent or getScrollElement not available');
      return;
    }

    this.ionContent
      .getScrollElement()
      .then((scrollEl) => {
        if (!scrollEl) {
          console.warn('scrollEl is null');
          return;
        }
        const scrollHeight = scrollEl.scrollHeight ?? 0;
        const clientHeight = scrollEl.clientHeight ?? 0;
        const diff = scrollHeight - scrollTop - clientHeight;
        const atBottom = diff < threshold;

        if (this.isAtBottom !== atBottom) {
          this.isAtBottom = atBottom;
          this.cdr.detectChanges();
        }
      })
      .catch((err) => {
        console.error('Error getting scroll element:', err);
      });
  }

  // TODO : Regex can’t fix pasted input with leading/trailing spaces.
  async initSignupForm() {
    const zipPattern = this.countryRegion === 'ca' ? GlobalRegex.ZIP_CODE_CA : GlobalRegex.ZIP_CODE_US;

    this.signUpForm = this.fb.group({
      // Common fields
      membershipCode: ['', [Validators.pattern(GlobalRegex.NUMBER_ONLY)]],
      mobileNumber: [
        '',
        { validators: [Validators.required], asyncValidators: [this.phoneValidator.phoneValidator()] },
      ],
      password: ['', [Validators.required, this.passwordValidator.passwordValidator()]],
      address: ['', [Validators.required, Validators.pattern(GlobalRegex.ADDRESS_US)]],
      city: ['', [Validators.required, Validators.pattern(GlobalRegex.CITY_US)]],
      zipCode: ['', [Validators.required, Validators.pattern(zipPattern)]],
      promoCode: [''],
      emailProviders: [],
      state: ['', [Validators.required]],
      receiveTextMessage: [false],

      // Personal account fields
      firstName: ['', [Validators.required, Validators.pattern(GlobalRegex.NAME)]],
      lastName: ['', [Validators.required, Validators.pattern(GlobalRegex.NAME)]],
      birthday: [''],

      // Business account fields
      businessName: ['', [Validators.required]],
      contactName: [''],
      businessPhoneNumber: [''],
      isNonProfit: [false],
      willUseBusinessChecks: [false],
      subscriptions: {},
    });

    this.validatedPromoCode = false;
    this.renderScanBarcode = true;

    this.updateFormValidation();
  }

  private async initCampaigns() {
    try {
      const audiencesRes = await firstValueFrom(
        this.subscriptionSvc.getAudiencesByType(EnumAudienceType.Subscription, '')
      );
      this.campaigns = audiencesRes.map((e) => {
        return {
          Id: e.Id,
          Name: e.Name,
          Checked: false,
        };
      });
    } catch (error) {
      console.error(error);
    }
  }
