import { Component, EventEmitter, Input, Output } from '@angular/core';

@Component({
  selector: 'mag-app-dialog',
  templateUrl: './mag-app-dialog.html',
  styleUrls: ['./mag-app-dialog.scss'],
})
export class MagAppDialogComponent {
  @Input() isOpen = false;

  @Output() dismiss = new EventEmitter<void>();

  openDialog() {
    this.isOpen = true;
  }

  closeDialog() {
    this.isOpen = false;
  }
}
