import { Inject, Injectable } from '@angular/core';
import { MagEComCoreApiHttpClient } from '@rsApp/modules/gateway/mag-ecom-core-api.service';
import { CacheService } from 'ionic-cache';
import { map, Observable, catchError } from 'rxjs';
import { IMagProductRes } from '../model/interface';
import { HttpHeaders } from '@angular/common/http';
import { MAG_PRODUCT_V2_HTTP_CLIENT } from '../../utils/ecom-api-configs';

@Injectable({ providedIn: 'root' })
export class ProductService {
  constructor(
    public cache: CacheService,
    private apiCart: MagEComCoreApiHttpClient,
    @Inject(MAG_PRODUCT_V2_HTTP_CLIENT) private api: MagEComCoreApiHttpClient
  ) {}

  getProductByUPC(
    upc: string,
    storeCode: string,
    includeOffers: boolean = false,
    user?: any
  ): Observable<IMagProductRes> {
    const params = {
      upc: upc,
      storeCode: storeCode,
      includeOffers,
      customerCode: user && user.ExternalCustomerID,
    };
    return this.api.get('/products/by-upc', { params }).pipe(
      map((data: any) => {
        return data.Data;
      }),
      catchError(() => {
        return [];
      })
    );
  }

  getSimilarProducts(productId: string, storeCode: string): Observable<IMagProductRes[]> {
    const params = {
      storeCode: storeCode,
      pageIndex: 0,
      pageSize: 20,
      includeOffers: true,
    };
    return this.api.get(`/products/${productId}/similar`, { params }).pipe(
      map((data: any) => {
        return data.Records;
      })
    );
  }

  searchProductByKeyword(keyword: string, storeCode: string) {
    const params = {
      storeCode: storeCode,
      keyword: keyword,
    };
    return this.api.post('/search', params).pipe(
      map((data: any) => {
        return data.Data.Records;
      })
    );
  }

  getProductByBarCode(barCode: string, storeCode: string) {
    const params = {
      StoreCode: storeCode,
      Barcode: barCode,
    };
    return this.api.get(`/products/get-by-barcode`, { params }).pipe(
      map((data: any) => {
        return data;
      })
    );
  }

  // addItem(productId: string, storeCode: string): any {
  //   const params = {
  //     storeCode: storeCode,
  //     pageIndex: 0,
  //     pageSize: 20,
  //   };
  //   return this.api.get(`/product/v2.0/api/products/${productId}/similar`, { params }).pipe(
  //     map((data: any) => {
  //       return data.Records;
  //     })
  //   );
  // }

  addItem(cartId: string, storeId: number, data, shoppingMode = '') {
    const headers = new HttpHeaders({
      shoppingMode: shoppingMode,
    });
    const options = {
      headers: headers,
    };
    const url = `/cart/v2.0/api/cart/${cartId}/add-item?storeId=${storeId}`;
    return this.apiCart.post(url, data, options);
  }

  emptyCart(cartId: string) {
    // const params = {
    //   shoppingMode: shoppingMode,
    // };
    const url = `/cart/v2.0/api/cart/${cartId}/empty-cart`;
    const req = this.apiCart.delete(url);
    return req;
  }

  removeItemFromCart(cartId: string, cartItemId: string, shoppingMode = '') {
    const headers = new HttpHeaders({
      shoppingMode: shoppingMode,
    });

    const options = {
      headers: headers,
    };
    const url = `/cart/${cartId}/remove-item/${cartItemId}`;
    const req = this.apiCart.delete(url, options);
    return req;
  }

  updateItem(cartId: string, storeId: number, data, shoppingMode = '') {
    const params = {
      storeId: storeId,
    };
    const headers = new HttpHeaders({
      shoppingMode: shoppingMode,
    });

    const options = {
      headers: headers,
      params: params,
    };

    return this.apiCart.put(`/cart/v2.0/api/cart/${cartId}/update-item?storeId=${storeId}`, data, options);
  }

  getCartInfo(cartId?: string) {
    const params = {
      cartId: cartId,
    };
    return this.apiCart.get('/cart/v2.0/api/cart/', { params }).pipe(
      map((data: any) => {
        return data;
      })
    );
  }

  getGuestCartIds() {
    try {
      return JSON.parse(localStorage.getItem('GUEST_CART_IDS'));
    } catch {
      return [];
    }
  }

  getMultiCartPreview(cartIds?: string[]) {
    return this.apiCart.post('/cart/v2.0/api/cart/review', cartIds && [...cartIds]).pipe(
      map((data: any) => {
        return data;
      })
    );
  }

  getProductRecommendation() {
    return this.api.get('/products/recommendations/tags').pipe(
      map((data: any) => {
        if (data?.Data?.Tags) {
          return data?.Data?.Tags;
        }
        return null;
      })
    );
  }
}
