import { Injectable } from '@angular/core';
import { ITenantSettings } from '../models/app-settings.model';
import { TenantSettingsStore } from './tenant-settings.service';
import { ModalController } from '@ionic/angular';
import { MagWarningComponent } from '@rsApp/components/mag-many-request/mag-warning-popup';
import { TranslateService } from '@ngx-translate/core';
import { EValidationErrorCode } from '@rsApp/modules/auth-v2/utils/errorMessage';
import { IResponse } from '@rsApp/modules/auth-v2/utils/interface';

@Injectable({
  providedIn: 'root',
})
export class ErrorHandler {
  public tenantSettings: ITenantSettings;

  constructor(
    public tenantSettingsStore: TenantSettingsStore,
    public modalCtrl: ModalController,
    public translate: TranslateService
  ) {
    this.tenantSettingsStore.getTenantSettings().then((rs) => {
      this.tenantSettings = rs;
    });
  }

  translateText(txt: string, contactLink: string = '') {
    return this.translate.instant(txt, { link: contactLink });
  }

  handleErrorWithCode(errorResponse: IResponse) {
    const errorCode = errorResponse?.InternalCode || false;
    switch (errorCode) {
      case EValidationErrorCode.TENANT_NOT_SUPPORT:
        this.showChannelNotSupport();
        break;
      case EValidationErrorCode.FAIL_TO_UPDATE:
        this.handleUpdateFailed();
        break;
      // case EValidationErrorCode.PHONE_EXISTS:
      //   this.handlePhoneExists();
      //   break;
      case EValidationErrorCode.REACHED_LIMIT:
        this.showLimitRequest();
        break;
      case EValidationErrorCode.SEND_OTP_FAILED:
        this.handleSendOtpFailed();
        break;
      case EValidationErrorCode.SYSTEM_ERROR:
        this.handleShowSystemError();
        break;
      default:
        this.handleShowSystemError();
        break;
    }
    return {
      error: true,
      errorCode: errorCode,
    };
  }

  async showChannelNotSupport() {
    const contactLink = this.tenantSettings?.pages?.contactUs || '';
    const modal = await this.modalCtrl.create({
      component: MagWarningComponent,
      componentProps: {
        title: this.translateText('error.channelNotSupport.title'),
        desc: this.translateText('error.channelNotSupport.message', contactLink),
        subDesc: this.translateText('error.channelNotSupport.subMessage'),
        btnConfig: {
          cancel: {
            btnLable: 'Close',
            handle: () => {
              this.modalCtrl.dismiss();
            },
          },
        },
      },
      showBackdrop: false,
      backdropDismiss: false,
      cssClass: 'many-request-modal',
    });

    await modal.present();
    return false;
  }

  async handleUpdateFailed() {
    const contactLink = this.tenantSettings?.pages?.contactUs || '';
    const modal = await this.modalCtrl.create({
      component: MagWarningComponent,
      componentProps: {
        title: this.translateText('error.failedUpdatePhone.title'),
        desc: this.translateText('error.failedUpdatePhone.message', contactLink),
        btnConfig: {
          cancel: {
            btnLable: 'Close',
            handle: () => {
              this.modalCtrl.dismiss();
            },
          },
        },
      },
      showBackdrop: false,
      backdropDismiss: false,
      cssClass: 'many-request-modal',
    });

    await modal.present();
    return false;
  }

  async showLimitRequest() {
    const modal = await this.modalCtrl.create({
      component: MagWarningComponent,
      componentProps: {
        title: this.translateText('sendMail.manyRequest'),
        desc: this.translateText('sendMail.manyRequestDesc'),
        btnConfig: {
          cancel: {
            btnLable: 'Close',
            handle: () => {
              this.modalCtrl.dismiss();
            },
          },
        },
      },
      showBackdrop: false,
      backdropDismiss: false,
      cssClass: 'many-request-modal',
    });

    await modal.present();
    return false;
  }

  async handleSendOtpFailed() {
    const contactLink = this.tenantSettings?.pages?.contactUs || '';
    const modal = await this.modalCtrl.create({
      component: MagWarningComponent,
      componentProps: {
        title: this.translateText('error.failSentOTP.title'),
        desc: this.translateText('error.failSentOTP.message', contactLink),
        btnConfig: {
          cancel: {
            btnLable: 'Close',
            handle: () => {
              this.modalCtrl.dismiss();
            },
          },
        },
      },
      showBackdrop: false,
      backdropDismiss: false,
      cssClass: 'many-request-modal',
    });

    await modal.present();
    return false;
  }

  async handleShowSystemError() {
    const contactLink = this.tenantSettings?.pages?.contactUs || '';
    const modal = await this.modalCtrl.create({
      component: MagWarningComponent,
      componentProps: {
        title: this.translateText('error.signIn.systemError.title'),
        desc: this.translateText('error.signIn.systemError.message', contactLink),
        btnConfig: {
          cancel: {
            btnLable: 'Close',
            handle: () => {
              this.modalCtrl.dismiss();
            },
          },
        },
      },
      showBackdrop: false,
      backdropDismiss: false,
      cssClass: 'many-request-modal',
    });
    await modal.present();
    return false;
  }
}
