import { Component, OnInit } from '@angular/core';
import { Router } from '@angular/router';
import { TranslateService } from '@ngx-translate/core';

@Component({
  selector: 'subscription-confirm',
  templateUrl: './subscription-confirm.html',
  styleUrls: ['./subscription-confirm.scss'],
})
export class SubscriptionConfirmationComponent implements OnInit {
  public contentText: {
    title: string;
    description: string;
    primaryButtonText?: string;
    secondaryButtonText?: string;
  } = {
    title: '',
    description: '',
    primaryButtonText: '',
    secondaryButtonText: '',
  };

  constructor(
    private router: Router,
    private translate: TranslateService
  ) {}
  type: string | undefined;
  ngOnInit() {
    const nav = this.router.getCurrentNavigation();
    this.type = nav?.extras?.state?.['type'];
    let renderType;
    switch (this.type) {
      case 'success':
        renderType = 'guestSubscriptionThanks';
        break;
      case 'resubscribeSms':
        renderType = 'subscriptionResubscribe';
        break;
      case 'verifyPhone':
        renderType = 'guestSubscriptionPhone';
        break;
      case 'verifyEmail':
        renderType = 'guestSubscriptionInbox';
        break;
    }
    this.setContentText(renderType);

    this.translate.onLangChange.subscribe(() => {
      this.setContentText(renderType);
    });
  }

  handleNavigate(page: string) {
    switch (page) {
      case 'home':
        this.router.navigate(['/tabs/home']);
        break;
      case 'weekly-ad':
        this.router.navigate(['/tabs/weekly-ad']);
        break;
    }
  }

  setContentText(type: string) {
    const baseKey = `notification.${type}`;

    const title = this.translate.instant(`${baseKey}.title`);
    const description = this.translate.instant(`${baseKey}.description`);
    const primaryButtonText = this.translate.instant(`${baseKey}.primaryButtonText`);
    const secondaryButtonKey = `${baseKey}.secondaryButtonText`;
    const secondaryButtonText = this.translate.instant(secondaryButtonKey);

    this.contentText = {
      title,
      description,
      primaryButtonText,
      ...(secondaryButtonText !== secondaryButtonKey && { secondaryButtonText }),
    };
  }
}
