import { Component, HostListener } from '@angular/core';
import { Router } from '@angular/router';
import { Platform } from '@ionic/angular';
import { WalletService } from '@rsApp/modules/account-v2/providers/wallet.service';
import { Utils } from '@rsApp/modules/utils/providers/utils';

@Component({
  selector: 'membership',
  templateUrl: './membership.component.html',
  styleUrls: ['./membership.component.scss'],
})
export class MembershipPageComponent {
  public magHTML: string = '';

  constructor(
    public router: Router,
    private platform: Platform,
    private walletService: WalletService,
    private utils: Utils
  ) {}

  @HostListener('window:clickAddWallet', ['$event'])
  listenSaveWallet(event: CustomEvent<string>) {
    if (this.platform.is('ios')) {
      this.walletService.addAppleWallet(event.detail);
    } else if (this.platform.is('android')) {
      this.utils.openInSystem(event.detail);
    }
  }

  ionViewWillEnter() {
    customElements.whenDefined('mag-dashboard').then(() => {
      this.magHTML = '<mag-dashboard></mag-dashboard>';
    });
  }

  ionViewDidLeave() {
    this.magHTML = '';
  }
}
