import { Component, OnInit } from '@angular/core';
import { Credential } from '@rsApp/modules/auth-v2/providers/credential.service';
import { AccountV2Service } from '../../providers/account-v2.service';
import { firstValueFrom, tap } from 'rxjs';
import { IUpdateEmailPrefPayload } from '../../utils/enum';
import { ToastService } from '@rsApp/components/toast.service';
import { IMagToastOptions } from '@rsApp/components/interface';
import { TranslateService } from '@ngx-translate/core';
import { User } from '../../providers/user.service';
import { IUser } from '@rsApp/modules/interfaces/user.interface';
import { AppSettings } from '@rsApp/modules/utils/providers/app-setting';
import { AccountSettingsMap, SettingKey } from '@rsApp/modules/auth-v2/utils/interface';
import isEmpty from 'lodash/isEmpty';

@Component({
  selector: 'mag-preferences-accordion',
  templateUrl: './mag-preferences-accordion.html',
  styleUrls: ['./mag-preferences-accordion.scss'],
})
export class MagPreferencesAccordionComponent implements OnInit {
  isReceiveEmail: boolean;
  selectedProviders: any = [];
  emailProviders = ['BigY', 'Tablet & Vine'];
  isSubmitting: boolean = false;
  isReceiveTextMessage: boolean;
  user: any;
  formatedPhone: string;

  receiveEmail;
  receiveTextMessage;
  accountSettings: AccountSettingsMap;
  communicationSettings: any;

  constructor(
    private cre: Credential,
    private aService: AccountV2Service,
    private toastService: ToastService,
    private translate: TranslateService,
    private userService: User,
    private appSettingsService: AppSettings
  ) {}

  async ngOnInit() {
    await this.setupCommunicationSetting();
    this.user = await this.cre.getCurrentUser();
    this.formatedPhone = this.formatPhone(this.user?.Phone);
    if (this.user) {
      const { ReceiveEmail, ReceiveTextMessage, General1, General2 } = this.user;
      this.isReceiveEmail = !!ReceiveEmail || !isEmpty(this.receiveEmail);
      this.isReceiveTextMessage = !!ReceiveTextMessage || !isEmpty(this.receiveTextMessage);

      const generalFlags = [General1, General2];

      this.selectedProviders = this.emailProviders?.filter((_, i) => generalFlags[i]);
    }
  }

  // TODO
  async setupCommunicationSetting() {
    const rs = await firstValueFrom(this.appSettingsService.getSettingValue(SettingKey.Communication));
    const communicationSetting = JSON.parse(rs);
    this.receiveTextMessage = communicationSetting?.find((setting) => setting?.Name === 'ReceiveTextMessage');
    this.receiveEmail = communicationSetting?.find((setting) => setting?.Name === 'ReceiveEmail');
    this.emailProviders = this.receiveEmail?.Children?.map((setting) => setting?.DisplayName?.En);
  }

  formatPhone(phone: string | null | undefined): string {
    if (!phone) return '';
    const digits = phone.replace(/\D/g, '').slice(0, 10);
    if (digits.length < 10) return phone;

    return `(${digits.slice(0, 3)}) ${digits.slice(3, 6)}-${digits.slice(6, 10)}`;
  }

  async savePreferences() {
    if (this.isSubmitting) return;

    this.isSubmitting = true;
    try {
      const general1 = this.selectedProviders.includes(this.emailProviders[0]);
      const general2 = this.selectedProviders.includes(this.emailProviders[1]);
      const payload: IUpdateEmailPrefPayload = {
        UserId: this.user?.UserId,
        ReceiveEmail: !!general1 || !!general2,
        ReceiveTextMessage: this.isReceiveTextMessage,
        General1: general1,
        General2: general2,
      };
      const res = await firstValueFrom(this.aService.updateEmailPreferences(this.user?.UserId, payload));
      if (!res) {
        return false;
      }
      await firstValueFrom(this.loadCurrentUser());

      this.toggleToast();
      return true;
    } catch (error) {
      console.error('Failed to update preferences:', error);
      return false;
    } finally {
      this.isSubmitting = false;
    }
  }

  private loadCurrentUser() {
    return this.userService.getUserById(this.user.UserId).pipe(
      tap((user: IUser) => {
        this.cre.setCurrentUser(user);
        this.user = user;
      })
    );
  }

  onEmailSelectionChange(updatedList: string[]) {
    this.selectedProviders = updatedList;
  }

  toggleToast() {
    const toastRemoveAddressConfig: IMagToastOptions = {
      message: this.translate.instant('toast.preferenceUpdateSuccess'),
      type: 'success',
    };
    this.toastService.create(toastRemoveAddressConfig);
  }
}
