import { NgModule } from '@angular/core';
import { PreloadAllModules, RouterModule, Routes } from '@angular/router';
import { AuthV2Module } from './modules/auth-v2/auth-v2.module';
import { TabsPageModule } from './modules/tabs/tabs.module';
import { AppGuards, AppGuardsWithoutAuth, isOutDateGuard } from './modules/utils/guard';
import { RecipeRedirectGuard } from './modules/auth-v2/guards/recipe-redirect-guard';

const routes: Routes = [
  {
    path: '',
    redirectTo: 'tabs/home',
    pathMatch: 'full',
  },
  {
    path: 'store',
    loadChildren: () => import('./modules/store/store.module').then((m) => m.StoreModule),
    canActivate: AppGuardsWithoutAuth,
  },
  {
    path: 'tutorial',
    loadChildren: () => import('./modules/tutorial/tutorial.module').then((m) => m.TutorialModule),
    canActivate: isOutDateGuard,
  },
  {
    path: 'maintenance',
    loadChildren: () => import('./modules/maintenance/maintenance.module').then((m) => m.MaintenanceModule),
  },
  {
    path: 'cart',
    loadChildren: () => import('./modules/ecom-v2/cart/cart-routing.module').then((m) => m.CartRoutingModule),
    canActivate: AppGuardsWithoutAuth,
  },
  {
    path: 'checkout',
    loadChildren: () =>
      import('./modules/ecom-v2/checkout/checkout-routing.module').then((m) => m.CheckoutRoutingModule),
    canActivate: AppGuards,
  },
  {
    path: 'order',
    loadChildren: () => import('./modules/ecom-v2/order/order-routing.module').then((m) => m.OrderRoutingModule),
    canActivate: AppGuards,
  },
  {
    path: 'recipe',
    loadChildren: () => import('./modules/ecom-v2/recipe/recipe-routing.module').then((m) => m.RecipeRoutingModule),
    canActivate: [...AppGuardsWithoutAuth, RecipeRedirectGuard],
  },
  {
    path: 'product',
    loadChildren: () => import('./modules/ecom-v2/product/product-routing.module').then((m) => m.ProductRoutingModule),
    canActivate: AppGuardsWithoutAuth,
  },
  {
    path: 'offers',
    loadChildren: () => import('./modules/ecom-v2/offer/offer-routing.module').then((m) => m.OfferRoutingModule),
    canActivate: AppGuardsWithoutAuth,
  },
  {
    path: 'dxpages',
    loadChildren: () => import('./modules/ecom-v2/dxpage/dxpage-routing.module').then((m) => m.DXPageRoutingModule),
    canActivate: AppGuardsWithoutAuth,
  },
  {
    path: 'shopping-list',
    loadChildren: () =>
      import('./modules/ecom-v2/shopping-list/shopping-list-routing.module').then(
        (m) => m.ShoppingListPageRoutingModule
      ),
    canActivate: AppGuardsWithoutAuth,
  },
  {
    path: 'notification',
    loadChildren: () =>
      import('./modules/notification/notification-routing.module').then((m) => m.NotificationRoutingModule),
    canActivate: AppGuards,
  },
  {
    path: 'subscription',
    loadChildren: () =>
      import('./modules/account-v2/subscription/subscription-routing.module').then((m) => m.SubscriptionModule),
    data: { requiredLogin: true },
    canActivate: isOutDateGuard,
  },
];

@NgModule({
  imports: [
    RouterModule.forRoot(routes, {
      preloadingStrategy: PreloadAllModules,
      bindToComponentInputs: true,
      canceledNavigationResolution: 'computed',
      paramsInheritanceStrategy: 'always',
      urlUpdateStrategy: 'deferred',
    }),
    TabsPageModule,
    AuthV2Module,
  ],
  exports: [RouterModule],
})
export class AppRoutingModule {}
