import { Injectable } from '@angular/core';
import { IFontFamily, IThemeConfigurations } from '@rsApp/modules/utils/models/app-settings.model';

type TVar = { [key: string]: string | { [key: string]: string } };

@Injectable({
  providedIn: 'root',
})
export class ThemeService {
  fonts: IFontFamily[];
  globalCss: TVar = {};
  _globalCssOrigin: TVar;
  _newVariables = {};
  _invalidSource = [null, 'null', '', undefined, '<Please provide font source URL>'];

  initialize(config: IThemeConfigurations) {
    const themerConfigStr = sessionStorage.getItem('themerConfig');
    if (!config) {
      console.warn('No theme configuration found!');
      return;
    }

    if (!themerConfigStr) {
      if (config?.fonts) this.fonts = config.fonts;
      if (config?.globalCss) this.globalCss = config.globalCss;
    } else {
      try {
        console.log('Applying the themer selected.');
        const themerConfig = JSON.parse(themerConfigStr);
        const themeConfig = JSON.parse(themerConfig.themeConfig);
        const { fonts, globalCss } = themeConfig;

        if (!fonts || !globalCss) throw new Error();

        this.fonts = fonts;
        this.globalCss = globalCss;
      } catch {
        if (config?.fonts) this.fonts = config.fonts;
        if (config?.globalCss) this.globalCss = config.globalCss;
        console.error('Parsing the theme configuration failed!');
      }
    }
    this._globalCssOrigin = { ...this.globalCss };

    this._loadFonts();
    this._setTheme();
    this._cssVariableListener();
  }

  private _setTheme() {
    if (!this.globalCss) {
      console.error('No theme configuration found!');
      return;
    }
    const css = this._jsonToCssParser(this.globalCss);
    this._injectCss(css);
  }

  private _loadFonts() {
    if (!this.fonts.length) {
      return;
    }

    this.fonts
      .filter((font) => !this._invalidSource.includes(font.source))
      .forEach((font: IFontFamily) => {
        const existingLinkEl = document.querySelector(`link[href="${font.source}"]`);

        if (!existingLinkEl) {
          const el = document.createElement('link');
          el.setAttribute('rel', 'stylesheet');
          el.href = font.source;
          document.head.appendChild(el);
        }
      });
  }

  private _injectCss(css: string, id = 'mag-variables') {
    // Check if a <style> element with the provided id already exists
    let styleEl = document.getElementById(id) as HTMLStyleElement;

    if (styleEl) {
      // If the style element exists, replace its content
      // eslint-disable-next-line no-unsanitized/property
      styleEl.innerHTML = css;
    } else {
      // If the style element does not exist, create and append it
      styleEl = document.createElement('style');
      styleEl.setAttribute('type', 'text/css');
      styleEl.setAttribute('id', id); // Set a unique id for future reference
      // eslint-disable-next-line no-unsanitized/property
      styleEl.innerHTML = css;
      document.head.appendChild(styleEl);
    }
  }

  private _jsonToCssParser(json: TVar) {
    const selectors = Object.keys(json);
    return selectors
      .map((selector) => {
        const definition = json[selector];
        const rules = Object.keys(definition);
        const result = rules
          .map((rule) => {
            return `${rule}:${definition[rule]}`;
          })
          .join(';');
        return `${selector}{${result}}`;
      })
      .join('\n');
  }

  private _cssVariableListener() {
    window.addEventListener(
      'message',
      (event) => {
        if (event.origin !== window.location.origin) return;

        // Check the type of the message
        if (event.data.action === 'updateCSSGlobalVariable') {
          const { variable, value } = event.data.data;
          this._newVariables[variable] = value;

          this.globalCss = {
            ':root': Object.assign(
              {},
              typeof this.globalCss[':root'] === 'object' && this.globalCss[':root'] !== null
                ? this.globalCss[':root']
                : {},
              typeof this._newVariables === 'object' && this._newVariables !== null ? this._newVariables : {}
            ),
          };
          this._setTheme();

          // Remove if the new and old value are the same
          const originValue = this._globalCssOrigin[':root'][variable];
          if (originValue === value) delete this._newVariables[variable];
          console.log(this._newVariables);
        }
      },
      false
    );
  }
}
