import type { Ga4MappedEvent } from './ga4.types';
import { mapSearchResultParams, mapViewItemListParams } from './mapSearchResultsToItems';
import { mapSelectItemParams } from './mapSelectItemToItems';
import { mapViewItemParams } from './mapViewItem';
import { mapAddToCartParams } from './mapAddToCartParams';
import { mapRemoveFromCartParams } from './mapRemoveFromCartParams';
import { mapViewCartParams } from './mapViewCartParams';
import { mapBeginCheckoutParams } from './mapBeginCheckoutParams';
import { mapPurchaseParams } from './mapPurchaseParams';

type CanonicalEventName =
  | 'view_item_list'
  | 'select_item'
  | 'view_item'
  | 'view_search_result'
  | 'add_to_cart'
  | 'remove_from_cart'
  | 'view_cart'
  | 'begin_checkout'
  | 'purchase';

function normalizeEventName(name: string): string {
  return String(name ?? '').trim();
}

type EventConfig = {
  aliases: readonly string[];
  map: (payload: any) => any | null | undefined;
};

const EVENT_CONFIG: Record<CanonicalEventName, EventConfig> = {
  view_item_list: {
    aliases: ['view_item_list', 'viewItemList', 'view_list_item', 'viewListItem'],
    map: mapViewItemListParams,
  },
  select_item: {
    aliases: ['select_item', 'selectItem'],
    map: mapSelectItemParams,
  },
  view_item: {
    aliases: ['view_item', 'viewItem'],
    map: mapViewItemParams,
  },
  view_search_result: {
    aliases: ['view_search_result', 'viewSearchResult', 'view_result_search', 'viewResultSearch'],
    map: mapSearchResultParams,
  },
  add_to_cart: {
    aliases: ['add_to_cart', 'addtocart'],
    map: mapAddToCartParams,
  },
  remove_from_cart: {
    aliases: ['remove_from_cart', 'removeFromCart'],
    map: mapRemoveFromCartParams,
  },
  view_cart: {
    aliases: ['view_cart', 'viewCart'],
    map: mapViewCartParams,
  },
  begin_checkout: {
    aliases: ['begin_checkout', 'beginCheckout'],
    map: mapBeginCheckoutParams,
  },
  purchase: {
    aliases: ['purchase'],
    map: mapPurchaseParams,
  },
};

const ALIAS_TO_CANONICAL: Record<string, CanonicalEventName> = (() => {
  const out: Record<string, CanonicalEventName> = {};
  (Object.keys(EVENT_CONFIG) as CanonicalEventName[]).forEach((canonical) => {
    EVENT_CONFIG[canonical].aliases.forEach((alias) => {
      out[alias] = canonical;
    });
  });
  return out;
})();

function toCanonicalName(eventName: string): CanonicalEventName | null {
  return ALIAS_TO_CANONICAL[normalizeEventName(eventName)] ?? null;
}

export function mapStencilToGa4(eventName: string, payload: any): Ga4MappedEvent | null {
  const canonical = toCanonicalName(eventName);
  if (!canonical) return null;

  const params = EVENT_CONFIG[canonical].map(payload);
  if (params == null) return null;

  return { name: canonical, params };
}
