import { Component, EventEmitter, Input, Output, SimpleChanges, OnChanges } from '@angular/core';

@Component({
  selector: 'mag-account-radio-options',
  templateUrl: './mag-account-radio-options.html',
  styleUrls: ['./mag-account-radio-options.scss'],
})
export class MagAccountRadioOptionsComponent implements OnChanges {
  @Input() title?: string = '';
  @Input() options: string[] = [];

  @Input() defaultValue?: string;
  @Output() selectionChange = new EventEmitter<string>();
  @Output() openToolTip = new EventEmitter<void>();

  selectedValue: string | undefined;

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['defaultValue'] && this.defaultValue !== undefined) {
      this.selectedValue = this.defaultValue;
    }
  }

  onSelectionChange(event: any) {
    this.selectedValue = event.detail.value;
    this.selectionChange.emit(this.selectedValue);
  }

  showHelpTooltip() {
    this.openToolTip.emit();
  }
}
