import { Inject, Injectable } from '@angular/core';
import { MAG_CENTRAL_HTTP_CLIENT } from '@rsApp/modules/ecom-v2/utils/ecom-api-configs';
import { MagEComCoreApiHttpClient } from '@rsApp/modules/gateway/mag-ecom-core-api.service';
import { map, Observable } from 'rxjs';
import { EnumAudienceType, IAudience, ISubscribePayload } from '../model/interface';

@Injectable({ providedIn: 'root' })
export class SubscriptionService {
  constructor(@Inject(MAG_CENTRAL_HTTP_CLIENT) private api: MagEComCoreApiHttpClient) {}

  getAudiencesByType(type: EnumAudienceType, storeCode?: string): Observable<IAudience[]> {
    return this.api.get(`/audience?type=${type}&storeCode=${storeCode || ''}`).pipe(
      map((data: IAudience[]) => {
        return data;
      })
    );
  }

  subscribeSubscription(payload: ISubscribePayload): Observable<any> {
    return this.api.post('/subscriptions/subscribe-page', payload);
  }

  getSubsciptionByEmail(email: string): Observable<any> {
    return this.api.get(`/subscriptions/by-email/${email}`);
  }
}
