// https://cookieconsent.orestbida.com/essential/getting-started.html#configuration
export const COOKIE_CONSENT_CATEGORIES = {
  C0001: 'Strictly Necessary',
  C0002: 'Performance Cookies',
  C0003: 'Functional Cookies',
  C0004: 'Targeting Advertising',
};
export const getCookieConsentOptions = (
  language: string,
  translation: CookieConsent.Translation
): CookieConsent.CookieConsentConfig => {
  return {
    autoShow: true,
    hideFromBots: true,
    guiOptions: {
      consentModal: {
        layout: 'bar inline',
        position: 'bottom right',
        equalWeightButtons: true,
        flipButtons: false,
      },
      preferencesModal: {
        layout: 'box',
        position: 'left',
        equalWeightButtons: true,
        flipButtons: false,
      },
    },

    categories: {
      [COOKIE_CONSENT_CATEGORIES['C0001']]: {
        readOnly: true,
        enabled: true,
      },
      [COOKIE_CONSENT_CATEGORIES['C0002']]: {
        enabled: true,
        readOnly: false,
      },
      [COOKIE_CONSENT_CATEGORIES['C0003']]: {
        enabled: true,
        readOnly: false,
      },
      [COOKIE_CONSENT_CATEGORIES['C0004']]: {
        enabled: true,
        readOnly: false,
      },
    },

    language: {
      default: language,
      translations: {
        [language]: translation,
      },
    },
  };
};

/**
 *
 * @param t I18n translation object
 * @param sectionNumber The section number to get the translation for
 * @returns
 */
export const getCookieConsentTranslation = (t: any, sectionNumber: number): CookieConsent.Translation => {
  const sections = [];

  for (let i = 0; i < sectionNumber; i++) {
    sections.push({
      title: t(`cookieConsent.preferencesModal.sections.${i}.title`),
      description: t(`cookieConsent.preferencesModal.sections.${i}.description`),
      linkedCategory: t(`cookieConsent.preferencesModal.sections.${i}.linkedCategory`),
      cookieTable: t(`cookieConsent.preferencesModal.sections.${i}.cookieTable`),
    });
  }
  return {
    consentModal: {
      title: t('cookieConsent.consentModal.title'),
      description: t('cookieConsent.consentModal.description'),
      acceptAllBtn: t('cookieConsent.consentModal.acceptAllBtn'),
      acceptNecessaryBtn: t('cookieConsent.consentModal.acceptNecessaryBtn'),
      showPreferencesBtn: t('cookieConsent.consentModal.showPreferencesBtn'),
    },
    preferencesModal: {
      title: t('cookieConsent.preferencesModal.title'),
      acceptAllBtn: t('cookieConsent.preferencesModal.acceptAllBtn'),
      acceptNecessaryBtn: t('cookieConsent.preferencesModal.acceptNecessaryBtn'),
      savePreferencesBtn: t('cookieConsent.preferencesModal.savePreferencesBtn'),
      closeIconLabel: t('cookieConsent.preferencesModal.closeIconLabel'),
      serviceCounterLabel: t('cookieConsent.preferencesModal.serviceCounterLabel'),
      sections: sections,
    },
  };
};
