import { Inject, Injectable } from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { map } from 'rxjs';
import { MagEComCoreApiHttpClient } from '@rsApp/modules/gateway/mag-ecom-core-api.service';
import { MAG_OFFER_DXP_CORE_HTTP_CLIENT } from '../../utils/ecom-api-configs';

@Injectable()
export class ProductDealService {
  constructor(
    public route: ActivatedRoute,
    @Inject(MAG_OFFER_DXP_CORE_HTTP_CLIENT) public offerDxpCoreApi: MagEComCoreApiHttpClient
  ) {}

  getOfferInfosByUpcs(upcs: string[], storeCode: string) {
    const params = { Upcs: upcs, storeCode: storeCode };
    return this.offerDxpCoreApi.post('/Offer/GetOfferInfosByUpcs', params).pipe(
      map((data: any) => {
        return data?.Data || [];
      })
    );
  }
}
