import { Component, EventEmitter, Output } from '@angular/core';
import { DxpComponentService } from '@rsApp/modules/utils/providers/dxp.component.service';
import { RouteTrackerService } from '@rsApp/modules/utils/providers/route-tracker.service';
import { Subject, takeUntil } from 'rxjs';

@Component({
  selector: 'app-location-fulfillment',
  templateUrl: './location-fulfillment.component.html',
  styleUrls: ['./location-fulfillment.component.scss'],
})
export class LocationFulfillmentComponent {
  @Output() closeModal: EventEmitter<any> = new EventEmitter();
  public destroy$ = new Subject();

  magFulfillmentMethod = '';

  constructor(
    private dxpComponentService: DxpComponentService,
    private routeTracker: RouteTrackerService
  ) {}

  async ionViewWillEnter() {
    await this.dxpComponentService.onConnected();
    this.routeTracker
      .getRenderType()
      .pipe(takeUntil(this.destroy$))
      .subscribe((value) => {
        this.magFulfillmentMethod = `<mag-fulfillment-method render-type="${value}"></mag-fulfillment-method>`;
      });

    window.addEventListener('fulfillmentClose', () => {
      this.closeModal.emit();
    });
  }

  ionViewWillLeave() {
    this.magFulfillmentMethod = '';
    this.destroy$.next(true);
    this.destroy$.complete();
    window.removeEventListener('fulfillmentClose', () => {
      this.closeModal.emit();
    });
  }
}
