export const usPhoneMask: MaskitoOptions = {
  mask: ['(', /\d/, /\d/, /\d/, ')', ' ', /\d/, /\d/, /\d/, '-', /\d/, /\d/, /\d/, /\d/],
};

export const caPhoneMask: MaskitoOptions = {
  mask: ['(', /\d/, /\d/, /\d/, ')', ' ', /\d/, /\d/, /\d/, '-', /\d/, /\d/, /\d/, /\d/],
};
// U.S. Postal Code Mask (5 digits)
export const usPostcodeMask: MaskitoOptions = {
  mask: /^[0-9]{0,5}$/,
};

// Canadian Postal Code Mask (A1A 1A1)
export const caPostCodeMask: MaskitoOptions = {
  mask: [/^[A-Za-z]?$/, /^[0-9]?$/, /^[A-Za-z]?$/, ' ', /^[0-9]?$/, /^[A-Za-z]?$/, /^[0-9]?$/], //eslint-disable-line
  postprocessors: [({ value, selection }) => ({ value: value.toUpperCase(), selection })],
};

// Mapping Enum to Postal Code Masks
export const postalCodeMasks: { [key in CountryRegion]: MaskitoOptions } = {
  [CountryRegion.US]: usPostcodeMask,
  [CountryRegion.CA]: caPostCodeMask,
};

export const phoneMasks: { [key in CountryRegion]: MaskitoOptions } = {
  [CountryRegion.US]: usPhoneMask,
  [CountryRegion.CA]: caPhoneMask,
};

//TODO
export const GlobalRegex = {
  // ✅ Email: must include @ and domain
  EMAIL: /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/,

  PASSWORD: /^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[!@#$%^&*()])(?!.*\s)$/,

  // ✅ Name: only letters and space between words (no numbers or special characters)
  NAME: /^[A-Za-z]+(?:[-'’‘ʼ ][A-Za-z]+)*$/,

  // ✅ Digits only (numbers)
  NUMBER_ONLY: /^[0-9]*$/,

  // ✅ Non-digit characters (used for stripping with .replace in Maskito)
  NON_DIGIT_CHARACTERS: /\D/g,

  CITY_US: /^[A-Za-z]+(?:[ '-][A-Za-z]+)*$/,

  // Address must start with a letter or digit, no extra spaces, allows common symbols.
  ADDRESS_US: /^[\w #.,;:'’‘ʼ_/ -]+$/,

  // US Postal Code: 5 digits
  ZIP_CODE_US: /^[0-9]{5}$/,

  // Canadian Postal Code: A1A 1A1 or A1A1A1 (with or without space)
  ZIP_CODE_CA: /^[A-Za-z]\d[A-Za-z][\s]?\d[A-Za-z]\d$/,

  // Phone format
  PHONE: /^\(\d{3}\)\s\d{3}-\d{4}$/,
};

