import { Component, EventEmitter, Input, Output, ChangeDetectorRef, ViewChild } from '@angular/core';
import { IonModal } from '@ionic/angular';

@Component({
  selector: 'mag-app-bottom-sheet',
  templateUrl: './mag-app-bottom-sheet.html',
  styleUrls: ['./mag-app-bottom-sheet.scss'],
})
export class MagAppBottomSheetComponent {
  @ViewChild('modal', { static: false }) modal!: IonModal;

  public isOpen = false;

  @Input() title = '';
  @Input() isBackdropDismiss: boolean = true;
  @Input() showBackBtn?: boolean;
  @Output() dismiss = new EventEmitter<void>();

  constructor(private cdr: ChangeDetectorRef) {}
  openModal() {
    this.isOpen = true;
    this.cdr.detectChanges();
  }

  async closeModal() {
    if (this.modal) {
      await this.modal.dismiss();
    }
  }

  onModalDismiss() {
    this.isOpen = false;
    this.cdr.detectChanges();
    this.dismiss.emit();
  }
}
