import { NgModule } from '@angular/core';
import { RouterModule, Routes } from '@angular/router';
import { SignInPageComponent } from './pages/sign-in/sign-in';
import { SignUpPageComponent } from './pages/sign-up/sign-up';
import { ForceChangePasswordPageComponent } from './pages/force-change-password/force-change-password';
import { VerifyOtpPageComponent } from './pages/verify-otp/verify-otp';
import { ForgotPasswordPageComponent } from './pages/forgot-password/forgot-password';
import { isOutDateGuard } from '../utils/guard';
import { EnterPhonePageComponent } from './pages/enter-phone/enter-phone';
import { VerifyPhoneComponent } from './pages/verify-phone/verify-phone';

const routes: Routes = [
  {
    path: 'sign-in',
    component: SignInPageComponent,
    canActivate: isOutDateGuard,
  },
  {
    path: 'sign-up',
    component: SignUpPageComponent,
    canActivate: isOutDateGuard,
  },
  {
    path: 'force-change-password',
    component: ForceChangePasswordPageComponent,
    canActivate: isOutDateGuard,
  },
  {
    path: 'verify-otp',
    component: VerifyOtpPageComponent,
    canActivate: isOutDateGuard,
  },
  {
    path: 'forgot-password',
    component: ForgotPasswordPageComponent,
    canActivate: isOutDateGuard,
  },
  {
    path: 'enter-phone',
    component: EnterPhonePageComponent,
    canActivate: isOutDateGuard,
  },
  {
    path: 'verify-phone',
    component: VerifyPhoneComponent,
    canActivate: isOutDateGuard,
  },
];

@NgModule({
  imports: [RouterModule.forChild(routes)],
  exports: [RouterModule],
})
export class AuthV2RoutingModule {}
