import { Component, OnInit, OnDestroy } from '@angular/core';
import { MenuController } from '@ionic/angular';
import { Storage } from '@ionic/storage';
import { DEFAULT_LOCALE, LOCAL_LOCALE_KEY } from '@rsApp/modules/utils/constants/constants';
import { LangChangeEvent, TranslateService } from '@ngx-translate/core';
import { Subject, firstValueFrom, takeUntil, timer } from 'rxjs';
import { skip } from 'rxjs/operators';
import { IMenu } from '@rsApp/modules/interfaces/menu.interface';
import { IStore, ISystemService } from '@rsApp/modules/interfaces/store.interface';
import { StoreService } from '@rsApp/modules/store/providers/store.service';
import { Utils, filterMenusByAuth, filterMenusByService, isMenuValid } from '@rsApp/modules/utils/providers/utils';
import { IUser } from '@rsApp/modules/interfaces/user.interface';
import { AuthService } from '@rsApp/modules/auth-v2/providers/auth-v2.service';
import { MenuService } from '@rsApp/modules/utils/providers/menu.service';
import { Router } from '@angular/router';
import { AppSettings } from '@rsApp/modules/utils/providers/app-setting';
import { TenantSettingsStore } from '@rsApp/modules/utils/providers/tenant-settings.service';
import { CookieConsentManager } from '@rsApp/modules/cookie-consent/cookie-consent.manager';
import { CookieConsentService } from '@rsApp/modules/utils/providers/cookie-consent.service';

@Component({
  selector: 'mag-drawer',
  templateUrl: 'mag-drawer.html',
  styleUrls: ['mag-drawer.scss'],
})
export class MagDrawerComponent implements OnInit, OnDestroy {
  menuCode = 'APP_MORE_MENU'; // TODO

  // UI Labels
  prevMenuLabel: string = 'Main Menu';
  userName: string = '';
  nameIcon: string = '';
  submenuTransitionClass = ''; // '' | 'slide-left' | 'slide-right'
  isTransitioning = false;

  // User & Store Context
  user: IUser;
  store: IStore;
  locale: string;
  allowGuest = false;

  // Menu State
  menuStack: Array<{ label: string; items: IMenu[] }> = [];
  renderMenu: IMenu[];
  allServices: ISystemService[];
  rootMenu: IMenu;
  isAllowShowPreferences = false;

  // UI Control Flags
  showBorder = false;
  enabledSubscribeBanner: boolean = false;
  enabledMessageCenter: boolean = false;

  private _destroy$: Subject<boolean> = new Subject();

  constructor(
    private menuCtrl: MenuController,
    private storage: Storage,
    private menuService: MenuService,
    public oStore: StoreService,
    public utils: Utils,
    private auth: AuthService,
    private router: Router,
    private appSettingsService: AppSettings,
    private translate: TranslateService,
    private tenantSettingsStore: TenantSettingsStore,
    private cookieConsentService: CookieConsentService
  ) {}

  async ngOnInit() {
    this.locale = (await this.storage.get(LOCAL_LOCALE_KEY)) || DEFAULT_LOCALE;
    this.appSettingsService
      .getSettingValue('subscribe_now_banner_support')
      .pipe(takeUntil(this._destroy$))
      .subscribe((settingValue) => {
        this.enabledSubscribeBanner = settingValue === 'true';
      });

    this.appSettingsService
      .getSettingValue('enable_message_center')
      .pipe(takeUntil(this._destroy$))
      .subscribe((settingValue) => {
        this.enabledMessageCenter = settingValue === 'true';
      });

    this.translate.onLangChange.pipe(skip(1), takeUntil(this._destroy$)).subscribe((event: LangChangeEvent) => {
      this.locale = event.lang;
      this.loadMenuData();
    });

    this.auth
      .getCurrentUser()
      .pipe(takeUntil(this._destroy$))
      .subscribe(async (user) => {
        this.refresh();
        if (user) {
          this.user = user;
          this.setUserInfo();
        } else {
          const guestModeSetting = await this.tenantSettingsStore.getGuestModeSetting();
          this.allowGuest = guestModeSetting?.SettingValue === 'true';
        }
        await this.getAllCustomServices();
        this.loadMenuData();
      });

    this._allowShowPreferences();
  }

  ngOnDestroy() {
    this._destroy$.next(true);
    this._destroy$.complete();
  }

  public async signOut() {
    this.closeMenu();
    await this.auth.logout();
    this.router.navigate(['/sign-in'], { replaceUrl: true });
  }

  private delay$(ms: number) {
    return timer(ms).pipe(takeUntil(this._destroy$));
  }

  // Get current level menu
  get currentMenu() {
    return this.menuStack.length > 0
      ? this.menuStack[this.menuStack.length - 1]
      : { label: 'Main Menu', items: this.renderMenu };
  }

  async fetchRootMenu() {
    try {
      const rs = await firstValueFrom(this.menuService.getMenu(this.menuCode, 'Mobile', this.locale, false));
      if (!rs) return null;
      return rs;
    } catch (error) {
      console.error('Failed to fetch root menu:', error);
      return null;
    }
  }

  async loadMenuData() {
    const rootMenu = await this.fetchRootMenu();

    this.rootMenu = rootMenu;
    if (!isMenuValid(rootMenu, this.user)) {
      this.rootMenu = null;
      console.warn('Root menu is not valid');
      return;
    }
    const menu = filterMenusByAuth(rootMenu?.Childs, this.user);
    this.renderMenu = filterMenusByService(menu, this.allServices);
  }

  async getAllCustomServices() {
    if (!this.allServices) {
      this.allServices = await firstValueFrom(this.oStore.getStoreSystemServices());
    }
    return this.allServices;
  }

  refresh() {
    this.user = null;
    this.nameIcon = '';
    this.userName = '';
    this.renderMenu = null;
  }

  setUserInfo() {
    const { LastName, FirstName } = this.user || {};
    this.userName = FirstName + ' ' + LastName;
    this.nameIcon = FirstName[0] + LastName[0];
  }

  updatePrevMenuLabel() {
    this.prevMenuLabel = this.menuStack?.length > 1 ? this.menuStack?.[this.menuStack?.length - 2]?.label : 'Main Menu';
  }

  // Called when clicking a menu item
  openMenuItem(item: any) {
    if (item?.Childs?.length > 0) {
      this.submenuTransitionClass = 'mag-drawer__slide-right';
      this.isTransitioning = true;

      this.delay$(320).subscribe(() => {
        this.menuStack.push({
          label: item.Label,
          items: item.Childs,
        });
        this.submenuTransitionClass = '';
        this.isTransitioning = false;
      });
    } else {
      this.closeMenu();
      this.onClickDynamicMenu(item);
    }
  }

  onClickDynamicMenu(menu: IMenu) {
    const mobileUrl = menu.UrlLink;
    if (mobileUrl) {
      if (mobileUrl.indexOf('func://') > -1) {
        const startIdxParams = mobileUrl.indexOf('(') + 1;
        const endIdxParams = mobileUrl.indexOf(')');
        const fnName = (mobileUrl.slice(0, startIdxParams - 1) + mobileUrl.slice(endIdxParams + 1)).replace(
          'func://',
          ''
        );
        const params = mobileUrl.slice(startIdxParams, endIdxParams);
        const fn = this[fnName];
        if (fn && typeof fn === 'function') {
          fn.call(this, params);
        }
        return;
      }
    }
    this.utils.navigateByUrl(mobileUrl);
  }

  async onClickPrivacyPreference() {
    this.closeMenu();

    const cookieConsent = CookieConsentManager.getInstance();

    if (cookieConsent) {
      cookieConsent.showPreferences();
    }
  }

  // TODO
  handleInAppBrowser(url) {
    this.utils.openInaAppBrowser(url);
  }

  closeMenu() {
    this.menuCtrl.close();
  }

  // Back to previous level
  goBack() {
    this.submenuTransitionClass = 'mag-drawer__slide-left';
    this.delay$(320).subscribe(() => {
      this.menuStack.pop();
      this.submenuTransitionClass = '';
      this.updatePrevMenuLabel();
    });
  }

  navigateSubscribe() {
    this.closeMenu();
  }

  goToSignIn() {
    this.router.navigate(['/sign-in'], { replaceUrl: true, state: { email: null } });
    this.menuCtrl.close();
  }

  navigateToMessageCenter() {
    this.openMenuItem({
      UrlLink: 'app://notification',
    });
  }

  private _allowShowPreferences() {
    this.cookieConsentService.listenCookieConsentinItialized.pipe(takeUntil(this._destroy$)).subscribe(() => {
      const cookieConsent = CookieConsentManager.getInstance();
      this.isAllowShowPreferences = cookieConsent?.allowShowPreferences();
    });
  }
}
