import { Component, EventEmitter, Input, OnInit, Output } from '@angular/core';
import { Router } from '@angular/router';
import { AbstractControl, FormBuilder, FormGroup, Validators } from '@angular/forms';
import { MaskitoOptions, maskitoTransform } from '@maskito/core';
import { Credential } from '@rsApp/modules/auth-v2/providers/credential.service';
import { PhoneValidator } from '@rsApp/modules/utils/validator/phone-validator-v2';
import { VerificationType } from '@rsApp/modules/auth-v2/utils/enum';
import { firstValueFrom } from 'rxjs';
import { AuthService } from '../../providers/auth-v2.service';
import { IUser } from '@rsApp/modules/interfaces/user.interface';
@Component({
  selector: 'enter-phone',
  templateUrl: 'enter-phone.html',
  styleUrls: ['./enter-phone.scss'],
})
export class EnterPhonePageComponent implements OnInit {
  @Input() showInfoBanner?: boolean = false;
  @Input() description?: string = '';
  @Input() phoneNumber?: AbstractControl;
  @Input() isModal: boolean = false;

  @Output() requestOtp = new EventEmitter<{ cellPhone: string; methodSelected: string }>();

  phoneControl: AbstractControl;
  methodSelected: string = VerificationType.Sms;
  isLoading: boolean = false;
  user: IUser;
  detailInfomation: FormGroup;
  phoneMask: MaskitoOptions;

  constructor(
    public router: Router,
    private fb: FormBuilder,
    private cre: Credential,
    private phoneValidator: PhoneValidator,
    private authService: AuthService
  ) {
    this.detailInfomation = this.fb.group({
      phone: ['', Validators.required],
    });
  }

  async ngOnInit() {
    if (this.phoneNumber) {
      this.phoneControl = this.phoneNumber;
    } else {
      this.detailInfomation = this.fb.group({
        phone: ['', Validators.required],
      });
      this.phoneControl = this.detailInfomation.get('phone');
    }

    this.user = (await this.getUser()) as IUser;
    this.getForm();
    this.setupPhoneValidation();
  }

  private setupPhoneValidation(): void {
    const phoneControl = this.detailInfomation.get('phone');
    const userId = this.user?.UserId;

    phoneControl?.clearValidators();
    phoneControl?.clearAsyncValidators();

    phoneControl?.setValidators([Validators.required]);
    phoneControl?.setAsyncValidators([this.phoneValidator.phoneValidator(userId)]);
  }

  async getForm() {
    if (!this.user) return;
    const maskedPhone = maskitoTransform(
      { value: this.user?.Phone, selection: [this.user?.Phone?.length, this.user?.Phone?.length] },
      this.phoneMask
    ).value;

    this.detailInfomation.patchValue({
      phone: maskedPhone || this.user?.Phone || '',
    });
  }

  async getUser() {
    return await firstValueFrom(this.authService.getUserByEmail(this.cre.currentUser?.Email));
  }

  goBack() {
    this.router.navigate(['/sign-in']);
  }
}
