import { AfterViewInit, Component, EventEmitter, Input, OnDestroy, OnInit, Output } from '@angular/core';
import { ModalController } from '@ionic/angular';
import { TranslateService } from '@ngx-translate/core';
import { AuthService } from '@rsApp/modules/auth-v2/providers/auth-v2.service';
import { Credential } from '@rsApp/modules/auth-v2/providers/credential.service';
import { VerificationType } from '@rsApp/modules/auth-v2/utils/enum';
import { EValidationErrorCode } from '@rsApp/modules/auth-v2/utils/errorMessage';
import { UserOtpVerificationRequest, UserValidateOtpRequest } from '@rsApp/modules/auth-v2/utils/interface';
import { IUser } from '@rsApp/modules/interfaces/user.interface';
import { ITenantSettings } from '@rsApp/modules/utils/models/app-settings.model';
import { TenantSettingsStore } from '@rsApp/modules/utils/providers/tenant-settings.service';
import { Subject, firstValueFrom, takeUntil } from 'rxjs';
import { MagOtpActionType } from '../interface';
import { IUpdateUserPayload } from '@rsApp/modules/account-v2/utils/enum';
import { AccountV2Service } from '@rsApp/modules/account-v2/providers/account-v2.service';
import { EventBusService } from '@rsApp/modules/utils/providers/event-bus.service';
import { ErrorHandler } from '@rsApp/modules/utils/providers/error-handler.service';
import { PhoneFormatPipe } from '@rsApp/modules/utils/pipes/phone-format/phone-format';
@Component({
  selector: 'mag-verify-otp',
  templateUrl: './mag-verify-otp.html',
  styleUrls: ['./mag-verify-otp.scss'],
  providers: [PhoneFormatPipe],
})
export class MagVerifyOtpComponent implements OnInit, OnDestroy, AfterViewInit {
  @Input() email: string;
  @Input() phoneNumber: string;
  @Input() methodSelectedVerify: string;
  @Input() actionType: MagOtpActionType = MagOtpActionType.SIGNUP;
  @Input() useDifferentEmailSupport = false;
  @Input() useDifferentPhoneSupport = false;
  @Input() dataUser: any;
  @Input() userPayload: IUpdateUserPayload;
  @Input() isLoading: boolean = false;
  @Input() modalMode = false;

  @Output() emailSwitched = new EventEmitter<any>();
  @Output() verifiedSuccess = new EventEmitter<{ type: MagOtpActionType; otp: string }>();
  @Output() eventChangeAnotherPhone = new EventEmitter<{ type: MagOtpActionType; otp: string }>();

  coolDownTime: number = 30; //ToDo: Get from settings
  isRequested: boolean = false;
  isDisabled: boolean = true;
  otpCode: string;
  isInvalid: boolean = false;
  coolDownTimer: any;
  formattedPhone: string;

  private tenantSettings: ITenantSettings;
  private destroy$ = new Subject<void>();

  config = {
    length: 6, //ToDo: Confirm 6 or 8 digits, 8 will break current layout
    autoFocus: true,
    containerClass: 'mag-otp__container',
    inputClass: 'mag-otp__input',
    disableAutoFocus: false,
    allowNumbersOnly: true,
    inputStyles: {
      color: 'var(--mag-color-text, #121212)',
      fontFamily: '  var(--mag-typography-platform-font-family, Lexend, Arial, sans-serif)',
      fontSize: 'var(--mag-typography-body-medium-font-size, 16px)',
      fontStyle: 'normal',
      fontWeight: 'var(--mag-typography-body-medium-font-weight-regular, 300)',
      lineHeight: 'var(--mag-typography-body-medium-line-height, 24px)',
    },
  };

  constructor(
    private tenantSettingsStore: TenantSettingsStore,
    private authService: AuthService,
    private cre: Credential,
    public modalCtrl: ModalController,
    private translate: TranslateService,
    private accountService: AccountV2Service,
    private eventBus: EventBusService,
    public errorHandler: ErrorHandler,
    public phoneFormat: PhoneFormatPipe
  ) {}

  async ngOnInit() {
    this.formattedPhone = this.phoneFormat.transform(this.phoneNumber);
    this.tenantSettings = await this.tenantSettingsStore.getTenantSettings();
    if (
      ![
        MagOtpActionType.VERIFY_PHONE,
        MagOtpActionType.VERIFY_PHONE_ACCOUNT,
        MagOtpActionType.VERIFY_PHONE_CONTACT,
      ].includes(this.actionType)
    ) {
      this.requestOtp();
    }
    this.handleCountDown();
    this.eventBus
      .on('resUpdateContact')
      .pipe(takeUntil(this.destroy$))
      .subscribe((event) => {
        this.isLoading = false;

        if (event?.payload?.status) return;
        this.isInvalid = !event?.payload?.status;
      });
  }

  ngAfterViewInit() {
    //auto focus the first input box after view init
    setTimeout(() => {
      const firstInput = document.querySelector<HTMLInputElement>('.mag-otp__container input');
      if (firstInput) {
        firstInput.focus();
      }
    }, 500);
  }

  async getUser() {
    return await firstValueFrom(this.authService.getUserByEmail(this.cre.currentUser?.Email));
  }

  async requestOtp(isRequest: boolean = false) {
    try {
      const tenantId = this.tenantSettings?.bannerId;
      const params = {
        Channel: VerificationType.Email,
        BannerId: tenantId,
      } as UserOtpVerificationRequest;

      switch (this.actionType) {
        case MagOtpActionType.DELETE_ACCOUNT: {
          const deleteResult = await firstValueFrom(this.authService.sendOtpDeleteAccount(this.email, tenantId));
          if (!deleteResult) {
            console.warn('OTP request for account deletion failed');
          }
          break;
        }
        case MagOtpActionType.SIGNUP: {
          const { Email } = (await this.getUser()) as IUser;
          params.Contact = Email;
          const result = await firstValueFrom(this.authService.sendOtpByChanel(params));
          if (!result || result.Status === false) {
            return this.errorHandler.handleErrorWithCode(result);
          }
          break;
        }
        case MagOtpActionType.VERIFY_PHONE_ACCOUNT:
        case MagOtpActionType.VERIFY_PHONE_CONTACT: {
          params.Contact = this.phoneNumber.replace(/\D/g, '');
          params.Channel = this.methodSelectedVerify as VerificationType;
          break;
        }
        case MagOtpActionType.VERIFY_PHONE: {
          if (!isRequest) return;
          const { Phone } = (await this.getUser()) as IUser;
          params.Contact = Phone;
          params.Channel = this.methodSelectedVerify as VerificationType;
          params.NewContact = this.phoneNumber.replace(/\D/g, '');
          const result = await firstValueFrom(this.authService.sendOtpByChanel(params));
          if (!result || result.Status === false) {
            return this.errorHandler.handleErrorWithCode(result);
          }
          break;
        }
        case MagOtpActionType.CHANGE_EMAIL: {
          params.Contact = this.email;
          break;
        }
        default:
          params.Contact = this.email;
          break;
      }

      // Handle OTP request for non-DELETE_ACCOUNT cases
      if (
        [MagOtpActionType.DELETE_ACCOUNT, MagOtpActionType.SIGNUP, MagOtpActionType.VERIFY_PHONE].indexOf(
          this.actionType
        ) == -1
      ) {
        const result = await firstValueFrom(this.authService.sendOtpByChanelUpdateAccount(params));
        if (!result || result.Status === false) {
          return this.errorHandler.handleErrorWithCode(result);
        }
      }
    } catch (error) {
      console.warn('OTP request failed:', error);
    }
  }

  async validateOtpCode(otpCode: string, validationType: MagOtpActionType): Promise<any> {
    try {
      if (!otpCode) {
        console.warn('OTP code is required');
        this.isLoading = false;
        return false;
      }

      let isValid: any = false;

      switch (validationType) {
        case MagOtpActionType.DELETE_ACCOUNT:
          // Call the service for deleting account

          isValid = await firstValueFrom(
            this.authService.validateOtpDeleteAccount(this.cre.currentUser.Email, otpCode)
          );
          break;

        case MagOtpActionType.SIGNUP: {
          // Call the service for validating OTP create account
          const payload: UserValidateOtpRequest = {
            Email: this.email,
            Otp: otpCode,
          };
          isValid = await firstValueFrom(this.authService.validateOtpByEmail(payload));
          break;
        }
        case MagOtpActionType.CHANGE_EMAIL:
          // Call the service for validating OTP change email

          isValid = await firstValueFrom(
            this.authService.validateOtpChangeEmail({
              Username: this.cre.currentUser.Email,
              NewUsername: this.email,
              Otp: otpCode,
            })
          );
          break;

        case MagOtpActionType.VERIFY_PHONE: {
          // Call the service for validating OTP phone verification
          const { Phone } = (await this.getUser()) as IUser;
          const payloadVerifyPhone: UserValidateOtpRequest = {
            Phone: Phone,
            Otp: otpCode,
          };
          isValid = await firstValueFrom(this.authService.validateOtpByPhone(payloadVerifyPhone));
          break;
        }
        case MagOtpActionType.VERIFY_PHONE_ACCOUNT: {
          // Call the service for validating OTP phone verification on the Account page;
          const params = {
            ...this.userPayload,
            Otp: otpCode,
          };
          isValid = await await firstValueFrom(this.accountService.updateUser(this.userPayload.UserId, params));
          if (isValid == EValidationErrorCode.OTP_INVALID) isValid = false;
          break;
        }
      }

      if (!isValid) {
        this.isInvalid = true;
        this.isLoading = false;
        console.warn('Invalid OTP code');
      }

      return isValid;
    } catch (error) {
      console.warn('OTP validation failed:', error);
      this.errorHandler.handleErrorWithCode(error);
    }
  }

  translateText(txt: string, contactLink: string = '') {
    return this.translate.instant(txt, { link: contactLink });
  }

  async getNewCode() {
    const res = await this.requestOtp(true);
    if (res && res?.error && res?.errorCode === EValidationErrorCode.REACHED_LIMIT) return;
    this.isRequested = false;
    this.handleCountDown();
  }

  validateOtpField() {
    const code = this.otpCode?.trim() || '';
    this.isInvalid = code.length != this.config.length;
  }

  //TODO: Api is not stable ,Review loading logic
  async processOtp() {
    this.validateOtpField();
    if (this.isInvalid || this.isLoading) return;
    this.isLoading = true;

    // Handle add/update contact on address-management.ts
    if (this.actionType == MagOtpActionType.VERIFY_PHONE_CONTACT) {
      this.verifiedSuccess.emit({ type: this.actionType, otp: this.otpCode });
      return;
    }

    const passed = await this.validateOtpCode(this.otpCode, this.actionType);
    if (this.actionType !== MagOtpActionType.SIGNUP) {
      this.isLoading = false;
    }
    if (!passed) {
      console.warn('OTP validation failed');
      return;
    }

    // Verify OTP successfully
    this.verifiedSuccess.emit({ type: this.actionType, otp: this.otpCode });
  }

  useDifferentEmail() {
    this.emailSwitched.emit();
  }

  useDifferentPhone() {
    this.eventChangeAnotherPhone.emit();
  }

  handleCountDown() {
    if (this.coolDownTimer) {
      clearInterval(this.coolDownTimer);
    }
    this.coolDownTimer = setInterval(() => {
      this.coolDownTime--;
      if (this.coolDownTime <= 0) {
        clearInterval(this.coolDownTimer);
        this.coolDownTime = 30;
        this.isRequested = true;
      }
    }, 1000);
  }

  onOtpChange(otpCode) {
    this.isInvalid = false;
    this.otpCode = otpCode;
  }

  ngOnDestroy() {
    this.destroy$.next();
    this.destroy$.complete(); // Proper cleanup of subscriptions
  }
}
