import type { Ga4Item, ViewItemListParams, ApiSearchContainer, ViewSearchResultsParams } from './ga4.types';

function pickLocalizedText(v: any): string | undefined {
  if (!v) return undefined;
  if (typeof v === 'string') return v;

  if (typeof v === 'object') {
    if (typeof v.en === 'string') return v.en;

    const first = Object.values(v).find((x) => typeof x === 'string');
    return first as string | undefined;
  }

  return undefined;
}

function toNumber(v: any): number | undefined {
  if (typeof v === 'number' && Number.isFinite(v)) return v;
  const n = Number(v);
  return Number.isFinite(n) ? n : undefined;
}

function extractProducts(payload: any): any[] {
  const root = payload?.response ?? payload?.data ?? payload?.result ?? payload?.results ?? payload;

  if (Array.isArray(root)) {
    if (root.length > 0 && Array.isArray(root[0]?.Results)) {
      return (root as ApiSearchContainer[]).flatMap((c) => (Array.isArray(c?.Results) ? c.Results : []));
    }

    if (root.length > 0 && (root[0]?.ProductId || root[0]?.Gtin)) {
      return root;
    }

    return [];
  }

  if (root && Array.isArray(root.Results)) return root.Results;

  return [];
}

function mapApiProductToGa4Item(p: any, idx: number): Ga4Item {
  return {
    item_id: p?.ProductId ?? p?.Gtin,
    item_name: pickLocalizedText(p?.DisplayName) ?? pickLocalizedText(p?.Title),
    item_brand: pickLocalizedText(p?.Brand?.Name) ?? p?.Brand?.Id,
    item_category: pickLocalizedText(p?.Categories?.Level1?.Name) ?? pickLocalizedText(p?.DocumentDepartment?.Name),
    item_category2: pickLocalizedText(p?.Categories?.Level2?.Name),
    item_category3: pickLocalizedText(p?.Categories?.Level3?.Name),
    item_category4: pickLocalizedText(p?.Categories?.Level4?.Name),
    item_category5: pickLocalizedText(p?.Categories?.Level5?.Name),
    item_variant: p?.Unit ?? pickLocalizedText(p?.Size),
    location_id: p?.BranchId,
    price: toNumber(p?.Price ?? p?.MinPrice ?? p?.MaxPrice),
    index: idx + 1,
  };
}

function mapSearchResponseToViewItemListParams(payload: any): ViewItemListParams {
  const products = extractProducts(payload);

  const item_list_id = payload?.item_list_id ?? payload?.listId ?? payload?.list_id ?? payload?.searchTerm;

  const item_list_name =
    payload?.item_list_name ??
    payload?.listName ??
    payload?.list_name ??
    (payload?.searchTerm ? `Search: ${payload.searchTerm}` : 'Search Results');

  return {
    item_list_id,
    item_list_name,
    items: products.map(mapApiProductToGa4Item),
  };
}

export function mapViewItemListParams(payload: any): ViewItemListParams {
  return mapSearchResponseToViewItemListParams(payload);
}

export function mapSearchResultParams(payload: any): ViewSearchResultsParams {
  console.log('first', payload);
  return typeof payload === 'string'
    ? String(payload ?? '').trim()
    : payload?.search_term ?? payload?.searchTerm ?? payload?.keyword ?? payload?.term ?? payload?.query;
}
