import { Inject, Injectable } from '@angular/core';
import { ENV } from '@app/env';
import { RelationshopEComCoreHttpClient } from '@rsApp/modules/gateway/rs-ecom-core-api.service';
import { IPageMetadata, IResponeWidgetLayout, IWidgetLayout } from '@rsApp/modules/interfaces/widget-layout.interface';
import { CMS_HTTP_CLIENT } from '@rsApp/modules/more/more.config';
import { Observable, of, firstValueFrom, from } from 'rxjs';
import { catchError, map, switchMap, shareReplay, finalize } from 'rxjs/operators';
import { refreshParam } from './utils';
import { EnumAppCommonInformation, WIDGET_CONTENT_TYPE, WIDGET_TYPE } from '../enum/enum';
import { EnvironmentService } from '../../../../environments/environment.service';
import { Credential } from '@rsApp/modules/auth-v2/providers/credential.service';
import { CurrentStore } from '@rsApp/modules/store/providers/current-store.service';
import { IUser } from '@rsApp/modules/interfaces/user.interface';
import { intersection, isEmpty } from 'lodash';
import { AuthService } from '@rsApp/modules/auth-v2/providers/auth-v2.service';

@Injectable({
  providedIn: 'root',
})
export class WidgetLayoutService {
  public groupCacheKey = 'CMS-Widget-Layout';
  public currentUserSegments = [];

  private _currentUser: IUser;
  private dynamicEnv: any = null;
  private layoutCache = new Map<string, Observable<IWidgetLayout>>();
  private inFlightRequests = new Map<string, Observable<IWidgetLayout>>();

  constructor(
    @Inject(CMS_HTTP_CLIENT) private apiCore: RelationshopEComCoreHttpClient,
    private environmentService: EnvironmentService,
    private cre: Credential,
    private currentStore: CurrentStore,
    private authService: AuthService
  ) {
    this._currentUser = this.cre.currentUser;
  }

  private async loadDynamicEnvironment() {
    try {
      this.dynamicEnv = await firstValueFrom(this.environmentService.getDynamicEnvironment());
    } catch (error) {
      console.warn('Failed to load dynamic environment in WidgetLayout service:', error);
    }
  }

  public getLayout(slug: string, objectId: string, type: string, refresher?): Observable<IWidgetLayout> {
    const cacheKey = `${slug}|${objectId || ''}|${(type && typeof type === 'string' && type.toLowerCase()) || ''}`;

    // Get from cache when no refresher is requested
    if (!refresher && this.layoutCache.has(cacheKey)) {
      return this.layoutCache.get(cacheKey);
    }

    // If refreshing, check if there's already an in-flight request for the same parameters
    // This ensures multiple widgets calling refresh() simultaneously share a single HTTP request
    if (refresher && this.inFlightRequests.has(cacheKey)) {
      return this.inFlightRequests.get(cacheKey);
    }

    const params = {
      slug: slug,
      objectId: objectId || '',
      type: (type && typeof type === 'string' && type.toLowerCase()) || '',
      appCode: ENV.SiteCode,
      platform: EnumAppCommonInformation.Platform,
    };
    Object.assign(params, refreshParam(refresher, this.groupCacheKey));

    const o = this.apiCore.get<IResponeWidgetLayout>(`/layout/GetlayoutBySlugOrObjectId`, { params: params }).pipe(
      map((response) => {
        if (response && response.Data && response.Data.Id) {
          const data: IWidgetLayout = response.Data as IWidgetLayout;
          data.ZoneInfoValue = data.ZoneInfo ? JSON.parse(data.ZoneInfo) : [];
          return data;
        }
        return null;
      }),
      catchError(() => {
        return of(null);
      }),
      // Share one request result - multiple subscribers will get the same response
      shareReplay(1),
      // Clean up in-flight request after completion (for refresh requests)
      finalize(() => {
        if (refresher) {
          this.inFlightRequests.delete(cacheKey);
          // Update cache with the refreshed data
          this.layoutCache.set(cacheKey, o);
        }
      })
    );

    // If refreshing, store in in-flight requests map so subsequent calls share the same Observable
    if (refresher) {
      this.inFlightRequests.set(cacheKey, o);
    } else {
      // Update cache for non-refresh requests
      this.layoutCache.set(cacheKey, o);
    }

    return o;
  }

  public getSEO(slug: string, objectId: string, type = 'page', refresher?): Observable<IPageMetadata> {
    const o = this.getSEOGetByUrlClient(slug, type, refresher).pipe(
      switchMap((response) => {
        if (response) {
          return of(response);
        }
        return this.getSEOGetByObjectIdClient(objectId, type, refresher);
      }),
      catchError(() => {
        return of(null);
      })
    );
    return o;
  }
  public getSEOGetByUrlClient(slug: string, type: string, refresher?): Observable<IPageMetadata> {
    // Ensure dynamic environment is loaded before making request
    if (!this.dynamicEnv) {
      return from(this.loadDynamicEnvironment()).pipe(
        switchMap(() => this.makeSEOGetByUrlClientRequest(slug, type, refresher))
      );
    }

    return this.makeSEOGetByUrlClientRequest(slug, type, refresher);
  }

  private makeSEOGetByUrlClientRequest(slug: string, type: string, refresher?): Observable<IPageMetadata> {
    const params = {
      url: slug,
      type: (type && type.toLowerCase()) || '',
      tenant: this.dynamicEnv.tenantId,
    };
    Object.assign(params, refreshParam(refresher, this.groupCacheKey));
    const o: any = this.apiCore.get<IResponeWidgetLayout>(`/PageMetadata/GetByUrlClient`, { params: params }).pipe(
      map((response) => {
        if (response && response.Data && response.Data.Id) {
          return response.Data;
        }
        return null;
      }),
      catchError(() => {
        return of(null);
      })
    );
    return o;
  }

  public getSEOGetByObjectIdClient(objectId: string, type: string, refresher?): Observable<IPageMetadata> {
    // Ensure dynamic environment is loaded before making request
    if (!this.dynamicEnv) {
      return from(this.loadDynamicEnvironment()).pipe(
        switchMap(() => this.makeSEOGetByObjectIdClientRequest(objectId, type, refresher))
      );
    }

    return this.makeSEOGetByObjectIdClientRequest(objectId, type, refresher);
  }

  private makeSEOGetByObjectIdClientRequest(objectId: string, type: string, refresher?): Observable<IPageMetadata> {
    const params = {
      objectId: objectId,
      type: (type && type.toLowerCase()) || '',
      tenant: this.dynamicEnv.tenantId,
    };
    Object.assign(params, refreshParam(refresher, this.groupCacheKey));
    const o: any = this.apiCore.get<IResponeWidgetLayout>(`/PageMetadata/GetByObjectIdClient`, { params: params }).pipe(
      map((response) => {
        if (response && response.Data && response.Data.Id) {
          return response.Data;
        }
        return null;
      }),
      catchError(() => {
        return of(null);
      })
    );
    return o;
  }

  async setWidget(widget: any, zoneName?: string) {
    if (isEmpty(widget)) {
      return;
    }

    if (typeof widget.Type == 'string') {
      if (parseInt(widget.Type)) {
        // = "20"
        widget.Type = parseInt(widget.Type);
      } else {
        // = "Flat"
        widget.Type = WIDGET_TYPE[widget.Type] as any;
      }
    }
    if (typeof widget.ContentType == 'string') {
      if (parseInt(widget.ContentType)) {
        // = "20"
        widget.ContentType = parseInt(widget.ContentType);
      } else {
        widget.ContentType = WIDGET_CONTENT_TYPE[widget.ContentType] as any;
      }
    }

    try {
      const options = JSON.parse(widget.Options) || {};
      widget.Style = options.Style;
      widget.ViewMore = options.ViewMore;
      widget.DisplayStores = options.DisplayStores || null;
      widget.DisplayDate = options.DisplayDate || null;
      widget.AuthRequired = options.AuthRequired || false;
      widget.NonAuthRequired = options.NonAuthRequired || false;
      widget.IsDisplayShadow = options.IsDisplayShadow || false;
      widget.IsRoundedCorners = options.IsRoundedCorners || false;
      widget.ProgramCodes = options.programcodes || options.ProgramCodes || null; // ['Digital_Deals_Store', 'Mass_Offers'] ||
      widget.OptionsValue = options;
      widget.ZoneName = zoneName;
    } catch (error) {
      console.warn('Set widget options error', error);
    }

    widget.IsValid = await this.checkWidgetValid(widget);
    return widget;
  }

  async checkWidgetValid(widget) {
    //Check valid widget
    let isDisplayStoresValid = false;

    if (
      widget.DisplayStores &&
      widget.DisplayStores.length > 0 &&
      this.currentStore.store &&
      this.currentStore.store.StoreId
    ) {
      const found = widget.DisplayStores.indexOf(this.currentStore.store.StoreCode.toString()) > -1;
      isDisplayStoresValid = !!found;
    } else if (
      (!this.currentStore.store || !this.currentStore.store.StoreCode) &&
      widget.OptionsValue &&
      widget.OptionsValue.IsAnonymousStore
    ) {
      //When Guest mode && IsAnonymousStore == true
      isDisplayStoresValid = true;
    }

    let isDisplayDateValid = true;
    if (widget.DisplayDate) {
      const today = new Date().getTime();
      const from = (widget.DisplayDate.Start && new Date(widget.DisplayDate.Start).getTime()) || null;
      const toDate = (widget.DisplayDate.End && new Date(widget.DisplayDate.End)) || null;
      let to = null;
      if (toDate) {
        toDate.setHours(23, 59, 59, 999);
        to = toDate.getTime();
      }
      const withinRange = ((from && today >= from) || !from) && ((to && today <= to) || !to);
      isDisplayDateValid = withinRange;
    }

    let isAuthRequiredValid = false;
    if (
      (widget.AuthRequired && this._currentUser) ||
      (widget.NonAuthRequired && !this._currentUser) ||
      (widget.AuthRequired && widget.NonAuthRequired)
    ) {
      isAuthRequiredValid = true;
    }

    const isUserSegmentValid = await this.checkDxpSegmentValid(widget);
    const isValid =
      isDisplayStoresValid && isDisplayDateValid && isAuthRequiredValid && isUserSegmentValid && widget.IsActive;
    return isValid;
  }

  public checkDxpSegmentValid(widget) {
    try {
      let isUserSegmentValid = false;
      if (!widget?.OptionsValue?.DisplayUserSegments || widget?.OptionsValue?.DisplayUserSegments.length == 0) {
        isUserSegmentValid = true;
      } else if (widget?.OptionsValue?.DisplayUserSegments.length > 0 && !this._currentUser) {
        isUserSegmentValid = false;
      } else if (widget?.OptionsValue?.DisplayUserSegments.length > 0) {
        //Load data user segments
        if (!this.currentUserSegments) {
          try {
            // this.currentUserSegments = this.authProvider.getDXPUserSegment(this._currentUser?.CustomerCode);
            this.authService.getUserSegment(this._currentUser.CustomerCode).subscribe((e) => console.log(e));
          } catch (error) {
            console.error(
              '🚀 ~ file: event.message.provider.ts ~ line 150 ~ EventMessageProvider ~ initializeGlobalStore ~ error',
              error
            );
          }
        }
        const isIntersected = intersection(this.currentUserSegments, widget?.OptionsValue?.DisplayUserSegments);
        isUserSegmentValid = isIntersected && isIntersected.length > 0;
      }
      return isUserSegmentValid;
    } catch (error) {
      console.error('🚀 ~ file: widget.provider.ts ~ line 257 ~ WidgetProvider ~ checkDxpSegmentValid ~ error', error);
      return false;
    }
  }
}
