import { Component, Input } from '@angular/core';

interface BtnConfig {
  btnLable: string;
  handle: () => void;
}

@Component({
  selector: 'mag-warning-popup',
  templateUrl: './mag-warning-popup.html',
  styleUrls: ['./mag-warning-popup.scss'],
})
export class MagWarningComponent {
  @Input() title: string = '';
  @Input() desc: string = '';
  @Input() subDesc: string = '';
  @Input() btnConfig: {
    cancel: BtnConfig;
    confirm: BtnConfig;
  };

  onConfirm() {
    return this.btnConfig?.confirm?.handle();
  }

  onCancel() {
    return this.btnConfig?.cancel?.handle();
  }
}
