import { Component, ViewEncapsulation } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { ModalController } from '@ionic/angular';
import { NgxPubSubService } from '@pscoped/ngx-pub-sub';
import { AuthService } from '@rsApp/modules/auth-v2/providers/auth-v2.service';
import { Credential } from '@rsApp/modules/auth-v2/providers/credential.service';
import { GoogleAnalyticTracker } from '@rsApp/modules/utils/providers/google-tracker.service';
import { Utils } from '@rsApp/modules/utils/providers/utils';
import { CacheService } from 'ionic-cache';
import { BaseStore } from '../../base-store';
import { CurrentStore } from '../../providers/current-store.service';
import { StoreService } from '../../providers/store.service';

@Component({
  selector: 'page-store-context',
  templateUrl: 'store-context.html',
  styleUrls: ['./store-context.scss', '../../styles/store-list.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class StoreContextPageComponent extends BaseStore {
  searchbar: string;
  limitedQuantity: any;
  isPickupDelivery = false;
  storeListLength: any;

  returnRoute: string;
  defaultHref: string;
  btnFillInstore = 'outline';
  btnFillOnline = 'outline';
  listStore: any[] = [];
  keyword;

  serviceList: any;

  constructor(
    public utils: Utils,
    public auth: AuthService,
    public cStore: CurrentStore,
    public modalCtrl: ModalController,
    public router: Router,
    public store: StoreService,
    public route: ActivatedRoute,
    public cache: CacheService,
    public cri: Credential,
    public events: NgxPubSubService,
    public googleTracking: GoogleAnalyticTracker
  ) {
    super(utils, cStore, router, cache, store, cri, events, googleTracking);
    const params = this.route.snapshot.paramMap;
    this.returnRoute = params.get('returnRoute');
    this.defaultHref = params.get('defaultHref');
  }

  async ionViewWillEnter() {
    await super.getCurrent();
    return true;
  }
  closer() {
    this.router.navigate([this.returnRoute]);
  }

  viewMoreStore() {
    if (this.returnRoute) {
      this.router.navigate(['/store/find', { router: this.returnRoute }]);
    } else {
      this.router.navigate(['/store/find']);
    }
  }
  public getPageName() {
    return 'StoreContextPage';
  }
}
