import { NgModule } from '@angular/core';
import { RouterModule, Routes } from '@angular/router';
import { AddressManagementComponent } from './pages/address-management/address-management';
import { MyAccountComponent } from './pages/my-account/my-account';
import { PersonalInformationComponent } from './pages/personal-infomation/personal-infomation';
import { SecuritySettingsComponent } from './pages/security-settings/security-settings';
import { ChangeEmailVerifyOtpComponent } from './pages/change-email-verify-otp/change-email-verify-otp';
import { AuthGuardService } from '../auth-v2/guards/auth-guard.service';

const routes: Routes = [
  {
    path: '',
    component: MyAccountComponent,
    canActivate: [AuthGuardService],
    data: {
      hideTab: true,
    },
  },
  {
    path: 'infomation',
    component: PersonalInformationComponent,
    canActivate: [AuthGuardService],
    data: {
      hideTab: true,
    },
  },
  {
    path: 'security',
    component: SecuritySettingsComponent,
    canActivate: [AuthGuardService],
    data: {
      hideTab: true,
    },
  },
  {
    path: 'security/verify-otp',
    component: ChangeEmailVerifyOtpComponent,
    canActivate: [AuthGuardService],
    data: {
      hideTab: true,
    },
  },
  {
    path: 'address',
    component: AddressManagementComponent,
    canActivate: [AuthGuardService],
    data: {
      hideTab: true,
    },
  },
];

@NgModule({
  imports: [RouterModule.forChild(routes)],
  exports: [RouterModule],
})
export class AccountV2RoutingModule {}
