import { Location } from '@angular/common';
import { Injectable } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { ModalController, NavController } from '@ionic/angular';
import { BehaviorSubject, firstValueFrom } from 'rxjs';

@Injectable({ providedIn: 'root' })
export class ProductSearchService {
  private $keyword: BehaviorSubject<string> = new BehaviorSubject('');
  private $criterias: BehaviorSubject<any> = new BehaviorSubject(null);

  constructor(
    public route: ActivatedRoute,
    private modalCtrl: ModalController,
    public navCtrl: NavController,
    private location: Location,
    private router: Router
  ) {}

  getKeyWord() {
    return this.$keyword.asObservable();
  }

  setKeyWord(kw: string) {
    this.$keyword.next(kw);
  }

  async getKeyWordString(): Promise<string> {
    return await firstValueFrom(this.$keyword.asObservable());
  }

  clearKeyWord() {
    this.setCriterias(null);
  }

  setCriterias(criterias: any) {
    this.$criterias.next(criterias);
  }

  getCriterias() {
    return this.$criterias.asObservable();
  }

  public handleNavigateBack() {
    this.clearKeyWord();
    this.navCtrl.back();
  }

  public isProductSearchListPage(): boolean {
    return this.location?.path()?.includes('product/product-search-list');
  }

  async handleNavigateProductSearchList(payload: { keyword: string; categories: any[]; brands: any[] }) {
    const { keyword = '', categories = [], brands = [] } = payload;
    const queryParams = {};

    if (keyword) {
      queryParams['keyword'] = keyword;
    }

    const cateParams: string[] = categories.reduce((arr: string[], cat) => {
      if (cat?.Id && cat?.Name) {
        arr.push(cat.Id);
      }
      return arr;
    }, []);

    const brandParams: string[] = brands.reduce((arr: string[], brand) => {
      if (brand?.Id) arr.push(brand.Id);
      return arr;
    }, []);

    if (cateParams.length) queryParams['cats'] = cateParams.join(';');
    if (brandParams.length) queryParams['brands'] = brandParams.join(';');

    const navOptions = {
      relativeTo: this.route,
      queryParams: queryParams,
    };
    this.setCriterias(queryParams);

    if (!this.isProductSearchListPage()) {
      this.navCtrl.navigateForward(['/product/product-search-list'], navOptions);
    }

    try {
      const topModal = await this.modalCtrl.getTop();
      if (topModal) {
        await topModal.dismiss();
      }
    } catch {
      // ignore if there's no modal or dismiss fails
    }
  }
}
