import { Component, Input, Output, EventEmitter } from '@angular/core';
import { FormBuilder, Validators } from '@angular/forms';
import { RecipeService } from '@rsApp/modules/ecom-v2/recipe/providers/recipe.service';
import { AppSettings } from '@rsApp/modules/utils/providers/app-setting';
import { firstValueFrom } from 'rxjs/internal/firstValueFrom';
import { Credential } from '@rsApp/modules/auth-v2/providers/credential.service';
import { ToastService } from '../toast.service';
import { GlobalRegex } from '@rsApp/modules/utils/enum/enum';

@Component({
  selector: 'mag-app-share-email',
  templateUrl: './mag-app-share-email.html',
  styleUrls: ['./mag-app-share-email.scss'],
})
export class MagAppShareEmailComponent {
  @Input() recipeCode: string;
  @Input() bannerId: string;
  @Input() siteCode: string;

  @Output() emailSubmitted = new EventEmitter<void>();

  mailForm: any;
  isLoading: boolean = false;

  constructor(
    private fb: FormBuilder,
    public appSettings: AppSettings,
    public recipeService: RecipeService,
    public cre: Credential,
    private toastService: ToastService
  ) {
    this.mailForm = this.fb.group({
      email: ['', [Validators.required, Validators.pattern(GlobalRegex.EMAIL)]],
    });
  }

  validateControl(controlName: string): boolean {
    const control = this.mailForm.get(controlName);
    if (control?.invalid) {
      control.markAsTouched();
      return false;
    }
    return true;
  }

  async handleMailShare() {
    if (this.isLoading) return; // Prevent multiple clicks
    this.isLoading = true;

    try {
      const isValid = this.validateControl('email');

      if (isValid) {
        const payload = {
          code: this.recipeCode,
          email: this.mailForm.get('email')?.value ?? '',
          userId: this.cre.currentUser?.UserId ?? '',
          platform: 'app',
          bannerId: this.bannerId,
          siteCode: this.siteCode,
          language: 'En',
        };

        const rs: any = await firstValueFrom(this.recipeService.shareRecipes(payload));

        this.toastService.create({
          message: rs ? `Shared to ${payload.email}` : rs?.message ?? 'Something went wrong',
          type: rs ? 'success' : 'error',
        });

        if (rs) this.emailSubmitted.emit();
      }
    } catch (error: any) {
      this.toastService.create({
        message: error?.message ?? 'Share failed',
        type: 'error',
      });
    } finally {
      this.isLoading = false; // Always executed
    }
  }
}
