import { Component, Input } from '@angular/core';
import { ModalController } from '@ionic/angular';

@Component({
  selector: 'mag-modal-confirm',
  templateUrl: './mag-modal-confirm.html',
  styleUrls: ['./mag-modal-confirm.scss'],
})
export class MagModalConfirmComponent {
  @Input() title: string | null = null;
  @Input() description: string | null = null;
  @Input() descriptionLine2?: string | null = null;
  @Input() confirmTitle: string | null = null;
  @Input() cancelTitle?: string | null = null;
  @Input() verticalButtons?: boolean = true;
  constructor(private modalCtrl: ModalController) {}

  onDidmiss(option: boolean) {
    this.modalCtrl.dismiss(option);
  }
}
