// https://stackoverflow.com/questions/19098797/fastest-way-to-flatten-un-flatten-nested-javascript-objects
const flatten = (function (isArray: (value: any) => boolean, wrapped: (value: any) => any) {
  return function (table: any): Record<string, any> {
    return reduce('', {}, table);
  };

  function reduce(path: string, accumulator: Record<string, any>, table: any): Record<string, any> {
    if (isArray(table)) {
      const length = table.length;

      if (length) {
        let index = 0;

        while (index < length) {
          const property = path + '[' + index + ']';
          const item = table[index++];
          if (wrapped(item) !== item) accumulator[property] = item;
          else reduce(property, accumulator, item);
        }
      } else accumulator[path] = table;
    } else {
      let empty = true;

      if (path) {
        for (const property in table) {
          const item = table[property];
          const newProperty = path + '.' + property;
          empty = false;

          if (wrapped(item) !== item) accumulator[newProperty] = item;
          else reduce(newProperty, accumulator, item);
        }
      } else {
        for (const property in table) {
          const item = table[property];
          empty = false;

          if (wrapped(item) !== item) accumulator[property] = item;
          else reduce(property, accumulator, item);
        }
      }

      if (empty) accumulator[path] = table;
    }

    return accumulator;
  }
})(Array.isArray, Object);

function unflatten(table: Record<string, any>): any {
  const result: any = {};

  for (const path in table) {
    let cursor = result;
    const length = path.length;
    let property = '';
    let index = 0;

    while (index < length) {
      const char = path.charAt(index);

      if (char === '[') {
        const start = index + 1;
        const end = path.indexOf(']', start);
        cursor = cursor[property] = cursor[property] || [];
        property = path.slice(start, end);
        index = end + 1;
      } else {
        cursor = cursor[property] = cursor[property] || {};
        const start = char === '.' ? index + 1 : index;
        const bracket = path.indexOf('[', start);
        const dot = path.indexOf('.', start);

        let end: number;

        if (bracket < 0 && dot < 0) {
          end = length;
          index = length;
        } else if (bracket < 0) {
          end = dot;
          index = dot;
        } else if (dot < 0) {
          end = bracket;
          index = bracket;
        } else {
          end = bracket < dot ? bracket : dot;
          index = end;
        }

        property = path.slice(start, end);
      }
    }

    cursor[property] = table[path];
  }

  return result[''];
}

export { flatten, unflatten };
