import { Component, OnInit, OnDestroy } from '@angular/core';
import { AbstractControl, FormBuilder, FormGroup, ValidationErrors, Validators } from '@angular/forms';
import { ActivatedRoute, Router } from '@angular/router';
import { Utils } from '@rsApp/modules/utils/providers/utils';
import { PasswordValidator } from '@rsApp/modules/utils/validator/password-validator-v2';
import { Credential } from '@rsApp/modules/auth-v2/providers/credential.service';
import { AuthService } from '../../providers/auth-v2.service';
import { Subject, firstValueFrom, takeUntil } from 'rxjs';
import { IUser } from '@rsApp/modules/interfaces/user.interface';

@Component({
  selector: 'force-change-password',
  templateUrl: 'force-change-password.html',
  styleUrls: ['./force-change-password.scss'],
})
export class ForceChangePasswordPageComponent implements OnInit, OnDestroy {
  updatePasswordForm: FormGroup;
  user: IUser;

  private _destroy$: Subject<boolean> = new Subject();

  constructor(
    public route: ActivatedRoute,
    public router: Router,
    private fb: FormBuilder,
    public passwordValidator: PasswordValidator,
    // public user: User,
    public utils: Utils,
    public cre: Credential,
    private authService: AuthService
  ) {
    this.updatePasswordForm = this.fb.group(
      {
        newPassword: ['', [Validators.required, this.passwordValidator.passwordValidator()]],
        reEnterPassword: ['', [Validators.required]],
      },
      { validators: this.passwordsMatchValidator }
    );
  }

  async ngOnInit() {
    this.authService
      .getCurrentUser()
      .pipe(takeUntil(this._destroy$))
      .subscribe((user) => {
        if (user) {
          this.user = user;
        }
      });
  }

  ngOnDestroy(): void {
    this._destroy$.next(true);
    this._destroy$.complete();
  }

  //TODO
  passwordsMatchValidator(form: AbstractControl): ValidationErrors | null {
    const password = form.get('newPassword')?.value;
    const confirmPassword = form.get('reEnterPassword')?.value;

    // eslint-disable-next-line security/detect-possible-timing-attacks
    if (password !== confirmPassword) {
      form.get('reEnterPassword')?.setErrors({ mismatchPassword: true });
      return { mismatchPassword: true };
    }

    return null;
  }

  syncUserData(user: IUser) {
    if (user.IsPwdTemporary) {
      user.IsPwdTemporary = false;
      this.authService.setCurrentUser(user);
      this.cre.setCurrentUser(user);
    }
  }

  async updatePassword() {
    try {
      const rs = await firstValueFrom(
        this.authService.forceChangePassword({
          userName: this.user?.Email,
          NewPassword: this.updatePasswordForm.value.newPassword,
          ResetPasswordToken: this.cre.currentUser?.ResetPasswordToken,
        })
      );
      if (rs) {
        this.syncUserData(this.user);
        this.router.navigate(['/tabs/home'], { replaceUrl: true });
      }
    } catch (err) {
      console.warn(err, 'Failed to update password');
    }
  }

  async changePassword() {
    if (this.updatePasswordForm.invalid) {
      this.updatePasswordForm.markAllAsTouched(); // Show all errors immediately
      return;
    }
    await this.updatePassword();
  }

  back() {
    this.router.navigate(['/sign-in']);
  }
}
