  public getSEOSlug(name: string, id?: string | number): string {
    if (!name) {
      return '';
    }
    const normalizedName = name
      .toLowerCase()
      .replace(/[^a-zA-Z0-9 ]/g, '')
      .replace(/ +/g, '-');

    const idPart = id !== undefined && id !== null && String(id).length > 0 ? `-${id}` : '';

    return `${normalizedName}${idPart}`;
  }

  public async mappingWebSEOUrl(type: 'product' | 'recipe' | 'blog', SEOUrl: string): Promise<string> {
    try {
      const tenantSettings = await this.tenantSettingsStore.getTenantSettings();
      const webDomain = tenantSettings.associatedWebUrl;
      if (!webDomain) {
        return '';
      }
      switch (type) {
        case 'product':
          return ''; // TODO: add product SEO url
        case 'recipe':
          return `${webDomain}/recipes/recipe-detail/${SEOUrl}`;
        case 'blog':
          return `${webDomain}${SEOUrl}`;
      }
    } catch (error) {
      console.error('Failed to mapping web SEO url:', error);
      return '';
    }
  }

