  convertToPhone(phone) {
    if (!phone) {
      return '';
    }
    const regxFormat1 = new RegExp(/[()](\d{3})[)] (\d{3})-(\d{4})/);
    const regxFormat2 = new RegExp(/(\d{3})-(\d{3})-(\d{4})/);
    if (regxFormat1.test(phone) || regxFormat2.test(phone)) {
      return phone;
    } else {
      if (phone.length === 10) {
        return phone.replace(/(\d{3})(\d{3})(\d{4})/, '$1-$2-$3');
      }
    }
  }

