export function refreshParam(refresher, groupkey?, key?, prefixKey?) {
  const params = {
    rCache: refresher ? 'fresh' : 'default',
    rCacheKey: key || null,
    rCacheGroupKey: groupkey || null,
    rPrefixCacheKey: prefixKey || null,
  };
  return _.omitBy(params, _.isNil);
}
export function preventBuble(event) {
  if (!event) {
    return;
  }
  if (event.stopPropagation) {
    event.stopPropagation();
  }
  if (event.preventDefault) {
    event.preventDefault();
  }
  if (!event.srcEvent) {
    return;
  }
  const srcEvent = event.srcEvent;
  if (srcEvent.stopPropagation) {
    srcEvent.stopPropagation();
  }
  if (srcEvent.preventDefault) {
    srcEvent.preventDefault();
  }
}

export function fillInAddress(place) {
  const newAddress: any = {};
  const address_components = place.address_components as google.maps.GeocoderAddressComponent[];
  let address1 = '';
  // Get each component of the address from the place details,
  // and then fill-in the corresponding field on the form.
  // place.address_components are google.maps.GeocoderAddressComponent objects
  // which are documented at http://goo.gle/3l5i5Mr
  for (const component of address_components) {
    const componentType = component.types[0];

    switch (componentType) {
      case 'street_number': {
        address1 = `${component.long_name} ${address1}`;
        break;
      }

      case 'route': {
        address1 += component.long_name;
        break;
      }

      case 'postal_code': {
        newAddress.ZipCode = `${component.long_name}`;
        break;
      }

      case 'locality':
        address1 += `, ${component.long_name} `;
        newAddress.City = component.long_name;
        break;

      case 'sublocality_level_1': {
        if (!newAddress.City) {
          address1 += `, ${component.short_name} `;
          newAddress.City = component.long_name;
        }
        break;
      }
      case 'administrative_area_level_1': {
        address1 += `, ${component.short_name} `;
        newAddress.State = component.short_name;
        break;
      }
      case 'country': {
        address1 += `, ${component.short_name} `;
        break;
      }
    }
  }

  newAddress.Address = address1;
  newAddress.lat = place.geometry.location.lat().toString();
  newAddress.lng = place.geometry.location.lng().toString();
  return newAddress;
}

export function strapiUrlAutoGenerate() {
  const tenantCode = (window as any).TenantCode?.toLowerCase();
  if (!tenantCode) {
    return null;
  }
  const envNameLower = ENV.SiteEnv?.toLowerCase();
  const envPrefix = envNameLower?.includes('production')
    ? ''
    : envNameLower?.includes('staging')
      ? 'stg-'
      : envNameLower + '-';

  return `https://${envPrefix}${tenantCode}-admin.mercatus.com/api`;
}

