export function isMenuValid(menu: IMenu, user): boolean {
  return !!menu && !menu?.IsDeleted && !!menu?.Childs && (!!user || !menu.Options?.AuthRequired);
}

export function filterMenusByAuth(menu: IMenu[], user): IMenu[] {
  return menu?.filter((item) => {
    const authRequired = item?.Options?.AuthRequired;
    return (!user && !authRequired) || !!user;
  });
}

export function filterMenusByService(menus: IMenu[], allServices: ISystemService[]): IMenu[] {
  return menus?.filter((menu) => {
    const serviceId = menu?.Options?.ServiceId;
    if (!serviceId) return true;

    const matchedService = allServices?.find((service) => service?.ServiceId === serviceId);
    return matchedService?.IsActive;
  });
}

// Function to strip locale prefix from keys
export const stripLocalePrefix = (obj, locale) => {
  const prefix = `${locale}.`;
  const result = {};
  for (const key in obj) {
    if (key.startsWith(prefix)) {
      result[key.slice(prefix.length)] = obj[key];
    } else {
      result[key] = obj[key];
    }
  }
  return result;
};

export function toBoolean(value): boolean {
  if (typeof value === 'boolean') return value;
  return value?.toLowerCase() === 'true';
}

export function preprocessParams(input: Record<string, string>): Record<string, string[]> {
  const result: Record<string, string[]> = {};

  for (const [key, value] of Object.entries(input)) {
    if (key === 'from') continue;
    if (value && !value?.trim()) continue;

    const parts = value
      ?.split(';')
      ?.map((v) => v?.trim())
      ?.filter(Boolean);
    if (parts?.length) {
      result[key] = parts;
    }
  }

  return result;
}

export function convertToArray(input) {
  if (Array.isArray(input)) return input;
  if (!input) return [];
  return [input];
}
