import { Injectable } from '@angular/core';
import { AuthService } from '@rsApp/modules/auth-v2/providers/auth-v2.service';
import { RegularExpression } from '../constants/constants';
import { Observable, catchError, map, of, switchMap, timer } from 'rxjs';
import { AbstractControl, ValidationErrors } from '@angular/forms';

@Injectable({
  providedIn: 'root',
})
export class PhoneValidator {
  constructor(private authService: AuthService) {}

  private time = 500;

  checkPhoneFormat() {
    return (control: AbstractControl): Observable<ValidationErrors | null> => {
      const phone = control.value;

      if (!phone) {
        return of(null);
      }
      const isPatternPassed = new RegExp(RegularExpression.PhoneNumber).test(phone);
      if (!isPatternPassed) {
        return of({ invalidPhoneFormat: true });
      }

      return of(null);
    };
  }

  phoneValidator(UserID?: string) {
    return (control: AbstractControl): Observable<ValidationErrors | null> => {
      const phone = control.value;

      if (!phone) {
        return of(null); // don't validate empty field
      }

      const isPatternPassed = new RegExp(RegularExpression.PhoneNumber).test(phone);

      if (!isPatternPassed) {
        return of({ invalidPhoneFormat: true });
      }

      // Debounce the request for 500ms
      return timer(this.time).pipe(
        switchMap(() => this.authService.checkPhoneExists(phone.replace(/\D/g, ''), UserID)),
        map((isExists) => (isExists ? { phoneExist: true } : null)),
        catchError(() => of(null))
      );
    };
  }
}
