import {
  Component,
  OnInit,
  OnDestroy,
  Input,
  Output,
  EventEmitter,
  ViewChild,
  NgZone,
  SimpleChanges,
  OnChanges,
} from '@angular/core';
import { Storage } from '@ionic/storage';
import { DEFAULT_LOCALE, LOCAL_LOCALE_KEY } from '@rsApp/modules/utils/constants/constants';
import { AccountManagementSettingKeys } from '@rsApp/modules/utils/models/app-settings.model';
import { AppSettings } from '@rsApp/modules/utils/providers/app-setting';
import { BehaviorSubject, firstValueFrom, Subject, takeUntil, tap } from 'rxjs';
import {
  EnumNotificationType,
  ESubscriptionChannel,
  EValidatePreferences,
  ICampaign,
  IMagDropdownOption,
  ISubscription,
} from '../../model/interface';
import { StoreService } from '@rsApp/modules/store/store.module';
import { IUser } from '@rsApp/modules/interfaces/user.interface';
import { SubscriptionService } from '../../providers/subscription.service';
import { User } from '../../providers/user.service';
import { AccountV2Service } from '../../providers/account-v2.service';
import { ToastService } from '@rsApp/components/toast.service';
import { Credential } from '@rsApp/modules/auth-v2/providers/credential.service';
import { MagAppDialogComponent } from '@rsApp/components/mag-app-dialog/mag-app-dialog';
import { Router } from '@angular/router';
import { enumInternalCode } from '@rsApp/modules/auth-v2/utils/interface';
import { TranslateService } from '@ngx-translate/core';
import { AuthService } from '@rsApp/modules/auth-v2/providers/auth-v2.service';

@Component({
  selector: 'app-mag-weekly-ads-subscription',
  templateUrl: './mag-weekly-ads-subscription.html',
  styleUrls: ['./mag-weekly-ads-subscription.scss'],
})
export class MagWeeklyAdsSubscriptionComponent implements OnInit, OnDestroy, OnChanges {
  @Input() isMyAccountPage: boolean = false;
  @Input() isSubscriptionPage: boolean = false;
  @Input() subscription: {
    Phone?: string;
    Name?: string;
    StoreCode?: string;
    AudienceIds?: string[];
    ReceiveEmail?: boolean;
    ReceiveTextMessage?: boolean;
  } | null = null;
  @Input() set errorSubcriptions(params) {
    if (!params) return;
    const { isErrorSelectedStoreCode, isErrorSelectedCampaign, isErrorSelectedChannel } = params;
    this.isErrorSelectedCampaign = isErrorSelectedCampaign;
    this.isErrorSelectedChannel = isErrorSelectedChannel;
    this.isErrorSelectedStoreCode = isErrorSelectedStoreCode;
  }
  @Input() isDisabled?: boolean = false;
  @Input() campaigns: ICampaign[];

  @Output() setValues = new EventEmitter<{
    selectedChannel: string[];
    selectedCampaign: string[];
    selectedStoreCode: string;
    isSubscribed: boolean;
  }>();

  @ViewChild('dialogThanksModal') dialogThanksModal!: MagAppDialogComponent;
  @ViewChild('dialogCheckPhoneModal') dialogCheckPhoneModal!: MagAppDialogComponent;

  public channelSources: ISubscription[];

  public currentLocale = DEFAULT_LOCALE;
  public storeOptions: IMagDropdownOption[] = [];
  public isSubscribed: boolean = true;
  public currentUser: IUser;
  public selectedStoreCode: string;
  public phoneModalTypes: EnumNotificationType = EnumNotificationType.PreferencesSubscriptionPhone;

  public isErrorSelectedStoreCode: boolean = false;
  public isErrorSelectedCampaign: boolean = false;
  public isErrorSelectedChannel: boolean = false;

  public selectedCampaign: string[] = [];
  public selectedChannel: string[] = [];

  public communicationSettings: any;
  public supportEmail: string = '';
  public isLoading: boolean = false;

  public formatedPhone: string = '';

  private $destroy = new Subject<boolean>();
  private $onSubmit = new BehaviorSubject<{ validate: EValidatePreferences; payload: IUser }>(null);

  instructionText: string;

  constructor(
    public appSettingsService: AppSettings,
    public storage: Storage,
    public router: Router,
    public store: StoreService,
    public subscriptionSvc: SubscriptionService,
    public cre: Credential,
    public userService: User,
    public accountService: AccountV2Service,
    private toastService: ToastService,
    private ngZone: NgZone,
    private translate: TranslateService,
    private authService: AuthService
  ) {
    Promise.all([this.getCurrentLocale(), this.initStoreList(), this.loadSettingAM()]).then(
      // eslint-disable-next-line @typescript-eslint/no-unused-vars
      ([_, __, settings]: [any, any, Record<AccountManagementSettingKeys, string>]) => {
        this.communicationSettings = settings?.communication_setting;
        this.supportEmail = settings?.email_customer_support;
        this.generateSelectedChannel();
        this.setValues.emit({
          selectedCampaign: this.selectedCampaign,
          selectedChannel: this.selectedChannel,
          selectedStoreCode: this.selectedStoreCode,
          isSubscribed: this.isSubscribed,
        });
        this.prepareInstructionText();
      }
    );
  }

  setDataSubscription() {
    const sub = this.subscription;
    if (!sub) return;

    this.selectedStoreCode = sub.StoreCode ? `${sub.StoreCode}` : null;
    this.selectedCampaign = sub.AudienceIds ? [...sub.AudienceIds] : [];

    if (!this.selectedCampaign.length) {
      this.campaigns = (this.campaigns || []).map((c) => ({ ...c, Checked: true }));
      this.selectedCampaign = (this.campaigns || []).map((c) => c.Id);
    } else {
      this.campaigns = (this.campaigns || []).map((c) => ({
        ...c,
        Checked: this.selectedCampaign.includes(c.Id),
      }));
    }

    if (sub.ReceiveEmail || sub.ReceiveTextMessage) {
      this.applyChannelsFromReceivePrefs(sub);
    }

    this.isErrorSelectedChannel = !this.selectedChannel.length;
    this.isErrorSelectedStoreCode = !this.selectedStoreCode;
    this.isErrorSelectedCampaign = !this.selectedCampaign.length;

    this.handleSetValues(false);
  }

  /** Updates channelSources Checked and selectedChannel from ReceiveEmail/ReceiveTextMessage. */
  private applyChannelsFromReceivePrefs(prefs: { ReceiveEmail?: boolean; ReceiveTextMessage?: boolean }): void {
    if (!this.channelSources?.length) {
      this.channelSources = this.transformCommunicationSettings(this.communicationSettings);
    }
    this.channelSources = this.channelSources.map((ch) => ({
      ...ch,
      Checked:
        ch.Name === 'ReceiveEmail'
          ? !!prefs.ReceiveEmail
          : ch.Name === 'ReceiveTextMessage'
            ? !!prefs.ReceiveTextMessage
            : ch.Checked,
    }));
    this.selectedChannel = this.channelSources.filter((ch) => ch.Checked).map((ch) => ch.Name);
  }
  ngOnChanges(changes: SimpleChanges) {
    if (changes['subscription']?.currentValue) {
      this.setDataSubscription();
    }

    if (changes['campaigns']) {
      if (this.subscription) {
        this.setDataSubscription();
      } else if (this.campaigns?.length) {
        this.campaigns = this.campaigns.map((c) => ({ ...c, Checked: true }));
        this.selectedCampaign = this.campaigns.map((c) => c.Id);
      }
    }
  }

  async ngOnInit() {
    this.currentUser = await this.cre.getCurrentUser();

    // Listen update user - start
    this.authService
      .getCurrentUser()
      .pipe(takeUntil(this.$destroy))
      .subscribe((user) => {
        if (!user) return;
        this.currentUser = user;
        const { Phone } = this.currentUser || {};
        this.formatedPhone = this.formatPhone(Phone);
      });
    // Listen update user - end

    await this.loadCurrentUser();
    if (this.currentUser) {
      this.formatedPhone = this.formatPhone(this.currentUser.CellPhone);

      this.selectedStoreCode = this.currentUser.StoreCode;
      this.selectedCampaign = this.currentUser.Subscription?.SubscriptionIds || [];

      this.isSubscribed = this.currentUser?.ReceiveEmail || this.currentUser?.ReceiveTextMessage;
    }

    this.$onSubmit.pipe(takeUntil(this.$destroy)).subscribe(async (params) => {
      if (!params) return;
      const { validate, payload } = params;

      const updateUserInfo = async (): Promise<boolean> => {
        this.isLoading = true;
        try {
          const isUpdated = await firstValueFrom(this.accountService.updateUser(this.currentUser.UserId, payload));
          if (isUpdated) {
            const user = await this.cre.setCurrentUser(payload).then(() => this.cre.getCurrentUser());
            this.currentUser = user;
            this.channelSources = this.updateChannelSources(this.channelSources);
          }
          return isUpdated;
        } catch (error) {
          console.error(error);
          if (error?.InternalCode === enumInternalCode.subscriptionSMS) {
            this.ngZone.run(() => {
              this.phoneModalTypes = EnumNotificationType.SubscriptionResubscribe;
              this.selectedChannel = this.updateSelection(false, 'ReceiveTextMessage', this.selectedChannel);
              this.channelSources = (this.channelSources || []).map((ch) => ({
                ...ch,
                Checked: ch.Name === 'ReceiveTextMessage' ? false : ch.Checked,
              }));
            });
          }
          return false;
        } finally {
          this.isLoading = false;
        }
      };

      const clearErrorsAndUpdate = () => {
        this.isErrorSelectedChannel = false;
        this.isErrorSelectedCampaign = false;
      };

      switch (validate) {
        case EValidatePreferences.REQUIRE_SELECTIONS_CHANNEL:
          this.isErrorSelectedChannel = true;
          this.isErrorSelectedCampaign = false;
          break;
        case EValidatePreferences.REQUIRE_SELECTION_CAMPAIGN:
          this.isErrorSelectedCampaign = true;
          this.isErrorSelectedChannel = false;
          break;
        case EValidatePreferences.REQUIRE_SELECTION_BOTH_FIELDS:
          this.isErrorSelectedChannel = true;
          this.isErrorSelectedCampaign = true;
          break;
        case EValidatePreferences.CHECK_YOUR_PHONE_MODAL:
          clearErrorsAndUpdate();
          await updateUserInfo();
          this.dialogCheckPhoneModal.openDialog();
          break;
        case EValidatePreferences.THANKS_FOR_SUBSCRIBING:
          clearErrorsAndUpdate();
          await updateUserInfo();
          this.dialogThanksModal.openDialog();
          break;
        case EValidatePreferences.SUCCESS:
          clearErrorsAndUpdate();
          await updateUserInfo();
          this.toastService.create({
            message: this.translate.instant('toast.preferenceUpdateSuccess'),
            type: 'success',
          });
          break;
      }
    });

    if (this.subscription) {
      this.setDataSubscription();
      this.formatedPhone = this.formatPhone(this.subscription.Phone);
      this.isSubscribed =
        !!this.subscription.ReceiveEmail || !!this.subscription.ReceiveTextMessage || !!this.subscription.StoreCode;
    }
    if (this.isSubscribed) {
      this.handleSetValues(false);
    }
  }

  ngOnDestroy() {
    this.$destroy.next(true);
  }

  onCloseModalThanksSubscribing() {
    this.dialogThanksModal.closeDialog();
  }

  onCloseModalCheckPhone() {
    this.dialogCheckPhoneModal.closeDialog();
  }

  onNavigateWeeklyAds() {
    this.onCloseModalThanksSubscribing();
    setTimeout(() => {
      this.router.navigate(['/tabs/weekly-ad']);
    }, 300);
  }

  private generateSelectedChannel(): void {
    const channels = this.transformCommunicationSettings(this.communicationSettings);
    this.channelSources = this.updateChannelSources(channels);
    this.selectedChannel = this.channelSources?.filter((ch) => ch.Checked)?.map((ch) => ch.Name) ?? [];
  }

  private updateChannelSources(channels?: ISubscription[]): ISubscription[] {
    return (channels ?? []).map((channel) => {
      let isChecked = Boolean(channel.Checked);
      if (
        this.currentUser &&
        channel.Name in this.currentUser &&
        (this.currentUser?.ReceiveEmail || this.currentUser?.ReceiveTextMessage)
      ) {
        isChecked = this.currentUser[channel.Name] === true;
      }
      return {
        ...channel,
        Checked: isChecked,
      };
    });
  }

  private async loadCurrentUser() {
    if (!this.currentUser) return;
    return await firstValueFrom(
      this.userService.getUserById(this.currentUser?.UserId, true).pipe(
        tap((user: IUser) => {
          this.cre.setCurrentUser(user);
          this.currentUser = user;
        })
      )
    );
  }

  private async loadSettingAM(): Promise<Record<AccountManagementSettingKeys, string>> {
    try {
      return await firstValueFrom(this.appSettingsService.getSettingByPath('ACCOUNT MANAGEMENT'));
    } catch (error) {
      console.error(error);
      return {} as Record<AccountManagementSettingKeys, string>;
    }
  }

  private async getCurrentLocale() {
    const currentLocale = (await this.storage.get(LOCAL_LOCALE_KEY)) || DEFAULT_LOCALE;
    this.currentLocale = currentLocale;
  }

  private capitalizeFirstLetter(text: string): string {
    if (!text) return '';
    return text.charAt(0).toUpperCase() + text.slice(1);
  }

  private transformCommunicationSettings(settings: any): ISubscription[] {
    const cap = this.capitalizeFirstLetter(this.currentLocale);
    return (settings ?? []).map((e: any) => ({
      Name: e.Name,
      Description: e.Description?.[cap] ?? '',
      DisplayName: e.DisplayName?.[cap] ?? '',
      Checked: e.DefaultValue === 'true',
    }));
  }

  private async initStoreList() {
    try {
      const storeList = await firstValueFrom(this.store.searchStores('', ''));
      const mapStores: IMagDropdownOption[] = storeList?.map((store) => ({
        value: store.StoreCode,
        label: [
          store.Name?.trim() || '',
          store.StoreCode ? `#${store.StoreCode}` : '',
          store.Address ? `- ${store.Address}` : '',
        ]
          .filter(Boolean)
          .join(' '),
        description: `${store.Address}, ${store.City}, ${store.State} ${store.ZipCode}`, // optional, for more info
      }));
      this.storeOptions = mapStores;
    } catch (err) {
      console.error('=== get store list err ===', err);
      this.storeOptions = [];
    }
  }

  private updateSelection(value: boolean, itemId: string, selectedList: string[]): string[] {
    if (value) {
      return selectedList.includes(itemId) ? selectedList : [...selectedList, itemId];
    } else {
      return selectedList.filter((id) => id !== itemId);
    }
  }

  private getUserChannels(
    channelSources: ISubscription[],
    currentUser: IUser
  ): Pick<IUser, 'ReceiveEmail' | 'ReceiveTextMessage'> {
    const obj: Pick<IUser, 'ReceiveEmail' | 'ReceiveTextMessage'> = {
      ReceiveEmail: false,
      ReceiveTextMessage: false,
    };
    if (!channelSources.length || !currentUser) return obj;

    channelSources.forEach((e) => {
      obj[e.Name] = currentUser?.[e.Name] || false;
    });
    return obj;
  }

  private validatePreferences(payload: Pick<IUser, 'ReceiveEmail' | 'ReceiveTextMessage'>): EValidatePreferences {
    const defaultUserChannel = this.getUserChannels(this.channelSources ?? [], this.currentUser);
    const unselectToSelectEmail = !defaultUserChannel.ReceiveEmail && payload.ReceiveEmail;
    const unselectToSelectTextMsg = !defaultUserChannel.ReceiveTextMessage && payload.ReceiveTextMessage;

    if (!this.selectedChannel.length && !this.selectedCampaign.length) {
      return EValidatePreferences.REQUIRE_SELECTION_BOTH_FIELDS;
    }

    if (!this.selectedChannel.length && this.selectedCampaign.length) {
      return EValidatePreferences.REQUIRE_SELECTIONS_CHANNEL;
    }

    if (this.selectedChannel.length && !this.selectedCampaign.length) {
      return EValidatePreferences.REQUIRE_SELECTION_CAMPAIGN;
    }

    if (unselectToSelectTextMsg) {
      return EValidatePreferences.CHECK_YOUR_PHONE_MODAL;
    }

    if (unselectToSelectEmail) {
      return EValidatePreferences.THANKS_FOR_SUBSCRIBING;
    }

    return EValidatePreferences.SUCCESS;
  }

  private validateSignUp() {
    this.isErrorSelectedStoreCode = !this.selectedStoreCode;
    this.isErrorSelectedChannel = !this.selectedChannel.length;
    this.isErrorSelectedCampaign = !this.selectedCampaign.length;
  }

  private handleSetValues(isValidate: boolean = true) {
    if (isValidate) this.validateSignUp();
    this.setValues.emit({
      selectedCampaign: this.selectedCampaign,
      selectedChannel: this.selectedChannel,
      selectedStoreCode: this.selectedStoreCode,
      isSubscribed: this.isSubscribed,
    });
  }

  handleChangeStore(event: CustomEvent): void {
    this.selectedStoreCode = event?.detail?.value;
    const campaignIds = (this.campaigns || []).map((c) => c.Id);
    this.selectedCampaign = this.selectedCampaign.filter((id) => campaignIds.includes(id));
    this.campaigns = (this.campaigns || []).map((c) => ({
      ...c,
      Checked: this.selectedCampaign.includes(c.Id),
    }));
    this.handleSetValues();
  }

  onChangeSwitch(event: CustomEvent) {
    const { checked } = event.detail;
    this.isSubscribed = checked;
    this.handleSetValues(false);
    this.isErrorSelectedCampaign = false;
    this.isErrorSelectedChannel = false;
    this.isErrorSelectedStoreCode = false;
  }

  formatPhone(phone: string | null | undefined): string {
    if (!phone) return '';
    const digits = phone.replace(/\D/g, '').slice(0, 10);
    if (digits.length < 10) return phone;

    return `(${digits.slice(0, 3)}) ${digits.slice(3, 6)} ${digits.slice(6, 10)}`;
  }

  handleChangeCheckBoxItem(event: CustomEvent, data: ISubscription | ICampaign, type: string) {
    const value = event.detail;
    if (type === ESubscriptionChannel.Campaign) {
      const { Id } = data as ICampaign;
      this.selectedCampaign = this.updateSelection(value, Id, this.selectedCampaign);
    } else if (type === ESubscriptionChannel.Channel) {
      const { Name } = data as ISubscription;
      this.selectedChannel = this.updateSelection(value, Name, this.selectedChannel);
    }
    this.handleSetValues();
  }

  async onPreferenceSubmit() {
    const channels: Pick<IUser, 'ReceiveEmail' | 'ReceiveTextMessage'> = {
      ReceiveEmail: false,
      ReceiveTextMessage: false,
    };

    if (this.selectedChannel.length) {
      (this.channelSources ?? []).forEach((ch) => {
        channels[ch.Name] = this.selectedChannel.includes(ch.Name);
      });
    }
    if (!this.isSubscribed) {
      channels.ReceiveEmail = false;
      channels.ReceiveTextMessage = false;
    }
    const updateUser: IUser = {
      ...this.currentUser,
      ...channels,
      Subscription: {
        StoreCode: this.selectedStoreCode,
        SubscriptionIds: this.selectedCampaign,
      },
    };
    const validateState = this.validatePreferences(channels);
    this.$onSubmit.next({ validate: validateState, payload: updateUser });
  }

  private prepareInstructionText(): void {
    this.translate
      .get('subscriptions.instructionText')
      .pipe(takeUntil(this.$destroy))
      .subscribe((translatedText) => {
        const supportEmailLink = this.supportEmail
          ? `<a href="mailto:${this.supportEmail}">${this.supportEmail}</a>`
          : '';
        this.instructionText = translatedText.replace('{supportEmail}', supportEmailLink);
      });
  }
}
