import { ICookieConsentProvider } from './cookie-consent.interface';
import { CookieConsentProvider } from './providers/cookieconsent.provider';
import { OneTrustProvider } from './providers/onetrust.provider';
import { CookieConsentConfig, CookieConsentProviderType } from './cookie-consent.type';
import { NoneCookieConsentProvider } from './providers/none.provider';

export class CookieConsentManager {
  private provider: ICookieConsentProvider;
  private static instance: CookieConsentManager | null = null;
  private isInitialized = false;

  constructor(providerType: CookieConsentProviderType, config: CookieConsentConfig) {
    switch (providerType) {
      case 'onetrust':
        this.provider = new OneTrustProvider(config);
        break;
      case 'cookieconsent':
        this.provider = new CookieConsentProvider(config);
        break;
      default:
        this.provider = new NoneCookieConsentProvider();
    }

    CookieConsentManager.instance = this;
  }

  static getInstance(): CookieConsentManager {
    // if (!CookieConsentManager.instance) {
    //   console.error('CookieConsentManager not initialized');
    // }
    return CookieConsentManager.instance;
  }

  initialize(callback: (categories: string[]) => void) {
    if (this.isInitialized) {
      return; // Prevent re-initialization
    }
    this.provider.initialize(callback);
    this.isInitialized = true;
  }

  async waitForInitialization(): Promise<boolean> {
    return this.provider.waitForInitialization();
  }

  hasConsent(category: string, categories: string[], callback: (hasConsent) => void) {
    return this.provider.hasConsent(category, categories, callback);
  }

  onConsentChange(callback: (categories: string[]) => void) {
    this.provider.onConsentChange(callback);
  }

  showPreferences() {
    this.provider.showPreferences();
  }

  removeCookies(categories: string[]) {
    this.provider.removeCookies(categories);
  }

  allowShowPreferences(): boolean {
    return this.provider.allowShowPreferences();
  }
}
