import { Component, OnInit, ViewChild, OnDestroy } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { Storage } from '@ionic/storage';
import { DEFAULT_LOCALE, LOCAL_LOCALE_KEY } from '../../constants/constants';
import { ActionType } from '../../enum/enum';
import { ITenantSettings, ITenantLanguage } from '../../models/app-settings.model';
import { unflatten } from '../../flat';
import { TenantSettingsStore } from '../../providers/tenant-settings.service';
import { MagAppBottomSheetComponent } from '@rsApp/components/mag-app-bottom-sheet/mag-app-bottom-sheet';
import { stripLocalePrefix } from '../../providers/utils';
import { Subject, takeUntil } from 'rxjs';
import merge from 'lodash/merge';

@Component({
  selector: 'switch-language',
  templateUrl: 'switch-language.html',
  styleUrls: ['./switch-language.scss'],
})
export class SwitchLanguageComponent implements OnInit, OnDestroy {
  currentLang: string;
  currentLangLabel: string;
  private _dxpComponentCustomMessages = {};
  private _tenantSettings: ITenantSettings;
  private _destroy$: Subject<boolean> = new Subject();

  selectedValue: string;

  @ViewChild('bottomSheet') bottomSheetComponent!: MagAppBottomSheetComponent;

  listLang: ITenantLanguage[];

  constructor(
    public translateService: TranslateService,
    private storage: Storage,
    public tenantSettingsStore: TenantSettingsStore
  ) {}

  async ngOnInit() {
    this.currentLang = this.translateService.currentLang || DEFAULT_LOCALE;
    this._tenantSettings = await this.tenantSettingsStore.getTenantSettings();
    this.listLang = this._tenantSettings?.languages?.filter((l) => l?.IsEnabled);
    this.setupLanguage();
  }

  ngOnDestroy() {
    this._destroy$.next(true);
    this._destroy$.complete();
  }

  setupLanguage() {
    if (this.currentLang && this.listLang) {
      this.selectedValue = this.currentLang;
      this.currentLangLabel = this.listLang.find((l) => l.Value === this.currentLang)?.Name;
    }
  }

  onSelectionChange(e) {
    if (!e?.detail?.value) return;
    this.selectedValue = e.detail.value;
    this.langChanged(e);
    this.bottomSheetComponent?.closeModal();
  }

  openLanguageSelect() {
    this.bottomSheetComponent?.openModal();
  }

  async langChanged(event: CustomEvent) {
    const newLang = event?.detail?.value;

    // Same language or no language selected, return
    if (this.currentLang === newLang || !newLang) return;

    // Update the current language
    this.currentLang = newLang;
    this.setupLanguage();

    // Update the current language in the storage
    await this.storage.set(LOCAL_LOCALE_KEY, newLang);

    // Get the language object
    const lang = this._tenantSettings?.languages?.find((l) => l.Value === newLang);

    // Update the translations
    const platformMsgs = unflatten(lang.CustomMessages?.platform);
    this.translateService.setTranslation(newLang, platformMsgs, true);

    this.translateService
      .getTranslation(newLang)
      .pipe(takeUntil(this._destroy$))
      .subscribe((existingTranslations) => {
        // Deep merge existing translations with custom ones
        const merged = merge({}, existingTranslations, platformMsgs);
        // Set the merged translations
        this.translateService.setTranslation(newLang, merged, false); // false = replace existing
        // Set new language
        this.translateService.use(newLang);
      });

    this._dxpComponentCustomMessages = lang.CustomMessages?.dxpComponent;
    const normailizeDxpComponentCustomMessages = stripLocalePrefix(this._dxpComponentCustomMessages, this.currentLang);

    // Post message to dxp component
    const payload = {
      action: ActionType.MagOnChangeLocale,
      data: { Locale: newLang, CustomMessages: normailizeDxpComponentCustomMessages || {} },
    };
    window.postMessage({ ...payload }, window.location.origin);
  }
}
