import { HttpClient } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { ENV } from '@app/env';
import { Platform } from '@ionic/angular';
import { Storage } from '@ionic/storage-angular';
import { EnumAppSettings } from '@rsApp/modules/utils/enum/enum';
import { ITenantSettingsRes } from '@rsApp/modules/utils/models/app-settings.model';
import { Observable, from, of, throwError } from 'rxjs';
import { catchError, finalize, map, shareReplay, switchMap } from 'rxjs/operators';
import { EnvironmentImpl } from './environment';
import { Router } from '@angular/router';

type TenantSettingSnapshot = {
  TenantId: number;
  SiteCode: string;
  TenantCode: string;
  DefaultLocale: string;
};

export type DynamicEnvironmentSettings = {
  firebaseConfig: any;
  googleMapAndroidKey: string;
  googleMapIosKey: string;
  googleMapBrowserKey: string;
  appBundle: string;
  tenantId: number;
  tenantCode: string;
  siteCode: string;
};

@Injectable({
  providedIn: 'root',
})
export class EnvironmentService {
  private env: EnvironmentImpl | null = null;
  private cacheKey = 'rs-environment';
  private loading$: Observable<EnvironmentImpl> | null = null;

  // List of required environment variables
  private readonly requiredVariables: (keyof EnvironmentImpl)[] = [
    'production',
    'SiteEnv',
    'TenantId',
    'TenantCode',
    'SiteCode',
    'APIComsumerKey',
    'APIUserName',
    'APIPassword',
    'CoreAPI',
    'DXPCoreAPI',
    'SettingAPI',
    'IdentityAPIUrl',
    'APIDistributionCore',
    'PuppeteerAPIUrl',
    'EcomCentralAPIURL',
    'EComBagAPIURL',
    'EComOrderAPIURL',
    'EComOrderAPIV2URL',
    'EComProductAPIURL',
    'EComProductAPIV2URL',
    'EComRecipeAPIV2URL',
    'EComOfferAPIV2URL',
    'EComDXPageAPIURL',
    'EComStoreAPIURL',
    'EComRewardAPIURL',
    'SmartConnectPickupAPIURL',
    'SCAdsAPIUrl',
    'CMSUrl',
    'ScriptUrl',
    'HostedpagePaymentProvider',
    'DxpCoreOfferAPI',
    'DxpCoreCouponAPI',
    'IndentityAPI',
    'DigitalEditionURL',
    'AppBundle',
    'firebaseConfig',
    'GOOGLE_MAPS_ANDROID_API_KEY',
    'GOOGLE_MAPS_IOS_API_KEY',
    'GOOGLE_MAPS_BROWSER_API_KEY',
    'LogLevel',
  ];

  constructor(
    private platform: Platform,
    private http: HttpClient,
    private storage: Storage,
    public router: Router
  ) {
    this.initStorage();
  }

  // Initialize Ionic Storage
  private async initStorage() {
    await this.storage.create();
  }

  // Get the already-loaded environment synchronously
  getLoadedEnvironment(): EnvironmentImpl {
    if (!this.env) {
      throw new Error('Environment not loaded. Ensure APP_INITIALIZER has completed.');
    }
    return this.env;
  }

  // Validate environment variables and log warnings for missing ones
  private validateEnvironment(env: EnvironmentImpl): void {
    const missingVariables: string[] = [];
    for (const key of this.requiredVariables) {
      const value = env[key];
      if (value === undefined || value === null || value === '') {
        missingVariables.push(key);
      }
    }
    if (missingVariables.length > 0) {
      console.warn('Missing or undefined environment variables:', missingVariables);
    }
  }

  // Load environment variables based on platform
  loadEnvironment(): Observable<EnvironmentImpl> {
    if (this.env) {
      return of(this.env);
    }

    if (this.loading$) {
      return this.loading$;
    }
    const isLocalhost = window.location.hostname === 'localhost';
    if (this.platform.is('hybrid') || isLocalhost) {
      // Native platform: Use process.env
      const env = this.createEnvironmentFromProcess();
      this.validateEnvironment(env);
      this.env = env;
      this.setAppDynamicTenantSettings();
      // Wrap in a shared observable for consistency with web branch
      this.loading$ = of(this.env).pipe(
        finalize(() => (this.loading$ = null)),
        shareReplay(1)
      );
      return this.loading$;
    } else {
      // Web platform: Check localStorage, then API
      this.loading$ = from(this.storage.get(this.cacheKey)).pipe(
        switchMap((cachedEnv: any) => {
          if (cachedEnv) {
            this.env = this.createEnvironmentFromObject(cachedEnv);
            this.validateEnvironment(this.env);
            this.setAppDynamicTenantSettings();
            return of(this.env);
          }
          return this.fetchEnvironmentFromApi().pipe(
            catchError((err) => {
              this.router.navigateByUrl('/maintenance');
              return throwError(() => err);
            })
          );
        }),
        finalize(() => (this.loading$ = null)),
        shareReplay(1)
      );
      return this.loading$;
    }
  }

  // Create environment object from process.env
  private createEnvironmentFromProcess(): EnvironmentImpl {
    const env = new EnvironmentImpl();
    env.firebaseConfig = env.firebaseConfig['PROJECT']; // Becareful with this, it's a hack to get the project id
    this.env = env;
    return env;
  }

  // Create environment object from API response or localStorage
  private createEnvironmentFromObject(data: any): EnvironmentImpl {
    const env = new EnvironmentImpl();

    // Dynamic data
    env.TenantId = data.TenantId;
    env.TenantCode = data.TenantCode;
    env.SiteCode = data.SiteCode;
    env.AppBundle = data.AppBundle;
    env.firebaseConfig = data.firebaseConfig;
    env.GOOGLE_MAPS_ANDROID_API_KEY = data.googleMapAndroidKey;
    env.GOOGLE_MAPS_IOS_API_KEY = data.googleMapIosKey;
    env.GOOGLE_MAPS_BROWSER_API_KEY = data.googleMapBrowserKey;

    return env;
  }

  // Set app dynamic tenant settings to window object
  private setAppDynamicTenantSettings() {
    try {
      if (typeof (window as any) === 'undefined') return;
      (window as any).TenantId = this.env.TenantId;
      (window as any).TenantCode = this.env.TenantCode;
      (window as any).SiteCode = this.env.SiteCode;
    } catch (error) {
      console.error(error);
    }
  }

  // Fetch environment variables from API and store in localStorage
  private fetchEnvironmentFromApi(): Observable<EnvironmentImpl> {
    const hostname = window.location.hostname;
    return this.http.get(`${ENV.TenantAPI}/TenantSetting/get-by-domain/${encodeURIComponent(hostname)}`).pipe(
      switchMap((tenantData: TenantSettingSnapshot) => {
        const { TenantId, SiteCode, TenantCode } = tenantData;
        const settingsApiUrl = `${ENV.TenantAPI}/TenantSetting/GetTenantSettingBySiteCode?name=${EnumAppSettings.Name}&platform=${EnumAppSettings.Platform}&tenantId=${TenantId}&siteCode=${SiteCode}`;
        return this.http.get(settingsApiUrl).pipe(
          map((settingsData: ITenantSettingsRes) => {
            const settings: any = {};
            if (settingsData.MobileEnvSettings) {
              const mobileEnvSettings = JSON.parse(settingsData.MobileEnvSettings);
              settings.firebaseConfig = mobileEnvSettings.firebase ? JSON.parse(mobileEnvSettings.firebase) : {};

              if (mobileEnvSettings.googleMaps) {
                settings.googleMapAndroidKey = mobileEnvSettings.googleMaps.android;
                settings.googleMapIosKey = mobileEnvSettings.googleMaps.ios;
                settings.googleMapBrowserKey = mobileEnvSettings.googleMaps.browser;
              }

              if (mobileEnvSettings.appBundle) {
                if (this.platform.is('ios')) {
                  settings.AppBundle = mobileEnvSettings.appBundle.ios;
                } else if (this.platform.is('android')) {
                  settings.AppBundle = mobileEnvSettings.appBundle.android;
                }
              }
            }
            const combinedData = {
              ...settingsData,
              TenantId,
              SiteCode,
              TenantCode,
              ...settings,
            };
            this.storage.set(this.cacheKey, combinedData);
            this.env = this.createEnvironmentFromObject(combinedData);
            this.validateEnvironment(this.env);
            this.setAppDynamicTenantSettings();
            return this.env;
          })
        );
      })
    );
  }

  getEnvironment(): Observable<EnvironmentImpl> {
    return this.loadEnvironment();
  }

  // Get dynamic environment settings (can be used in components)
  getDynamicEnvironment(): Observable<DynamicEnvironmentSettings> {
    return this.loadEnvironment().pipe(
      map((env: EnvironmentImpl) => ({
        firebaseConfig: env.firebaseConfig,
        googleMapAndroidKey: env.GOOGLE_MAPS_ANDROID_API_KEY,
        googleMapIosKey: env.GOOGLE_MAPS_IOS_API_KEY,
        googleMapBrowserKey: env.GOOGLE_MAPS_BROWSER_API_KEY,
        appBundle: env.AppBundle,
        tenantId: env.TenantId,
        tenantCode: env.TenantCode,
        siteCode: env.SiteCode,
      }))
    );
  }
}
