import { Inject, Injectable } from '@angular/core';
import { Credential } from '@rsApp/modules/auth-v2/providers/credential.service';
import { MagEComCoreApiHttpClient } from '@rsApp/modules/gateway/mag-ecom-core-api.service';
import { IStore, IStoreService, ISystemService, TSystemAttribute } from '@rsApp/modules/interfaces/store.interface';
import { cacheErrorHandle, Utils } from '@rsApp/modules/utils/providers/utils';
import { CacheService } from 'ionic-cache';
import { firstValueFrom, of, ReplaySubject } from 'rxjs';
import { catchError } from 'rxjs/operators';
import { STORE_HTTP_CLIENT } from '../store.config';
import { DEFAULT_SHOP_PATH, isAttValueTrue, IStoreNearByPayload } from '../utils';
import { StoreService } from './store.service';
import { User } from '@rsApp/modules/account-v2/providers/user.service';
import { ActionType } from '@rsApp/modules/utils/enum/enum';

@Injectable({
  providedIn: 'root',
})
export class CurrentStore {
  public cacheKey = 'cache-currentStore';
  public store: IStore;
  public store$: ReplaySubject<any>;
  public currentSystemService: ISystemService;
  public currentShopPath: string;
  public allServices: ISystemService[] = [];

  constructor(
    @Inject(STORE_HTTP_CLIENT) private storeApi: MagEComCoreApiHttpClient,
    private cache: CacheService,
    private cre: Credential,
    private storeService: StoreService,
    public utils: Utils,
    private userService: User
  ) {
    this.store$ = <ReplaySubject<any>>new ReplaySubject(1);
  }

  async init() {
    if (this.store) return;
    await this.setStore(await this.getStore());
  }

  public storeState() {
    return this.store$.asObservable();
  }

  public async getStore(): Promise<IStore> {
    try {
      const store = await this.cache.getItem(this.cacheKey).catch(cacheErrorHandle);
      if (store) return store;
    } catch (error) {
      console.warn('Failed to get store from cache', error);
      return null;
    }
  }

  public async setStore(store: IStore, shopPath?: string) {
    this.store = store;
    if (!store) {
      this.cache.removeItem(this.cacheKey);
    } else {
      this.setCurrentSystemServiceAndShopPath(store, shopPath);
      this.cache.saveItem(this.cacheKey, store, undefined, 60 * 60 * 12 * 15);
    }
    this.store$.next(store);
  }

  public async updateStoreForUser(store: IStore, shopPath?: string) {
    try {
      const user = await this.cre.getCurrentUser();
      if (!user) return;
      const needUpdate = store.StoreCode !== user.StoreCode || shopPath !== user.ShopPath;
      if (!needUpdate) return;
      const result = await firstValueFrom(this.userService.setStore(store, user, shopPath));
      if (!result) return;
      await firstValueFrom(this.userService.refreshCurrentUser(user?.UserId));
    } catch (error) {
      console.warn('Failed to update store for user', error);
    }
  }

  public getDefaultSystemService(store: IStore, allService: ISystemService[]) {
    try {
      let defaultSystemService: ISystemService = null;
      const storeService = store?.StoreServices;
      const defaultStoreService = storeService?.find((ser: IStoreService) => {
        const settingAtts = ser.SettingAttributes as TSystemAttribute;
        return isAttValueTrue(settingAtts?.is_default_shop_path?.Value);
      });

      defaultSystemService = allService?.find((ser) => {
        return defaultStoreService
          ? ser?.ServiceId === defaultStoreService?.ServiceId
          : ser?.ServiceId === storeService[0]?.ServiceId;
      });

      return defaultSystemService;
    } catch (error) {
      console.warn('Failed to get default system service', error);
      return null;
    }
  }

  public async setCurrentSystemServiceAndShopPath(store: IStore, shopPath?: string) {
    try {
      let systemService: ISystemService = null;
      const allService = await firstValueFrom(this.storeService.getStoreSystemServices());
      this.allServices = allService;
      const storeServices = store?.StoreServices;
      if (!allService?.length || !storeServices?.length) return;

      if (shopPath) {
        const storeService = storeServices.find((ser) => {
          const Attributes = ser?.SettingAttributes as TSystemAttribute;
          return Attributes?.shop_path?.Value === shopPath;
        });
        systemService = allService.find((ser) => ser?.ServiceId === storeService?.ServiceId);
      } else {
        systemService = this.getDefaultSystemService(store, allService);
      }
      if (!systemService) return;
      this.currentSystemService = systemService;
      this.currentShopPath = systemService.SettingAttributes?.shop_path?.Value || DEFAULT_SHOP_PATH;
      this.updateStoreForUser(store, this.currentShopPath);
    } catch (error) {
      console.warn('Failed to set current system service and shop path', error);
    }
  }

  public async autoAssignStore() {
    try {
      const [currentUserPosition, user] = await Promise.all([
        this.utils.getCurrentPosition(),
        this.cre.getCurrentUser(),
      ]);

      const storeParams: IStoreNearByPayload = {
        latitude: currentUserPosition?.isLocationOn ? currentUserPosition?.lat : null,
        longitude: currentUserPosition?.isLocationOn ? currentUserPosition?.lng : null,
        zipcode: '',
      };

      // Prevent undefined when getCurrentPosition throw error data
      // Only call get ZipCode or IP API if GPS not available and isLocationOn false
      if (currentUserPosition?.isLocationOn === false) {
        if (user?.ZipCode) {
          storeParams.zipcode = user.ZipCode;
        } else {
          const { location } = await this.utils.getLatLngFromIpAddress();
          const payload = {
            action: ActionType.MagInitPlatformGeoIp,
            data: {
              PlatformGeoIpLocation: {
                lat: location?.lat,
                lng: location?.lng,
              },
            },
          };
          window.postMessage({ ...payload }, window.location.origin);
          storeParams.latitude = location?.lat ?? null;
          storeParams.longitude = location?.lng ?? null;
        }
      }

      let store: IStore;
      store = await firstValueFrom(this.storeService.getStoreNearBy(storeParams));
      if (!store?.StoreId) {
        const storeList = await firstValueFrom(this.storeService.searchStoreList());
        if (storeList.length > 0) {
          store = storeList[0];
        } else {
          console.warn('No stores found from fallback search');
          return;
        }
      }
      // save system service, shop path, current store
      await this.setStore(store);
      return store;
    } catch (error) {
      console.warn('Failed to auto assign store', error);
      return null;
    }
  }

  public async setStoreByStoreCode(storeCode: string, shopPath?: string) {
    try {
      if (!storeCode) return;
      const store = await firstValueFrom(this.storeService.getStoreByCode(storeCode));
      if (!store) return;
      const resultShopPath = shopPath ?? this.currentShopPath;
      await this.setStore(store, resultShopPath);
    } catch (error) {
      console.warn('Failed to set store by store code', error);
    }
  }

  isEcom() {
    return this.store && this.currentShopPath !== 'InStore' && this.currentShopPath !== 'MakeAList';
  }

  isShowDeptFilter() {
    return this.store && this.store.ShowDeptFilter;
  }

  getDetailConfigByCurrentStore(store: IStore, key) {
    const seq = this.storeApi
      .get(`/Config/${store.StoreId}/${store.Provider.Id}/${this.currentSystemService.ServiceId}/${key}`)
      .pipe(
        catchError(() => {
          return of(null);
        })
      );
    return seq;
  }

  // Find store for user when sign up
  async findUserNearByStore(zipCode: string | number) {
    try {
      const currentUserPosition = await this.utils.getCurrentPosition();
      const { isLocationOn, lat, lng } = currentUserPosition || {};

      const storeParams: IStoreNearByPayload = {
        latitude: isLocationOn ? lat : null,
        longitude: isLocationOn ? lng : null,
        zipcode: zipCode || null,
      };

      const nearestStore = await firstValueFrom(this.storeService.getStoreNearBy(storeParams));

      if (nearestStore?.StoreCode) {
        return nearestStore;
      }
      const fallbackStores = await firstValueFrom(this.storeService.searchStoreList());
      return fallbackStores?.[0] || null;
    } catch (error) {
      console.warn('Error findUserNearByStore when sign up', error);
      return null;
    }
  }
}
