import { Component, EventEmitter, Input, OnInit, Output, OnDestroy } from '@angular/core';
import { Router } from '@angular/router';
import { AbstractControl, FormBuilder, FormGroup, Validators } from '@angular/forms';
import { MaskitoOptions, maskitoTransform } from '@maskito/core';
import { Credential } from '@rsApp/modules/auth-v2/providers/credential.service';
import { PhoneValidator } from '@rsApp/modules/utils/validator/phone-validator-v2';
import { ModalController, NavController } from '@ionic/angular';
import { VerificationType, VerificationMethod } from '@rsApp/modules/auth-v2/utils/enum';
import { firstValueFrom, Subject, takeUntil } from 'rxjs';
import { AuthService } from '../../providers/auth-v2.service';
import { IUser } from '@rsApp/modules/interfaces/user.interface';
import { UserOtpVerificationRequest } from '../../utils/interface';
import { ITenantSettings } from '@rsApp/modules/utils/models/app-settings.model';
import { TranslateService } from '@ngx-translate/core';
import { TenantSettingsStore } from '@rsApp/modules/utils/providers/tenant-settings.service';
import { ErrorHandler } from '@rsApp/modules/utils/providers/error-handler.service';
import { EventBusService } from '@rsApp/modules/utils/providers/event-bus.service';
@Component({
  selector: 'enter-phone-component',
  templateUrl: 'enter-phone-component.html',
  styleUrls: ['./enter-phone-component.scss'],
})
export class EnterMobileFormComponent implements OnInit, OnDestroy {
  @Input() showInfoBanner?: boolean = false;
  @Input() description?: string = '';
  @Input() valuePhone?: string = '';
  @Input() phoneNumber?: AbstractControl;
  @Input() isModal: boolean = false;
  @Input() methodSelectedVerify: string;

  @Output() requestOtp = new EventEmitter<{ cellPhone?: string; methodSelected?: string; status?: boolean }>();

  phoneControl: AbstractControl;
  methodSelected: string = VerificationType.Sms;
  isLoading: boolean = false;
  user: IUser;
  detailInfomation: FormGroup;
  phoneMask: MaskitoOptions;

  private tenantSettings: ITenantSettings;
  private destroy$ = new Subject<void>();

  listMethod = [
    { name: VerificationMethod.Sms, value: VerificationType.Sms },
    { name: VerificationMethod.Call, value: VerificationType.Call },
  ];

  constructor(
    public router: Router,
    public modalCtrl: ModalController,
    public tenantSettingsStore: TenantSettingsStore,
    private fb: FormBuilder,
    private cre: Credential,
    private phoneValidator: PhoneValidator,
    private navCtrl: NavController,
    private authService: AuthService,
    private translate: TranslateService,
    public errorHandler: ErrorHandler,
    private eventBus: EventBusService
  ) {
    this.detailInfomation = this.fb.group({
      phone: ['', Validators.required],
    });
  }

  async ngOnInit() {
    if (this.phoneNumber) {
      this.phoneControl = this.phoneNumber;
    } else {
      this.detailInfomation = this.fb.group({
        phone: ['', Validators.required],
      });
      this.phoneControl = this.detailInfomation.get('phone');
    }

    this.tenantSettings = await this.tenantSettingsStore.getTenantSettings();
    this.user = (await this.getUser()) as IUser;
    this.getForm();
    this.setupPhoneValidation();
    this.eventBus
      .on('sms')
      .pipe(takeUntil(this.destroy$))
      .subscribe((event) => {
        this.methodSelected = event?.name;
      });
  }

  private setupPhoneValidation(): void {
    const phoneControl = this.detailInfomation.get('phone');
    const userId = this.user?.UserId;

    phoneControl?.clearValidators();
    phoneControl?.clearAsyncValidators();

    phoneControl?.setValidators([Validators.required]);
    phoneControl?.setAsyncValidators([this.phoneValidator.phoneValidator(userId)]);
  }

  async getForm() {
    if (!this.user) return;
    const maskedPhone = maskitoTransform(
      { value: this.user?.Phone, selection: [this.user?.Phone?.length, this.user?.Phone?.length] },
      this.phoneMask
    ).value;

    this.detailInfomation.patchValue({
      phone: maskedPhone || this.user?.Phone || '',
    });
  }

  async getUser() {
    return await firstValueFrom(this.authService.getUserByEmail(this.cre.currentUser?.Email));
  }

  goBack() {
    this.router.navigate(['/sign-in']);
  }

  onSelectionChange(e) {
    if (!e?.detail?.value) return;
    this.methodSelected = e.detail.value;
  }

  translateText(txt: string, contactLink: string = '') {
    return this.translate.instant(txt, { link: contactLink });
  }

  async handleReceiveOTP() {
    if (!this.phoneControl.valid) return;
    this.isLoading = true;
    try {
      if (!this.isModal) {
        const payload = {
          cellPhone: this.phoneControl?.value,
          methodSelected: this.methodSelected,
        };

        const tenantId = this.tenantSettings?.bannerId;
        const { Phone } = (await this.getUser()) as IUser;
        const params = {
          Channel: this.methodSelected,
          BannerId: tenantId,
          Contact: Phone,
          NewContact: this.phoneControl?.value?.replace(/\D/g, ''),
        } as UserOtpVerificationRequest;
        const result = await firstValueFrom(this.authService.sendOtpByChanel(params));
        if (!result || result.Status === false) {
          this.isLoading = false;
          return this.errorHandler.handleErrorWithCode(result);
        }
        this.isLoading = false;
        this.navCtrl.navigateRoot(['/verify-phone'], {
          state: payload,
        });
      } else {
        const tenantId = this.tenantSettings?.bannerId;
        const params = {
          BannerId: tenantId,
          Channel: this.methodSelected as VerificationType,
          Contact: this.valuePhone.replace(/\D/g, ''),
        } as UserOtpVerificationRequest;

        const result = await firstValueFrom(this.authService.sendOtpByChanelUpdateAccount(params));
        if (!result || result.Status === false) {
          // status return false will emit close modal
          this.isModal && this.requestOtp.emit({ status: false });
          this.isLoading = false;
          return this.errorHandler.handleErrorWithCode(result);
        }
        this.isLoading = false;
        this.requestOtp.emit({ status: true, methodSelected: params.Channel });
      }
    } catch (error) {
      console.warn('OTP request failed:', error);
    }
  }

  ngOnDestroy() {
    this.destroy$.next();
    this.destroy$.complete(); // Proper cleanup of subscriptions
  }
}
