  private async loadDynamicEnvironment() {
    try {
      await firstValueFrom(this.environmentService.getDynamicEnvironment());
    } catch (error) {
      console.warn('Failed to load dynamic environment in AppSettings service:', error);
    }
  }

  async loadScriptDxpComponent() {
    try {
      this.appSettings.getSettingValue('DXP_COMPONENT_BUILD_NUMBER_APP').subscribe(async (settingValue) => {
        if (!settingValue || typeof settingValue !== 'string') {
          console.warn('DXP_COMPONENT_BUILD_NUMBER_APP is not set');
          return;
        }

        const settingBuildNumber = JSON.parse(settingValue);
        const buildNumber = settingBuildNumber[ENV.AppVersion] || settingBuildNumber['stable'];
        if (!buildNumber) {
          console.warn('DXP_COMPONENT_BUILD_NUMBER_APP is invalid');
          return;
        }

        // Ensure dynamic environment is loaded before init dxp component
        if (!(window as any)?.TenantId) {
          await this.loadDynamicEnvironment();
        }

        this.initScriptDxpComponent(buildNumber);
      });
    } catch (error) {
      console.error('loadScriptDxpComponent error: ', error);
    }
  }

  public initScriptDxpComponent(buildNumber: string) {
    const node = document.createElement('script'); // creates the script tag
    node.src = `${ENV.ScriptUrl}/dxp/dxp-component${buildNumber}/dxp-component.esm.js`; // sets the source (insert url in between quotes)
    // node.src = `http://localhost:3333/build/dxp-component.esm.js`;

    node.type = 'module'; // set the script type
    node.async = true; // makes script run asynchronously
    node.charset = 'utf-8';
    // append to head of document
    document.getElementsByTagName('head')[0].appendChild(node);

    //Google Analytic gtag.js
    const gtagScriptInit = document.createElement('script');
    gtagScriptInit.async = true;
    gtagScriptInit.src = `https://www.googletagmanager.com/gtag/js?id=${ENV.GoogleAnalyticsTagID}`;
    document.getElementsByTagName('head')[0].appendChild(gtagScriptInit);

    const gtagScript = document.createElement('script');
    gtagScript.textContent =
      `window.dataLayer = window.dataLayer || [];` +
      `function gtag() { dataLayer.push(arguments) };` +
      `gtag('js', new Date());` +
      `gtag('config', '${ENV.GoogleAnalyticsTagID}', {
        send_page_view: false
      });`;
    document.getElementsByTagName('head')[0].appendChild(gtagScript);

    const link = document.createElement('link');
    link.href = `${ENV.ScriptUrl}/dxp/dxp-component${buildNumber}/dxp-component.css`;
    // link.href = `http://localhost:3333/build/dxp-component.css`;
    link.rel = 'stylesheet';
    document.getElementsByTagName('head')[0].appendChild(link);
  }

  async initializeDxpComponent(
    {
      user,
      store,
      cre,
      currentShoppingList,
    }: {
      user: IUser;
      store: IStore;
      cre: any;
      currentShoppingList: any;
      customMessages?: any;
    },
    tenantSettings: ITenantSettings
  ) {
    const currentLocale = this.translate.currentLang || (await this.storage.get(LOCAL_LOCALE_KEY)) || DEFAULT_LOCALE;
    customElements.whenDefined('dxp-widget').then(() => {
      const data: {
        CurrentUser: IUser;
        CurrentShopPath: string;
        CurrentStore: IStore;
        CurrentShoppingList: any;
        CurrentShoppingListId: any;
        CurrentShoppingCart: any;
        AllServices: ISystemService[];
        ViewMode: string;
        Authorization: string;
        IsApp: boolean;
        IsNativePlatform: boolean;
        TenantSettings: ITenantSettings;
        RefreshToken: string;
        CurrentCustomService: ICurrentCustomService;
        Source: string;
        Locale: string;
        TrackingCode: string;
      } = {
        CurrentUser: user || null,
        CurrentShopPath: this.cStore?.currentShopPath || null,
        CurrentStore: store || null,
        CurrentCustomService: {
          SystemServiceId: this.cStore?.currentSystemService?.ServiceId,
          SystemService: this.cStore?.currentSystemService,
        },
        AllServices: this.cStore?.allServices || [],
        CurrentShoppingList: currentShoppingList,
        CurrentShoppingListId: currentShoppingList ? currentShoppingList.CS_UserShoppingListId : null,
        CurrentShoppingCart: null,
        ViewMode: 'Mobile',
        Authorization: cre ? 'Bearer ' + cre.rsApiToken : '',
        RefreshToken: cre ? cre.refreshToken : '',
        IsApp: true,
        IsNativePlatform: Capacitor.isNativePlatform(),
        TenantSettings: tenantSettings,
        Source: 'Mobile',
        TrackingCode: ENV.TrackingCode || 'Mobile',
        Locale: currentLocale,
      };
      const payload = {
        action: 'initializeDXPComponent',
        data: data,
      };
      //pass data to dxp component
      window.postMessage({ ...payload }, window.location.origin);
    });
  }

