import { Component, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { ModalController, NavController } from '@ionic/angular';
import { TranslateService } from '@ngx-translate/core';
import { AuthService } from '@rsApp/modules/auth-v2/providers/auth-v2.service';
import { Credential } from '@rsApp/modules/auth-v2/providers/credential.service';
import { ITenantSettings } from '@rsApp/modules/utils/models/app-settings.model';
import { AppSettings } from '@rsApp/modules/utils/providers/app-setting';
import { TenantSettingsStore } from '@rsApp/modules/utils/providers/tenant-settings.service';
import { firstValueFrom } from 'rxjs';
import { User } from '../../providers/user.service';
import { IMagToastOptions } from '@rsApp/components/interface';
import { ToastService } from '@rsApp/components/toast.service';

@Component({
  selector: 'mag-account-order',
  templateUrl: './mag-account-order.html',
  styleUrls: ['./mag-account-order.scss'],
})
export class MagAccountOrderComponent implements OnInit {
  // Reactive form to confirm delete action
  confirmOrder: FormGroup;
  tenantSettings: ITenantSettings;
  isLoading: boolean = false;
  hasActiveOrder: boolean = false;

  txtConfirm: string = 'YES';
  hotlineSupport: string = '';
  deleteAccountTime: string = '30';

  private readonly ACCOUNT_PATH = 'ACCOUNT MANAGEMENT';

  openOrderDeactivationNotices: string[] = [];
  nonOpenOrderDeactivationNotices: string[] = [];
  notices: string[] = [];

  constructor(
    private translate: TranslateService,
    private fb: FormBuilder,
    private modalCtrl: ModalController,
    private authService: AuthService,
    public cre: Credential,
    private tenantSettingsStore: TenantSettingsStore,
    private navCtrl: NavController,
    private userService: User,
    public appSettingsService: AppSettings,
    private toastService: ToastService
  ) {
    this.confirmOrder = this.fb.group({
      confirm: ['', Validators.required],
    });
  }
  async ngOnInit() {
    const [appSetting, hasActiveOrder] = await Promise.all([
      this.tenantSettingsStore.getTenantSettings(),
      firstValueFrom(this.userService.checkActiveOrder(this.cre?.currentUser?.UserId)),
      this.loadWBSettings(),
    ]);
    this.tenantSettings = appSetting;
    this.hasActiveOrder = hasActiveOrder as boolean;
    this.setupNotices(this.hasActiveOrder, this.deleteAccountTime);
  }

  setupNotices(hasActiveOrder: boolean, deleteAccountTime: string) {
    const openOrderDeactivationNotices = [
      this.translate.instant('accountInfo.YourOpenOrdersWill'),
      this.translate.instant('accountInfo.yourAccountWillBe'),
      this.translate.instant('accountInfo.youWillBe'),
      this.translate.instant('accountInfo.deleteAccountAfterOrders', { deleteAccountTime }),
    ];

    const nonOpenOrderDeactivationNotices = [
      this.translate.instant('accountInfo.yourAccountWillBe'),
      this.translate.instant('accountInfo.youWillBe'),
      this.translate.instant('accountInfo.loseAccessWarning'),
    ];

    this.notices = hasActiveOrder ? openOrderDeactivationNotices : nonOpenOrderDeactivationNotices;
  }

  async loadWBSettings() {
    const rs = await firstValueFrom(this.appSettingsService.getSettingByPath(this.ACCOUNT_PATH));

    this.txtConfirm = rs['delete_account_confirm_text'] || 'YES';
    this.hotlineSupport = rs['hotline_phone_customer_support'] || '';
    this.deleteAccountTime = rs['delete_account_after_days'] || '';
  }

  /**
   * Closes the modal without performing delete
   */
  close(): void {
    this.modalCtrl.dismiss();
  }

  /**
   * Handles the account delete action if the form is valid
   */
  async onDeleteAccount() {
    const toastDeletedAccount: IMagToastOptions = {
      message: this.translate.instant('toast.deletedAccount'),
      type: 'success',
    };
    const toastDeletedAccountFail: IMagToastOptions = {
      message: 'Your account cannot be deleted at this time. Please try again later.', //TODO translate
      type: 'error',
    };
    const confirm: string = this.confirmOrder.value.confirm;
    if ((confirm && confirm.trim()) !== this.txtConfirm) {
      const controls = this.confirmOrder.get('confirm');
      controls.setErrors({ invalidConfirmText: true });
      return;
    }
    this.isLoading = true;
    const isDelete = await this.handleDelete();
    if (isDelete) {
      await this.authService.logout();
      this.toastService.create(toastDeletedAccount);

      this.isLoading = false;
      this.modalCtrl.dismiss(true);
      this.navCtrl.navigateRoot(['/sign-in']);
    } else {
      this.toastService.create(toastDeletedAccountFail);
      this.isLoading = false;
    }
  }

  async handleDelete() {
    try {
      return await firstValueFrom(
        this.authService.deleteAccount(this.cre.currentUser.UserId, this.tenantSettings?.bannerId)
      );
    } catch (error) {
      console.warn(error);
    }
  }
}
