import { Injectable } from '@angular/core';
import { RelationshopCoreHttpClient } from '@rsApp/modules/gateway/rs-api-core.service';
import { catchError, Observable, of, throwError } from 'rxjs';
import {
  IChangePasswordPayload,
  IUpdateEmailPrefPayload,
  IUpdateOrganizationStatusPayload,
  IUpdateUserPayload,
} from '../utils/enum';
import { enumInternalCode } from '@rsApp/modules/auth-v2/utils/interface';
import { EValidationErrorCode } from '@rsApp/modules/auth-v2/utils/errorMessage';
@Injectable({ providedIn: 'root' })
export class AccountV2Service {
  constructor(private api: RelationshopCoreHttpClient) {}

  getOrganizationStatus(customerCode: string): Observable<any> {
    return this.api.get<any>(`/loyalty/organization-status?customercode=${customerCode}`).pipe(
      catchError((error) => {
        console.error('Error fetching organization status:', error);
        return throwError(() => new Error('Failed to fetch organization status.'));
      })
    );
  }
  updateOrganizationStatus(payload: IUpdateOrganizationStatusPayload): Observable<any> {
    return this.api.put<any>('/loyalty/organization-status', payload).pipe(
      catchError((error) => {
        console.error('Error updating organization status:', error);
        return throwError(() => new Error('Failed to update organization status. Please try again later.'));
      })
    );
  }

  updateUser(userId: string, payload: IUpdateUserPayload): Observable<any> {
    return this.api.put<any>(`/users/update/${userId}`, payload).pipe(
      catchError((error) => {
        console.error('Error updating user:', error);
        if (error?.error?.InternalCode == enumInternalCode.subscriptionSMS) {
          return throwError(() => error?.error);
        } else if (error?.error?.InternalCode == EValidationErrorCode.OTP_INVALID) {
          return of(error?.error?.InternalCode);
        }
        return throwError(() => new Error('Failed to update user. Please try again later.'));
      })
    );
  }

  public changePassword(payload: IChangePasswordPayload): Observable<boolean> {
    return this.api.put<boolean>(`/Users/update-password`, payload).pipe(
      catchError((error) => {
        console.error('Error validating membership code:', error);
        return throwError(() => new Error('Failed to validate membership code. Please try again later.'));
      })
    );
  }

  updateEmailPreferences(userId: string, payload: IUpdateEmailPrefPayload): Observable<boolean> {
    return this.api.put<boolean>(`/users/update/${userId}`, payload).pipe(
      catchError((error) => {
        console.error('Error fetching email preferences:', error);
        return throwError(() => new Error('Failed to fetch email preferences. Please try again later.'));
      })
    );
  }
}
