import { Component, EventEmitter, Input, Output } from '@angular/core';

@Component({
  selector: 'mag-app-alert',
  templateUrl: './mag-app-alert.html',
  styleUrls: ['./mag-app-alert.scss'],
})
export class MagAppAlertComponent {
  @Input() title = '';
  @Input() message = '';
  @Input() actionText = '';

  @Output() closeAlert = new EventEmitter<void>();

  close() {
    this.closeAlert.emit();
  }
}
