import { Component, EventEmitter, Input, Output, OnInit } from '@angular/core';
import { FormControl } from '@angular/forms';
import { MaskitoOptions } from '@maskito/core';
import { CountryRegion, phoneMasks, postalCodeMasks } from '@rsApp/modules/utils/enum/enum';
import { ErrorMessagePipe } from '../input-error.service';
import { TenantSettingsStore } from '@rsApp/modules/utils/providers/tenant-settings.service';

@Component({
  selector: 'mag-app-input',
  templateUrl: './mag-app-input.html',
  styleUrls: ['./mag-app-input.scss'],
  providers: [ErrorMessagePipe],
})
export class MagAppInputComponent implements OnInit {
  @Input() label: string = '';
  @Input() placeholder?: string = '';
  @Input() type?: 'text' | 'address' | 'email' | 'password' | 'date' | 'tel' | 'zipCode';
  @Input() required?: boolean = false;
  @Input() disabled?: boolean = false;
  @Input() allowPasswordStength?: boolean = false;
  @Input() context?: string = '';
  @Input() maxLength?: number;
  @Input() readOnly?: boolean;

  @Input() customClass?: string = '';
  @Input() controlName?: string;
  @Input() control?: FormControl;
  @Input() className?: string = '';

  @Output() mobileCheckboxChanged = new EventEmitter<boolean>();
  @Output() eventBlured = new EventEmitter<any>();

  isFocused: boolean = false;
  isPasswordFocused: boolean = false;

  // Getter and setter for control's value
  get value() {
    return this.control?.value;
  }

  set value(val: string) {
    this.control?.setValue(val); // Update the value of the form control
  }

  // Method to handle blur event
  onFocus() {
    this.isFocused = true;
  }

  onBlur(control?: string) {
    this.isFocused = false;
    this.control.markAsTouched(); // Optional: mark control as touched
    this.eventBlured.emit(control);
  }

  // -------------------- Masking --------------------
  selectedCountry: CountryRegion;
  postalCodeMask: MaskitoOptions;
  phoneMask: MaskitoOptions;

  async applyMaskBaseOnCountry() {
    const tenantInfo = await this.tenantSettingsStore.getTenantSettings();
    this.selectedCountry = tenantInfo?.country ? CountryRegion[tenantInfo.country.toUpperCase()] : CountryRegion.US;
    this.postalCodeMask = postalCodeMasks[this.selectedCountry];
    this.phoneMask = phoneMasks[this.selectedCountry];
  }

  // -------------------- Password --------------------
  showPassword: boolean = false;

  passwordStrengthValid: boolean = false;

  get showPasswordStrength(): boolean {
    return this.type === 'password' && this.allowPasswordStength && this.isPasswordFocused;
  }

  async ngOnInit() {
    if (['zipCode', 'tel'].indexOf(this.type) > -1) {
      this.applyMaskBaseOnCountry();
    }
  }
  onPasswordFocus() {
    this.isPasswordFocused = true;
  }

  onPasswordBlur(): void {
    this.isPasswordFocused = !this.control.valid;
  }

  togglePasswordVisibility() {
    this.showPassword = !this.showPassword;
  }

  // -------------------- Autocomplete --------------------
  autocompleteResults: google.maps.places.AutocompletePrediction[] = [];
  private autocompleteService!: google.maps.places.AutocompleteService;

  // private initAutocomplete() {
  //   if ((window as any).google) {
  //     this.autocompleteService = new google.maps.places.AutocompleteService();
  //   } else {
  //     console.error('Google Maps SDK not loaded.');
  //   }
  // }

  onSearchInput(event: any) {
    const input: string = event?.detail?.value;
    this.value = input;

    if (input && this.autocompleteService) {
      this.autocompleteService.getPlacePredictions({ input, types: ['address'] }, (predictions, status) => {
        if (status === google.maps.places.PlacesServiceStatus.OK && predictions) {
          this.autocompleteResults = predictions;
        } else {
          this.autocompleteResults = [];
        }
      });
    }
  }

  onCheckboxChange(event: any) {
    this.mobileCheckboxChanged.emit(event.detail.checked);
  }

  onResultSelect(result: google.maps.places.AutocompletePrediction) {
    this.value = result.description;
    // this.onChange(result.description);
    this.autocompleteResults = [];
  }

  highlightText(text: string): string {
    const searchTerm = this.value;
    if (!searchTerm) return text;

    const escapedSearchTerm = searchTerm.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    // eslint-disable-next-line security/detect-non-literal-regexp
    const regex = new RegExp(`(${escapedSearchTerm})`, 'gi');
    return text.replace(regex, '<span class="highlight">$1</span>');
  }

  // -------------------- General Methods --------------------
  constructor(
    private errorPipe: ErrorMessagePipe,
    private tenantSettingsStore: TenantSettingsStore
  ) {
    // this.initAutocomplete();
  }

  get errorMessage(): string | null {
    const label = this.type !== 'zipCode' ? this.label.toLowerCase() : this.label;
    return this.control ? this.errorPipe.transform(this.control, this.controlName, label, this.context) : null;
  }

  get placeholderWithAsterisk(): string {
    if (this.required && this.placeholder && !this.placeholder.trim().endsWith('*')) {
      return `${this.placeholder.trim()} *`;
    }
    return this.placeholder || '';
  }
}
