import type { RemoveFromCartParams, Ga4Item } from './ga4.types';

function pickLocalizedText(v: any): string | undefined {
  if (!v) return undefined;
  if (typeof v === 'string') return v;

  if (typeof v === 'object') {
    if (typeof v.en === 'string') return v.en;
    if (typeof v.En === 'string') return v.En;

    const first = Object.values(v).find((x) => typeof x === 'string');
    return first as string | undefined;
  }

  return undefined;
}

function toNumber(v: any): number | undefined {
  if (typeof v === 'number' && Number.isFinite(v)) return v;
  const n = Number(v);
  return Number.isFinite(n) ? n : undefined;
}

function getCategoryName(categories: any, level: number): string | undefined {
  if (!Array.isArray(categories)) return undefined;
  const found = categories.find((c) => Number(c?.Level) === level);
  return found?.CategoryName;
}

function mapCartItemToGa4Item(p: any, idx: number): Ga4Item {
  const price = toNumber(p?.Price) ?? toNumber(p?.Stores?.[0]?.Prices?.[0]?.Price) ?? toNumber(p?.TotalPrice);

  const quantity = toNumber(p?.Quantity) ?? 1;

  return {
    item_id: p?.ProductId ?? p?.Upc ?? p?.Id ?? p?.item_id,
    item_name: pickLocalizedText(p?.DisplayName) ?? pickLocalizedText(p?.Name) ?? p?.item_name,
    item_brand: p?.BrandName?.BrandName ?? p?.Brands?.[0]?.BrandName ?? p?.item_brand,
    item_category: getCategoryName(p?.Categories, 1),
    item_category2: getCategoryName(p?.Categories, 2),
    item_category3: getCategoryName(p?.Categories, 3),
    item_category4: getCategoryName(p?.Categories, 4),
    item_category5: getCategoryName(p?.Categories, 5),
    item_variant: p?.Unit ?? p?.item_variant,
    location_id: p?.Stores?.[0]?.StoreCode ?? p?.StoreCode ?? p?.location_id,
    price,
    quantity,
    index: idx + 1,
  };
}

export function mapRemoveFromCartParams(payload: any): RemoveFromCartParams | null {
  const item = payload?.item ?? payload?.cartItem ?? payload?.data?.item ?? payload?.data?.cartItem ?? payload;

  if (!item || (!item.ProductId && !item.Upc && !item.Id)) return null;

  const quantity = toNumber(item?.Quantity) ?? 1;
  const price = toNumber(item?.Price) ?? toNumber(item?.TotalPrice);

  const value =
    toNumber(item?.TotalPriceWithSavings) ??
    toNumber(item?.TotalPrice) ??
    (price != null ? price * quantity : undefined);

  return {
    currency: payload?.Currency ?? payload?.currency ?? 'USD',
    value,
    items: [mapCartItemToGa4Item(item, 0)],
  };
}
