import { AfterViewChecked, Component, OnDestroy, OnInit, ViewChild } from '@angular/core';
import { NavigationEnd, Router } from '@angular/router';
import { Network } from '@capacitor/network';
import { IonTabs, ModalController } from '@ionic/angular';
import { AuthService } from '@rsApp/modules/auth-v2/providers/auth-v2.service';
import { GuestMsgComponent } from '@rsApp/modules/utils/components/guest-msg/guest-msg';
import { filter, map, tap } from 'rxjs/operators';
import { DynamicMenu } from '../more/providers/dynamic-menu.service';
import { LOCAL_LOCALE_KEY } from '../utils/constants/constants';
import { CurrentStore } from '../store/store.module';
import { Storage } from '@ionic/storage';
import { firstValueFrom } from 'rxjs';
import { TranslateService } from '@ngx-translate/core';

@Component({
  selector: 'app-tabs',
  templateUrl: 'tabs.page.html',
  styleUrls: ['tabs.page.scss'],
})
export class TabsPageComponent implements OnInit, OnDestroy, AfterViewChecked {
  @ViewChild('tabs', { static: false }) tabs?: IonTabs;

  public subsriptions = [];
  public isOffline = false;
  public isHiddenCartIcon: boolean;
  public locale: string;
  public loaded: boolean = false;
  public appBottomNavigation: Array<any> = [];
  private menuCode = 'app_bottom_navigation';
  private tabsInitialized = false;

  constructor(
    public auth: AuthService,
    private router: Router,
    public modalCtrl: ModalController,
    public dynamicMenuSvc: DynamicMenu,
    public cStore: CurrentStore,
    private storage: Storage,
    private translate: TranslateService
  ) {
    const navigationO = this.router.events.pipe(
      filter((event) => event instanceof NavigationEnd),
      map(() => {
        const lRoute = getLeaftActiveRoute(this.router.routerState.snapshot.root);
        return lRoute.routeConfig;
      }),
      // delay for init tab;
      // delay(200),
      tap((routeConfig: any) => {
        if (routeConfig.data && routeConfig.data.hiddenCartIcon) {
          this.isHiddenCartIcon = true;
        }
        if (routeConfig.data && routeConfig.data.hideTab) {
          this.hideTabs();
        } else {
          this.showTabs();
          this.isHiddenCartIcon = false;
        }
      })
    );
    navigationO.subscribe();
  }

  ngAfterViewChecked() {
    if (this.loaded && this.tabs && !this.tabsInitialized) {
      this.tabsInitialized = true;
      this.setTabIndex();
      // cheat
      // setTimeout(() => {
      //   const outlet: any = this.tabs.outlet,
      //     stackCtrl = outlet.stackCtrl;
      //   overrideStackCtrl.bind(stackCtrl)();
      // }, 1000);
      // end cheat
    }
  }
  setTabIndex() {
    if (!this.tabs) return;
    const tabBar = document.querySelector('ion-tab-bar');
    const tabButtons = tabBar?.querySelectorAll('ion-tab-button');

    tabButtons?.forEach((btn) => {
      (btn as HTMLElement).setAttribute('tabindex', '-1');
    });
  }

  async ngOnInit() {
    this.appBottomNavigation = await this.getBottomNavigation();
    this.loaded = true;
    this.listenNetwork();
  }

  async getBottomNavigation() {
    const currentLocale = await this.storage.get(LOCAL_LOCALE_KEY);
    const appBottomNavigation = await firstValueFrom(
      this.dynamicMenuSvc
        .getMenu(this.menuCode, this.auth.user, this.cStore.store, 'Mobile', currentLocale, false)
        .pipe(
          map((menu) => {
            if (menu?.Childs?.length > 0) {
              const { Childs } = menu;
              const menuMapping = Childs.map((item) => {
                const urlArray = item?.UrlLink.split('/');
                const hasUrlLink = urlArray.length > 1;
                return {
                  tab: urlArray?.[0]?.toLowerCase() || item?.Label?.toLowerCase(),
                  routeLink: hasUrlLink ? item?.UrlLink : null,
                  icon: item.Icon,
                  label: item.Label,
                };
              });
              return menuMapping;
            }
            return [];
          })
        )
    );
    return appBottomNavigation && appBottomNavigation.length > 0 ? appBottomNavigation : this._getDefaultTabs();
  }
  ngOnDestroy() {
    for (let i = 0; i < this.subsriptions.length; i++) {
      this.subsriptions[i].unsubscribe();
    }
  }

  listenNetwork() {
    Network.addListener('networkStatusChange', (status) => {
      this.isOffline = !status.connected;
    });
  }

  public hideTabs() {
    const tabBar = document.getElementById('dxptabbar');
    if (tabBar && tabBar.style) {
      tabBar.style.display = 'none';
    }
  }
  public showTabs() {
    const tabBar = document.getElementById('dxptabbar');
    if (tabBar && tabBar.style) {
      tabBar.style.display = 'flex';
    }
  }

  async showGuestMsg(bUrl) {
    getLeaftActiveRoute(this.router.routerState.snapshot.root);
    const m = await this.modalCtrl.create({
      component: GuestMsgComponent,
      componentProps: {
        backUrl: bUrl,
      },
    });
    await m.present();
  }

  private _getDefaultTabs() {
    return [
      {
        tab: 'home',
        routeLink: '/tabs/home',
        icon: 'home.svg',
        label: this.translate.instant('header.home'),
      },
      {
        tab: 'browse',
        routeLink: '/tabs/browse',
        icon: 'browse.svg',
        label: this.translate.instant('header.browse'),
      },
      {
        tab: 'deals',
        routeLink: '/tabs/deals',
        icon: 'save-money.svg',
        label: this.translate.instant('header.save'),
      },
    ];
  }
}
function getLeaftActiveRoute(route) {
  if (route.firstChild) {
    return getLeaftActiveRoute(route.firstChild);
  }
  return route;
}

