import { Inject, Injectable } from '@angular/core';

import { BehaviorSubject, Observable, of } from 'rxjs';
import { catchError, map } from 'rxjs/operators';

// import { Http, Response, Headers, RequestOptions, URLSearchParams } from '@angular/http';
import { RelationshopEComCoreHttpClient } from '@rsApp/modules/gateway/rs-ecom-core-api.service';
import { IMenu, IResponeMenu } from '@rsApp/modules/interfaces/menu.interface';
import { AppSettings } from '@rsApp/modules/utils/providers/app-setting';
import { refreshParam } from '@rsApp/modules/utils/providers/utils';
import { CMS_HTTP_CLIENT } from '../more.config';

@Injectable()
export class DynamicMenu {
  groupCacheKey = 'CMS-MENU;';
  public $appBottomNavigation = new BehaviorSubject<[]>([]);

  constructor(
    public appSetting: AppSettings,
    @Inject(CMS_HTTP_CLIENT) private apiCore: RelationshopEComCoreHttpClient
  ) {}

  setBottomNavigation(appBottomNavigation: any) {
    return this.$appBottomNavigation.next(appBottomNavigation);
  }

  getBottomNavigation() {
    return this.$appBottomNavigation?.value || [];
  }

  public getMenu(
    menuCode: string,
    user: any,
    store: any,
    platform = 'Mobile',
    locale: string,
    refresher = true
  ): Observable<IMenu> {
    const params = {
      user: user,
      store: store,
      locale: locale,
    };
    Object.assign(params, refreshParam(refresher, this.groupCacheKey));
    const o = this.apiCore.get<IResponeMenu>(`/Menu/GetMenuByCode/${menuCode}/${platform}`, { params: params }).pipe(
      map((responseMenu) => {
        return (responseMenu && responseMenu.Data) || null;
      }),
      catchError(() => {
        return of(null);
      })
    );
    return o;
  }
}
