import { Location } from '@angular/common';
import { Component } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { ENV } from '@app/env';
import { Capacitor } from '@capacitor/core';
import { AlertController, IonRouterOutlet, ModalController, NavController, Platform } from '@ionic/angular';
import { Credential } from '@rsApp/modules/auth-v2/providers/credential.service';
import { Utils, cacheErrorHandle } from '@rsApp/modules/utils/providers/utils';
import { CacheService } from 'ionic-cache';
import _ from 'lodash';
import { tap } from 'rxjs/operators';
import { StoreService } from '../../providers/store.service';
@Component({
  selector: 'page-find-store',
  templateUrl: 'find-store.html',
  styleUrls: ['./find-store.scss'],
})
export class FindStorePageComponent {
  cri: any = {
    keyword: '',
    lat: null,
    lng: null,
    isNearBy: false,
    isPickup: false,
    isDelivery: false,
    states: {},
    cities: {},
    banners: {},
    featureLists: {},
    systemList: {},
    areas: {},
  };
  states: any[];
  featureLists: any[];
  allFeatureLists: any[];
  customServices: any[];
  systemServices: any[];
  rawCities: any[];
  cities: any[];
  areas: any[];
  rawAreas: any[];
  services: any[];

  _router: string;
  defaultHref: string;

  isMapOn: boolean;
  isShowFullFeature = false;
  isFullCity = false;
  isBlockLoading = false;
  banners = [
    {
      Banner: 'BigY',
      DisplayName: 'Big Y',
      BannerHost: 'www.bigy.com',
      CS_BannerID: 30,
      ImageMapData: ' ',
      UploadFTPFolder: 'BigY',
    },
    {
      Banner: 'BigyExpress',
      DisplayName: 'Big Y Express',
      BannerHost: 'www.bigyexpress.com',
      CS_BannerID: 31,
      ImageMapData: null,
      UploadFTPFolder: null,
    },
    {
      Banner: 'FreshAcres',
      DisplayName: 'FreshAcres',
      BannerHost: 'Sandboxfreshacres.relationshop.net',
      CS_BannerID: 32,
      ImageMapData: null,
      UploadFTPFolder: null,
    },
  ];

  constructor(
    public navCtrl: NavController,
    public utils: Utils,
    public modalCtrl: ModalController,
    public router: Router,
    public route: ActivatedRoute,
    public store: StoreService,
    public location: Location,
    public alertCtrl: AlertController,
    public platform: Platform,
    public cache: CacheService,
    public cre: Credential,
    public routerOutlet: IonRouterOutlet
  ) {
    const params = this.route.snapshot.paramMap;
    this._router = params.get('router');
    this.defaultHref = params.get('defaultHref');
  }

  async ionViewDidEnter() {
    const params = await this.cache.getItem('store-search-params').catch(cacheErrorHandle);
    if (params) {
      Object.assign(this.cri, params);
    }
    this.cri.isNearBy = false;
    this.utils.getCities().pipe(
      tap((data: any) => {
        this.rawCities = data;
        this.cities = this.isFullCity ? this.rawCities : data.slice(0, 6);
      })
    );
    this.store.getStoreStates().pipe(
      tap((data: any) => {
        this.states = data.filter((obj) => obj.StateId === 'TX' || obj.StateId === 'NM');
      })
    );

    this.store.getStoreSystemServices(true).pipe(
      tap((data: any) => {
        data = _.orderBy(data, ['Priority'], ['asc']);
        // const servicesStore = data.filter(service => service.isActive &&  service.ServiceGroup !== 'SystemService' && service.ServiceGroup !== 'CustomService');
        // this.allFeatureLists = servicesStore;
        // this.featureLists = servicesStore.slice(0, 6);
        this.systemServices = data.filter(
          (service) =>
            service.IsActive &&
            service.CS_ServicesID !== ENV.OnlineOrderSvcId &&
            (service.ServiceGroup === 'SystemService' || service.ServiceGroup === 'CustomService')
        );
        // this.customServices = data.filter(service => service.ServiceGroup === 'CustomService')
      })
    );

    this.store.getStoreInStoreervices().pipe(
      tap((data: any) => {
        // const customService = data.filter(service => service.ServiceGroup === 'CustomService');
        // this.customServices = _.orderBy(customService, ['Priority'], ['asc']);

        data = _.map(data, function (d) {
          d.Priority = d.Priority !== null ? d.Priority : 0;
          return d;
        });
        data = _.orderBy(data, ['Priority'], ['asc']);
        const servicesStore = data;
        this.allFeatureLists = servicesStore;
        this.featureLists = this.isShowFullFeature ? this.allFeatureLists : servicesStore.slice(0, 6);
      })
    );

    const areas = await this.utils.getCityArea().toPromise();
    this.rawAreas = _.sortBy(areas, ['Priority', 'CityAreaName']);
    this.areas = this.rawAreas.slice(0, 6);

    // const s = combineLatest(cityS, stateS, getStoreSystemServices, getStoreInStoreervices).subscribe(() => {
    //   // hide loading;
    // });
  }

  async doFindStore(event = null) {
    if (event !== null && event.keyCode !== 13) return;
    if (this.cri.cities) {
      _.forIn(this.cri.cities, (val, key) => {
        if (!val) {
          delete this.cri.cities[key];
        }
      });
    }
    if (this.cri.states) {
      _.forIn(this.cri.states, (val, key) => {
        if (!val) {
          delete this.cri.states[key];
        }
      });
    }
    if (this.cri.areas) {
      _.forIn(this.cri.areas, (val, key) => {
        if (!val) {
          delete this.cri.areas[key];
        }
      });
    }
    if (this.cri.banners) {
      _.forIn(this.cri.banners, (val, key) => {
        if (!val) {
          delete this.cri.banners[key];
        }
      });
    }
    if (this.cri.featureLists) {
      _.forIn(this.cri.featureLists, (val, key) => {
        if (!val) {
          delete this.cri.featureLists[key];
        }
      });
    }

    if (this.cri.systemList) {
      _.forIn(this.cri.systemList, (val, key) => {
        if (!val) {
          delete this.cri.systemList[key];
        }
      });
    }

    await this.cache.saveItem('store-search-params', this.cri, 'store');
    this.router.navigate(
      [
        '../result-find',
        {
          view: this.isMapOn ? 'map' : 'list',
        },
      ],
      {
        state: {
          searchParams: this.cri,
        },
        relativeTo: this.route,
      }
    );
    this.isMapOn = false;
  }

  doReset() {
    this.isBlockLoading = false;
    this.cri = {
      keyword: '',
      lat: null,
      lng: null,
      isPickup: false,
      isDelivery: false,
      isNearBy: false,
      states: {},
      cities: {},
      banners: {},
      featureLists: {},
      systemList: {},
      areas: {},
    };
  }

  async goNearby() {
    if (this.isBlockLoading) {
      return;
    }
    this.isBlockLoading = true;
    this.utils.getCurrentPosition().then((res: any) => {
      if (!res.isLocationOn) {
        this.utils.alertError('Please enable location services to see stores near you.', this.goAppSettings.bind(this));
        this.isBlockLoading = false;
        return;
      }
      this.doReset();
      this.cri.isNearBy = true;
      // this.isMapOn = true;
      this.doFindStore();
    });
  }
  onStateChange() {
    this.cities = _.filter(this.rawCities, (city) => {
      const valid = !!this.cri.states[city.State];
      // remove selected cities in uncheck states
      if (!valid && this.cri.cities[city.City]) {
        delete this.cri.cities[city.City];
      }
      return valid;
    });
  }

  seeMoreFeature() {
    this.featureLists = this.allFeatureLists;
    this.isShowFullFeature = true;
  }

  seeLessFeature() {
    this.featureLists = this.allFeatureLists.slice(0, 6);
    this.isShowFullFeature = false;
  }

  seeMoreCity() {
    this.areas = this.rawAreas;
    this.isFullCity = true;
  }

  seeLessCity() {
    this.areas = this.rawAreas.slice(0, 6);
    this.isFullCity = false;
  }

  goAppSettings() {
    if (!Capacitor.isNativePlatform()) {
      return;
    }
    this.utils.openAppSettings();
  }
  public back() {
    if (this.routerOutlet && this.routerOutlet.canGoBack()) {
      this.navCtrl.setDirection('back');
      this.routerOutlet.pop();
    } else if (!this.cre.currentUser) {
      this.utils.navigateRoot(['/sign-in']);
    } else {
      this.router.navigate(['/tabs/home']);
    }
  }
  public getPageName() {
    return 'DirectionsMapPage';
  }
}
