import { Injectable, Inject, NgModule } from '@angular/core';
import { MagEComCoreApiHttpClient } from '@rsApp/modules/gateway/mag-ecom-core-api.service';
import { IOriginalStore, IStore, ISystemService } from '@rsApp/modules/interfaces/store.interface';
import { Observable, of, from, firstValueFrom } from 'rxjs';
import { map } from 'rxjs/operators';
import { STORE_HTTP_CLIENT } from '../store.config';
import { IStoreNearByPayload, transformStore, transformSystemServices } from '../utils';
@NgModule({})
export class StoreServiceModule {}

@Injectable({
  providedIn: StoreServiceModule,
})
export class StoreService {
  // Cache for store system services to avoid duplicate API calls
  private storeSystemServicesPromise: Promise<any[]> | null = null;
  private storeSystemServicesCache: any[] | null = null;

  constructor(
    @Inject(STORE_HTTP_CLIENT) private storeApi: MagEComCoreApiHttpClient,
    private apiCore: MagEComCoreApiHttpClient
  ) {}

  searchStores(keyword, sort, isNearBy: boolean = false) {
    return this.storeApi.get(`/store/company/0/location/search`, { params: { keyword, sort, isNearBy } }).pipe(
      map((store: IStore[]) => {
        return store;
      })
    );
  }

  getStoreByCode(code: string) {
    const seq = this.storeApi.get(`/store/by-storeCode/${code}?overrideCache=true`).pipe(
      map((store: IOriginalStore) => {
        return transformStore(store);
      })
    );
    return seq;
  }

  getStoreNearByOld(latlng) {
    const params = { latlng };
    return this.storeApi.get(`/store/company/0/by-coordian`, { params }).pipe(
      map((store: IStore) => {
        return store;
      })
    );
  }

  getStoreNearBy(payloads: IStoreNearByPayload) {
    return this.storeApi.get(`/Store/nearby`, { params: { ...payloads } }).pipe(
      map((store: IOriginalStore) => {
        return transformStore(store);
      })
    );
  }

  searchStoreList(keyword: string = ''): Observable<IStore[]> {
    const params = {
      keyword,
      sort: 'location',
    };

    return this.storeApi.get<IStore[]>(`/store/company/0/location/search`, { params });
  }

  getStoreSystemServices(refresh?: boolean): Observable<any[]> {
    // If refresh is requested, clear both cache and ongoing promise
    if (refresh) {
      this.storeSystemServicesPromise = null;
      this.storeSystemServicesCache = null;
    }

    // If we have cached data and no refresh requested, return from cache immediately
    if (this.storeSystemServicesCache && !refresh) {
      return of(this.storeSystemServicesCache);
    }

    // If there's an ongoing API call (promise), wait for that instead of creating a new one
    if (this.storeSystemServicesPromise && !refresh) {
      return from(this.storeSystemServicesPromise);
    }

    // Create new promise and cache it to prevent duplicate calls
    this.storeSystemServicesPromise = this.fetchStoreSystemServices();

    return from(this.storeSystemServicesPromise);
  }

  private async fetchStoreSystemServices(): Promise<any[]> {
    try {
      // Make API call with default cache
      const seq = this.storeApi.get(`/service/all`, { params: { rCache: 'default' } }).pipe(
        map((services) => {
          const transformedServices = transformSystemServices(services);
          // Cache the transformed result
          this.storeSystemServicesCache = transformedServices;
          return transformedServices;
        })
      );

      const result = await firstValueFrom(seq);
      return result;
    } finally {
      // Reset promise after completed to allow next "fresh" request
      this.storeSystemServicesPromise = null;
    }
  }

  getStoreInStoreervices() {
    const seq = this.storeApi.get(`/InstoreService`).pipe(
      map((services: any) => {
        return services;
      })
    );
    return seq;
  }

  getStoreCities() {
    return this.apiCore.get('/cities');
  }

  getStoreStates() {
    return this.apiCore.get('/states');
  }

  getStoreProviver(store, shopPath) {
    try {
      const seq = this.storeApi.get(`/StoreEcomProvider/${store.StoreId}/${shopPath}`, {
        params: { model: 'simple', rCache: 'd' },
      });
      return seq;
    } catch {
      return of(null);
    }
  }

  getProviver(provider) {
    try {
      const seq = this.storeApi.get(`/Provider/${provider?.ProviderId}`, { params: { rCache: 'd' } });
      return seq;
    } catch {
      return of(null);
    }
  }

  displayStoreType(store) {
    if (!store || !store.ShopOnline || (!store.Pickup && !store.Delivery)) return '';
    const pickupText = store.Pickup ? 'Pickup ' : '';
    const deliveryText = store.Delivery ? 'Delivery ' : '';
    const andText = store.Pickup && store.Delivery ? '& ' : '';
    const type = `${deliveryText}${andText}${pickupText}Available`;
    return type;
  }

  getGroupStore(store: IStore) {
    const attribute = store.Attributes.find((attribute) => attribute.Name === 'Group');
    return attribute && attribute.Values && attribute.Values[0];
  }

  getSystemServiceById(serviceId: number, allServices: ISystemService[]) {
    if (!allServices?.length) {
      console.warn('No services found');
      return null;
    }
    const matchedService = allServices?.find((x) => Number(x.ServiceId) === Number(serviceId));
    if (!matchedService) {
      console.warn('No service found with id', serviceId);
      return null;
    }
    return matchedService;
  }
}
