import { Component, Input, OnInit, OnDestroy, Optional } from '@angular/core';
import { PerformanceLoggerService } from '@rsApp/modules/utils/providers/performance-logger.service';

@Component({
  selector: 'home-skeleton',
  templateUrl: './home-skeleton.component.html',
  styleUrls: ['./home-skeleton.component.scss'],
})
export class HomeSkeletonComponent implements OnInit, OnDestroy {
  @Input() timeout: number = 2000; // Default 2 seconds, configurable (fallback)
  public visible: boolean = true;
  public shouldRender: boolean = true;
  private timeoutId: any;
  private hideTimeoutId: any;
  private perfLogger?: PerformanceLoggerService;

  constructor(@Optional() perfLogger?: PerformanceLoggerService) {
    this.perfLogger = perfLogger;
  }

  ngOnInit() {
    this.perfLogger?.mark('SKELETON_SHOWN');
    this.perfLogger?.log('💀 Home skeleton displayed');
    // Hide the skeleton after the specified timeout as fallback
    this.timeoutId = setTimeout(() => {
      this.perfLogger?.log('⏰ Skeleton timeout reached, hiding...');
      this.hide();
    }, this.timeout);
  }

  show() {
    // Clear any existing timeouts
    if (this.timeoutId) {
      clearTimeout(this.timeoutId);
    }
    if (this.hideTimeoutId) {
      clearTimeout(this.hideTimeoutId);
    }

    // Show skeleton
    this.shouldRender = true;
    this.visible = true;
    this.perfLogger?.log('💀 Home skeleton shown (refresh)');

    // Set timeout to hide if widgets don't load
    this.timeoutId = setTimeout(() => {
      this.perfLogger?.log('⏰ Skeleton timeout reached, hiding...');
      this.hide();
    }, this.timeout);
  }

  hide() {
    if (this.timeoutId) {
      clearTimeout(this.timeoutId);
    }
    this.perfLogger?.mark('SKELETON_HIDDEN');
    this.perfLogger?.log('💀 Home skeleton hidden');
    this.visible = false;
    // Remove from DOM after fade animation completes (0.5s)
    this.hideTimeoutId = setTimeout(() => {
      this.shouldRender = false;
      this.perfLogger?.log('🗑️ Skeleton removed from DOM');
    }, 500);
  }

  ngOnDestroy() {
    if (this.timeoutId) {
      clearTimeout(this.timeoutId);
    }
    if (this.hideTimeoutId) {
      clearTimeout(this.hideTimeoutId);
    }
  }
}
