import { Location } from '@angular/common';
import { Component, OnDestroy, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { ENV } from '@app/env';
import { Browser } from '@capacitor/browser';
import { AlertController, ModalController, NavController, Platform } from '@ionic/angular';
import { TranslateService } from '@ngx-translate/core';
import { NgxPubSubService } from '@pscoped/ngx-pub-sub';
import { User } from '@rsApp/modules/account-v2/providers/user.service';
import { AuthService } from '@rsApp/modules/auth-v2/providers/auth-v2.service';
import { Credential } from '@rsApp/modules/auth-v2/providers/credential.service';
import { enumTrackAction } from '@rsApp/modules/utils/enum/enum';
import { AppSettings } from '@rsApp/modules/utils/providers/app-setting';
import { GoogleAnalyticTracker } from '@rsApp/modules/utils/providers/google-tracker.service';
import { Utils, cacheErrorHandle } from '@rsApp/modules/utils/providers/utils';
import { CacheService } from 'ionic-cache';
import orderBy from 'lodash/orderBy';
import { Subject, firstValueFrom, forkJoin, takeUntil } from 'rxjs';
import { CurrentStore } from '../../providers/current-store.service';
import { StoreService } from '../../providers/store.service';
import { getInStoreServices, getPhoneNumber } from '../../utils';
import { BaseStore } from './../../base-store';
import { EditOrderService } from '@rsApp/modules/ecom-v2/edit-order.service';
import { CategoryService } from '@rsApp/modules/browse/provider/category.service';

@Component({
  selector: 'page-store-info',
  templateUrl: 'info.html',
  styleUrls: ['./info.scss'],
})
export class StoreInfoPageComponent extends BaseStore implements OnDestroy, OnInit {
  showPharmacy = false;
  showAdditionalServices = false;
  storeCode: string;
  storeInfo: any;
  type: string;
  serviceLabel: string;
  serviceName: string;
  currentSystemService;
  phoneNumber;
  PharmacyPhone;
  isSignup: boolean;
  views: any;
  starbuck: any = {};
  inStoreServices = [];
  inStoreServiceLabels = [];
  isLockerPickup = false;
  backInfo: any; // {route: ['/singup/account'], key: 'selected-store'};
  deptShow: any = {};
  serviceShow: any = {};
  isSeletedStore: any;
  OnlineOrderSvcId: any;
  enabledWeeklyAd: boolean;
  accordionState: { [key: string]: number | null } = {
    departments: null,
    services: null,
  };

  backRoute: string;

  weeklyAdTargetedUrl: string;
  isEditOrder: boolean = false;
  private destroy$ = new Subject<boolean>();

  constructor(
    public router: Router,
    public route: ActivatedRoute,
    public user: User,
    public store: StoreService,
    public utils: Utils,
    public modalCtrl: ModalController,
    public cStore: CurrentStore,
    public navCtrl: NavController,
    public auth: AuthService,
    public cre: Credential,
    public location: Location,
    public cache: CacheService,
    public alertCtrl: AlertController,
    public platform: Platform,
    public events: NgxPubSubService,
    public googleTracking: GoogleAnalyticTracker,
    private appSettings: AppSettings,
    private translate: TranslateService,
    public shoppingCart: EditOrderService,
    public categoryService: CategoryService
  ) {
    super(utils, cStore, router, cache, store, cre, events, googleTracking);
    const params = this.route.snapshot.paramMap;
    this.storeCode = params.get('storeCode');
    this.type = params.get('type');
    this.isSignup = !!params.get('isSignup');
    this.OnlineOrderSvcId = ENV.OnlineOrderSvcId;
  }

  ngOnInit() {
    this.route.paramMap.pipe(takeUntil(this.destroy$)).subscribe((params) => {
      this.storeCode = params.get('storeCode');
    });

    this.shoppingCart
      .cartObs()
      .pipe(takeUntil(this.destroy$))
      .subscribe(() => {
        this.isEditOrder = this.shoppingCart.isEditMode();
      });
  }

  async ionViewWillEnter() {
    super.getCurrent();
  }

  async ionViewDidEnter() {
    const back = await this.cache.getItem('store-back').catch(cacheErrorHandle);
    if (back) {
      this.backInfo = back;
    }
    this.currentSystemService = this.cStore?.currentSystemService;
    this.serviceLabel = this.currentSystemService?.DisplayName.toLowerCase().replace(/ /g, ' ');
    const storeInfo = await firstValueFrom(this.store.getStoreByCode(this.storeCode));
    if (storeInfo) {
      this.setup(storeInfo);
    }

    forkJoin([
      this.appSettings.getSettingValue('digital_circular_support'),
      this.appSettings.getSettingValue('digital_circular_targeted_url_store_locator'),
    ])
      .pipe(takeUntil(this.destroy$))
      .subscribe(([digitalSupport, digitalTargetUrl]) => {
        this.enabledWeeklyAd = digitalSupport?.toLowerCase() === 'true';
        this.weeklyAdTargetedUrl = JSON.parse(digitalTargetUrl)?.app || '';
      });
  }

  async setup(storeInfo) {
    // Store contacts
    this.phoneNumber = storeInfo?.Phone && getPhoneNumber(storeInfo.Phone);
    this.PharmacyPhone = storeInfo?.PharmacyPhone && getPhoneNumber(storeInfo.PharmacyPhone);

    this.isLockerPickup = storeInfo.StoreServices.findIndex((x) => x?.DisplayName === 'Locker Pickup') > -1;

    //InStoreServices
    const inStoreServicesByGroup = getInStoreServices(storeInfo?.InstoreServices);
    this.inStoreServices = inStoreServicesByGroup;
    this.inStoreServiceLabels = Object.keys(inStoreServicesByGroup);

    // Store Departments
    let store = this.sortDepartments(storeInfo);
    store = this.formatDepartmentDetails(store);

    this.starbuck = store?.DepartmentStores?.find((item) => item?.CS_DepartmentID === 9);

    this.storeInfo = store;

    this.isSeletedStore =
      this.currentStore && this.storeInfo && this.getSelectedStore(this.currentStore, this.storeInfo);
  }

  ngOnDestroy() {
    this.destroy$.next(true);
    this.destroy$.complete();
  }

  getSelectedStore(currentStore, storeInfo) {
    return currentStore.StoreCode === storeInfo.StoreCode ? currentStore : null;
  }

  /**
   * TODO: Move to utils Formats phone number into (123) 456-7890
   */
  formatPhone(phone: string): string {
    const digits = phone.replace(/\D/g, '').substring(0, 10);
    if (digits.length < 10) return phone;
    return `(${digits.substring(0, 3)}) ${digits.substring(3, 6)}-${digits.substring(6)}`;
  }

  formatMFHours(mFHours: string): string[] {
    if (!mFHours) return [];
    const weekdays = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday'];
    let parts = mFHours.split(';').filter((part) => part);

    // Case Monday - Friday same time
    if (parts.length == 1) {
      // return [`${weekdays[0]} - ${weekdays[weekdays.length - 1]}: ${parts[0]}`];
      parts = Array(5).fill(parts[0]);
    }

    return weekdays.map((key, index) => {
      const time = parts[index]; // cycle through parts
      if (time) {
        const translatedDay = this.translate.instant(`common.weekdays.${key}`);
        return `${translatedDay}: ${time}`;
      }
    });
  }

  sortDepartments(store: any): any {
    if (!store?.DepartmentStores) return store;
    store.DepartmentStores = orderBy(store.DepartmentStores, ['Priority'], ['asc']);
    return store;
  }

  formatDepartmentDetails(store: any): any {
    if (!store?.DepartmentStores) return store;

    store.DepartmentStores.forEach((item: any) => {
      if (item?.DepartmentMFHours) {
        item.formatDepartmentMFHours = this.formatMFHours(item.DepartmentMFHours).filter((hour) => hour);
      }

      if (item?.DepartmentPhone) {
        item.DepartmentPhone = this.formatPhone(item.DepartmentPhone);
      }
    });

    return store;
  }

  toggleAccordion(group: string, index: number): void {
    this.accordionState[group] = this.accordionState[group] === index ? null : index;
  }

  async goWeeklyAd() {
    if (!this.currentStore || this.currentStore.StoreCode !== this.storeInfo.StoreCode) {
      this.cache.saveItem('selected-store', this.storeInfo);
    }
    this.events.publishEvent(enumTrackAction.WeeklyAdTileClick);

    await this.selectStore(this.storeInfo, this.currentSystemService, false);
    this.categoryService.loadCategories(true);
    this.router.navigate([this.weeklyAdTargetedUrl || '/tabs/weekly-ad']);
  }

  // TODO
  openMapInSystem(url) {
    if (!url) {
      return;
    }
    if (this.platform.is('android')) {
      return window.open(url, '_system');
    } else {
      return Browser.open({ url: url, windowName: '_system' });
    }
  }

  async goDirections() {
    /*
    await this.cache.saveItem('store_storeInfo', this.storeInfo);
    this.router.navigate(['../direction'], {relativeTo: this.route});
    */
    const alert = await this.alertCtrl.create({
      message: 'Open in Maps?',
      cssClass: 'cus-alert-modal only-message-aler-modal',
      buttons: [
        {
          text: 'OK',
          handler: () => {
            this.openMapInSystem(this.mapLink(this.storeInfo.Latitude, this.storeInfo.Longitude));
          },
          cssClass: 'btn-ok',
        },
      ],
    });
    await alert.present();
    // let m = await this.utils.alert('', 'Open in Maps?');
    // let rs = await alert.onDidDismiss();
    // if (rs.data.yes) {
    //   this.utils.openInSystem(this.mapLink(this.storeInfo.Latitude, this.storeInfo.Longitude));
    // }
  }
  mapLink(lat, long) {
    if (this.platform.is('android')) {
      return 'geo:' + lat + ',' + long + '?z=8&q=' + lat + ',' + long;
    } else {
      return 'http://maps.apple.com/?q=' + lat + ',' + long + '&ll=' + lat + ',' + long;
    }
  }

  goStoreList() {
    this.router.navigate(['/tabs/store/result-find']);
  }

  openLink(url) {
    if (!url) return;
    this.utils.openInaAppBrowser(url);
  }
  findStore() {
    this.router.navigate(['../find'], { relativeTo: this.route });
  }
  public getPageName() {
    return 'StoreInfoPage';
  }
}
