import { Component, Input, ViewChild, OnInit } from '@angular/core';
import { FormControl } from '@angular/forms';
import { MagAppBottomSheetComponent } from '../mag-app-bottom-sheet/mag-app-bottom-sheet';
import { DEFAULT_LOCALE, LOCAL_LOCALE_KEY } from '@rsApp/modules/utils/constants/constants';
import { Storage } from '@ionic/storage';
import { toUtcMonthStartIso } from '@rsApp/modules/utils/providers/date-utils';

@Component({
  selector: 'mag-app-date-picker',
  templateUrl: 'mag-app-date-picker.html',
  styleUrls: ['./mag-app-date-picker.scss'],
})
export class MagAppDatePickerComponent implements OnInit {
  @Input() label?: string = '';
  @Input() placeholder?: string = '';
  @Input() type = 'month-year';
  @Input() required?: boolean = false;
  @Input() disabled?: boolean = false;
  @Input() customClass?: string = '';
  @Input() controlName?: string;
  @Input() control?: FormControl;
  @Input() className?: string = '';

  @ViewChild('bottomSheet') bottomSheetComponent!: MagAppBottomSheetComponent;

  locale = DEFAULT_LOCALE;
  isPickerOpen = false;
  maxDate = new Date().toISOString();
  ionDateValue: string;
  // Getter and setter for control's value
  get value() {
    return this.control?.value;
  }

  set value(val: string) {
    this.control?.setValue(val); // Update the value of the form control
  }

  constructor(private storage: Storage) {}

  async ngOnInit() {
    this.locale = (await this.storage.get(LOCAL_LOCALE_KEY)) || DEFAULT_LOCALE;
    this.ionDateValue = this.control?.value || toUtcMonthStartIso(this.maxDate);
  }

  // Method to handle blur event
  onBlur() {
    this.control?.markAsTouched();
    //for ion datetime default value
  }

  openPicker() {
    this.bottomSheetComponent.openModal();
  }

  // Output Utc month start
  selectDate(event: any) {
    this.value = toUtcMonthStartIso(event.detail.value);
  }
}
