import { Injectable, OnDestroy } from '@angular/core';
import _ from 'lodash';
import {
  enumTrackAction,
  enumTrackingProduct,
  enumTrackingShoppingCart,
  enumTrackingEventChange,
  enumTrackingShoppingList,
  TRACKING_ACTION_NAME,
} from '../enum/enum';
import { Subscription } from 'rxjs';
import { NgxPubSubService } from '@pscoped/ngx-pub-sub';
import { CookieConsentManager } from '@rsApp/modules/cookie-consent/cookie-consent.manager';

@Injectable({
  providedIn: 'root',
})
export class DXPTracker implements OnDestroy {
  subscriptions: Subscription[] = [];

  constructor(public events: NgxPubSubService) {
    if (!(<any>window).dxp_at) {
      (<any>window).dxp_at = [];
    }
  }

  init() {
    this.registerEvent();
  }

  private trackEventWithCookieConsent(eventName: string, data: any, metadata: any) {
    const cookieConsent = CookieConsentManager.getInstance();

    if (!cookieConsent) return;

    cookieConsent.hasConsent('C0002', null, (hasConsent) => {
      if (hasConsent) {
        try {
          (<any>window).dxp_at.push([eventName, data, metadata]);
        } catch (error) {
          console.error(`Error in ${eventName}:`, error);
        }
      }
    });
  }

  trackPage(pageName: any, url?: any) {
    this.trackEventWithCookieConsent('trackPageView', '', { PageUrl: url, PageTitle: pageName });
  }

  trackEventActionECommerce(actionType, value, metadata?: any) {
    const data = {
      actionType: actionType,
      actionName: TRACKING_ACTION_NAME[actionType],
      actionValue: value,
    };

    this.trackEventWithCookieConsent('trackEventActionECommerce', data, metadata);
  }

  registerEvent() {
    //Ecommerce Events
    const obsSearchItem = this.events.subscribe(enumTrackAction.SearchItem, ({ keyword }) => {
      if (!keyword) {
        return;
      }

      this.trackEventActionECommerce(enumTrackingProduct.SearchItem, keyword);
    });

    this.subscriptions.push(obsSearchItem);

    //
    const obsCategoryView = this.events.subscribe(enumTrackAction.CategoryView, ({ externalId }) => {
      this.trackViewProductList(externalId);
    });

    this.subscriptions.push(obsCategoryView);

    //
    const obsProductView = this.events.subscribe(enumTrackAction.ProductView, ({ product }) => {
      this.trackProductView(product);
    });

    this.subscriptions.push(obsProductView);

    //
    const obsAddEcommerceItem = this.events.subscribe(enumTrackAction.AddEcommerceItem, ({ product }) => {
      this.trackAddItemCart(product);
    });

    this.subscriptions.push(obsAddEcommerceItem);

    //
    const obsTrackEcommerceShoppingCart = this.events.subscribe(
      enumTrackAction.TrackEcommerceShoppingCart,
      ({ shoppingCart }) => {
        this.trackViewCart(shoppingCart);
      }
    );

    this.subscriptions.push(obsTrackEcommerceShoppingCart);

    //
    const obsRemoveEcommerceItem = this.events.subscribe(enumTrackAction.RemoveEcommerceItem, ({ product }) => {
      this.trackRemoveItemCart(product);
    });

    this.subscriptions.push(obsRemoveEcommerceItem);

    //
    const obsTrackEcommerceCartUpdate = this.events.subscribe(
      enumTrackAction.TrackEcommerceCartUpdate,
      ({ shoppingCart }) => {
        this.trackCartUpdate(shoppingCart);
      }
    );

    this.subscriptions.push(obsTrackEcommerceCartUpdate);

    //
    const obsTrackEcommerceAllowsSubstitutions = this.events.subscribe(
      enumTrackAction.AllowsSubstitutions,
      ({ isAllows }) => {
        this.trackAllowsSubstitutions(isAllows);
      }
    );

    this.subscriptions.push(obsTrackEcommerceAllowsSubstitutions);

    //
    const obsChooseTimeSlot = this.events.subscribe(enumTrackAction.ChooseTimeSlot, ({ selectedSlot }) => {
      this.trackChooseTimeSlot(selectedSlot);
    });
    this.subscriptions.push(obsChooseTimeSlot);

    // const obsChooseStore = this.events.subscribe(enumTrackAction.ChooseStore, ({ selectedStoreId , preStoreId}) => {
    // 	this.trackChooseStore(selectedStoreId , preStoreId);
    // });
    // this.subscriptions.push(obsChooseStore);

    // const obsChooseContext = this.events.subscribe(enumTrackAction.ChooseContext, ({selectedshopPath , preshopPath }) => {
    // 	this.trackChooseContext(selectedshopPath , preshopPath);
    // });
    // this.subscriptions.push(obsChooseContext);

    //
    const obsAddEcommerceItemToList = this.events.subscribe(enumTrackAction.AddEcommerceItemToList, ({ product }) => {
      this.trackAddItemToList(product);
    });

    this.subscriptions.push(obsAddEcommerceItemToList);

    //
    const obsRemoveEcommerceItemToList = this.events.subscribe(
      enumTrackAction.RemoveEcommerceItemToList,
      ({ product }) => {
        this.trackRemoveItemToList(product);
      }
    );

    this.subscriptions.push(obsRemoveEcommerceItemToList);

    //
    const obsViewShoppingList = this.events.subscribe(enumTrackAction.ViewShoppingList, ({ ListID }) => {
      if (!ListID) {
        return;
      }

      this.trackEventActionECommerce(enumTrackingShoppingList.ViewList, ListID);
    });

    this.subscriptions.push(obsViewShoppingList);

    //
    const obsShopListGrandTotal = this.events.subscribe(enumTrackAction.ShopListGrandTotal, ({ items }) => {
      if (!items) {
        return;
      }

      const totalPrice = _.sumBy(items, function (i) {
        return i.ItemPrice ? parseFloat(i.ItemPrice) : 0;
      });
      const metadata = {
        TotalItem: items.length,
        TotalQuantity: _.sumBy(items, function (i) {
          return i.Quantity;
        }),
        StoreCredit: totalPrice,
        ShoppingCartItems: items.map((x) => {
          return {
            Id: x.ProductUPC,
            Quantity: x.Quantity,
            ProductVariantName: x.ProductName,
            Price: x.ItemPrice,
            AllowSubstitutions: x.AllowSubstitutions,
          };
        }),
      };

      this.trackEventActionECommerce(enumTrackingShoppingList.ShopList, totalPrice, metadata);
    });

    this.subscriptions.push(obsShopListGrandTotal);

    //
    const obsAddItemShoppingList = this.events.subscribe(enumTrackAction.AddItemShoppingList, ({ item }) => {
      if (!item) {
        return;
      }
      this.trackEventActionECommerce(enumTrackingShoppingList.AddItem, item.Note);
    });

    this.subscriptions.push(obsAddItemShoppingList);

    //
    const obsCheckOffItems = this.events.subscribe(enumTrackAction.CheckOffItems, ({ ItemIDs }) => {
      if (!ItemIDs) {
        return;
      }
      this.trackEventActionECommerce(enumTrackingShoppingList.CheckOffItems, ItemIDs.join(','));
    });

    this.subscriptions.push(obsCheckOffItems);

    //
    const obsEmptyList = this.events.subscribe(enumTrackAction.EmptyList, ({ ItemIDs }) => {
      if (!ItemIDs) {
        return;
      }
      this.trackEventActionECommerce(enumTrackingShoppingList.EmptyList, ItemIDs.join(','));
    });

    this.subscriptions.push(obsEmptyList);

    //
    const obsShareList = this.events.subscribe(enumTrackAction.ShareList, ({ ListID }) => {
      if (!ListID) {
        return;
      }
      this.trackEventActionECommerce(enumTrackingShoppingList.ShareList, ListID);
    });

    this.subscriptions.push(obsShareList);

    //
    const obsPrintList = this.events.subscribe(enumTrackAction.PrintList, ({ ListID }) => {
      if (!ListID) {
        return;
      }
      this.trackEventActionECommerce(enumTrackingShoppingList.PrintList, ListID);
    });

    this.subscriptions.push(obsPrintList);

    //
    const obsRemoveList = this.events.subscribe(enumTrackAction.RemoveList, ({ ListID }) => {
      if (!ListID) {
        return;
      }
      this.trackEventActionECommerce(enumTrackingShoppingList.RemoveList, ListID);
    });

    this.subscriptions.push(obsRemoveList);

    //
    const obsListUpdate = this.events.subscribe(enumTrackAction.ListUpdate, ({ ItemIDs }) => {
      if (!ItemIDs) {
        return;
      }
      this.trackEventActionECommerce(enumTrackingShoppingList.ListUpdate, ItemIDs.join(','));
    });

    this.subscriptions.push(obsListUpdate);
  }

  trackViewProductList(externalId) {
    if (!externalId) {
      return;
    }

    this.trackEventActionECommerce(enumTrackingProduct.ViewProductList, externalId);
  }

  trackProductView(product) {
    if (!product) {
      return;
    }

    console.log(product);
    const { Upc, Name, Brand } = product;
    const productCategory = (product.Categories && product.Categories[0] && product.Categories[0].CategoryName) || '';
    const metadata = {
      ProductName: Name,
      UPC: Upc,
      ItemSize: 1 || '',
      ProductCategory: productCategory,
      ProductBrand: Brand || '',
    };

    this.trackEventActionECommerce(enumTrackingProduct.ViewProduct, product.DisplayPrice, metadata);
  }

  trackAddItemCart(product) {
    if (!product) {
      return;
    }

    const { UPC, Name, Quantity } = product;
    const quantity = Quantity || 1;
    const productCategory =
      product.CategoryName ||
      (product.ProductCategories && product.ProductCategories[0] && product.ProductCategories[0].CategoryName) ||
      '';
    const metadata = {
      ProductName: Name,
      UPC: UPC,
      ItemSize: (product && product.ItemSize) || '',
      ProductCategory: productCategory,
      ProductBrand: (product && product.ProductBrand) || '',
      ProductQuantity: quantity,
      IsRecommended: product.IsSaleItem || false,
    };

    this.trackEventActionECommerce(enumTrackingShoppingCart.AddToCart, UPC, metadata);
  }

  trackRemoveItemCart(product) {
    if (!product) {
      return;
    }

    const { UPC, Name, Quantity } = product;
    const quantity = Quantity || 1;
    const productCategory =
      product.CategoryName ||
      (product.ProductCategories && product.ProductCategories[0] && product.ProductCategories[0].CategoryName) ||
      '';
    const metadata = {
      ProductName: Name,
      UPC: UPC,
      ItemSize: (product && product.ItemSize) || '',
      ProductCategory: productCategory,
      ProductBrand: (product && product.ProductBrand) || '',
      ProductQuantity: quantity,
    };

    this.trackEventActionECommerce(enumTrackingShoppingCart.RemoveFromCart, UPC, metadata);
  }

  trackViewCart(shoppingCart) {
    if (!shoppingCart) {
      return;
    }
    const subTotalText = shoppingCart.SubTotalText
      ? shoppingCart.SubTotalText.replace(/[&\\#,+()$~%'":*?<>{}_]/g, '')
      : 0;
    this.trackEventActionECommerce(enumTrackingShoppingCart.ViewCart, subTotalText, { ...shoppingCart });
  }

  trackCartUpdate(shoppingCart) {
    if (!shoppingCart) {
      return;
    }
    const subTotalText = shoppingCart.SubTotalText
      ? shoppingCart.SubTotalText.replace(/[&\\#,+()$~%'":*?<>{}_]/g, '')
      : 0;
    this.trackEventActionECommerce(enumTrackingShoppingCart.CartUpdate, subTotalText, { ...shoppingCart });
  }

  trackChooseTimeSlot(data) {
    if (!data) {
      return;
    }

    this.trackEventActionECommerce(enumTrackingEventChange.ChooseTimeslot, data.SlotDateTimeShort, {
      previousTimeSlot: data.SlotDateTimeShort,
    });
  }

  trackChooseStore(selectedStoreId, preStoreId) {
    if (!selectedStoreId || !preStoreId) {
      return;
    }

    this.trackEventActionECommerce(enumTrackingEventChange.ChooseStore, selectedStoreId, {
      PreviousStoreId: preStoreId,
    });
  }

  trackChooseContext(selectedshopPath, preshopPath) {
    if (!selectedshopPath || !preshopPath) {
      return;
    }

    this.trackEventActionECommerce(enumTrackingEventChange.ChooseContext, selectedshopPath, {
      PreviousContext: preshopPath,
    });
  }

  trackAllowsSubstitutions(value) {
    if (!value) {
      return;
    }

    this.trackEventActionECommerce(enumTrackingShoppingCart.AllowsSubstitutions, value);
  }

  trackAddItemToList(product) {
    if (!product) {
      return;
    }

    const { UPC, Name, Quantity } = product;
    const quantity = Quantity || 1;
    const productCategory =
      product.CategoryName ||
      (product.ProductCategories && product.ProductCategories[0] && product.ProductCategories[0].CategoryName) ||
      '';
    const metadata = {
      ProductName: Name,
      UPC: UPC,
      ItemSize: (product && product.ItemSize) || '',
      ProductCategory: productCategory,
      ProductBrand: (product && product.ProductBrand) || '',
      ProductQuantity: quantity,
      IsRecommended: product.IsSaleItem || false,
    };

    this.trackEventActionECommerce(enumTrackingShoppingList.AddToList, UPC, metadata);
  }

  trackRemoveItemToList(product) {
    if (!product) {
      return;
    }

    const { ProductUPC, ProductName, Quantity } = product;
    const quantity = Quantity || 1;
    const productCategory =
      product.CategoryName ||
      (product.ProductCategories && product.ProductCategories[0] && product.ProductCategories[0].CategoryName) ||
      '';
    const metadata = {
      ProductName: ProductName,
      UPC: ProductUPC,
      ItemSize: (product && product.ItemSize) || '',
      ProductCategory: productCategory,
      ProductBrand: (product && product.ProductBrand) || '',
      ProductQuantity: quantity,
    };

    this.trackEventActionECommerce(enumTrackingShoppingList.RemoveFromList, ProductUPC, metadata);
  }

  ngOnDestroy() {
    this.subscriptions.forEach((s) => {
      s.unsubscribe();
    });
  }

  handlePushDxpTracking(eventName: string, payload, extraData?) {
    const cookieConsent = CookieConsentManager.getInstance();

    if (!cookieConsent) return;

    cookieConsent.hasConsent('C0002', null, (hasConsent) => {
      if (hasConsent) {
        try {
          window.postMessage(
            { action: 'DXPTrackingEvent', data: { eventName, payload, extraData } },
            window.location.origin
          ); // Push Tracking Event to DXP
        } catch (error) {
          console.error(`Error in ${eventName}:`, error);
        }
      }
    });
  }
}
