import { Injectable, NgModule } from '@angular/core';
import { RelationshopIdentityHttpClient } from '@rsApp/modules/gateway/identity-api.service';
import { RelationshopCoreHttpClient } from '@rsApp/modules/gateway/rs-api-core.service';
import { IStore } from '@rsApp/modules/interfaces/store.interface';
import { IUser } from '@rsApp/modules/interfaces/user.interface';
import { ITenantSettings } from '@rsApp/modules/utils/models/app-settings.model';
import { tap } from 'rxjs/operators';
import { IResponse, ISignupPayload } from '@rsApp/modules/auth-v2/utils/interface';
import { IMagAdress } from '../utils/enum';
import { MagEComCoreApiHttpClient } from '@rsApp/modules/gateway/mag-ecom-core-api.service';
import { Observable, BehaviorSubject } from 'rxjs';
@NgModule({})
export class UserServiceModule {}

@Injectable({
  providedIn: 'root',
})
export class User {
  _user: any;
  _appSetting: ITenantSettings;
  private _email$ = new BehaviorSubject<{ email: string; path: string } | null>(null);

  constructor(
    public apiCore: RelationshopCoreHttpClient,
    public identityapi: RelationshopIdentityHttpClient,
    private orderApi: MagEComCoreApiHttpClient
  ) {}

  /** Function for back navigation from Forgot Password to Sign In */
  setterEmail(email: string, path: string) {
    return this._email$.next({ email, path });
  }
  getterEmail() {
    return this._email$?.getValue();
  }
  /** End */

  /**
   * Send a POST request to our signup endpoint with the data
   * the user entered on the form.
   */
  signup(accountInfo: any, bannerId: number) {
    let birthDay: string = accountInfo.BirthDay;
    if (birthDay) {
      const parts = birthDay.split('/'); //['MM', 'DD', 'YYYY']
      birthDay = [parts[2], parts[0], parts[1]].join('/');
    }
    const interestClubString = JSON.stringify(accountInfo.InterestClub);
    // interestClubString = interestClubString.replace(/\"/g, '\\"');
    const newAccount = {
      isReceiveCard: true,
      Email: accountInfo.Email,
      UserEmail: accountInfo.UserEmail,
      Password: accountInfo.Password,
      FirstName: accountInfo.FirstName,
      LastName: accountInfo.LastName,
      Address: accountInfo.Address,
      City: accountInfo.City,
      State: accountInfo.State,
      ZipCode: accountInfo.ZipCode,
      Latitude: accountInfo.Latitude,
      Longitude: accountInfo.Longitude,
      Phone: accountInfo.Phone,
      CellPhone: accountInfo.CellPhone,
      StoreID: accountInfo.StoreID,
      LoyaltyAutoEnroll: accountInfo.LoyaltyAutoEnroll,
      ReceiveEmail: accountInfo.ReceiveEmail,
      ReceiveTextMessage: accountInfo.ReceiveTextMessage,
      SRCardID: accountInfo.SRCardID,
      BannerID: bannerId,
      InterestClub: interestClubString,
      DestinationCard: accountInfo.IsMerge ? accountInfo.DestinationCard : '',
      IsMerge: accountInfo.IsMerge,
    };

    const seq = this.apiCore.post('/users/new', newAccount);
    return seq;
  }

  updateUserProfile(username, profile, value) {
    const body = ' ' + value + ' ';
    return this.apiCore.put(`/Users/profile/${username}/${profile}`, body);
  }

  validateUser(email, phone, firstName, lastName, username) {
    const user = {
      Email: email, //user Email of userRO
      Phone: phone,
      FirstName: firstName,
      LastName: lastName,
      UserName: username, //email of userRO
    };
    const seq = this.apiCore.post('/users/validate', user);

    return seq;
  }

  public getUserById(userId, includeExternal = false) {
    return this.apiCore.get('/users/get-by-id/' + userId, { params: { includeExternal: includeExternal + '' } });
  }

  public getUnitedFirestoreTokenByUserId(userId) {
    return this.apiCore.get('/FireStore?userId=' + userId, { responseType: 'text' });
  }

  forgotUserName(email: string, bannerId: number) {
    return this.apiCore.post(
      '/ForgotPassword/ForgotUserName',
      {},
      { params: { email: email, bannerid: bannerId + '' } }
    );
  }

  forgotPassWord(email: string, bannerId: number) {
    return this.apiCore.post('/ForgotPassword/email', {}, { params: { email: email, bannerid: bannerId + '' } });
  }

  createAccount(accountInfo: ISignupPayload) {
    return this.apiCore.post('/users/create', accountInfo);
  }

  updateUserById(user) {
    let birthDay: string = user.BirthDay;
    if (birthDay) {
      const parts = birthDay.split('/'); //['MM', 'DD', 'YYYY']
      birthDay = [parts[2], parts[0], parts[1]].join('/');
    }
    const userConvert = {
      Address: user.Address,
      ApplicationKey: user.ApplicationKey,
      BannerHost: user.BannerHost,
      BannerID: user.BannerID,
      BannerName: user.BannerName,
      BirthDay: birthDay,
      CellPhone: user.CellPhone && user.CellPhone.replace(/\D/g, ''),
      ChangedUserName: user.ChangedUserName,
      City: user.City,
      CreatedDate: user.CreatedDate,
      Email: user.Email,
      ExternalCustomerCardID: user.ExternalCustomerCardID,
      ExternalCustomerID: user.ExternalCustomerID,
      FirstName: user.FirstName,
      IsAuthorized: user.IsAuthorized,
      IsLockedOut: user.IsLockedOut,
      LastLoginDate: user.LastLoginDate,
      LastName: user.LastName,
      LastPasswordChangeDate: user.LastPasswordChangeDate,
      LastUpdatedByUser: user.LastUpdatedByUser,
      LastUpdatedDate: user.LastUpdatedDate,
      ListRoles: user.ListRoles,
      LoyaltyAutoEnroll: user.LoyaltyAutoEnroll,
      MiddleName: user.MiddleName,
      Password: user.Password,
      Phone: user.Phone && user.Phone.replace(/\D/g, ''),
      ReceiveEmail: user.ReceiveEmail,
      ReceivePostalMail: user.ReceivePostalMail,
      ReceiveTextMessage: user.ReceiveTextMessage,
      SRCardID: user.SRCardID,
      SecondaryCellPhone: user.SecondaryCellPhone && user.SecondaryCellPhone.replace(/\D/g, ''),
      State: user.State,
      StoreID: user.StoreID,
      StoreManagerID: user.StoreManagerID,
      StoreName: user.StoreName,
      StoreZipCode: user.StoreZipCode,
      Token: user.Token,
      UserEmail: user.UserEmail,
      UserId: user.UserId,
      ZipCode: user.ZipCode,
      ShopPath: user.ShopPath,
      IsVerifiedEmail: user.IsVerifiedEmail,
      IsVerifiedPhone: user.IsVerifiedPhone,
      Latitude: user.Latitude,
      Longitude: user.Longitude,
    };
    return this.apiCore.put(`/users/${userConvert.UserId}`, userConvert).pipe(
      tap(() => {
        this.setUserCache(user.UserId).subscribe();
      })
    );
  }

  setUserCache(userId) {
    const url = `/cache/SetUserCache?key=cs.user:QRY:session_current_user:${userId}`;
    return this.apiCore.post(url, null);
  }
  updatePassword(email, oldPassword, newPassword) {
    const passwordBody = {
      Email: email,
      OldPassword: oldPassword,
      NewPassword: newPassword,
    };
    return this.apiCore.put('/users/password', passwordBody);
  }

  searchUsersByField(field, val) {
    const params = {
      field: field,
      value: val,
    };
    return this.apiCore.get('/Users/SearchUsers', { params: { field: params.field, value: params.value } });
  }

  checkUserExists(email, currentUsername?) {
    return this.apiCore.get(`/users/email/${email}/v5`, { params: { un: currentUsername || '' } });
  }

  checkActiveOrder(userId) {
    return this.orderApi.get(`/order/v2.0/api/order/active/user/${userId}`);
  }

  updateUserName(username, newUsername, pwd) {
    const body = '"' + pwd + '"';
    return this.apiCore.post('/users/change-username/v5', body, {
      params: { username: username, newUsername: newUsername },
    });
  }

  getAddresses(userId): Observable<Array<IMagAdress>> {
    return this.apiCore.get('/users/contacts/user', { params: { userId: userId } }) as Observable<Array<IMagAdress>>;
  }

  getAddressesById(contactId) {
    return this.apiCore.get('/users/contact', { params: { contactId: contactId } });
  }

  removeAddressById(contactId) {
    return this.apiCore.get('/users/contact/delete', { params: { contactId: contactId } });
  }

  updateAddress(address: IMagAdress): Observable<IResponse> {
    const body = {
      CS_ContactID: address.CS_ContactID,
      Address: address.Address,
      City: address.City,
      FirstName: address.FirstName,
      LastName: address.LastName,
      Phone: address.Phone,
      State: address.State,
      UserId: address.UserId,
      ZipCode: address.ZipCode,
      IsBilling: address.IsBilling,
      IsDelivery: address.IsDelivery,
    } as any;

    if (address.Otp) {
      body.Otp = address.Otp;
    }
    return this.apiCore.post('/users/contact/update', body) as Observable<IResponse>;
  }

  addAddress(address: IMagAdress): Observable<IResponse> {
    const body = {
      CS_ContactID: address.CS_ContactID,
      Address: address?.Address,
      City: address.City,
      FirstName: address.FirstName,
      LastName: address.LastName,
      Phone: address?.Phone,
      State: address.State,
      UserId: address.UserId,
      ZipCode: address.ZipCode,
      IsBilling: address.IsBilling,
      IsDelivery: address.IsDelivery,
    } as any;

    if (address.Otp) {
      body.Otp = address.Otp;
    }
    return this.apiCore.post('/users/contact/add', body) as Observable<IResponse>;
  }

  public setStore(store: IStore, user: IUser, shopPath?) {
    const data: any = {
      UserEmail: user.UserName,
      Email: user.Email,
      UserId: user.UserId,
      StoreID: store.StoreId,
      StoreZipCode: store.ZipCode,
      StoreName: store.Name,
      StoreCode: store.StoreCode,
    };
    if (shopPath) {
      data.ShopPath = shopPath;
    }
    return this.apiCore.put(`/users/${data.UserId}/UpdateShoppingMode`, data);
  }

  public refreshCurrentUser(userId: string) {
    return this.apiCore.get(`/users/get-by-id/${userId}`);
  }

  // region Earth Fare functions
  public sendOtpEmail(email: string, bannerId: number) {
    return this.identityapi.post(`/OTP/EmailVerification?email=${email}&bannerId=${bannerId}`, '');
  }
  public validateOtpEmail(email, otp) {
    return this.identityapi.get(`/OTP/validateOtp?email=${email}&otp=${otp}`);
  }

  public getLoyaltyMembers(email) {
    return this.apiCore.get(`/user/GetLoyaltyRegMember?email=${email}`);
  }
  public getCardInfo(card) {
    return this.apiCore.get(`/Loyalty/cards/${card}/demographic`);
  }
  // check card in loyaly
  public checkCard(card: any) {
    // return this.apiCore.get(`/user/VerifyLoyaltyRegMember?cardId=${card.cardId}&lastName=trang`)
    let url = `/user/VerifyLoyaltyRegMember?cardId=${card.cardId}`;
    if (card.lastName) {
      url += `&lastName=${card.lastName}`;
    }
    return this.apiCore.get(url);
  }
  // check card is linked account
  public isUsedCard(card: string) {
    return this.apiCore.get(`/users/card/${card}?un=`);
  }
  getUserByCard(card: string) {
    return this.apiCore.get(`/Loyalty/user-card/${card}`);
  }
  sendSupportEmail(obj: any, bannerId: number) {
    Object.assign(obj, { BannerID: bannerId });
    return this.apiCore.post('/feedbacks', obj);
  }
  public linkCard(user, card) {
    return this.apiCore.post(`/Loyalty/users/${user.Email}/relink`, card);
  }

  getBirthTreat(userId) {
    return this.apiCore.get(`/loyalty/club/${userId}?type=BirthTreat`);
  }

  updateBirthTreat(username, children) {
    const params = {
      username,
      Options: {
        IsReceivedLetter: false,
        FamilyMembers: JSON.stringify(children),
      },
    };
    return this.apiCore.post(`/loyalty/enrollclub?type=BirthTreat`, params);
  }

  getInterestClub(username) {
    return this.apiCore.get(`/Users/profile/${username}/InterestClub`);
  }

  updateInterestClub(username, pets) {
    let params = JSON.stringify(pets);
    params = params.replace(/"/g, '\\"');
    return this.apiCore.put(`/Users/profile/${username}/InterestClub`, '"' + params + '"');
  }
  changePassword(username, newPassword) {
    return this.apiCore.post(`/users/${username}/password`, '"' + newPassword + '"');
  }

  changeUserName(payload) {
    return this.apiCore.post(`/users/admin/change-username`, payload);
  }

  updateUserForceVeriyEmail(user, isForceVerìyEmail) {
    return this.apiCore.put(`/users/${user.UserId}/force-verify-email`, isForceVerìyEmail).pipe(
      tap(() => {
        this.setUserCache(user.UserId).subscribe();
      })
    );
  }

  getUserChangePassword(rsg: string) {
    return this.apiCore.get(`/users/reset-password/get/${rsg}`);
  }

  // end region Earth Fare function
}
