import { Injectable } from '@angular/core';
import { Credential } from '@rsApp/modules/auth-v2/providers/credential.service';
import { RelationshopCoreHttpClient } from '@rsApp/modules/gateway/rs-api-core.service';
import { RelationshopEComCoreHttpClient } from '@rsApp/modules/gateway/rs-ecom-core-api.service';
import { RelationshopSettingHttpClient } from '@rsApp/modules/gateway/rs-setting-api.service';
import { each, filter, find } from 'lodash';
import { forkJoin, of } from 'rxjs';
import { catchError, map } from 'rxjs/operators';
import { IDXPSetting } from '../models/app-settings.model';

function refreshParam(refresher, groupkey?, key?, prefixKey?) {
  return {
    rCache: refresher ? 'fresh' : 'default',
    rCacheKey: key || null,
    rCacheGroupKey: groupkey || null,
    rPrefixCacheKey: prefixKey || null,
  };
}
@Injectable({
  providedIn: 'root',
})
export class AppSettings {
  groupCacheKey = 'setting;';
  saleTagImage = '';
  rewardTagImage = '';
  appSettingsCacheKey = 'AppSettings';
  constructor(
    public dxpCoreApi: RelationshopCoreHttpClient,
    public settingApi: RelationshopSettingHttpClient,
    public ecomApi: RelationshopEComCoreHttpClient,
    private cre: Credential
  ) {
    //Preload setting to improve performance
    if (this.cre.rsApiToken) {
      this.getSaleTagImage();
      this.getRewardTagImage();
    }
  }

  public getSettingValue(settingName: string, refeshCache?: boolean) {
    const settings = this.settingApi
      .get('/setting/by-name/' + settingName, { params: { rCache: refeshCache ? 'fresh' : 'd' } })
      .pipe(
        map((data: IDXPSetting) => {
          if (data) {
            return data.SettingValue;
          }
          return '';
        })
      );
    return settings;
  }

  public getSettingByPath(path: string) {
    const settingsData = this.settingApi.get('/setting/by-path?path=' + path, { params: { rCache: 'd' } }).pipe(
      map((settings: Array<IDXPSetting>) => {
        if (!settings || settings.length === 0) return {};
        return settings.reduce((acc, setting) => {
          const { SettingValue, IsActive, IsDeleted } = setting || {};
          if (SettingValue && IsActive && !IsDeleted) {
            let settingValue;
            try {
              settingValue = JSON.parse(SettingValue);
            } catch {
              settingValue = SettingValue || null;
            }
            return {
              ...acc,
              [setting.SettingName]: settingValue,
            };
          }
          return acc;
        }, {});
      })
    );
    return settingsData as any;
  }

  public getSettingValues(settingNames: string[]) {
    const reqs = settingNames.map((settingName) => this.getSettingValue(settingName));
    const settingO = forkJoin(reqs).pipe(
      map((data) => {
        const settings = filter(data, (o: IDXPSetting) => settingNames.indexOf(o.SettingName) > -1).map((o) => ({
          [o.SettingName]: o.SettingValue,
        }));
        return settings;
      })
    );
    return settingO;
  }
  public setting2Object(settings) {
    const o = {};
    each(settings, (setting) => {
      o[setting.SettingName] = setting.SettingValue;
    });
    return o;
  }
  public getEcomSettingValue(settingName, storeID) {
    return this.ecomApi.get('/checkout/messageresources', { params: { keyword: settingName, storeId: storeID } });
  }

  public getLastVersion(bannerId) {
    return this.dxpCoreApi.get(`/app/version?banner=${bannerId}`);
  }

  public getProgramsSetting(refresher?) {
    const params = {};
    const url = `/settings/HOMEPAGE_PROGRAMS`;
    Object.assign(params, refreshParam(refresher, this.groupCacheKey));
    const o = this.dxpCoreApi.get(url, { params: params }).pipe(
      catchError(() => {
        console.error('getSettingPrograms error');
        return [];
      }),
      map((settingResult) => {
        return JSON.parse(settingResult);
      })
    );
    return o;
  }

  public getProgramsSettingByProgramCode(programCode, refresher?) {
    const params = {};
    const url = `/settings/HOMEPAGE_PROGRAMS`;
    Object.assign(params, refreshParam(refresher, this.groupCacheKey));
    const o = this.dxpCoreApi.get(url, { params: params }).pipe(
      catchError(() => {
        console.error('getSettingPrograms error');
        return [];
      }),
      map((settingResult) => {
        const settings = JSON.parse(settingResult);
        return find(settings, (setting) => setting.ProgramCode === programCode);
      })
    );
    return o;
  }

  public getSaleTagImage(refresher?) {
    const params = {};
    const saleTagImg = this.saleTagImage || localStorage.getItem('DEFAULT_IMAGE_SALE_TAG_URL');

    if (saleTagImg) {
      return of(saleTagImg);
    }
    const url = `/settings/DEFAULT_IMAGE_SALE_TAG_URL`;
    Object.assign(params, refreshParam(refresher, this.groupCacheKey));
    const o = this.dxpCoreApi.get<string>(url, { params: params }).pipe(
      catchError(() => {
        console.error('getSaleTagImage error');
        return of('');
      }),
      map((settingResult) => {
        this.saleTagImage = settingResult;
        return settingResult;
      })
    );
    return o;
  }

  public getRewardTagImage(refresher?) {
    const params = {};
    if (this.rewardTagImage) {
      return of(this.rewardTagImage);
    }
    const url = `/settings/DEFAULT_IMAGE_REWARD_TAG_URL`;
    Object.assign(params, refreshParam(refresher, this.groupCacheKey));
    const o = this.dxpCoreApi.get<string>(url, { params: params }).pipe(
      catchError(() => {
        console.error('getRewardTagImage error');
        return of('');
      }),
      map((settingResult) => {
        this.rewardTagImage = settingResult;
        return settingResult;
      })
    );
    return o;
  }

  public getDynamicNavigationServiceSetting(refresher?) {
    const params = {};
    const url = `/settings/SERVICE_DYNAMIC_MENU_APP`;
    Object.assign(params, refreshParam(refresher, this.groupCacheKey));
    const o = this.dxpCoreApi.get(url, { params: params }).pipe(
      catchError(() => {
        return of('[]');
      }),
      map((settingResult: any) => {
        return JSON.parse(settingResult || '[]');
      })
    );
    return o;
  }

  public getHolidayDinnerServiceSetting(refresher?) {
    const params = {};
    const url = `/settings/HOLIDAY_DINNER_SERVICE_ENABLE_APP`;
    Object.assign(params, refreshParam(refresher, this.groupCacheKey));
    const o = this.dxpCoreApi.get(url, { params: params }).pipe(
      catchError(() => {
        console.error('getHolidayDinnerServiceSetting error');
        return of(false);
      }),
      map((settingResult) => {
        return settingResult === 'true';
      })
    );
    return o;
  }

  public getFloralServiceSetting(refresher?) {
    const params = {};
    const url = `/settings/FLORAL_SERVICE_ENABLE_APP`;
    Object.assign(params, refreshParam(refresher, this.groupCacheKey));
    const o = this.dxpCoreApi.get(url, { params: params }).pipe(
      catchError(() => {
        console.error('getFloralServiceSetting error');
        return of(false);
      }),
      map((settingResult) => {
        return settingResult === 'true';
      })
    );
    return o;
  }

  public getColorMappingSetting(refresher?) {
    const params = {};
    const url = `/settings/PRODUCT_ATTRIBUTES`;
    Object.assign(params, refreshParam(refresher, this.groupCacheKey));
    const o = this.dxpCoreApi.get(url, { params: params }).pipe(
      catchError(() => {
        console.error('getColorMappingSetting error');
        return of(false);
      }),
      map((settingResult: any) => {
        return JSON.parse(settingResult);
      })
    );
    return o;
  }

  public getProductInforSetting(refresher?) {
    const params = {};
    const url = `/settings/ORDER_OF_PRODUCT_INFORMATION_DISPLAY`;
    Object.assign(params, refreshParam(refresher, this.groupCacheKey));
    const o = this.dxpCoreApi.get(url, { params: params }).pipe(
      catchError(() => {
        console.error('getProductInforSetting error');
        return of(false);
      }),
      map((settingResult: any) => {
        return JSON.parse(settingResult);
      })
    );
    return o;
  }

  public getSettingsByPatch(settingName?: string) {
    return this.settingApi.get('/setting/by-path?path=' + settingName, { params: { rCache: 'd' } }).pipe(
      map((data: IDXPSetting) => {
        return data || [];
      }),
      catchError(() => {
        return [];
      })
    );
  }
}
