import { Component } from '@angular/core';
import { Router } from '@angular/router';
import { TranslateService } from '@ngx-translate/core';
import { IMagToastOptions, MagOtpActionType } from '@rsApp/components/interface';
import { ToastService } from '@rsApp/components/toast.service';
import { AuthService } from '@rsApp/modules/auth-v2/providers/auth-v2.service';
import { firstValueFrom } from 'rxjs';

@Component({
  selector: 'change-email-verify-otp',
  templateUrl: './change-email-verify-otp.html',
  styleUrls: ['./change-email-verify-otp.scss'],
})
export class ChangeEmailVerifyOtpComponent {
  email: string;
  actionType: MagOtpActionType = MagOtpActionType.CHANGE_EMAIL;

  constructor(
    public router: Router,
    private translate: TranslateService,
    private authService: AuthService,
    private toastService: ToastService
  ) {
    this.email = this.router.getCurrentNavigation()?.extras.state?.email;
  }

  back() {
    this.router.navigate(['/tabs/my-account/security']);
  }

  async handleOtpVerified() {
    try {
      await firstValueFrom(this.authService.refreshUser());
      this.router.navigate(['/tabs/my-account']);

      const toastChangeEmailConfig: IMagToastOptions = {
        message: this.translate.instant('toast.changeEmailSuccess'),
        type: 'success',
      };
      this.toastService.create(toastChangeEmailConfig);
    } catch (error) {
      console.warn(error);
    }
  }

  useDifferentEmail() {
    this.router.navigate(['/tabs/my-account/security'], {
      state: { actionType: 'changeEmail' },
    });
  }
}
