import { Component, ViewChild, OnInit } from '@angular/core';
import { FormBuilder, Validators, FormGroup } from '@angular/forms';
import { Router } from '@angular/router';
import { Credential } from '@rsApp/modules/auth-v2/providers/credential.service';
import { PhoneValidator } from '@rsApp/modules/utils/validator/phone-validator-v2';
import { User } from '../../providers/user.service';
import { ToastService } from '@rsApp/components/toast.service';
import { IMagToastOptions, MagOtpActionType } from '@rsApp/components/interface';
import { maskitoTransform } from '@maskito/core';
import { firstValueFrom } from 'rxjs';
import { GlobalRegex, phoneMasks, POSTAL_CODE_LABEL, postalCodeMasks } from '@rsApp/modules/utils/enum/enum';
import { IMagAdress } from '../../utils/enum';
import { AuthService } from '@rsApp/modules/auth-v2/providers/auth-v2.service';
import { MagAppDialogComponent } from '@rsApp/components/mag-app-dialog/mag-app-dialog';
import { IResponse, enumInternalCode } from '@rsApp/modules/auth-v2/utils/interface';
import { TranslateService } from '@ngx-translate/core';
import { TenantSettingsStore } from '@rsApp/modules/utils/providers/tenant-settings.service';
import { IUser } from '@rsApp/modules/interfaces/user.interface';
import { ForceVerifyPhoneComponent } from '../../components/mag-force-verify-phone/mag-force-verify-phone';
import { EventBusService } from '@rsApp/modules/utils/providers/event-bus.service';
import { ITenantSettings } from '@rsApp/modules/utils/models/app-settings.model';

@Component({
  selector: 'address-management',
  templateUrl: './address-management.html',
  styleUrls: ['./address-management.scss'],
})
export class AddressManagementComponent implements OnInit {
  // Reactive form group for address input
  addressForm: FormGroup;

  // Controls visibility of all address fields
  isShowAllFields: boolean = true;

  // Context and state
  actionType: 'add' | 'edit';
  userAddress: any;
  contactId: string;
  accounType: string;
  isBusinessMobileNumber: boolean = false;

  currentPhone: string;
  // Toast configurations
  // toastAddAddressConfig: IMagToastOptions = {
  //   message: 'New address added successfully.',
  //   type: 'success',
  // };

  // toastUpdateAddressFail: IMagToastOptions = {
  //   message: 'Address updated failed.',
  //   type: 'error',
  // };
  isLoading: boolean = false;

  systemAlertConfig = {
    title: '',
    message: '',
    actionText: '',
  };
  countryRegion: string = 'us';
  postalCodeLabel = POSTAL_CODE_LABEL;
  currentUser: IUser;
  isForceVerifyPhone: boolean = false;
  verifyPhoneActionType: MagOtpActionType = MagOtpActionType.VERIFY_PHONE;
  otpActionType: MagOtpActionType = MagOtpActionType.VERIFY_PHONE_CONTACT;
  isPhoneVerify: boolean = false;

  public SettingKeyAM = 'ACCOUNT MANAGEMENT';
  public tenantSettings: ITenantSettings;

  @ViewChild('dialogModal') dialogComponent!: MagAppDialogComponent;
  @ViewChild('forceVerifyPhone') forceVerifyPhone!: ForceVerifyPhoneComponent;

  constructor(
    private fb: FormBuilder,
    private router: Router,
    public phoneValidator: PhoneValidator,
    private user: User,
    private cre: Credential,
    private toastService: ToastService,
    private authService: AuthService,
    private translate: TranslateService,
    private tenantSettingsStore: TenantSettingsStore,
    private eventBus: EventBusService
  ) {
    this.tenantSettingsStore.getTenantSettings().then((settings) => {
      this.tenantSettings = settings;
      this.countryRegion = this.tenantSettings?.country ? this.tenantSettings.country.toLowerCase() : 'us';
      this.initForm();
    });

    // Retrieve state passed from router
    const payload = this.router.getCurrentNavigation()?.extras?.state;
    const { actionType, address } = payload || {};

    this.accounType = this.cre?.currentUser?.AccountType || 'Personal';

    this.actionType = actionType;
    if (address) {
      this.userAddress = JSON.parse(address);
    }

    // Pre-fill form for editing
    if (this.userAddress && this.actionType === 'edit') {
      const { Phone, Address, City, ZipCode, State, FirstName, LastName, IsBilling, IsDelivery } = this.userAddress;
      this.tenantSettingsStore.getTenantSettings().then((rs) => {
        this.countryRegion = rs?.country ? rs.country.toLowerCase() : 'us';
        const zipPattern = this.countryRegion === 'ca' ? GlobalRegex.ZIP_CODE_CA : GlobalRegex.ZIP_CODE_US;
        this.addressForm.get('ZipCode')?.setValidators([Validators.required, Validators.pattern(zipPattern)]);

        const maskedPhone = maskitoTransform(
          { value: Phone, selection: [Phone.length, Phone.length] },
          phoneMasks[this.countryRegion]
        ).value;
        const maskedZip = maskitoTransform(
          { value: ZipCode, selection: [ZipCode.length, ZipCode.length] },
          postalCodeMasks[this.countryRegion]
        ).value;
        this.currentPhone = maskedPhone;
        this.addressForm.patchValue({
          Phone: maskedPhone,
          Address,
          City,
          ZipCode: maskedZip,
          State,
          FirstName,
          LastName,
          IsBilling,
          IsDelivery,
        });
      });
    }

    this.systemAlertConfig = {
      title: this.translate.instant('toast.addAddressError'),
      message: this.translate.instant('toast.updateAddressFailed'),
      actionText: this.translate.instant('common.close'),
    };
  }

  async initForm() {
    const zipPattern = this.countryRegion === 'ca' ? GlobalRegex.ZIP_CODE_CA : GlobalRegex.ZIP_CODE_US;
    // Initialize form
    this.addressForm = this.fb.group({
      Phone: ['', { validators: [Validators.required, Validators.pattern(GlobalRegex.PHONE)] }], // phone , busines phone
      // MobileNumber: [''], // cell phones
      Address: ['', [Validators.required, Validators.pattern(GlobalRegex.ADDRESS_US)]],
      City: ['', [Validators.required, Validators.pattern(GlobalRegex.CITY_US)]],
      ZipCode: ['', [Validators.required, Validators.pattern(zipPattern)]],
      State: ['', [Validators.required]],
      FirstName: ['', [Validators.required, Validators.pattern(GlobalRegex.NAME)]],
      LastName: ['', [Validators.required, Validators.pattern(GlobalRegex.NAME)]],
      IsBilling: [false],
      IsDelivery: [false],
    });
  }
  private async checkIsForceVerifyPhone() {
    this.isPhoneVerify = (await this.cre.getCurrentUser())?.IsForceVerifyPhone || false;
  }

  // onBusinessPhoneChecked(event) {
  //   this.isBusinessMobileNumber = event.detail.checked;
  // }

  /**
   * Composes and formats form data for submission
   */
  composeData(): IMagAdress {
    return {
      Phone: this.addressForm.value.Phone?.replace(/\D/g, ''),
      // MobileNumber: this.isBusinessMobileNumber
      //   ? this.addressForm?.value.Phone?.replace(/\D/g, '')
      //   : this.addressForm?.value?.MobileNumber?.replace(/\D/g, ''),
      Address: this.addressForm.value.Address,
      City: this.addressForm.value.City,
      ZipCode: this.addressForm.value.ZipCode,
      State: this.addressForm.value.State?.Id || this.addressForm.value.State,
      FirstName: this.addressForm.value.FirstName,
      LastName: this.addressForm.value.LastName,
      IsBilling: this.addressForm.value.IsBilling,
      IsDelivery: this.addressForm.value.IsDelivery,
      CS_ContactID: this.actionType === 'edit' ? this.userAddress.CS_ContactID : 0,
      UserId: this.cre.currentUser.UserId,
    };
  }

  ngOnInit() {
    this.currentUser = this.cre.currentUser;
    this.checkIsForceVerifyPhone();
  }

  showToast(msg): IMagToastOptions {
    return {
      message: this.translate.instant(msg),
      type: 'success',
    };
  }

  /**
   * Adds a new address
   */
  async addAddress(prop?) {
    try {
      this.isLoading = true;
      const data = this.composeData();

      if (prop?.otp) {
        data.Otp = prop.otp;
      }

      const result = await firstValueFrom(this.user.addAddress(data));
      if (!result) {
        return this.dialogComponent.openDialog();
      }
      this.forceVerifyPhone.closeBottomSheet();
      this.eventBus.emit('resUpdateContact', { status: true });
      this.toastService.create(this.showToast('toast.addAddressSuccess'));
      await firstValueFrom(this.authService.refreshUser());
      this.router.navigate(['/tabs/my-account']);
    } catch (exception) {
      const { error }: { error: IResponse } = exception;
      if (!error || !error?.Status || error.InternalCode != null) {
        switch (error.InternalCode) {
          case enumInternalCode.phoneExits:
            return this.currentPhoneInvalid();
          case enumInternalCode.otpInvalid:
            this.eventBus.emit('resUpdateContact', { status: false });
            break;
          default:
            return this.dialogComponent.openDialog();
        }
      }
    } finally {
      this.isLoading = false;
    }
  }

  currentPhoneInvalid() {
    const control = this.addressForm.get('Phone');
    return control.setErrors({ phoneExist: true });
  }

  /**
   * Check is update phone number
   */
  checkDataUpdate(cb: any) {
    if (this.addressForm.invalid) {
      this.addressForm.markAllAsTouched();
      return;
    }

    if (
      this.isPhoneVerify &&
      this.addressForm.value.IsBilling &&
      this.addressForm.value.Phone?.replace(/\D/g, '') != this.cre.currentUser.Phone
    ) {
      this.isForceVerifyPhone = true;
      this.forceVerifyPhone.openBottomSheet();
    } else {
      cb();
    }
  }

  /**
   * Updates an existing address
   * */
  async updateAddress(prop?) {
    try {
      const data = this.composeData();
      this.isLoading = true;

      if (prop?.otp) {
        data.Otp = prop.otp;
      }

      const result = await firstValueFrom(this.user.updateAddress(data));
      if (!result) {
        return this.dialogComponent.openDialog();
      }
      this.forceVerifyPhone.closeBottomSheet();
      this.eventBus.emit('resUpdateContact', { status: true });
      this.toastService.create(this.showToast('toast.updateAddressSuccess'));
      await firstValueFrom(this.authService.refreshUser());
      this.router.navigate(['/tabs/my-account']);
    } catch (exception) {
      const { error }: { error: IResponse } = exception;
      if (!error || !error?.Status || error?.InternalCode != null) {
        switch (error.InternalCode) {
          case enumInternalCode.phoneExits:
            return this.currentPhoneInvalid();
          case enumInternalCode.otpInvalid:
            this.eventBus.emit('resUpdateContact', { status: false });
            break;
          default:
            return this.dialogComponent.openDialog();
        }
      }
    } finally {
      this.isLoading = false;
    }
  }

  /**
   * Triggered when user clicks Save
   */
  onSave() {
    switch (this.actionType) {
      case 'add':
        this.checkDataUpdate(() => this.addAddress());
        break;
      case 'edit':
        this.checkDataUpdate(() => this.updateAddress());
        break;
    }
  }

  /**
   * Handles state dropdown selection
   */
  onStateSelected(state: any) {
    this.addressForm.get('State')?.setValue(state);
  }

  /**
   * Navigates back to account page
   */
  back() {
    this.router.navigate(['/tabs/my-account']);
  }

  // Lifecycle placeholder (can be removed or implemented if needed)

  // Placeholder for future expansion (getAddress logic)
  closeAlert() {
    this.dialogComponent.closeDialog();
  }

  verifyPhoneSuccess(data) {
    if (this.actionType == 'add') {
      this.addAddress(data);
    } else {
      this.updateAddress(data);
    }
  }
}
