import { Inject, Injectable } from '@angular/core';
import { MagEComCoreApiHttpClient } from '@rsApp/modules/gateway/mag-ecom-core-api.service';
import { CacheService } from 'ionic-cache';
import { map, Observable } from 'rxjs';
import { MAG_RECIPE_V2_HTTP_CLIENT } from '../../utils/ecom-api-configs';
import { IMagRecipe } from '../model/interface';

@Injectable()
export class RecipeService {
  constructor(
    public cache: CacheService,
    @Inject(MAG_RECIPE_V2_HTTP_CLIENT) private api: MagEComCoreApiHttpClient
  ) {}

  getRecipe(payload): Observable<IMagRecipe> {
    const params = {
      userId: payload?.userId,
    };
    return this.api.get(`/Recipes/get-by-code?code=${payload?.Code}`, { params }).pipe(
      map((data: any) => {
        return data.Data;
      })
    );
  }

  getRecipes(payload) {
    const url = `/Recipes/search`;
    return this.api.post(url, payload).pipe(
      map((data: any) => {
        return data.Data;
      })
    );
  }

  filterRecipes(payload) {
    const url = `/Recipes/Search/filters`;
    return this.api.post(url, payload).pipe(
      map((data: any) => {
        return data.Data;
      })
    );
  }

  getFavoriteRecipes(payload) {
    const url = `/RecipeFavorites/all`;
    return this.api.get(url, payload).pipe(
      map((data: any) => {
        return data.Data;
      })
    );
  }

  getFavoriteRecipe(code: string): Observable<IMagRecipe> {
    return this.api.get(`/RecipeFavorites/detail/${code}`).pipe(
      map((data: any) => {
        return data.Data;
      })
    );
  }

  addFavoriteRecipe(payload) {
    console.log(payload, 'payload');
    const url = `/RecipeFavorites/add`;
    return this.api.post(url, payload);
  }

  removeFavoriteRecipe(code: string) {
    const url = `/RecipeFavorites/delete/${code}`;
    const req = this.api.delete(url);
    return req;
  }

  shareRecipes(payload) {
    const url = `/Recipes/share`;
    return this.api.post(url, payload);
  }
}
