import { Component, Input, OnChanges, OnInit, SimpleChanges } from '@angular/core';
import { PasswordValidator } from '@rsApp/modules/utils/validator/password-validator-v2';

@Component({
  selector: 'mag-app-password-strength',
  templateUrl: './mag-app-password-strength.html',
  styleUrls: ['./mag-app-password-strength.scss'],
})
export class MagAppPasswordStrengthComponent implements OnChanges, OnInit {
  @Input() password: string = '';
  constructor(private passwordValidator: PasswordValidator) {}

  ngOnChanges(changes: SimpleChanges) {
    if (changes['password']) {
      this.checkPasswordStrength();
    }
  }

  strengthLabel: string = '';
  strengthClass: string = '';
  passedRules: boolean[] = [];
  criterias;

  ngOnInit() {
    this.criterias = this.passwordValidator.getCriterias();
  }

  checkPasswordStrength() {
    if (this.password) {
      this.passedRules = this.passwordValidator.validatePasswordStrength(this.password);
    }
  }
}
