import { Component, Input, OnInit } from '@angular/core';
import { Router } from '@angular/router';
import { CategoryService } from '@rsApp/modules/browse/provider/category.service';
import { ProductSearchService } from '@rsApp/modules/ecom-v2/product/providers/product-search.service';
import { DxpComponentService } from '@rsApp/modules/utils/providers/dxp.component.service';

@Component({
  selector: 'app-search',
  templateUrl: './search.component.html',
  styleUrls: ['./search.component.scss'],
})
export class SearchComponent implements OnInit {
  @Input() isShowBackButton = false;
  @Input() isLocalSearch = false;
  public keyword = '';

  constructor(
    public router: Router,
    public productSearchService: ProductSearchService,
    public dxpComponentService: DxpComponentService,
    private categorySvc: CategoryService
  ) {}

  ngOnInit(): void {
    customElements.whenDefined('mag-search').then(() => {
      this.categorySvc.initialData();
    });
  }

  setKeyword(value) {
    this.keyword = value;
  }

  clearKeyword() {
    this.productSearchService.setCriterias({ keyword: '' });
  }

  submitSearchLocal() {
    this.productSearchService.setCriterias({ keyword: this.keyword });
  }
}
