import { Injectable, OnDestroy } from '@angular/core';
import { EnumMagFulfillmentManagementRenderType, RegexRouteName } from '@rsApp/core/enum';
import { IMagProductRes } from '@rsApp/modules/ecom-v2/product/model/interface';
import { CurrentStore, StoreService } from '@rsApp/modules/store/store.module';
import { isAttValueTrue } from '@rsApp/modules/store/utils';
import { BehaviorSubject, firstValueFrom, Observable, from, switchMap, Subject } from 'rxjs';
import { catchError, distinctUntilChanged, filter, map, takeUntil, tap } from 'rxjs/operators';
import { AppSettings } from './app-setting';
import { toBoolean } from './utils';
import { NavigationEnd, Router } from '@angular/router';

@Injectable({ providedIn: 'root' })
export class RouteTrackerService implements OnDestroy {
  private renderTypeFromDefaultService$ = new BehaviorSubject<EnumMagFulfillmentManagementRenderType | null>(null);
  private renderType$ = new BehaviorSubject<EnumMagFulfillmentManagementRenderType | null>(null);
  private initPromise: Promise<void> | null = null;
  private destroy$ = new Subject<void>();
  public previousPath: string | null = null;
  public currentPath: string | null = null;

  constructor(
    private router: Router,
    private cStore: CurrentStore,
    private storeService: StoreService,
    private appSettingsService: AppSettings
  ) {
    this.setupRouterEvents();
  }

  private setupRouterEvents(): void {
    this.router.events
      .pipe(
        takeUntil(this.destroy$),
        filter((ev) => ev instanceof NavigationEnd),
        map((ev) => (ev as NavigationEnd).urlAfterRedirects),
        distinctUntilChanged(),
        tap((path) => {
          // Store previous path before updating current
          this.previousPath = this.currentPath;
          this.currentPath = path;

          if (path && this.renderTypeFromDefaultService$.value) {
            if (RegexRouteName.MAG_CART.test(path)) {
              this.renderType$.next(EnumMagFulfillmentManagementRenderType.Cart);
            } else {
              this.renderType$.next(this.renderTypeFromDefaultService$.value);
            }
          }
        })
      )
      .subscribe();
  }

  public async initDefaultService(): Promise<void> {
    if (this.initPromise) {
      return this.initPromise;
    }

    if (this.renderTypeFromDefaultService$.value) {
      return Promise.resolve();
    }

    this.initPromise = this.doInitDefaultService();
    return this.initPromise;
  }

  public getPreviousPage(): string | null {
    const path = this.previousPath;
    const previousPage = path ? `${window.location.origin}${path}` : '';
    return previousPage;
  }

  private async doInitDefaultService(): Promise<void> {
    try {
      const res = await this.fetchRenderTypeFromDefaultService();
      if (res) {
        this.renderTypeFromDefaultService$.next(res);
        this.renderType$.next(res);
      }
    } catch (error) {
      console.error('Failed to initialize RouteTrackerService:', error);
    } finally {
      this.initPromise = null;
    }
  }

  private async fetchRenderTypeFromDefaultService(): Promise<EnumMagFulfillmentManagementRenderType> {
    try {
      const isAdjust = toBoolean(await firstValueFrom(this.appSettingsService.getSettingValue('adjust_ui_temporary')));
      if (isAdjust) {
        return EnumMagFulfillmentManagementRenderType.Common;
      }

      const allService = await firstValueFrom(this.storeService.getStoreSystemServices());
      if (!allService || allService.length === 0) {
        console.warn('No store system services found');
        return EnumMagFulfillmentManagementRenderType.Common;
      }

      const defaultSvc = allService.find((ser) => isAttValueTrue(ser.SettingAttributes?.is_default_shop_path?.Value));
      if (!defaultSvc) {
        console.warn('Default service not found');
        return EnumMagFulfillmentManagementRenderType.ShoppingList;
      }

      const { Value } = defaultSvc.SettingAttributes.is_available_for_checkout;
      return isAttValueTrue(Value)
        ? EnumMagFulfillmentManagementRenderType.Cart
        : EnumMagFulfillmentManagementRenderType.ShoppingList;
    } catch (error) {
      console.error('Error fetching render type from default service:', error);
      return null;
    }
  }

  public async checkIsAvaiableCheckoutProductSvc(product: IMagProductRes): Promise<boolean> {
    try {
      if (!product?.Stores?.[0]?.Services?.[0]?.ServiceId) {
        console.warn('Product service information is missing');
        return false;
      }

      const currentStore = await this.cStore.getStore();
      if (!currentStore?.StoreServices) {
        console.warn('Current store services not found');
        return false;
      }

      const currentService = currentStore.StoreServices.find(
        (service) => service?.ServiceId === product.Stores[0].Services[0].ServiceId
      );

      if (!currentService?.SettingAttributes?.is_available_for_checkout?.Value) {
        return false;
      }

      return isAttValueTrue(currentService.SettingAttributes.is_available_for_checkout.Value);
    } catch (error) {
      console.error('Error checking checkout availability:', error);
      return false;
    }
  }

  public getRenderType(): Observable<EnumMagFulfillmentManagementRenderType | null> {
    return this.ensureInitializedDefaultService(this.renderType$);
  }

  public getRenderTypeFromDefaultService(): Observable<EnumMagFulfillmentManagementRenderType | null> {
    return this.ensureInitializedDefaultService(this.renderTypeFromDefaultService$);
  }

  private ensureInitializedDefaultService<T>(source$: BehaviorSubject<T>): Observable<T> {
    if (source$.value) {
      return source$.asObservable();
    }

    return from(this.initDefaultService()).pipe(
      switchMap(() => source$.asObservable()),
      catchError((error) => {
        console.error('Error in ensureInitializedAndGetData:', error);
        return source$.asObservable();
      })
    );
  }

  ngOnDestroy(): void {
    this.destroy$.next();
    this.destroy$.complete();
  }
}
