  async init() {
    this.tenantSettings = await this.tenantSettingsStore.getTenantSettings();
    const trackingMatomoObs = this.appSettingsService.getSettingsByPatch('TRACKING').subscribe((settings) => {
      const getSetting = (name: string) => find(settings, { SettingName: name })?.SettingValue;

      this.EnableMatomo = getSetting('tracking_matomo') === 'true';

      if (!this.EnableMatomo) return;

      try {
        const url = getSetting('tracking_matomo_url');
        const siteJson = getSetting('tracking_matomo_sites');
        const siteId = siteJson ? JSON.parse(siteJson)?.[0]?.id : null;

        if (!url || !siteId) return;

        // https://github.com/Arnaud73/ngx-matomo/issues/28
        // https://github.com/matomo-org/matomo/issues/15229
        (window as any)?.['_paq'].push(['HeatmapSessionRecording::disable']);

        this.matomoInitializer.initializeTracker({
          scriptUrl: `${url}/1338.js`,
          trackerUrl: `${url}/1338.php`,
          siteId,
        });

        this.cre.getRsSessionId();
        this.trackInstallGoal();
        this.registerEvent();
      } catch (error) {
        console.error('Matomo initialization error:', error);
      }
    });
    this.subscriptions.push(trackingMatomoObs);
    const obsSaveToken = this.events.subscribe(enumTrackAction.SaveToken, async ({ options }) => {
      await this.saveToken(options);
    });
    this.subscriptions.push(obsSaveToken);
  }

