  async trackPage(pageName: any, url?: any) {
    if (Capacitor.isNativePlatform()) {
      FirebaseAnalytics.setCurrentScreen({
        screenName: pageName,
        screenClassOverride: pageName,
      })
        .then()
        .catch((err) => {
          console.error('Error tracking view:', pageName, err);
        });
    }

    await this.checkCookieConsentPermission();

    if (this.EnableMatomo && this.isActivePerformanceCookie) {
      try {
        const dynamicEnv = await firstValueFrom(this.environmentService.getDynamicEnvironment());
        url = url || window.location.pathname;
        this.matomoTracker.setCustomUrl('http://' + dynamicEnv.appBundle + url);
        // let serviceType = "";
        // if (url.indexOf('online-order') > -1) {
        // 	serviceType = 'OnlineOrder';
        // }
        this.matomoTracker.trackPageView(pageName);
      } catch (error) {
        console.error('trackPage', error);
      }
    }
  }

  async trackEcommerceOrder(order) {
    await this.checkCookieConsentPermission();

    if (!this.EnableMatomo || !this.isActivePerformanceCookie || !order) {
      return;
    }
    try {
      const { Orders, OrderId } = order;
      const { Summary } = Orders?.[0]?.CartSummary || {};
      const { TotalWithSavings, SubTotal, TaxTotal, PickedFee, ServiceFee, Savings } = Summary || {};
      const shippingFee = (ServiceFee || 0) + (PickedFee || 0);

      await this.matomoTracker.trackEcommerceOrder(
        OrderId,
        TotalWithSavings,
        SubTotal,
        TaxTotal,
        shippingFee,
        Savings?.TotalSavings
      );
    } catch (error) {
      console.error('trackEcommerceOrder', error);
    }
  }

