  trackProductView(product) {
    if (!this.EnableMatomo || !this.isActivePerformanceCookie || !product) {
      return;
    }
    try {
      const category = product?.Categories?.map((category) => category?.CategoryName);
      const price = Number.parseFloat(product?.DisplayPrice?.replace('$', ''));
      this.matomoTracker.setEcommerceView(product?.Upc, product?.Name?.['En'], category, price);
      this.matomoTracker.trackPageView(`ProductDetailPage - ${product?.Name}`); // Calling trackPageView is required when tracking a product view
    } catch (error) {
      console.error('trackProductView', error);
    }
  }

