  async saveToken(opts) {
    const dynamicEnv = await firstValueFrom(this.environmentService.getDynamicEnvironment());
    const obj = {
      Udid: this.utils.deviceId,
      AppName: this.tenantSettings?.appName,
      AppVersion: ENV.AppVersion,
      CompanyId: 1,
      Platform: this.utils.deviceInfo.platform,
      PlatformVersion: this.utils.deviceInfo.osVersion,
      Device: this.utils.deviceInfo.model,
      Notification: opts.Notification,
      ApplicationId: dynamicEnv.appBundle,
      DeviceToken: opts.DeviceToken,
      UserName: opts.UserName,
      TenantId: dynamicEnv.tenantId,
      NotificationOptIn: true,
      CustomerCode: (await this.cre.getCurrentUser())?.CustomerCode,
    };
    const location: any = await this.utils.getCurrentPosition();
    if (location.isLocationOn) {
      Object.assign(obj, { Latitude: location.lat, Longtitude: location.lng });
    }
    return firstValueFrom(this.magEComCoreApiHttpClient.post('/central-list/v1.0/api/UserDevice/add', obj));
  }

  // another detail trackGoal
  async trackInstallGoal() {
    if (this.EnableMatomo) {
      try {
        const appVersion = await this.cache.getItem('app_version').catch(() => {
            return null;
          }),
          cacheTime = 60 * 60 * 24 * 365; // 365 days = year
        // refresh cache time and save new app version
        this.cache.saveItem('app_version', ENV.AppVersion, null, cacheTime);
        if (appVersion === ENV.AppVersion) {
          return;
        }
        this.trackEvent('System', 'Install', ENV.AppVersion, 1);
      } catch (error) {
        console.error('trackInstallGoal', error);
      }
    }

    // this.trackGoal(1, ENV.AppVersion);
    // this.trackEvent('System', 'Install', ENV.AppVersion, 1);
  }

  ngOnDestroy() {
    this.subscriptions.forEach((s) => {
      s.unsubscribe();
    });
  }

  private checkCookieConsentPermission() {
    this.isActivePerformanceCookie = false;

    return new Promise((resolve) => {
      const cookieConsent = CookieConsentManager.getInstance();
      if (!cookieConsent) {
        resolve(false);
        return;
      }

      cookieConsent.hasConsent('C0002', null, (hasConsent) => {
        this.isActivePerformanceCookie = hasConsent;
        resolve(hasConsent);
      });
    });
  }
