import { cloneDeep, groupBy } from 'lodash';
import { IMagStoreServiceAttributes, IStore, IStoreService } from '../interfaces/store.interface';
import { EnumServiceAttributeKey } from '@rsApp/core/enum';
import * as moment from 'moment-timezone';

export interface IStoreNearByPayload {
  latitude: number;
  longitude: number;
  zipcode?: string | number;
}

export const DEFAULT_SHOP_PATH = 'grocery';

export const transformSystemServices = (services): IMagStoreServiceAttributes[] => {
  if (services.length) {
    const items: any[] = services.map((service) => {
      const { Attributes } = service;
      const defaultValue = { ...service, SettingAttributes: null };
      if (!Attributes.length) return defaultValue;
      const attKeys = Object.values(EnumServiceAttributeKey);
      const transformAtt = Attributes.reduce((obj: any, att) => {
        const _att = cloneDeep(att);
        delete _att.Name;
        if (attKeys.includes(att.Name)) {
          Object.assign(obj, { [att.Name]: { ..._att, Value: _att?.Values?.length ? _att?.Values[0] : '' } });
        }
        return obj;
      }, {});
      return { ...service, SettingAttributes: transformAtt };
    });
    return items;
  }
  return [];
};

export const transformStore = (store): IStore => {
  const { StoreServices } = store;
  const defaultValue = { ...store, StoreServices: [] };
  if (!StoreServices.length) return defaultValue;
  const attKeys = Object.values(EnumServiceAttributeKey);
  const _storeServices: IStoreService[] = StoreServices?.map((svc) => {
    const transformAtt = svc?.Attributes?.reduce((obj, att) => {
      const _att = cloneDeep(att);
      delete _att.Name;
      if (attKeys.includes(att.Name)) {
        Object.assign(obj, { [att.Name]: { ..._att, Value: _att?.Values?.length ? _att?.Values[0] : '' } });
      }
      return obj;
    }, {});
    return { ...svc, SettingAttributes: transformAtt };
  });
  return { ...store, StoreServices: _storeServices };
};

export const isAttValueTrue = (str) => /^true$/i.test(str);
export const isAttValueFalse = (str) => /^false$/i.test(str);

export const getInStoreServices = (services) => {
  return groupBy(services, (item) => item.ServiceGroup || 'Additional Store Services');
};

export const getCurrentDayInTimezone = (timezone) => {
  return moment.utc().tz(timezone).format('dddd');
};

export const getPhoneNumber = (phone) => {
  return phone.replace('(', '').replace(')', '').replace(' ', '-');
};

export const getStoreHour = (zone, storeInfo) => {
  const currentDay = getCurrentDayInTimezone(zone);
  const hour = currentDay && storeInfo?.WorkingDay?.find((item) => item.DayName == currentDay);
  return hour;
};
