import { Injectable } from '@angular/core';
import { ActivatedRouteSnapshot, CanActivate, Router, UrlTree } from '@angular/router';
import { AuthService } from '../../auth-v2/providers/auth-v2.service';
import { TenantSettingsStore } from '@rsApp/modules/utils/providers/tenant-settings.service';
import { Observable, of, switchMap, take, from, map, catchError } from 'rxjs';

@Injectable({
  providedIn: 'root',
})
export class GuestGuardService implements CanActivate {
  constructor(
    public authService: AuthService,
    public router: Router,
    public tenantSettingsStore: TenantSettingsStore
  ) {}

  canActivate(next: ActivatedRouteSnapshot): Observable<boolean | UrlTree> {
    return from(this.tenantSettingsStore.getGuestModeSetting()).pipe(
      switchMap((setting) => {
        const isSupportGuestMode = setting?.SettingValue === 'true';
        if (isSupportGuestMode) {
          return of(true);
        }
        // not yet login, redirect to login page
        const backUrl = (<any>next)._routerState.url;
        return this.authService.getCurrentUser().pipe(
          take(1),
          map((user) => (user ? true : this.router.createUrlTree(['/sign-in', { returnRoute: backUrl }])))
        );
      }),
      catchError(() => {
        return of(this.router.createUrlTree(['/sign-in']));
      })
    );
  }
}
