import { Component, OnInit } from '@angular/core';
import { ActivatedRoute, NavigationEnd, Router } from '@angular/router';
import { firstValueFrom } from 'rxjs';
import { Credential } from '@rsApp/modules/auth-v2/providers/credential.service';
import { User } from '../../providers/user.service';
import { MagModalConfirmComponent } from '@rsApp/components/mag-confirm-modal/mag-modal-confirm';
import { ModalController } from '@ionic/angular';
import { ToastService } from '@rsApp/components/toast.service';
import { IMagToastOptions } from '@rsApp/components/interface';
import { TranslateService } from '@ngx-translate/core';
@Component({
  selector: 'mag-address-accordion',
  templateUrl: './mag-address-accordion.html',
  styleUrls: ['./mag-address-accordion.scss'],
})
export class MagAddressAccordionComponent implements OnInit {
  // Address list containers
  addressList: any;
  deliveryBillingAddresses: any;
  nonDeliveryBillingAddresses: any;
  isForcePhoneVerify: boolean = false;

  // Type (can be used for context switching or filtering UI)
  type: string;

  constructor(
    public route: ActivatedRoute,
    private router: Router,
    private userService: User,
    private cre: Credential,
    private modalCtrl: ModalController,
    private toastService: ToastService,
    private translate: TranslateService
  ) {
    // Reload address list on route change (only if returning to /my-account)
    this.router.events.subscribe(async (event) => {
      if (event instanceof NavigationEnd && event.urlAfterRedirects === '/tabs/my-account') {
        await this.loadAddress();
      }
    });
  }

  // Angular lifecycle hook
  async ngOnInit() {
    await this.loadAddress();
    this.checkIsForceVerifyPhone();
  }

  /**
   * Fetches and formats the list of addresses for the current user
   */
  async loadAddress() {
    try {
      const data: any = await firstValueFrom(this.userService.getAddresses(this.cre.currentUser.UserId));
      if (!data?.length) {
        this.addressList = [];
        this.deliveryBillingAddresses = [];
        this.nonDeliveryBillingAddresses = [];
        return;
      }

      this.addressList = data.map((address) => ({
        ...address,
        Phone: this.formatPhone(address.Phone),
        isVerified: address.IsBilling,
      }));

      this.deliveryBillingAddresses =
        this.addressList.filter(({ IsBilling, IsDelivery }) => IsBilling || IsDelivery) || [];
      this.nonDeliveryBillingAddresses =
        this.addressList.filter(({ IsBilling, IsDelivery }) => !IsBilling && !IsDelivery) || [];
    } catch (error) {
      console.warn('Failed to load address list', error);
      this.addressList = [];
      this.deliveryBillingAddresses = [];
      this.nonDeliveryBillingAddresses = [];
    }
  }

  /**
   * Formats phone number into (123) 456-7890
   */
  formatPhone(phone: string): string {
    const digits = phone.replace(/\D/g, '').substring(0, 10);
    if (digits.length < 10) return phone;
    return `(${digits.substring(0, 3)}) ${digits.substring(3, 6)}-${digits.substring(6)}`;
  }

  /**
   * Handles actual deletion of address from server
   */
  async performRemove(contactId: string) {
    // Toast configuration for address removal
    const toastRemoveAddressConfig: IMagToastOptions = {
      message: this.translate.instant('toast.deletedAddressSuccess'), // TODO: Update message if needed
      type: 'success',
    };
    try {
      const rs = await firstValueFrom(this.userService.removeAddressById(contactId));
      if (rs) {
        await this.loadAddress();
        this.toastService.create(toastRemoveAddressConfig);
      }
    } catch (error) {
      console.warn('Failed to remove address', error);
    }
  }

  /**
   * Opens a confirmation modal before address deletion
   */
  async openConfirmModal(address: any) {
    const modal = await this.modalCtrl.create({
      component: MagModalConfirmComponent,
      componentProps: {
        title: this.translate.instant('accountInfo.removeAddress'),
        description: this.translate.instant('accountInfo.confirmDeleteAccount'),
        confirmTitle: this.translate.instant('accountInfo.yesDeleteAccount'),
        cancelTitle: this.translate.instant('accountInfo.noDeleteAccount'),
      },
      cssClass: 'mag-confirm-modal',
    });

    modal.onDidDismiss().then(async (result) => {
      if (result.data) {
        await this.performRemove(address.CS_ContactID);
      }
    });

    await modal.present();
  }

  /**
   * Triggered when remove action is initiated from UI
   */
  async removeAddress(address?: any) {
    await this.openConfirmModal(address);
  }

  /**
   * Handles user actions for address card
   */
  handleAction(actionType: 'add' | 'edit' | 'remove', data?: any) {
    switch (actionType) {
      case 'add':
      case 'edit':
        this.router.navigate(['/tabs/my-account/address'], {
          state: { actionType, address: JSON.stringify(data) },
        });
        break;
      case 'remove':
        this.removeAddress(data);
        break;
    }
  }

  private async checkIsForceVerifyPhone() {
    this.isForcePhoneVerify = (await this.cre.getCurrentUser())?.IsForceVerifyPhone || false;
  }
}
