import { Component, OnDestroy, OnInit } from '@angular/core';
import { FormBuilder, Validators, FormGroup } from '@angular/forms';
import { ActivatedRoute, Router } from '@angular/router';
import { firstValueFrom, Subject, takeUntil } from 'rxjs';
import { AuthService } from '@rsApp/modules/auth-v2/providers/auth-v2.service';
import { TenantSettingsStore } from '@rsApp/modules/utils/providers/tenant-settings.service';
import { ITenantSettings } from '@rsApp/modules/utils/models/app-settings.model';
import { Credential } from '@rsApp/modules/auth-v2/providers/credential.service';
import { IMagToastOptions } from '@rsApp/components/interface';
import { ToastService } from '@rsApp/components/toast.service';
import { UserActionField } from '../../utils/enum';
import { enumInternalCode, IResponse } from '@rsApp/modules/auth-v2/utils/interface';
import { Utils } from '@rsApp/modules/utils/providers/utils';
import { TranslateService } from '@ngx-translate/core';
import { GlobalRegex } from '@rsApp/modules/utils/enum/enum';
import { EmailValidator } from '@rsApp/modules/utils/validator/email-validator-v2';
import { IUser } from '@rsApp/modules/interfaces/user.interface';
import { PasswordValidator } from '@rsApp/modules/utils/validator/password-validator-v2';

@Component({
  selector: 'security-settings',
  templateUrl: './security-settings.html',
  styleUrls: ['./security-settings.scss'],
})
export class SecuritySettingsComponent implements OnDestroy, OnInit {
  // Forms
  updateEmailForm: FormGroup;
  updatePasswordForm: FormGroup;

  // Current action context
  actionType: string;
  dataSource: any;
  user: IUser;
  returnRoute: string;

  // Application config
  tenantSettings: ITenantSettings;

  // Expose enum to template
  UserActionField = UserActionField;
  title: string;

  // Toast for success message

  isLoading: boolean = false;
  private _destroy$: Subject<boolean> = new Subject();

  constructor(
    public route: ActivatedRoute,
    public router: Router,
    private fb: FormBuilder,
    private authService: AuthService,
    private tenantSettingsStore: TenantSettingsStore,
    public cre: Credential,
    private toastService: ToastService,
    public utils: Utils,
    private translate: TranslateService,
    public emailValidator: EmailValidator,
    public passwordValidator: PasswordValidator
  ) {
    // Initialize forms
    this.updateEmailForm = this.fb.group({
      currentEmail: ['', [Validators.required, Validators.pattern(GlobalRegex.EMAIL)]],
      newEmail: [
        '',
        {
          validators: [Validators.required, Validators.pattern(GlobalRegex.EMAIL)],
          asyncValidators: [this.emailValidator.emailValidator()],
        },
      ],
      currentPassword: ['', [Validators.required]],
    });

    this.updatePasswordForm = this.fb.group({
      currentPassword: ['', [Validators.required]],
      newPassword: ['', [Validators.required, this.passwordValidator.passwordValidator()]],
      reEnterPassword: ['', [Validators.required]],
    });

    // Get action type from route state
    const payload = this.router.getCurrentNavigation()?.extras?.state;
    this.actionType = payload?.actionType;
    this.title = this.actionType === 'changeEmail' ? 'accountInfo.email' : 'accountInfo.password';
    this.returnRoute = payload?.returnRoute;
  }

  /**
   * Lifecycle hook
   */
  async ngOnInit() {
    this.tenantSettings = await this.tenantSettingsStore.getTenantSettings();

    this.authService
      .authState()
      .pipe(takeUntil(this._destroy$))
      .subscribe((user) => {
        if (user) {
          this.user = user;
          this.updateEmailForm.get('currentEmail')?.setValue(user.Email);
        }
      });
  }

  ngOnDestroy(): void {
    this._destroy$.next(true);
    this._destroy$.complete();
  }
  /**
   * Sends OTP to new email for verification
   */
  async sendOtp(): Promise<any> {
    try {
      const email = this.updateEmailForm.value.newEmail;
      const response = await firstValueFrom(this.authService.sendOtp(email, this.tenantSettings?.bannerId));
      return response;
    } catch (error) {
      console.error('Failed to send OTP:', error);
      return null;
    }
  }

  /**
   * Navigates to OTP verification screen with required data
   */
  async verifyEmail() {
    const otpResponse = await this.sendOtp();
    if (!otpResponse) {
      console.warn('OTP sending failed');
      return;
    }
    this.router.navigate(['/verify-otp'], {
      state: {
        accountInfo: {
          userIdentifier: this.updateEmailForm.value.newEmail,
          password: this.updateEmailForm.value.currentPassword,
          currentIdentifier: this.updateEmailForm.value.currentEmail,
        },
        actionType: 'changeEmail',
        isUserDiferenceEmail: true,
      },
    });
  }

  async validatePassword(): Promise<boolean> {
    const passwordControl = this.updateEmailForm.get('currentPassword');
    try {
      this.isLoading = true;
      const isValid = await firstValueFrom(this.authService.validatePassword(passwordControl.value));
      if (!isValid) {
        passwordControl.setErrors({ failedAttempt: true });
        return false;
      }
      return isValid;
    } catch (error) {
      console.warn('Password validation failed', error);
      return false;
    } finally {
      this.isLoading = false;
    }
  }

  /**
   * Handles email update flow
   */
  async handleChangeEmail() {
    if (this.updateEmailForm.invalid) {
      this.updateEmailForm.markAllAsTouched();
      return;
    }
    const validPassword = await this.validatePassword();
    if (!validPassword) {
      console.warn('Password validation failed');
      return;
    }
    this.router.navigate(['/tabs/my-account/security/verify-otp'], {
      state: {
        email: this.updateEmailForm?.value?.newEmail,
      },
    });
  }

  syncUserData(user: IUser) {
    if (user.IsForceUpdatePassword) {
      user.IsForceUpdatePassword = false;
      this.authService.setCurrentUser(user);
      this.cre.setCurrentUser(user);
    }
  }

  /**
   * Updates user password via API
   */
  async updatePassword() {
    try {
      const toastChangePasswordConfig: IMagToastOptions = {
        message: this.translate.instant('toast.passwordUpdateSuccess'),
        type: 'success',
      };
      const result = await firstValueFrom(
        this.authService.updatePassword({
          Email: this.user?.Email,
          OldPassword: this.updatePasswordForm.value.currentPassword,
          NewPassword: this.updatePasswordForm.value.newPassword,
        })
      );
      if (!result) return;
      this.syncUserData(this.user);
      this.toastService.create(toastChangePasswordConfig);
      this.router.navigate(['/tabs/my-account'], { replaceUrl: true });
    } catch (exception) {
      const { error }: { error: IResponse } = exception;
      if (!error || (!error?.Status && error?.InternalCode === enumInternalCode.currentPasswordInvalid))
        return this.currentPasswordInvalid();
    }
  }

  currentPasswordInvalid() {
    const control = this.updatePasswordForm.get('currentPassword');
    return control.setErrors({ failedAttempt: true });
  }

  passwordNotMatch() {
    const control = this.updatePasswordForm.get('reEnterPassword');
    return control.setErrors({ mismatchPassword: true });
  }

  /** TODO
   * Validates and initiates password update
   */
  async handleChangePassword() {
    if (this.updatePasswordForm.invalid) {
      return this.updatePasswordForm.markAllAsTouched();
    }

    // Optionally add matching check for password fields
    const { newPassword, reEnterPassword } = this.updatePasswordForm.value;
    if (newPassword !== reEnterPassword) return this.passwordNotMatch();
    this.isLoading = true;
    await this.updatePassword();
    this.isLoading = false;
  }

  /**
   * Unified save handler based on action type
   */
  onSave() {
    switch (this.actionType) {
      case 'changeEmail':
        this.handleChangeEmail();
        break;
      case 'changePassword':
        this.handleChangePassword();
        break;
    }
  }

  /**
   * Navigates back to My Account
   */
  back() {
    if (this.returnRoute) {
      this.router.navigate([this.returnRoute]);
    } else {
      this.router.navigate(['/tabs/my-account']);
    }
  }
}
