import { Component, ViewEncapsulation } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { ModalController } from '@ionic/angular';
import { NgxPubSubService } from '@pscoped/ngx-pub-sub';
import { enumStoreId } from '@rsApp/core/enum';
import { AuthService } from '@rsApp/modules/auth-v2/providers/auth-v2.service';
import { Credential } from '@rsApp/modules/auth-v2/providers/credential.service';
import { GoogleAnalyticTracker } from '@rsApp/modules/utils/providers/google-tracker.service';
import { Utils } from '@rsApp/modules/utils/providers/utils';
import { CacheService } from 'ionic-cache';
import { BaseStore } from '../../base-store';
import { CurrentStore } from '../../providers/current-store.service';
import { StoreService } from '../../providers/store.service';

@Component({
  selector: 'page-near-store',
  templateUrl: 'near-store.html',
  styleUrls: ['./near-store.scss', '../../styles/store-list.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class NearStorePageComponent extends BaseStore {
  searchbar: string;
  limitedQuantity: any;
  isPickupDelivery = false;
  storeListLength: any;

  returnRoute: string;
  defaultHref: string;
  btnFillInstore = 'outline';
  btnFillOnline = 'outline';
  listStore: any[] = [];
  keyword;

  serviceList: any;

  constructor(
    public utils: Utils,
    public auth: AuthService,
    public cStore: CurrentStore,
    public modalCtrl: ModalController,
    public router: Router,
    public store: StoreService,
    public route: ActivatedRoute,
    public cache: CacheService,
    public cri: Credential,
    public events: NgxPubSubService,
    public googleTracking: GoogleAnalyticTracker
  ) {
    super(utils, cStore, router, cache, store, cri, events, googleTracking);
    const params = this.route.snapshot.paramMap;
    this.returnRoute = params.get('returnRoute');
    this.defaultHref = params.get('defaultHref');
  }

  async ionViewWillEnter() {
    await super.getCurrent();
    this.initSelectedStore();
    await this.loadData();
    /*
    if(!this.currentStore && (!this.listStore || this.listStore.length === 0) ){
      this.viewMoreStore();
      return false;
    }
    */
    return true;
  }

  async loadData() {
    this.keyword =
      (this.currentUser && this.currentUser.ZipCode) || (this.currentStore && this.currentStore.Zipcode) || '';
    const stores = await this.searchStores();
    this.listStore = stores;
  }

  async searchStores() {
    try {
      await this.utils.showLoading();
      let stores: any = [];

      const position = await this.utils.getCurrentPosition();

      if (position && position.isLocationOn) {
        stores = await this.store.getStoreNearByOld(position.lat + ',' + position.lng).toPromise(); // TODO
      } else if (this.keyword) {
        stores = await this.store.searchStores(this.keyword, 'l').toPromise();
      }
      this.utils.hideLoading();
      if (stores !== null) {
        const listStore = [];
        stores.every((s) => {
          if (
            s.CS_BannerID !== enumStoreId.UnitedExpress &&
            (!this.currentStore || (this.currentStore && this.currentStore.StoreCode !== s.StoreCode))
          ) {
            // s.StoreType = this.cStore.displayStoreType(s); TODO
            listStore.push(s);
          }
          if (listStore.length === 3) return false;
          return true;
        });
        return listStore;
      }
      return [];
    } catch (error) {
      console.error(error);
      this.utils.hideLoading();
      return [];
    }
  }

  closer() {
    this.router.navigate([this.returnRoute]);
  }

  async initSelectedStore() {
    // const storePath = null;
    if (this.cStore.store) {
      // storePath = this.cStore.store.ShopPath && this.cStore.store.ShopPath.toLowerCase();
      this.serviceList = this.cStore.currentSystemService;
    }
    // if (this.currentUser && this.currentUser.ShopPath) {
    //   storePath = this.currentUser.ShopPath.toLowerCase();
    // } else if (this.cStore.store) {

    //   storePath = this.cStore.store.ShopPath && this.cStore.store.ShopPath.toLowerCase();
    //   this.serviceList = this.cStore.store.SystemService;
    // }
    // this.selectStorePath(storePath);
  }

  viewMoreStore() {
    if (this.returnRoute) {
      this.router.navigate(['/store/find', { router: this.returnRoute }]);
    } else {
      this.router.navigate(['/store/find']);
    }
  }
  public getPageName() {
    return 'NearStorePage';
  }
  // not use any more
  /*
  selectStorePath(path) {
    if (path === "online") {
      this.btnFillOnline = "solid";
      this.btnFillInstore = "outline";
    }
    else if (path === "instore") {
      this.btnFillInstore = "solid";
      this.btnFillOnline = "outline";
    }
  }
  */
}
