import {
  Injectable,
  Component,
  CUSTOM_ELEMENTS_SCHEMA,
  ElementRef,
  ViewChild,
  OnInit,
  AfterViewChecked,
} from '@angular/core';
import { Router, CanActivate, UrlTree } from '@angular/router';
import { firstValueFrom, from, Observable, of } from 'rxjs';
import { map, catchError, timeout, switchMap } from 'rxjs/operators';
import { Platform, AlertController } from '@ionic/angular';
import { Utils } from '@rsApp/modules/utils/providers/utils';
import { ENV } from '@app/env';
import { ModalController } from '@ionic/angular';
import { AppSettings } from '@rsApp/modules/utils/providers/app-setting';
import { TenantSettingsStore } from '@rsApp/modules/utils/providers/tenant-settings.service';
import { CookieConsentService } from '@rsApp/modules/utils/providers/cookie-consent.service';
import { Capacitor } from '@capacitor/core';

@Injectable({
  providedIn: 'root',
})
export class IsOutDateGuardService implements CanActivate {
  constructor(
    public appSetting: AppSettings,
    public router: Router,
    public platform: Platform,
    public alertCtrl: AlertController,
    public utils: Utils,
    public modalCtrl: ModalController,
    private tenantSettingsStore: TenantSettingsStore,
    private cookieConsentService: CookieConsentService
  ) {}
  canActivate(): Observable<boolean | UrlTree> | Promise<boolean | UrlTree> | boolean | UrlTree {
    if (!Capacitor.isNativePlatform()) return true;
    const s = from(this.tenantSettingsStore.getTenantSettings()).pipe(
      timeout(3000),
      switchMap(async (settings) => {
        const bannerId = (await settings)?.bannerId || 10008;
        return firstValueFrom(this.appSetting.getLastVersion(bannerId));
      }),
      map((rs: any) => {
        let isActive = true;
        const buidNumber = parseInt(ENV.BuildNumber) || 600000;
        let device = null;
        if (this.platform.is('ios')) {
          device = 'IOS';
        } else if (this.platform.is('android')) {
          device = 'Android';
        }
        if (!device) {
          this.cookieConsentService.emitForce(false);
          return isActive;
        }
        const platformSetting = rs.Device.find((el) => el.DeviceName == device);
        if (!platformSetting) {
          this.cookieConsentService.emitForce(false);
          return isActive;
        }

        const globalBuildNumber = parseInt(platformSetting.Version) || 0;
        if (buidNumber < globalBuildNumber) {
          this.showOutDate(platformSetting);
          this.cookieConsentService.emitForce(true);
        } else {
          isActive = true;
          this.cookieConsentService.emitForce(false);
        }
        return isActive;
      }),

      map((isActive) => {
        return isActive;
      }),
      catchError(() => {
        return of(true);
      })
    );
    return s;
  }

  async showOutDate(platformSetting) {
    const imgUrls = await firstValueFrom(this.appSetting.getSettingValue('image_force_update'));
    const m = await this.modalCtrl.create({
      component: OutDateModalComponent,
      componentProps: { platformSetting, imgUrls },
    });

    m.onDidDismiss().then(() => {
      const buidNumber = parseInt(ENV.BuildNumber) || 600000;
      const globalBuildNumber = parseInt(platformSetting.Version) || 0;
      if (buidNumber < globalBuildNumber) {
        this.showOutDate(platformSetting);
      }
    });

    m.present();
  }
}

@Component({
  selector: 'page-outdate',
  template: `
    <ion-content class="ion-padding-horizontal outdate-content" #outDate>
      <h1>We've made some<br />improvements in our App</h1>
      <p>Use the link below to get the latest update.</p>
      <ion-button class="update-now-btn" (click)="clickUpdate()">UPDATE NOW</ion-button>
    </ion-content>
  `,
  styles: [
    `
      .outdate-content {
        text-align: center;
        --padding-top: var(--safe-area-inset-top);
      }
      .outdate-content ion-button {
        position: absolute;
        left: 50%;
        margin-left: -60px;
        width: 120px;
        bottom: 100px;
        --background: var(--mag-color-surface-button-filled-brand, #008000);
      }
    `,
  ],
  standalone: true,
  schemas: [CUSTOM_ELEMENTS_SCHEMA],
})
export class OutDateModalComponent implements OnInit, AfterViewChecked {
  platformSetting: any;
  imgUrls: string;
  public loaded: boolean = true;

  @ViewChild('outDate') outDate!: ElementRef<HTMLDivElement>;

  constructor(public utils: Utils) {}
  ngOnInit() {
    if (!this.platformSetting) return;
  }
  ngAfterViewChecked() {
    if (this.loaded && this.outDate) {
      this.loaded = false;
      const elm = this.outDate.nativeElement;
      elm?.setAttribute('style', `--background: white url(${this.imgUrls}) no-repeat center/cover`);
    }
  }
  clickUpdate() {
    this.utils.openInSystem(this.platformSetting.AppLink);
  }
}
