import { Component, OnDestroy, OnInit, ViewChild } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { MagOtpActionType } from '@rsApp/components/interface';
import { MagAppBottomSheetComponent } from '@rsApp/components/mag-app-bottom-sheet/mag-app-bottom-sheet';
import { AuthService } from '@rsApp/modules/auth-v2/providers/auth-v2.service';
import { Credential } from '@rsApp/modules/auth-v2/providers/credential.service';
import { firstValueFrom, Subject, takeUntil } from 'rxjs';
import { MagAccountOrderComponent } from '../mag-account-order/mag-account-order';
import { ModalController } from '@ionic/angular';
import { AppSettings } from '@rsApp/modules/utils/providers/app-setting';
import { Capacitor } from '@capacitor/core';
import { Utils } from '@rsApp/modules/utils/providers/utils';

@Component({
  selector: 'mag-security-accordion',
  templateUrl: './mag-security-accordion.html',
  styleUrls: ['./mag-security-accordion.scss'],
})
export class MagSecurityAccordionComponent implements OnInit, OnDestroy {
  // Constructor: Injecting required services
  constructor(
    public route: ActivatedRoute,
    private router: Router,
    public cre: Credential,
    private authService: AuthService,
    private modalCtrl: ModalController,
    private appSettingsService: AppSettings,
    public utils: Utils
  ) {}

  // Current user email
  userEmail: string;

  // Controls delete account logic
  isDeleteOn: boolean = false;

  // Data passed to OTP modal
  updateAccountConfig: any;
  isBiometricSupported: boolean = false;

  isVerified: boolean = false;
  deleteActionType: MagOtpActionType = MagOtpActionType.DELETE_ACCOUNT;
  isOpenConfirmPassword: boolean = false;
  // platform: EPlatform = null;
  private _destroy$: Subject<boolean> = new Subject();

  // ViewChild references for modals
  @ViewChild('bottomSheet') bottomSheetComponent!: MagAppBottomSheetComponent;
  @ViewChild('bottomSheetOtp') bottomSheetOtpComponent!: MagAppBottomSheetComponent;

  // Lifecycle hook
  async ngOnInit() {
    if (!this.cre.currentUser) return;
    const { Email, IsVerified, IsVerifiedEmail } = this.cre.currentUser;

    if (Capacitor.isNativePlatform()) {
      //TODO: defind ios/android platform
      // this.platform = Capacitor.getPlatform() as EPlatform;
      this.isBiometricSupported = await this.initWBSettings();
      // && this.platform !== null;
    }

    this.userEmail = Email;
    this.isVerified = IsVerified || IsVerifiedEmail;
    this.onAuthChange();
  }

  onAuthChange() {
    this.authService
      .authState()
      .pipe(takeUntil(this._destroy$))
      .subscribe((user) => {
        if (user) {
          this.userEmail = user?.Email;
        }
      });
  }

  ngOnDestroy() {
    this._destroy$.next(true);
    this._destroy$.complete();
  }

  async initWBSettings() {
    try {
      const value = await firstValueFrom(this.appSettingsService.getSettingValue('biometric_support'));
      return JSON.parse(value);
    } catch (err) {
      console.warn('Error fetching biometric support setting:', err);
      return false;
    }
  }

  // Action router handler
  handleAction(actionType?: string) {
    switch (actionType) {
      case 'changeEmail':
      case 'changePassword':
        this.router.navigate(['/tabs/my-account/security'], {
          state: { actionType: actionType },
        });
        break;
      case 'deleteAccount':
        this.handleDeleteAccount();
        break;
      case 'biometric':
        this.utils.openAppSettings();
    }
  }

  // Opens the delete confirmation modal
  handleDeleteAccount() {
    this.isOpenConfirmPassword = true;

    this.bottomSheetComponent.openModal();
  }

  onDismissHandle() {
    this.isOpenConfirmPassword = false;
  }

  // Handles confirmation of delete action and triggers OTP modal
  async handleConfirmDelete(confirmed: boolean) {
    if (!confirmed) return;
    this.bottomSheetComponent.closeModal();
    this.isDeleteOn = true;
    this.bottomSheetOtpComponent.openModal();
  }

  // Callback after OTP is verified
  handleVerifiedSuccess() {
    this.isDeleteOn = false;
    this.bottomSheetOtpComponent.closeModal();
    this.openDeleteAccountModal();
  }

  async openDeleteAccountModal() {
    const modal = await this.modalCtrl.create({
      component: MagAccountOrderComponent,
      componentProps: {},
    });

    await modal.present();
  }
}
