import { run, acceptedCategory, showPreferences } from 'vanilla-cookieconsent';
import { cookieConsentCdn } from '../cookie-consent.cdn';
import { ICookieConsentProvider } from '../cookie-consent.interface';
import { COOKIE_CONSENT_CATEGORIES, getCookieConsentOptions } from '../options/cookieconsent.option';

export class CookieConsentProvider implements ICookieConsentProvider {
  private language: string;
  private translation: CookieConsent.Translation;
  private isInitialized = false;
  private initializationPromise: Promise<boolean> | null = null;

  constructor(config: { language: string; translation?: CookieConsent.Translation }) {
    this.language = config.language;
    this.translation = config.translation;
  }

  initialize(callback: (categories: string[]) => void) {
    if (this.isInitialized) {
      return;
    }

    this.initializationPromise = new Promise((resolve) => {
      run({
        ...getCookieConsentOptions(this.language, this.translation),
        onFirstConsent: ({ cookie }) => {
          if (callback) {
            callback(cookie.categories || []);
          }
        },
        onChange: ({ cookie }) => {
          if (callback) {
            callback(cookie.categories || []);
          }
        },
        onConsent: ({ cookie }) => {
          if (callback) {
            callback(cookie.categories || []);
          }
        },
      });
      this.isInitialized = true;
      resolve(true);
    });

    // Load CSS dynamically
    const cssLink = document.createElement('link');
    cssLink.rel = 'stylesheet';
    cssLink.href = cookieConsentCdn.cookieconsentCss;
    document.head.appendChild(cssLink);
  }

  async waitForInitialization(): Promise<boolean> {
    if (this.isInitialized) {
      return true;
    }
    if (this.initializationPromise) {
      return this.initializationPromise;
    }
    return false;
  }

  hasConsent(categoryId: string, categories: string[], callback: (hasConsent) => void): void {
    if (categories) {
      callback(categories.some((categoryName) => COOKIE_CONSENT_CATEGORIES[categoryId] === categoryName));
      return;
    }

    const categoryName = COOKIE_CONSENT_CATEGORIES[categoryId];
    callback(acceptedCategory(categoryName));
  }

  onConsentChange(callback: (categories: string[]) => void) {
    window.addEventListener(
      'cc:onChange',
      (event: CustomEvent) => {
        callback(event.detail.cookie.categories);
      },
      { once: true }
    );
  }

  showPreferences() {
    showPreferences();
  }

  removeCookies(categories: string[]) {
    // Clear cookies for specified categories
    const cookies = document.cookie.split(';').map((c) => c.split('=')[0].trim());
    cookies.forEach((cookie) => {
      if (!this.isStrictlyNecessary(cookie) && this.isCookieInCategories(cookie, categories)) {
        document.cookie = `${cookie}=; Max-Age=-99999999; Path=/; Domain=${location.hostname}`;
      }
    });
  }

  allowShowPreferences(): boolean {
    return true;
  }

  private isStrictlyNecessary(cookie: string): boolean {
    const necessaryCookies = ['gCaptcha', 'gtm', 'cookieconsent'];
    return necessaryCookies.some((nc) => cookie.includes(nc));
  }

  private isCookieInCategories(cookie: string, categories: string[]): boolean {
    // Map cookies to categories based on configuration
    const cookieCategoryMap: { [key: string]: string[] } = {
      performance: ['_ga', '_gid', '_gat'],
      // Add other category mappings as needed
    };
    return categories.some((category) => cookieCategoryMap[category]?.some((pattern) => cookie.includes(pattern)));
  }
}
