import { RelationshopCoreHttpClient } from '@rsApp/modules/gateway/rs-api-core.service';
import { CurrentStore } from '@rsApp/modules/store/providers/current-store.service';
import { StoreService } from '@rsApp/modules/store/store.module';
import { DEFAULT_SHOP_PATH } from '@rsApp/modules/store/utils';
import { CacheVersioningService, CacheVersionModule } from '@rsApp/modules/utils/providers/cache-versioning.service';
import { refreshParam, Utils } from '@rsApp/modules/utils/providers/utils';
import { CacheService } from 'ionic-cache';
import { firstValueFrom, from, Observable, of, ReplaySubject, throwError } from 'rxjs';
import { catchError, map, switchMap, take, tap } from 'rxjs/operators';
import {
  ILoginResponse,
  IResponse,
  IValidateMembershipCodePayload,
  IValidatePromocodePayload,
  UserChangePhoneOtpRequest,
  UserOtpVerificationRequest,
  UserValidateOtpRequest,
} from '../utils/interface';
