  public sendOtpDeleteAccount(username: string, bannerId: number) {
    return this.rsApiCore.get(`/accounts/${username}/otp?bannerId=${bannerId}`, {}).pipe(
      map((rs) => rs),
      catchError(() => of(null))
    );
  }

  getUserByEmail(email): Observable<IUser> {
    return this.rsApiCore.get(`/users/get-by-email/${email}`).pipe(
      map((rs) => rs as IUser),
      catchError(() => of(null))
    );
  }

  public getUser(userId, includeExternal = false) {
    return this.rsApiCore.get('/users/get-by-id/' + userId, { params: { includeExternal: includeExternal + '' } }).pipe(
      tap((user: any) => {
        if (!user.SRCardID) {
          return;
        }
        this.updateExternalCustomerID(user).pipe(take(1)).subscribe();
      })
    );
  }

  forceChangePassword(payload) {
    return this.rsApiCore.post(`/users/set-password/`, payload);
  }

  checkPhoneExists(phone, UserId?) {
    const queryParams = UserId ? `?userid=${UserId}` : '';
    return this.rsApiCore.get(`/users/check-phone/${phone}${queryParams}`);
  }

  checkEmailExists(email, currentUsername?) {
    return this.rsApiCore.get(`/users/check-email/${email}`, { params: { un: currentUsername || '' } });
  }

  checkUserExists(userName, currentUsername?) {
    return this.rsApiCore.get(`/users/check-username/${userName}`, { params: { un: currentUsername || '' } });
  }

  public markVerifyEmail(userId) {
    return this.rsApiCore.get('/users/mark-verify-email?userid=' + userId);
  }

  public refreshUser() {
    return this.getUser(this.cre.currentUser.UserId).pipe(
      tap((user: any) => {
        this.setCurrentUser(user);
        this.cre.setCurrentUser(user);
      })
    );
  }

  getCardDemographic(userSRCardID, refresher?) {
    const params = {};
    const cacheGroup = 'reward';
    Object.assign(params, refreshParam(refresher, cacheGroup, null));
    return this.rsApiCore.get(`/Loyalty/cards/${userSRCardID}/demographic`, { params: params });
  }

  public updateExternalCustomerID(user) {
    try {
      return this.getCardDemographic(user.SRCardID).pipe(
        map((cardDemographic: any) => {
          if (cardDemographic && cardDemographic.CustomerCode) {
            user.ExternalCustomerID = cardDemographic.CustomerCode + '';
            user.Segments = cardDemographic.Segments;
          }
          return user;
        })
      );
    } catch {
      return of(null);
    }
  }

  public sendEmailVerification(username, bannerId: number) {
    return this.rsApiCore.post('/Users/email-verification?sender=' + username + '&bannerId=' + bannerId, '');
  }

  // FaceID
  public async getIsFace() {
    let value = await this.cache.getItem('isFace').catch(() => null);
    if (value === null) {
      value = true;
    }
    return value;
  }

  public setIsFace(value: any) {
    const cacheTime = 60 * 60 * 24 * 60; // 60 days
    this.cache.saveItem('isFace', value, null, cacheTime);
  }

  //Notification
  public async getNotification() {
    let value = await this.cache.getItem('setting-notification').catch(() => null);
    if (value === null) {
      value = true;
    }
    return value;
  }

  public async setNotification(value) {
    const cacheTime = 60 * 60 * 24 * 60; // 60 days x100 ~~ setting manual don't need ttl
    this.cache.saveItem('setting-notification', value, null, cacheTime);
  }

