import { Location } from '@angular/common';
import { ChangeDetectorRef, Component, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { Capacitor } from '@capacitor/core';
import { ModalController, NavController, Platform } from '@ionic/angular';
import { NgxPubSubService } from '@pscoped/ngx-pub-sub';
import { User } from '@rsApp/modules/account-v2/providers/user.service';
import { AuthService } from '@rsApp/modules/auth-v2/providers/auth-v2.service';
import { Credential } from '@rsApp/modules/auth-v2/providers/credential.service';
import { GoogleAnalyticTracker } from '@rsApp/modules/utils/providers/google-tracker.service';
import { Utils, cacheErrorHandle } from '@rsApp/modules/utils/providers/utils';
import { CacheService } from 'ionic-cache';
import { firstValueFrom } from 'rxjs';
import { CurrentStore } from '../../providers/current-store.service';
import { StoreService } from '../../providers/store.service';
import { BaseStore } from './../../base-store';

@Component({
  selector: 'page-result-find-store',
  templateUrl: 'result-find-store.html',
  styleUrls: ['./result-find-store.scss', '../../styles/store-list.scss'],
})
export class ResultFindStorePageComponent extends BaseStore implements OnInit {
  public pageTitle = 'Select a Store';
  public view = 'list'; // map|list
  public currentUser: any = null;
  public currentStore: any = null;
  public resultCount = 0;
  public filter = {
    keyword: '',
    isNearBy: false,
  };
  type = 'findStore'; // findStore|chooseStore
  stores: Array<any>;

  map: any; // google map object
  public backInfo: any; // {route: ['/singup/account'], key: 'selected-store'};
  public stopEvent = false;

  systemServices = [];
  userAddress: string;
  backRoute: string;
  nearBySortData: string = '';

  constructor(
    public router: Router,
    public route: ActivatedRoute,
    public navCtrl: NavController,
    public user: User,
    public store: StoreService,
    public cStore: CurrentStore,
    public utils: Utils,
    public modalCtrl: ModalController,
    public auth: AuthService,
    public cache: CacheService,
    public location: Location,
    public cri: Credential,
    public events: NgxPubSubService,
    public platform: Platform,
    public googleTracking: GoogleAnalyticTracker,
    public cd: ChangeDetectorRef
  ) {
    super(utils, cStore, router, cache, store, cri, events, googleTracking);
    const params = this.route.snapshot.paramMap;
    Object.assign(this.filter, {
      keyword: params.get('keyword') || '',
      isNearBy: !!params.get('isNearBy') || false,
    });
    this.view = params.get('view') || 'list';
    this.currentUser = this.cri.currentUser;
  }

  ngOnInit(): void {
    this.route.queryParams.subscribe((params) => {
      this.backRoute = params['backRoute'] || this.backRoute;
    });
  }

  async ionViewWillEnter() {
    super.getCurrent();
    const params = await this.cache.getItem('store-search-params').catch(cacheErrorHandle);
    if (params) {
      Object.assign(this.filter, params);
    }

    const back = await this.cache.getItem('store-back').catch(cacheErrorHandle);
    if (back) {
      this.backInfo = back;
    }
    await this.getStoreSystemServices();
    await this.search();
  }

  async getStoreSystemServices() {
    try {
      const res = await firstValueFrom(this.store.getStoreSystemServices(true));
      this.systemServices = res;
    } catch (error) {
      console.error('Error fetching system services', error);
    }
  }

  async getNearByPosition(): Promise<string> {
    // Default fallback value if location cannot be determined
    const fallback = 'l';

    try {
      // Attempt to get device's GPS location first
      const currentPosition = await this.utils.getCurrentPosition();
      // Check if location service is enabled and position is available
      if (currentPosition?.isLocationOn) {
        // Return formatted string with latitude and longitude from GPS
        return `latlng:${currentPosition.lat},${currentPosition.lng}`;
      }

      // Fallback: get location based on IP address
      const { location } = await this.utils.getLatLngFromIpAddress();
      if (location?.lat && location?.lng) {
        return `latlng:${location.lat},${location.lng}`;
      }

      // If neither GPS nor IP-based location is available, return default fallback
      return fallback;
    } catch (err) {
      // Catch any errors from GPS or IP location fetching
      console.warn('Failed to get location:', err);
      return fallback;
    }
  }

  configStoreData(stores) {
    this.stores = stores;
    this.resultCount = this.stores.length;
    if (this.currentStore) {
      this.stores = this.stores.filter((s) => s.StoreCode !== this.currentStore.StoreCode);
    }
  }

  async search(event = null, isNearBy = false) {
    if (event !== null && event.keyCode !== 13) {
      return;
    }
    await this.utils.showLoading();
    let sort: string = 'l';
    try {
      if (this.filter.isNearBy) {
        sort = this.nearBySortData || 'l';
      }
      //case default
      const stores = await firstValueFrom(this.store.searchStores(this.filter.keyword, sort, isNearBy));
      if (stores) {
        this.configStoreData(stores);
      }
    } catch (error) {
      console.warn('Error searching stores', error);
    } finally {
      await this.utils.hideLoading();
    }
  }

  toggleMap() {
    this.view = this.view === 'map' ? 'list' : 'map';
  }

  reset() {
    this.filter = {
      keyword: this.filter.keyword,
      isNearBy: false,
    };
  }
  async nearBy() {
    const nearyby = !this.filter.isNearBy;
    this.stopEvent = true;
    this.reset();
    this.filter.isNearBy = nearyby;
    if (nearyby) {
      // If true, fetch the nearby position (GPS first, fallback to IP, else default)
      this.nearBySortData = await this.getNearByPosition();
    } else {
      // If 'nearyby' is false, clear the 'nearBySortData' since we don't need location info
      this.nearBySortData = '';
    }
    await this.search(null, this.filter.isNearBy);
    this.stopEvent = false;
  }

  async viewMore() {
    this.reset();
    await this.cache.saveItem('store-search-params', this.filter, 'store');
    this.router.navigate(['../find'], { relativeTo: this.route });
  }

  goAppSettings() {
    if (!Capacitor.isNativePlatform()) {
      return;
    }
    this.utils.openAppSettings();
  }

  goBackPage() {
    this.navCtrl.navigateBack(this.backRoute || '/tabs/home', { replaceUrl: true });
  }

  public getPageName() {
    return 'ResultFindStorePage';
  }
}
