import { NgxGpAutocompleteOptions } from '@angular-magic/ngx-gp-autocomplete';
import { EnumCountryAddress } from '../enum/enum';

export const RegularExpression = {
  Password: /^(?=.*[A-Za-z])(?=.*\d)(?=.*[@$!%*#?&])[A-Za-z\d@$!%*#?&]{8,}$/,
  Email: /^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,4}$/i,
  PhoneNumber: /^[(]\d{3}[)] (\d{3})[-](\d{4})$/g,
  OnlyAlphabets: /^[aA-zZ]+$/,
  AddressPattern: /^[a-zA-Z0-9 .,]+$/,
  ZipPattern: /^\d{5}$/,
};

export const autoCompleteAddressOptions: NgxGpAutocompleteOptions = {
  componentRestrictions: { country: ['us'] },
  fields: ['address_components', 'geometry'],
  types: ['address'],
};

export const RegularExpressionByCountry: {
  [key: string]: {
    [key: string]: {
      regex: RegExp;
      hint: string;
    };
  };
} = {
  [EnumCountryAddress.US]: {
    address: {
      regex: /^[\w #.,;:'_/]+$/,
      hint: `Enter a string with letters, numbers, spaces, underscores, and the following characters: #, ., ,, ;, :, ' (no leading or trailing spaces).`,
    },
    zipCode: {
      regex: /^\d{5}(?:-\d{4})?$/,
      hint: `Enter a 5-digit ZIP code, optionally followed by a hyphen and 4 additional digits (e.g., 12345 or 12345-6789).`,
    },
  },
  [EnumCountryAddress.CA]: {
    address: {
      regex: /^[\w #.,;:'\-_/]+$/,
      hint: `Please enter a string containing letters, numbers, spaces, underscores, or the following characters: #, ., ,, ;, :, ', -, / (no leading or trailing spaces).`,
    },
    postalCode: {
      regex: /^[A-Za-z]\d[A-Za-z][ ]?\d[A-Za-z]\d$/,
      hint: `Enter a Canadian postal code in the format A1A 1A1 or A1A-1A1 (where A is a letter and 1 is a digit).`,
    },
  },
};

export const DEFAULT_LOCALE = 'en';
export const LOCAL_LOCALE_KEY = 'local-locale-key';
