import { Component } from '@angular/core';
import { ModalController, NavController } from '@ionic/angular';
import { Router } from '@angular/router';
import { LearnMoreComponent } from '../learn-more/learn-more';
import { NgxPubSubService } from '@pscoped/ngx-pub-sub';
import { ActionType } from '../../enum/enum';
import { ENV } from '@app/env';

@Component({
  selector: 'guest-msg',
  templateUrl: 'guest-msg.html',
  styleUrls: ['./guest-msg.scss'],
})
export class GuestMsgComponent {
  backUrl: string;
  constructor(
    public router: Router,
    // public state: ActivatedRouteSnapshot,
    public modalCtrl: ModalController,
    public navCtrl: NavController,
    public events: NgxPubSubService
  ) {
    this.backUrl = this.router.url;
  }

  public async goLogin() {
    await this.modalCtrl.dismiss(true);
    this.events.publishEvent('close-modal');
    if (ENV.DeviceMode === 'Web') {
      const payload = {
        action: ActionType.LoginWithPopupHeader,
      };
      window.postMessage(payload, window.location.origin);
    } else {
      this.navCtrl.navigateRoot(['/sign-in', { returnRoute: this.backUrl || '' }]);
    }
  }
  public async goSignup() {
    await this.modalCtrl.dismiss(true);
    this.events.publishEvent('close-modal');
    if (ENV.DeviceMode === 'Web') {
      const payload = {
        action: ActionType.viewSignUp,
      };
      window.postMessage(payload, window.location.origin);
    } else {
      this.navCtrl.navigateRoot(['/sign-up', { returnRoute: this.backUrl || '' }]);
    }
  }
  public async showLearn() {
    const m = await this.modalCtrl.create({
      component: LearnMoreComponent,
    });
    m.present();
  }
}
