import { Injectable } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { IMagToastOptions } from '@rsApp/components/interface';
import { ToastService } from '@rsApp/components/toast.service';

@Injectable({
  providedIn: 'root',
})
export class AuthUtils {
  constructor(
    private translate: TranslateService,
    private toastService: ToastService
  ) {}
  async showToast(toastSuccessConfig: IMagToastOptions) {
    return await this.toastService.create(toastSuccessConfig);
  }
  async toastCreateSuccess() {
    const toastSuccessConfig: IMagToastOptions = {
      message: this.translate.instant('toast.createAccountSuccess'),
      type: 'success',
    };
    return this.showToast(toastSuccessConfig);
  }

  async toastVerifyEmailSuccess() {
    const toastEmailVerifiedConfig: IMagToastOptions = {
      message: this.translate.instant('toast.verifyEmailSuccess'),
      type: 'success',
    };
    return this.showToast(toastEmailVerifiedConfig);
  }

  async toastVerifyAccountSuccess() {
    const toastEmailVerifiedConfig: IMagToastOptions = {
      message: this.translate.instant('toast.verifyAccountSuccess'),
      type: 'success',
    };
    return this.showToast(toastEmailVerifiedConfig);
  }
}
