import { Injectable } from '@angular/core';
import { Router, CanActivate, UrlTree } from '@angular/router';
import { Observable, of } from 'rxjs';
import { take, switchMap } from 'rxjs/operators';
import { AuthService } from '../providers/auth-v2.service';
import { MagModalConfirmComponent } from '@rsApp/components/mag-confirm-modal/mag-modal-confirm';
import { ModalController } from '@ionic/angular';

@Injectable({
  providedIn: 'root',
})
export class ForceChangePasswordGuardService implements CanActivate {
  private isModalOpen = false; // 🛡️ Modal lock

  constructor(
    private auth: AuthService,
    private router: Router,
    private modalCtrl: ModalController
  ) {}

  canActivate(): Observable<boolean | UrlTree> {
    return this.auth.getCurrentUser().pipe(
      take(1),
      switchMap((user) => (user ? this.handleCheckGuardUser(user) : of(true)))
    );
  }

  handleCheckGuardUser(user: any): Observable<boolean | UrlTree> {
    return new Observable<boolean | UrlTree>((observer) => {
      if (user?.IsPwdTemporary) {
        observer.next(this.router.createUrlTree(['/force-change-password']));
        observer.complete();
        return;
      }
      if (user?.IsForceUpdatePassword && user?.IsVerifiedEmail && user?.IsVerifiedPhone && !this.isModalOpen) {
        this.isModalOpen = true;
        setTimeout(() => {
          this.presentUpdatePasswordModal().then((confirmed) => {
            this.isModalOpen = false; // 🔓 Unlock after modal is handled
            if (confirmed) {
              this.router.navigate(['/tabs/my-account/security'], {
                state: { actionType: 'changePassword', returnRoute: '/sign-in' },
              });
            }
          });
        }, 5000);
      }
      observer.next(true);
      observer.complete();
    });
  }

  async presentUpdatePasswordModal(): Promise<boolean> {
    const modal = await this.modalCtrl.create({
      component: MagModalConfirmComponent,
      componentProps: {
        title: "We've Updated Our Password Requirements!",
        description: `To help keep your account safe and secure, we've improved our password criteria.<br><br>
        Please take a moment to update your password to continue logging in and loading savings to your myBigY account.<br><br>
        Your new password must include:<br><br>
        At least 12 characters. Both uppercase and lowercase letters. At least 1 number and at least 1 special character (like @, !, or $)<br><br>
        Thanks for helping us protect your account!`,
        confirmTitle: 'Update Password',
      },
      cssClass: 'mag-confirm-modal',
      backdropDismiss: false,
    });

    const resultPromise = modal.onDidDismiss();
    await modal.present();
    const result = await resultPromise;

    return result?.data === true;
  }
}
