import { Pipe, PipeTransform } from '@angular/core';
import { AbstractControl } from '@angular/forms';
import { TranslateService } from '@ngx-translate/core';

@Pipe({
  name: 'errorMessage',
  pure: false, // needed to reevaluate when control state changes
})
export class ErrorMessagePipe implements PipeTransform {
  constructor(private translate: TranslateService) {}

  transform(
    control: AbstractControl,
    controlName: string,
    label: string,
    context?: string,
    formName?: string
  ): string | null {
    if (!control?.errors || !control.touched) return null;

    const errors = control.errors;

    for (const suffix of Object.keys(errors)) {
      const message = this.resolveMessage(suffix, controlName, label, formName, context);
      if (message) return message;
    }
    return null;
  }

  private resolveMessage(
    suffix: string,
    controlName: string,
    label: string,
    formName: string = 'accountForm',
    context?: string
  ): string | null {
    const suffixKey = `forms.${formName}.errors.${suffix}`;
    const params = { label };
    if (['required', 'pattern'].includes(suffix)) {
      const possibleKeys = [
        context && `${suffixKey}.${context}.${controlName}`,
        context && `${suffixKey}.${context}`,
        `${suffixKey}.${controlName}`,
        `${suffixKey}.generic`,
      ].filter(Boolean) as string[];

      for (const key of possibleKeys) {
        const message = this.tryTranslate(key, params);
        if (message) return message;
      }

      return null;
    }

    // Fallback for other validation error types
    return this.tryTranslate(suffixKey, params);
  }

  private tryTranslate(key: string, params: Record<string, string> = {}): string | null {
    const value = this.translate.instant(key, params);
    return value !== key ? value : null;
  }
}
