import { Injectable } from '@angular/core';
import { IUser } from '@rsApp/modules/interfaces/user.interface';
import { CacheService } from 'ionic-cache';

@Injectable({
  providedIn: 'root',
})
export class Credential {
  public rsApiToken: string = null;
  public refreshToken: string = null;
  public rsApiSesstionId: string = null;
  public currentUser: any = null;
  public cacheTime = 60 * 60 * 24 * 7 * 24; // TTL in seconds for 24 weeks
  public extras: any = {};
  public pendingVerifyUser: string | null = null;

  public constructor(public cache: CacheService) {}
  public async getCurrentUser(): Promise<IUser> {
    if (this.currentUser) {
      return this.currentUser;
    }

    this.currentUser = await this.cache.getItem('cache-user').catch(() => {
      return null;
    });

    return this.currentUser;
  }

  public async setCurrentUser(user) {
    this.currentUser = user;
    if (!user) {
      await this.cache.removeItem('cache-user');
    } else {
      await this.cache.saveItem('cache-user', user, null, this.cacheTime);
    }
    return null;
  }

  public async getRsApiToken() {
    if (this.rsApiToken) {
      return this.rsApiToken;
    }
    this.rsApiToken = await this.cache.getItem('cache-rs-token').catch(() => {
      return null;
    });
    return this.rsApiToken;
  }

  public async getRsSessionId() {
    // TODO
    // this.rsApiSesstionId = await this.matomoTracker.getVisitorId();
    return this.rsApiSesstionId;
  }

  public async setRsApiToken(token) {
    this.rsApiToken = token;
    if (token) {
      await this.cache.saveItem('cache-rs-token', token, null, this.cacheTime);
    } else {
      await this.cache.removeItem('cache-rs-token');
    }
    return null;
  }

  public async getRefreshToken() {
    if (this.refreshToken) {
      return this.refreshToken;
    }
    this.refreshToken = await this.cache.getItem('cache-refresh-token').catch(() => {
      console.warn('No refresh token found in cache');
      return null;
    });
    return this.refreshToken;
  }

  public async setRefreshToken(token) {
    this.refreshToken = token;
    if (token) {
      await this.cache.saveItem('cache-refresh-token', token, null, this.cacheTime);
    } else {
      await this.cache.removeItem('cache-refresh-token');
    }
    return null;
  }
}
