import { Injectable } from '@angular/core';
import { ENV } from '@app/env';

@Injectable({
  providedIn: 'root',
})
export class PerformanceLoggerService {
  private startTime: number = performance.now();
  private markers: Map<string, number> = new Map();
  private logs: Array<{ event: string; timestamp: number; duration?: number; message?: string }> = [];

  constructor() {
    if (!ENV.EnablePerformanceLogging) return;
    this.mark('APP_START');
    this.log('🚀 App initialization started');
  }

  mark(label: string): void {
    if (!ENV.EnablePerformanceLogging) return;
    const now = performance.now();
    this.markers.set(label, now);
    const duration = this.markers.has('APP_START') ? now - this.markers.get('APP_START')! : 0;
    this.logs.push({
      event: label,
      timestamp: now,
      duration: duration,
    });
    console.log(`[PERF] ${label} - ${duration.toFixed(2)}ms from start`);
  }

  log(message: string, data?: any): void {
    if (!ENV.EnablePerformanceLogging) return;
    const now = performance.now();
    const duration = this.markers.has('APP_START') ? now - this.markers.get('APP_START')! : 0;
    this.logs.push({
      event: 'LOG',
      timestamp: now,
      duration: duration,
      message: message,
    });
    if (data) {
      console.log(`[PERF] ${message} (${duration.toFixed(2)}ms)`, data);
    } else {
      console.log(`[PERF] ${message} (${duration.toFixed(2)}ms)`);
    }
  }

  measure(label: string, startLabel: string): void {
    if (!ENV.EnablePerformanceLogging) return;
    const start = this.markers.get(startLabel);
    if (start) {
      const now = performance.now();
      const duration = now - start;
      this.log(`${label} took ${duration.toFixed(2)}ms`, { from: startLabel });
    }
  }

  getLogs(): Array<{ event: string; timestamp: number; duration?: number; message?: string }> {
    if (!ENV.EnablePerformanceLogging) return [];
    return this.logs;
  }

  printSummary(label: string): void {
    if (!ENV.EnablePerformanceLogging) return;
    console.group(`📊 Performance Summary ${label}`);
    this.logs.forEach((log) => {
      if (log.duration !== undefined) {
        console.log(`[${log.duration.toFixed(2)}ms] ${log.event}${log.message ? ' - ' + log.message : ''}`);
      }
    });
    const totalTime = performance.now() - this.startTime;
    console.log(`\n⏱️  Total Time: ${totalTime.toFixed(2)}ms`);
    console.groupEnd();
  }
}
