import { AfterViewChecked, Component, ElementRef, ViewChild, OnInit, OnDestroy } from '@angular/core';
import { ActivatedRoute, NavigationEnd, Router } from '@angular/router';
import { Capacitor } from '@capacitor/core';
import { Credential } from '@rsApp/modules/auth-v2/providers/credential.service';
import JsBarcode from 'jsbarcode';
import { firstValueFrom, Subject, takeUntil } from 'rxjs';
import { WalletService } from '../../providers/wallet.service';
import { AccountChoice } from '../../utils/enum';
import { AppSettings } from '@rsApp/modules/utils/providers/app-setting';
import { User } from '../../providers/user.service';

@Component({
  selector: 'mag-personal-info-accordion',
  templateUrl: './mag-personal-info-accordion.html',
  styleUrls: ['./mag-personal-info-accordion.scss'],
})
export class MagPersonalInfoAccordionComponent implements AfterViewChecked, OnInit, OnDestroy {
  public SettingKeyAM = 'ACCOUNT MANAGEMENT';

  constructor(
    public route: ActivatedRoute,
    public cre: Credential,
    public walletService: WalletService,
    private appSettingsService: AppSettings,
    public router: Router,
    private userService: User
  ) {
    // Reload user on route change (only if returning to /my-account)
    this.router.events.pipe(takeUntil(this._destroy$)).subscribe(async (event) => {
      if (event instanceof NavigationEnd && event.urlAfterRedirects === '/tabs/my-account') {
        await this.loadUser();
        this.isMembershipSupported = (await this.initWBSettings()) && !!this.user?.LoyaltyCardId;
      }
    });
  }

  ngOnDestroy() {
    this._destroy$.next(true);
    this._destroy$.complete();
  }

  @ViewChild('barcode') barcode!: ElementRef<SVGSVGElement>;

  user: any;
  AccountChoice = AccountChoice;
  platform: string;
  isSavingWallet = false;
  formatedPhone: string;
  isMembershipSupported: boolean = false;
  isForcePhoneVerify: boolean = false;

  private _destroy$: Subject<boolean> = new Subject();

  async ngOnInit(): Promise<void> {
    this.platform = Capacitor.getPlatform();
    this.checkIsForceVerifyPhone();
  }

  async loadUser() {
    const user: any = await firstValueFrom(this.userService.getUserById(this.cre.currentUser.UserId));
    this.user = user;
    const { CellPhone, Phone } = this.user || {};
    this.formatedPhone = this.formatPhone(Phone || CellPhone);
  }

  private async checkIsForceVerifyPhone() {
    this.isForcePhoneVerify = (await this.cre.getCurrentUser())?.IsForceVerifyPhone || false;
  }

  async initWBSettings() {
    try {
      const value = await firstValueFrom(this.appSettingsService.getSettingValue('loyalty_support'));
      if (!value) {
        console.warn('Loyalty support setting not found or empty');
      }
      return JSON.parse(value);
    } catch (err) {
      console.warn('Error fetching loyalty_support setting:', err);
      return false;
    }
  }

  ngAfterViewChecked(): void {
    if (this.user?.LoyaltyCardId && this.barcode?.nativeElement) {
      this.renderBarcode();
    }
  }

  formatPhone(phone: string | null | undefined): string {
    if (!phone) return '';
    const digits = phone.replace(/\D/g, '').slice(0, 10);
    if (digits.length < 10) return phone;

    return `(${digits.slice(0, 3)}) ${digits.slice(3, 6)}-${digits.slice(6, 10)}`;
  }

  private renderBarcode(): void {
    try {
      const isUPC = /^\d{11}$/.test(this.user.LoyaltyCardId);
      const format = isUPC ? 'UPC' : 'CODE128';
      JsBarcode(this.barcode.nativeElement, this.user.LoyaltyCardId, {
        format: format,
        displayValue: true,
        font: 'monospace',
        fontOptions: 'bold',
        fontSize: 18,
        textMargin: 4,
        lineColor: '#000',
        width: 2,
        height: 80,
        margin: 0,
      });
    } catch {
      this.isMembershipSupported = false;
    }
  }

  async saveWallet(): Promise<void> {
    if (!this.user?.LoyaltyCardId) {
      console.warn('Loyalty card information not available');
      return;
    }

    // Prevent multiple click
    if (this.isSavingWallet) {
      return;
    }

    this.isSavingWallet = true;

    try {
      if (this.platform === 'ios') {
        await firstValueFrom(this.walletService.saveAppleWallet(this.user.LoyaltyCardId));
      } else {
        await firstValueFrom(this.walletService.saveGoogleWallet(this.user.LoyaltyCardId));
      }
    } catch (error) {
      console.warn('Unexpected error in saveWallet:', error);
    } finally {
      this.isSavingWallet = false;
    }
  }
}
