import { Component, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { NavController } from '@ionic/angular';
import { TranslateService } from '@ngx-translate/core';
import { MagOtpActionType } from '@rsApp/components/interface';
import { ToastService } from '@rsApp/components/toast.service';
import { Credential } from '@rsApp/modules/auth-v2/providers/credential.service';
import { CacheService } from 'ionic-cache';
import { firstValueFrom } from 'rxjs';
import { AuthService } from '../../providers/auth-v2.service';
import { User } from '@rsApp/modules/account-v2/providers/user.service';
import { AuthUtils } from '../../utils/auth.utils';
import { IUser } from '@rsApp/modules/interfaces/user.interface';

@Component({
  selector: 'verify-otp',
  templateUrl: 'verify-otp.html',
  styleUrls: ['./verify-otp.scss'],
})
export class VerifyOtpPageComponent implements OnInit {
  public actionType: MagOtpActionType = MagOtpActionType.SIGNUP;
  public email: string;
  public password: string;
  public userInfo: any;
  public firstSignup = false; // check if the user signup first time and navigate to verify otp first time
  public receiveEmail = false;
  public receiveTextMessage = false;

  public isLoading: boolean = false;

  constructor(
    private authService: AuthService,
    public cre: Credential,
    public router: Router,
    public route: ActivatedRoute,
    public cache: CacheService,
    private toastService: ToastService,
    private navController: NavController,
    private translate: TranslateService,
    private navCtrl: NavController,
    private userService: User,
    private authUtils: AuthUtils
  ) {
    this.firstSignup = !this.cre.currentUser?.Email;

    const { email, password, receiveTextMessage, receiveEmail } =
      this.router.getCurrentNavigation()?.extras.state || {};

    this.email = this.firstSignup ? email ?? '' : this.cre.currentUser?.Email;
    this.password = password ?? '';
    this.receiveTextMessage = receiveTextMessage ?? false;
    this.receiveEmail = receiveEmail ?? false;
  }

  async ngOnInit() {
    this.userInfo = await this.preFetchUser();
    if (!this.userInfo) {
      console.warn('User not found!');
      if (this.firstSignup) {
        this.back();
      } else {
        this.navigateToReturnRoute();
      }
      return;
    }
  }

  async ionViewDidEnter() {
    if (this.firstSignup) return this.authUtils.toastCreateSuccess();
  }

  async preFetchUser() {
    try {
      const user = await firstValueFrom(this.authService.getUserByEmail(this.email));
      if (!user) {
        console.warn('User not found');
        return null;
      }
      return user;
    } catch (error) {
      console.warn('Failed to fetch user:', error);
      return null;
    }
  }

  async handleOtpVerified() {
    const user: IUser = await firstValueFrom(this.authService.getUserByEmail(this.email));
    if (!user) {
      console.warn('User not found!');
      this.isLoading = false;
      return;
    }
    user.IsVerifiedEmail = true;
    user.IsForceUpdatePassword = this.cre.currentUser?.IsForceUpdatePassword; // SBMV1-177 - only change this field after user update password
    await this.authService.setCurrentUser(user);
    this.isLoading = false;
    // if IsForceVerifyPhone = true pass Toast 'account verified done' because user need to verify phone after verify email
    if (!user?.IsForceVerifyPhone) this.authUtils.toastVerifyAccountSuccess();
    this.navigateToReturnRoute();
  }

  useDifferentEmail() {
    this.navController.back();
  }

  private navigateToReturnRoute(): void {
    this.navCtrl.navigateRoot(['/tabs/home'], {
      state: {
        receiveEmail: this.receiveEmail,
        receiveTextMessage: this.receiveTextMessage,
      },
    });
  }

  async back() {
    this.userService.setterEmail(null, null);
    this.navCtrl.navigateRoot(['/sign-in']);
  }
}
