import { AfterViewInit, Component, ElementRef, Input, OnDestroy, OnInit, ViewChild } from '@angular/core';
import { MenuController } from '@ionic/angular';
import { EnumMagFulfillmentManagementRenderType } from '@rsApp/core/enum';
import { of, Subject, take, takeUntil, tap } from 'rxjs';
import { AuthService } from '../auth-v2/providers/auth-v2.service';
import { Credential } from '../auth-v2/providers/credential.service';
import { IUser } from '../interfaces/user.interface';
import { DxpComponentService } from '../utils/providers/dxp.component.service';
import { RouteTrackerService } from '../utils/providers/route-tracker.service';
import { TenantSettingsStore } from '../utils/providers/tenant-settings.service';

@Component({
  selector: 'app-header',
  templateUrl: './header.component.html',
  styleUrls: ['./header.component.scss'],
})
export class HeaderComponent implements OnInit, AfterViewInit, OnDestroy {
  @Input() currentStore;
  @Input() isShowBackButton = false;
  @Input() isHideCartListIcons = false;
  @Input() isLocalSearch = false;
  @Input() isSimpleHeader = false;
  @Input() headerNoBorder = false;

  @ViewChild('headerTop') headerTop: ElementRef;

  private destroy$ = new Subject<boolean>();
  private contentListenerElm: HTMLIonContentElement;

  public isShoppingList: boolean = false;
  public innerIconCart = '';
  public innerIconShoppingList = '';
  public innerOrderAlterationBanner = '';
  public nameIcon = '';
  public defaultLogoUrl: string;
  public isAdjustUI: boolean = false; // isAdjustUI == true: hide searchbar, hide shopping card/list icons

  constructor(
    public cre: Credential,
    private dxpService: DxpComponentService,
    private tenantSettingsStore: TenantSettingsStore,
    private auth: AuthService,
    private routeTracker: RouteTrackerService,
    private menu: MenuController
  ) {}

  async ngOnInit() {
    await this.dxpService.onConnected();
    this.innerIconCart = '<mag-icon-cart></mag-icon-cart>';
    this.innerIconShoppingList = '<mag-icon-shopping-list></mag-icon-shopping-list>';
    this.routeTracker
      .getRenderType()
      .pipe(take(1))
      .subscribe((value) => {
        this.isAdjustUI = value == EnumMagFulfillmentManagementRenderType.Common;
        if (!this.isAdjustUI) {
          this.isShoppingList = value === EnumMagFulfillmentManagementRenderType.ShoppingList;
        }

        this.innerOrderAlterationBanner = '<mag-order-alterations-banner></mag-order-alterations-banner>';
      });

    this.initialReduceUserName().subscribe();
    await this.getTenantInfo();
  }

  ngAfterViewInit() {
    if (!this.isSimpleHeader) {
      this.handleScrollHeader();
    }
  }

  handleScrollHeader() {
    const pagesWithoutAriaHidden = document.querySelectorAll('.ion-page:not([aria-hidden])');

    if (!pagesWithoutAriaHidden.length) return;
    const pagesWithIonContent = Array.from(pagesWithoutAriaHidden).filter((page) => page.querySelector('ion-content'));

    if (!pagesWithIonContent.length) return;
    const content = pagesWithIonContent[pagesWithIonContent.length - 1]?.querySelector('ion-content');
    content.scrollEvents = true;
    const headerTopElement: HTMLElement = this.headerTop.nativeElement;
    const headerTopClassList = headerTopElement.classList;
    const heightContent = window.innerHeight - headerTopElement.clientHeight;

    this.contentListenerElm = content;

    this.contentListenerElm.addEventListener('ionScroll', (e) => {
      if (this.isAdjustUI) return;

      const target = e.target;
      const partOfContent = heightContent * 0.1; // 10% height of content
      const isHidden = e.detail.scrollTop > Math.abs(target.offsetTop - partOfContent);

      if (isHidden) {
        if (!headerTopClassList.contains('hidden')) {
          headerTopClassList.add('hidden');
        }
      } else {
        if (headerTopClassList.contains('hidden')) {
          headerTopClassList.remove('hidden');
        }
      }
    });
  }

  async getTenantInfo() {
    const tenantsetting = await this.tenantSettingsStore.getTenantSettings();
    if (tenantsetting) {
      this.defaultLogoUrl = tenantsetting?.logoUrl;
    }
  }

  openMenu() {
    this.menu.open('mainMenu');
  }

  ngOnDestroy() {
    this.innerIconCart = '';
    this.innerIconShoppingList = '';
    this.destroy$.next(true);
    this.destroy$.complete();
    if (this.contentListenerElm) this.contentListenerElm.removeAllListeners();
    this.contentListenerElm = null;
  }

  initialReduceUserName() {
    try {
      return this.auth.getCurrentUser().pipe(
        tap((user: IUser) => {
          if (user && Object.keys(user).length) {
            const { LastName, FirstName } = user;
            this.nameIcon = FirstName[0] + LastName[0];
          }
        }),
        takeUntil(this.destroy$)
      );
    } catch {
      console.log('Can not get user data!');
      return of(null);
    }
  }
}
