import { Component, ElementRef, Input, OnChanges, OnDestroy, ViewChild } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { ENV } from '@app/env';
import { Capacitor } from '@capacitor/core';
import { GoogleMap, Marker } from '@capacitor/google-maps';
import { PopoverController } from '@ionic/angular';
import { NgxPubSubService } from '@pscoped/ngx-pub-sub';
import { AuthService } from '@rsApp/modules/auth-v2/providers/auth-v2.service';
import { Credential } from '@rsApp/modules/auth-v2/providers/credential.service';
import { CurrentStore } from '@rsApp/modules/store/providers/current-store.service';
import { StoreService } from '@rsApp/modules/store/providers/store.service';
import { GoogleAnalyticTracker } from '@rsApp/modules/utils/providers/google-tracker.service';
import { Utils } from '@rsApp/modules/utils/providers/utils';
import { CacheService } from 'ionic-cache';
import filter from 'lodash/filter';
import find from 'lodash/find';
import forEach from 'lodash/forEach';
import { firstValueFrom } from 'rxjs';
import { EnvironmentService } from '../../../../../environments/environment.service';
import { BaseStore } from '../../base-store';

@Component({
  selector: 'store-map',
  templateUrl: 'store-map.html',
  styleUrls: ['./store-map.scss'],
})
export class StoreMapComponent extends BaseStore implements OnChanges, OnDestroy {
  @Input() listStore: any;
  @Input() showCurrentStore: boolean;

  map: GoogleMap;
  subscribes = [];
  markers = [];

  @ViewChild('map_canvas', { static: true })
  mapRef: ElementRef<HTMLElement>;

  constructor(
    public utils: Utils,
    public auth: AuthService,
    public cStore: CurrentStore,
    public router: Router,
    public route: ActivatedRoute,
    public cache: CacheService,
    public store: StoreService,
    public cri: Credential,
    public events: NgxPubSubService,
    public googleTracking: GoogleAnalyticTracker,
    public popoverCtrl: PopoverController,
    private environmentService: EnvironmentService
  ) {
    super(utils, cStore, router, cache, store, cri, events, googleTracking);
  }

  async ngOnChanges() {
    if (this.listStore && this.showCurrentStore) {
      await super.getCurrent();
      const stores = this.listStore;
      await this.loadMap(stores);
    }
  }

  //TODO: creare global map service once
  async loadMap(stores) {
    // if (!stores) return;
    if (!stores) {
      stores = [];
    }
    // Create a map after the view is ready and the native platform is ready.
    if (this.showCurrentStore && this.currentStore) {
      //filter to remove current store in list
      stores = filter(stores, (store) => {
        return store?.StoreCode !== this.currentStore?.StoreCode;
      });
      // and unshift current store to list
      stores.unshift(Object.assign({}, this.currentStore));
    }
    let sumlat = 0,
      sumlng = 0;
    const length = stores?.length || 1; // for exclude case divide 0

    stores.forEach((store) => {
      sumlat += Number(store?.Latitude || 0);
      sumlng += Number(store?.Longitude || 0);
    });

    if (!this.map && this.mapRef) {
      const dynamicEnv = await firstValueFrom(this.environmentService.getDynamicEnvironment());
      const apiKey = !Capacitor.isNativePlatform()
        ? dynamicEnv.googleMapBrowserKey
        : Capacitor.getPlatform() === 'ios'
          ? dynamicEnv.googleMapIosKey
          : dynamicEnv.googleMapAndroidKey; // Your Google Maps API Key
      await new Promise((resolve) => {
        //set value value for map bc await GoogleMap too slow
        (this.map as any) = true;
        setTimeout(async () => {
          this.map = await GoogleMap.create({
            id: 'map_canvas', // Unique identifier for this map instance
            element: this.mapRef.nativeElement, // reference to the capacitor-google-map element
            apiKey: apiKey,
            config: {
              center: {
                // The initial position to be rendered by the map
                lat: sumlat / length,
                lng: sumlng / length,
              },
              zoom: ENV.MapZoom, // The initial zoom level to be rendered by the map
            },
            forceCreate: true,
          });
          resolve(true);
        }, 300);
      });

      await this.loadStoreMarker(stores);
      this.map.setOnMarkerClickListener((event) => {
        if (!Capacitor.isNativePlatform()) {
          this.ngOnDestroy();
          const findStore =
            event?.latitude === Number(this.currentStore?.Latitude) &&
            event?.longitude === Number(this.currentStore?.Longitude)
              ? this.currentStore
              : find(
                  this.listStore,
                  (s) =>
                    s?.StoreCode == event?.title &&
                    event?.latitude === Number(s?.Latitude) &&
                    event?.longitude === Number(s?.Longitude)
                );

          if (findStore) {
            super.viewInfo(findStore.StoreCode);
          }
        }
      });
      this.map.setOnInfoWindowClickListener((event) => {
        const findStore =
          event.latitude === Number(this.currentStore?.Latitude) &&
          event.longitude === Number(this.currentStore?.Longitude)
            ? this.currentStore
            : find(
                this.listStore,
                (s) =>
                  s?.StoreCode == event?.title &&
                  event?.latitude === Number(s?.Latitude) &&
                  event?.longitude === Number(s?.Longitude)
              );

        if (!findStore) {
          return;
        }

        this.ngOnDestroy();
        super.viewInfo(findStore?.StoreCode);
      });
    } else if (this.map) {
      await this.clearMarkers();
      await this.loadStoreMarker(stores);
      setTimeout(() => {
        this.map.setCamera({
          coordinate: {
            // The initial position to be rendered by the map
            lat: sumlat / length,
            lng: sumlng / length,
          },
          zoom: ENV.MapZoom, // The initial zoom level to be rendered by the map
        });
      }, 700);
    }
  }

  async loadStoreMarker(stores) {
    const markers: Marker[] = stores.map((store) => {
      const cityStateZipcode = `${store.City && this.titleCase(store.City)} ${store.State} ${store.ZipCode}`;
      return {
        title: store?.StoreCode,
        snippet: `${store?.Address} ${cityStateZipcode} - View Detail`,
        iconUrl: store?.MapPin || store?.StoreIconURL || '',
        iconSize: { width: 40, height: 40 },
        coordinate: {
          lat: Number(store?.Latitude || 0),
          lng: Number(store?.Longitude || 0),
        },
      };
    });
    // Add a marker to the map
    this.markers = await this.map.addMarkers(markers);
  }

  titleCase(str) {
    const splitStr = str?.toLowerCase()?.split(' ');
    for (let i = 0; i < splitStr?.length; i++) {
      // You do not need to check if i is larger than splitStr length, as your for does that for you
      // Assign it back to the array
      splitStr[i] = splitStr[i].charAt(0).toUpperCase() + splitStr[i].substring(1);
    }
    // Directly return the joined string
    return splitStr?.join(' ');
  }

  async clearMarkers() {
    await this.map.removeMarkers(this.markers);
    this.markers = [];
  }

  async ngOnDestroy() {
    if (!this.subscribes) {
      return;
    }
    forEach(this.subscribes, (s) => {
      if (s && s.unsubscribe) {
        s.unsubscribe();
      }
    });
    await this?.map?.destroy();
    this.map = null;
  }
}
