import { Injectable } from '@angular/core';
import { AuthService } from '@rsApp/modules/auth-v2/providers/auth-v2.service';
import { Observable, catchError, map, of, switchMap, timer } from 'rxjs';
import { AbstractControl, ValidationErrors } from '@angular/forms';
import { Credential } from '@rsApp/modules/auth-v2/providers/credential.service';
@Injectable({
  providedIn: 'root',
})
export class EmailValidator {
  constructor(
    private authService: AuthService,
    public cre: Credential
  ) {}

  private time = 500;

  emailValidator() {
    return (control: AbstractControl): Observable<ValidationErrors | null> => {
      const email = control?.value;
      if (!email) {
        return of(null); // don't validate empty field
      }
      if (email?.trim() === this.cre?.currentUser?.Email?.trim()) {
        return of({ matchCurrentEmail: true });
      }
      // Debounce the request for 500ms
      return timer(this.time).pipe(
        switchMap(() => this.authService.checkEmailExists(email, this.cre.currentUser.userName)),
        map((isExists) => (isExists ? { emailExist: true } : null)),
        catchError(() => of(null))
      );
    };
  }
}
