import { Component, ViewChild, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { AuthService } from '@rsApp/modules/auth-v2/providers/auth-v2.service';
import { GlobalRegex } from '@rsApp/modules/utils/enum/enum';
import { AppSettings } from '@rsApp/modules/utils/providers/app-setting';
import { catchError, firstValueFrom, of } from 'rxjs';

import { MaskitoOptions } from '@maskito/core';
import { ISubscribePayload } from '@rsApp/modules/account-v2/model/interface';
import { ESubscriptionInternalCode } from '@rsApp/modules/auth-v2/utils/enum';
import { phoneMasks } from '@rsApp/modules/utils/enum/enum';
import { AccountManagementSettingKeys } from '@rsApp/modules/utils/models/app-settings.model';
import { PhoneValidator } from '@rsApp/modules/utils/validator/phone-validator-v2';
import { MagWeeklyAdsSubscriptionComponent } from '../../../components/mag-weekly-ads-subscription/mag-weekly-ads-subscription';
import { SubscriptionService } from '../../../providers/subscription.service';
import { TranslateService } from '@ngx-translate/core';

@Component({
  selector: 'subscription',
  templateUrl: './subscription.html',
  styleUrls: ['./subscription.scss'],
})
export class SubscriptionComponent implements OnInit {
  subscriptionForm: FormGroup;
  supportEmail: string = '';
  isSubmitting: boolean = false;
  subscripstionsError = {
    isErrorSelectedStoreCode: false,
    isErrorSelectedCampaign: false,
    isErrorSelectedChannel: false,
  };
  subscription: {
    Phone?: string;
    Name?: string;
    StoreCode?: string;
    AudienceIds?: string[];
    ReceiveEmail?: boolean;
    ReceiveTextMessage?: boolean;
  } | null = null;
  phoneMask: MaskitoOptions;
  countryRegion: string = 'us';
  rawEmail: string = '';
  instructionText: string = '';
  constructor(
    public auth: AuthService,
    private router: Router,
    private appSettingsService: AppSettings,
    private fb: FormBuilder,
    private phoneValidator: PhoneValidator,
    private subscriptionService: SubscriptionService,
    private translate: TranslateService
  ) {
    Promise.all([this.loadSettingAM()]).then(([settings]: [Record<AccountManagementSettingKeys, string>]) => {
      this.supportEmail = settings?.email_customer_support;
    });
    this.subscriptionForm = this.fb.group({
      name: [''],
      email: [''],
      phone: [''],
      subscriptions: {},
    });
  }

  @ViewChild('weeklyAdsComponent') weeklyAdsComponent: MagWeeklyAdsSubscriptionComponent;
  async ngOnInit() {
    const supportGuest = await this.initWBSettings();
    this.phoneMask = phoneMasks[this.countryRegion];

    if (!supportGuest) {
      this.auth.getCurrentUser().subscribe((user) => {
        if (user) {
          this.router.navigate(['/tabs/my-account']);
        } else {
          this.router.navigate(['tabs/home']);
        }
      });
    }
    this.prepareInstructionText();
  }

  private async initWBSettings(): Promise<boolean> {
    try {
      const value = await firstValueFrom(
        this.appSettingsService.getSettingValue('support_subscription_page_for_guest')
      );
      return JSON.parse(value);
    } catch (err) {
      console.warn('Error fetching support_subscription_page_for_guest:', err);
      return false;
    }
  }

  private async loadSettingAM(): Promise<Record<AccountManagementSettingKeys, string>> {
    try {
      const setting: Record<AccountManagementSettingKeys, string> = await firstValueFrom(
        this.appSettingsService.getSettingByPath('ACCOUNT MANAGEMENT')
      );
      return setting;
    } catch (error) {
      console.error(error);
    }
  }

  private updateValidatorsByChannels(channels: string[]) {
    const phoneControl = this.subscriptionForm.get('phone');
    const emailControl = this.subscriptionForm.get('email');

    if (channels.includes('ReceiveTextMessage')) {
      phoneControl?.setValidators([Validators.required]);
      phoneControl?.setAsyncValidators([this.phoneValidator.checkPhoneFormat()]);
    } else {
      phoneControl?.clearValidators();
    }

    if (channels.includes('ReceiveEmail')) {
      emailControl?.setValidators([Validators.required, Validators.pattern(GlobalRegex.EMAIL)]);
    } else {
      emailControl?.clearValidators();
    }

    phoneControl?.updateValueAndValidity();
    emailControl?.updateValueAndValidity();
  }

  setValueSubscriptions(data: { selectedChannel: string[]; selectedCampaign: string[]; selectedStoreCode: string }) {
    if (!data) return;
    const { selectedCampaign, selectedChannel, selectedStoreCode } = data;
    this.subscriptionForm.get('subscriptions').setValue({
      storeCode: selectedStoreCode,
      subscriptionIds: selectedCampaign,
      channels: selectedChannel,
    });

    this.updateValidatorsByChannels(selectedChannel);
  }
  private fetchSubscriptionByEmail(email: string) {
    return this.subscriptionService.getSubsciptionByEmail(email).pipe(catchError(() => of(null)));
  }

  onBlurInput(control: string) {
    const emailCtrl = this.subscriptionForm.get('email');
    if (control !== 'email' || !emailCtrl?.valid || this.rawEmail === emailCtrl.value) return;

    const emailValue = emailCtrl.value;

    this.fetchSubscriptionByEmail(emailValue).subscribe((data) => {
      if (data) {
        this.subscription = data;
        this.subscriptionForm.patchValue({ name: data.Name });
        this.weeklyAdsComponent?.setDataSubscription();
      }
    });

    this.rawEmail = emailValue;
  }

  prepareInstructionText() {
    this.translate.get('subscriptions.guestSubscription.instructionText').subscribe((translatedText) => {
      const supportEmailLink = `<a href="mailto:${this.supportEmail}">${this.supportEmail}</a>`;

      this.instructionText = translatedText.replace('{supportEmail}', this.supportEmail ? supportEmailLink : '');
    });
  }

  private validateFormAndSubscriptions(): boolean {
    const data = this.subscriptionForm.getRawValue();
    const subscriptions = data.subscriptions;

    if (subscriptions) {
      const { storeCode, subscriptionIds, channels } = subscriptions;
      this.subscripstionsError = {
        isErrorSelectedCampaign: !subscriptionIds?.length,
        isErrorSelectedChannel: !channels?.length,
        isErrorSelectedStoreCode: !storeCode,
      };
    }

    const invalidWeeklyAds =
      this.subscripstionsError.isErrorSelectedCampaign ||
      this.subscripstionsError.isErrorSelectedChannel ||
      this.subscripstionsError.isErrorSelectedStoreCode;

    if (this.subscriptionForm.invalid) {
      this.subscriptionForm.markAllAsTouched();
      return false;
    }

    return !invalidWeeklyAds;
  }

  private buildSubscriptionPayload(data: any): ISubscribePayload {
    const Phone = data?.phone?.replace(/\D/g, '');
    const subs = data.subscriptions;
    return {
      Name: data.name,
      Email: data.email,
      Phone,
      AudienceIds: subs.subscriptionIds,
      StoreCode: subs.storeCode,
      ReceiveEmail: subs.channels.includes('ReceiveEmail'),
      ReceiveTextMessage: subs.channels.includes('ReceiveTextMessage'),
    };
  }

  async subscribe() {
    try {
      if (this.isSubmitting) return;

      const isValid = this.validateFormAndSubscriptions();
      if (!isValid) return;

      this.isSubmitting = true;
      const payload = this.buildSubscriptionPayload(this.subscriptionForm.getRawValue());
      const result = await firstValueFrom(this.subscriptionService.subscribeSubscription(payload));
      this.handleSubscriptionResult(result, payload);
    } catch (error) {
      console.error('Error during signup:', error);
    } finally {
      this.isSubmitting = false;
    }
  }
  private navigateWithType(type: string) {
    this.router.navigate(['/subscription/subscribe-confirm'], { state: { type } });
  }

  handleSubscriptionResult(result: any, payload: ISubscribePayload) {
    if (result?.ErrorCode === ESubscriptionInternalCode.ResubscribeSmsFailed) {
      return this.navigateWithType('resubscribeSms');
    }
    if (result?.EmailVerified === true) {
      if (result?.SmsVerified === true || payload?.ReceiveTextMessage === false) {
        return this.navigateWithType('success');
      }
      return this.navigateWithType('verifyPhone');
    } else {
      return this.navigateWithType('verifyEmail');
    }
  }
}
