import { Injectable, OnDestroy } from '@angular/core';
import { Capacitor } from '@capacitor/core';
import { Keyboard, KeyboardInfo } from '@capacitor/keyboard';
import { Platform } from '@ionic/angular';
@Injectable({ providedIn: 'root' })
export class UseKeyboard implements OnDestroy {
  private showListener: any;
  private hideListener: any;

  constructor(public platform: Platform) {}

  public async init() {
    if (!Capacitor.isNativePlatform() || Capacitor.getPlatform() === 'ios') return;
    this.showListener = await Keyboard.addListener('keyboardWillShow', (info: KeyboardInfo) => {
      document.body.style.setProperty('--keyboard-height', `${info.keyboardHeight}px`);
    });
    this.hideListener = await Keyboard.addListener('keyboardWillHide', () => {
      document.body.style.setProperty('--keyboard-height', `0px`);
    });
  }

  removeListeners() {
    this.showListener?.remove();
    this.hideListener?.remove();
  }

  ngOnDestroy() {
    this.removeListeners();
  }
  ionViewWillLeave() {
    this.removeListeners();
  }
}
