import { Component, EventEmitter, Input, Output, OnChanges } from '@angular/core';

@Component({
  selector: 'mag-content-block-page',
  templateUrl: './mag-content-block-page.html',
  styleUrls: ['./mag-content-block-page.scss'],
})
export class MagContentBlockPageComponent implements OnChanges {
  @Input() iconType: 'checkmark' | 'phone' | 'inbox' | 'warning';
  @Input() variant: 'success' | 'warning';
  @Input() title: string;
  @Input() description: string;
  @Input() primaryButtonText: string;
  @Input() secondaryButtonText: string;

  @Output() primaryAction: EventEmitter<any> = new EventEmitter();
  @Output() secondaryAction: EventEmitter<any> = new EventEmitter();
  @Output() closeAction: EventEmitter<any> = new EventEmitter();

  public config;

  ngOnChanges() {
    this.config = {
      iconType: this.iconType,
      variant: this.variant,
      type: 'page',
      title: this.title,
      description: this.description,
      primaryButton: {
        label: this.primaryButtonText,
      },
      secondaryButton: {
        label: this.secondaryButtonText,
      },
    };
  }
}
