import { Injectable } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';

@Injectable({
  providedIn: 'root',
})
export class PasswordValidator {
  constructor(private translate: TranslateService) {}

  getCriterias() {
    return [
      {
        label: this.translate.instant('accountInfo.minimumCharacters'),
        check: (password: string) => password.length >= 12,
      },
      {
        label: this.translate.instant('accountInfo.uppercaseLowercase'),
        check: (password: string) => /[a-z]/.test(password) && /[A-Z]/.test(password),
      },
      {
        label: this.translate.instant('accountInfo.leastOneNumber'),
        check: (password: string) => /\d/.test(password),
      },
      {
        label: `${this.translate.instant('accountInfo.leastOneSpecial')} ! @ # $ % ^ & * ( )`,
        check: (password: string) => /[!@#$%^&*()]/.test(password),
      },
      {
        label: this.translate.instant('accountInfo.noSpaces'),
        check: (password: string) => !/\s/.test(password),
      },
    ];
  }

  validatePasswordStrength(password: string): boolean[] {
    return this.getCriterias().map((rule) => rule.check(password));
  }

  passwordValidator() {
    return (control: any) => {
      const password = control.value;
      const passedRules = this.validatePasswordStrength(password);

      if (!password) {
        return { required: true }; // Handle required case
      }

      const valid = passedRules.every((rule) => rule === true);
      return valid ? null : { passwordStrength: 'Failed' };
    };
  }
}
