import type { SelectItemParams, Ga4Item } from './ga4.types';

function pickLocalizedText(v: any): string | undefined {
  if (!v) return undefined;
  if (typeof v === 'string') return v;

  if (typeof v === 'object') {
    if (typeof v.en === 'string') return v.en;
    const first = Object.values(v).find((x) => typeof x === 'string');
    return first as string | undefined;
  }

  return undefined;
}

function toNumber(v: any): number | undefined {
  if (typeof v === 'number' && Number.isFinite(v)) return v;
  const n = Number(v);
  return Number.isFinite(n) ? n : undefined;
}

function mapApiProductToGa4Item(p: any, idx: number): Ga4Item {
  return {
    item_id: p?.ProductId ?? p?.Gtin ?? p?.item_id,
    item_name: pickLocalizedText(p?.DisplayName) ?? pickLocalizedText(p?.Title) ?? p?.item_name,
    item_brand: pickLocalizedText(p?.Brand?.Name) ?? p?.Brand?.Id ?? p?.item_brand,
    item_category: pickLocalizedText(p?.Categories?.Level1?.Name) ?? pickLocalizedText(p?.DocumentDepartment?.Name),
    item_category2: pickLocalizedText(p?.Categories?.Level2?.Name),
    item_category3: pickLocalizedText(p?.Categories?.Level3?.Name),
    item_category4: pickLocalizedText(p?.Categories?.Level4?.Name),
    item_category5: pickLocalizedText(p?.Categories?.Level5?.Name),
    item_variant: p?.Unit ?? pickLocalizedText(p?.Size) ?? p?.item_variant,
    location_id: p?.BranchId ?? p?.location_id,
    price: toNumber(p?.Price ?? p?.MinPrice ?? p?.MaxPrice ?? p?.price),
    quantity: toNumber(p?.quantity),
    index: idx + 1,
  };
}

export function mapSelectItemParams(payload: any): SelectItemParams | null {
  const selected =
    payload?.selectedItem ??
    payload?.selectedProduct ??
    payload?.item ??
    payload?.product ??
    payload?.data?.item ??
    payload?.data?.product ??
    payload;

  if (!selected?.ProductId && !selected?.Gtin && !selected?.item_id) return null;

  const item_list_id = payload?.item_list_id ?? payload?.listId ?? payload?.list_id;
  const item_list_name = payload?.item_list_name ?? payload?.listName ?? payload?.list_name;

  const item = mapApiProductToGa4Item(selected, 0);

  return {
    item_list_id,
    item_list_name,
    items: [
      {
        ...item,
        item_list_id: item_list_id ?? item.item_list_id,
        item_list_name: item_list_name ?? item.item_list_name,
      },
    ],
  };
}
