import { Router } from '@angular/router';
import { NgxPubSubService } from '@pscoped/ngx-pub-sub';
import { Credential } from '@rsApp/modules/auth-v2/providers/credential.service';
import { CurrentStore } from '@rsApp/modules/store/providers/current-store.service';
import { StoreService } from '@rsApp/modules/store/providers/store.service';
import { ActionType } from '@rsApp/modules/utils/enum/enum';
import { Utils } from '@rsApp/modules/utils/providers/utils';
import { CacheService } from 'ionic-cache';
import _ from 'lodash';
import { IStore, ISystemService } from '../interfaces/store.interface';
import { GoogleAnalyticTracker } from '../utils/providers/google-tracker.service';

export class BaseStore {
  public currentStore: any;
  public currentUser: any;

  constructor(
    public utils: Utils,
    public cStore: CurrentStore,
    public router: Router,
    public cache: CacheService,
    public store: StoreService,
    public cri: Credential,
    public events: NgxPubSubService,
    public googleTracking: GoogleAnalyticTracker
  ) {
    this.getCurrent();
  }

  async getCurrent() {
    this.currentStore = await this.cStore.getStore();
    this.currentUser = await this.cri.getCurrentUser();
  }

  viewInfo(storeCode) {
    this.router.navigate(['/tabs/store/info', { storeCode }]);
  }

  private eventTrackingChangeStore(storeId, serviceName) {
    this.googleTracking.gtagTrackChangeStore(storeId, serviceName);
  }

  async selectStore(store: IStore, service: ISystemService, isBackRoute: boolean = true) {
    try {
      if (!store) {
        return null;
      }
      await this.utils.showLoading();
      const isShopPath = Boolean(service?.SettingAttributes?.is_shop_path.Value || 'false');
      const payload = {
        action: ActionType.RefreshTimeslot,
        data: {
          service,
        },
      };
      window.postMessage(payload, window.location.origin);
      this.eventTrackingChangeStore(store.StoreId, '');

      if (isShopPath) {
        await this.cStore.setStore(store, service?.SettingAttributes?.shop_path.Value);

        if (!isBackRoute) return;

        const back = await this.cache.getItem('store-back').catch(() => {
          return null;
        });
        const backRoute = back && back.route && back.route.length > 0 ? back.route : ['/tabs/home'];
        setTimeout(async () => {
          //Wait 'change-store' save store info
          if (backRoute && backRoute[0].search('/purchase/order-sumary') > -1) {
            if (this.currentStore?.Provider?.Code !== store?.Provider?.Code) {
              this.utils.navigateRoot(['/tabs/purchase'], true);
              return;
            }
          }

          await this.utils.navigateRoot(backRoute, true);
          this.utils.hideLoading();
        }, 500);
      } else {
        await this.utils.showLoading();
        if ((this.currentStore && this.currentStore.StoreCode !== store.StoreCode) || !this.currentStore) {
          await this.cStore.setStore(store);
        }

        if (!isBackRoute) return;

        const pageName = _.replace(service?.SettingAttributes?.mobile_url, 'app://', '');
        await this.router.navigateByUrl(pageName);
        this.utils.hideLoading();
      }
    } catch (error) {
      console.error(error);
      this.utils.hideLoading();
    }
  }
}
