import { Inject, Injectable, InjectionToken, LOCALE_ID } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { Location } from '@angular/common';
import { NavController } from '@ionic/angular';
import { MagEComCoreApiHttpClient } from '@rsApp/modules/gateway/mag-ecom-core-api.service';
import {
  AllCategoriesResponse,
  AllDepartmentsResponse,
  Category,
  Department,
} from '@rsApp/modules/interfaces/category.interface';
import { ActionType } from '@rsApp/modules/utils/enum/enum';
import { BehaviorSubject, map, Observable, Subscription } from 'rxjs';
import { CurrentStore } from '@rsApp/modules/store/store.module';
export const MAG_HTTP_CLIENT = new InjectionToken<MagEComCoreApiHttpClient>('MAG_HTTP_CLIENT');
export const MAG_PRODUCT_API = new InjectionToken<string>('MAG_PRODUCT_API');
@Injectable({
  providedIn: 'root',
})
export class CategoryService {
  private getAllDepartmentsPath = '/departments/get-all';
  private getAllCategoriesPath = '/categories/get-hierarchy-categories';
  private localeCode = 'En';

  private categories$ = new BehaviorSubject<Category[]>(null);
  private departments$ = new BehaviorSubject<Department[]>(null);

  private getCategoriesSub: Subscription;
  private getDepartmentsSub: Subscription;

  public categoryCodes: string[] = [];
  public categoryNames: string[] = [];

  constructor(
    @Inject(MAG_HTTP_CLIENT) private api: MagEComCoreApiHttpClient,
    @Inject(LOCALE_ID) private locale: string,
    private route: ActivatedRoute,
    private navCtrl: NavController,
    private location: Location,
    private router: Router,
    public store: CurrentStore
  ) {
    this.localeCode = this.getLocaleCode();
  }

  initialData() {
    if (this.getCategoriesSub && this.getDepartmentsSub) {
      return;
    }

    this.getCategoriesSub = this.getCategories().subscribe((category) => {
      if (!category) this.loadCategories();
    });

    this.getDepartmentsSub = this.getDepartments().subscribe((departments) => {
      if (!departments) this.loadDepartments();
    });
  }

  clearSubscription() {
    if (this.getCategoriesSub) {
      this.getCategoriesSub.unsubscribe();
      this.getCategoriesSub = null;
    }
    if (this.getDepartmentsSub) {
      this.getDepartmentsSub.unsubscribe();
      this.getDepartmentsSub = null;
    }
  }

  public getLocaleCode() {
    const countryCode = this.locale.split('-')[0];
    return countryCode[0].toUpperCase() + countryCode.slice(1);
  }

  public getNameOfCategory(target: Category | Department) {
    return target?.Name[this.localeCode] || target?.Name?.En;
  }

  getDepartments() {
    return this.departments$.asObservable();
  }

  async loadDepartments(refetchData?: boolean) {
    if (this.departments$.getValue() === null || refetchData) {
      const store = await this.store.getStore();
      const storeCode = store?.StoreCode;
      if (!storeCode) return;
      this.fetchAllDepartments(storeCode).subscribe((departments) => {
        this.departments$.next(departments);
      });
    }
  }

  setCategories(categories?: Category[]) {
    return this.categories$.next(categories);
  }

  getCategories() {
    return this.categories$.asObservable();
  }

  async loadCategories(refetchData?: boolean) {
    if (this.categories$.getValue() === null || refetchData) {
      const store = await this.store.getStore();
      const storeCode = store?.StoreCode;
      if (!storeCode) return;
      this.fetchAllCategories(storeCode).subscribe((categories) => {
        const payload = {
          action: ActionType.MagOnChangeCategory,
          data: categories,
        };
        window.postMessage({ ...payload }, window.location.origin);
        this.categories$.next(categories);
      });
    }
  }

  getCategoryByCode(code: string | string[]): Category | null {
    let data = this.categories$.getValue();
    if (!data?.length) {
      const deps = this.departments$.getValue();
      if (deps?.length) {
        data = deps.map((dep) => dep.Category);
      }
    }

    if (Array.isArray(code)) {
      let category: Category | undefined = data?.find((cat) => cat.Code === code[0]);
      for (let i = 1; i < code.length && category; i++) {
        category = category?.SubCategories?.find((subCat) => subCat.Code === code[i]);
      }
      return category || null;
    } else {
      return data?.find((cat) => cat.Code === code) || null;
    }
  }

  fetchAllDepartments(storeCode): Observable<Department[]> {
    return this.api.get(`${this.getAllDepartmentsPath}?storeCode=${storeCode}`).pipe(
      map((response: AllDepartmentsResponse) => {
        return response.Data;
      })
    );
  }

  fetchAllCategories(storeCode): Observable<Category[]> {
    return this.api.get(`${this.getAllCategoriesPath}?storeCode=${storeCode}`).pipe(
      map((response: AllCategoriesResponse) => {
        return response.Data;
      })
    );
  }

  saveCategoryCodesAndNames(codes: string | string[], names: string | string[]) {
    if (!codes || !names) return;
    if (Array.isArray(codes) && Array.isArray(names)) {
      this.categoryCodes = codes;
      this.categoryNames = names;
    } else if (this.categoryCodes.includes(codes as string)) {
      const index = this.categoryCodes.indexOf(codes as string);
      this.categoryCodes = this.categoryCodes.slice(0, index + 1);
      this.categoryNames = this.categoryNames.slice(0, index + 1);
    } else if (this.categoryCodes.length >= 5) {
      this.categoryCodes.shift();
      this.categoryNames.shift();
    } else {
      this.categoryCodes.push(codes as string);
      this.categoryNames.push(names as string);
    }
  }

  navigateToCategoryPage(categoryCodes: string | string[], categoryNames: string | string[]) {
    this.saveCategoryCodesAndNames(categoryCodes, categoryNames);

    const urlCategory = '/tabs/browse/category';
    const queryParams = {
      cats: this.categoryCodes.join(';'),
      catsName: this.categoryNames.join(';'),
    };

    const navOptions = { queryParams, relativeTo: this.route };

    if (this.location.path() === urlCategory) {
      navOptions['replaceUrl'] = true;
      navOptions['queryParamsHandling'] = 'merge';
    }

    // this.navCtrl.navigateForward([urlCategory], navOptions);
    this.router.navigate([urlCategory], navOptions);
  }

  navigateToAllCategories() {
    this.router.navigate(['/tabs/browse/category']);
  }

  resetCategoryAndDepartment() {
    this.categoryCodes = [];
    this.categoryNames = [];
  }
}
