import { Component, NgZone, OnInit, ViewChild } from '@angular/core';
import { ITenantSettings } from '@rsApp/modules/utils/models/app-settings.model';
import { TenantSettingsStore } from '@rsApp/modules/utils/providers/tenant-settings.service';
import { FormBuilder, Validators } from '@angular/forms';
import { filter, firstValueFrom, of } from 'rxjs';
import { NgxPubSubService } from '@pscoped/ngx-pub-sub';
import { GlobalRegex, enumTrackAction } from '@rsApp/modules/utils/enum/enum';
import { GoogleAnalyticTracker } from '@rsApp/modules/utils/providers/google-tracker.service';
import { ActivatedRoute, NavigationEnd, Router } from '@angular/router';
import { AuthService } from '../../providers/auth-v2.service';
import { MagAppDialogComponent } from '@rsApp/components/mag-app-dialog/mag-app-dialog';
import { ELoginFailCode } from '../../utils/enum';
import { ModalController, NavController } from '@ionic/angular';
import { MagModalConfirmComponent } from '@rsApp/components/mag-confirm-modal/mag-modal-confirm';
import { SignInErrorMessages } from '../../utils/errorMessage';
import { TranslateService } from '@ngx-translate/core';
import { Capacitor } from '@capacitor/core';
import { NativeBiometric } from '@capgo/capacitor-native-biometric';
import { Storage } from '@ionic/storage';
import { ChangeDetectorRef, OnDestroy } from '@angular/core';
import { AppSettings } from '@rsApp/modules/utils/providers/app-setting';
import { SettingKey } from '../../utils/interface';
import { SubscriptionService } from '@rsApp/modules/account-v2/providers/subscription.service';
import { Credential } from '@rsApp/modules/auth-v2/providers/credential.service';

import { User } from '@rsApp/modules/account-v2/providers/user.service';
import { iosSmooth } from '@rsApp/animations/route-animation';
@Component({
  selector: 'sign-in',
  templateUrl: 'sign-in.html',
  styleUrls: ['./sign-in.scss'],
})
export class SignInPageComponent implements OnInit, OnDestroy {
  private tenantSettings: ITenantSettings;
  logoUrl: string;
  showPassword: boolean = false;
  isUserAuthorized: boolean = false;
  isSubmitting: boolean = false;
  isCheckedBiometric: boolean = false;
  loginForm;
  returnRoute: string;
  email: string;
  permissionDenied: boolean = false;
  invalidUsernamePassword: boolean = false;
  allowGuest: boolean = false;
  isMultiLingual: boolean = false;
  contactLink: string;
  systemAlertConfig: {
    title: string;
    message: string;
    actionText: string;
  };
  account = { username: '', password: '' };
  isBiometricSupported = false;
  isWeeklyAdsSupport: boolean = false;
  subscriptionData: {
    Phone?: string;
    Name?: string;
    StoreCode?: string;
    AudienceIds?: string[];
    ReceiveEmail?: boolean;
    ReceiveTextMessage?: boolean;
  } | null = null;

  constructor(
    private tenantSettingsStore: TenantSettingsStore,
    private fb: FormBuilder,
    public events: NgxPubSubService,
    private googleTracking: GoogleAnalyticTracker,
    public router: Router,
    public route: ActivatedRoute,
    private authService: AuthService,
    private modalCtrl: ModalController,
    private navCtrl: NavController,
    private translate: TranslateService,
    private ngZone: NgZone,
    private storage: Storage,
    private cd: ChangeDetectorRef,
    private appSettingsService: AppSettings,
    private subscriptionService: SubscriptionService,
    private userService: User,
    private cre: Credential
  ) {
    const params = this.route.snapshot.paramMap;
    this.returnRoute = params.get('returnRoute') || null;

    this.email = this.router.getCurrentNavigation().extras.state?.email;

    this.loginForm = this.fb.group({
      userIdentifier: [this.email || '', [Validators.required, Validators.pattern(GlobalRegex.EMAIL)]],
      password: ['', [Validators.required]],
    });
  }
  @ViewChild('dialogModal') dialogComponent!: MagAppDialogComponent;

  async ngOnInit() {
    const isVerifyUser = this.isUserVerify();
    if (isVerifyUser) return;
    // Listen for closing on consent cookie Closed
    document.addEventListener('allSDKViewsDismissed', this.onConsentClosed);
    // Detect navigate to sign-in page and reset the form
    this.router.events.pipe(filter((event) => event instanceof NavigationEnd)).subscribe((event: any) => {
      if (event.url === '/sign-in') {
        this.reset();
      }
    });

    this.tenantSettings = await this.tenantSettingsStore.getTenantSettings();
    this.contactLink = this.tenantSettings?.pages?.contactUs || '';
    this.systemAlertConfig = {
      title: this.translate.instant('error.signIn.systemError.title'),
      message: this.translate.instant('error.signIn.systemError.message', { link: this.contactLink }),
      actionText: this.translate.instant('common.close'),
    };
    this.isMultiLingual = this.tenantSettings?.languages?.length > 1;
    this.logoUrl = this.tenantSettings?.logoUrl;
    const guestModeSetting = await this.tenantSettingsStore.getGuestModeSetting();
    this.allowGuest = guestModeSetting?.SettingValue === 'true';
    this.isWeeklyAdsSupport = await this.initWBSettings();
  }

  async initWBSettings() {
    try {
      const value = await firstValueFrom(
        this.appSettingsService.getSettingValue(SettingKey.PrimarySubscriptionSupport)
      );
      if (!value) {
        console.warn('Loyalty support setting not found or empty');
      }
      return JSON.parse(value);
    } catch (err) {
      console.warn('Error fetching loyalty_support setting:', err);
      return false;
    }
  }

  async ionViewWillEnter() {
    const getUser = this.userService.getterEmail();
    if (getUser?.path === 'forgot-password') {
      const email = getUser?.email || '';
      this.loginForm.patchValue({ userIdentifier: email });
      this.isUserAuthorized = true;
    }
  }

  isUserVerify() {
    const user = this.cre.currentUser;
    if (!user) return false;
    if (user && user?.IsForceVerifyEmail && !user.IsVerifiedEmail) return false;
    if (user && user.IsForceVerifyPhone && !user.IsVerifiedPhone) return false;
    return true;
  }

  async ionViewDidEnter() {
    const isVerifyUser = this.isUserVerify();
    if (isVerifyUser) {
      requestAnimationFrame(() => {
        this.navCtrl.navigateRoot(['/tabs/home'], {
          animated: true,
          animation: iosSmooth,
        });
      });
      return;
    }
    const isCookieOpen = await this.storage.get('forceOpenBanner');
    if (Capacitor.isNativePlatform() && !isCookieOpen) {
      this.startBiometricIfAllowed();
    }
  }

  ngOnDestroy() {
    document.removeEventListener('allSDKViewsDismissed', this.onConsentClosed);
  }

  // Starting Biometric pipeline
  private async startBiometricIfAllowed() {
    document.removeEventListener('allSDKViewsDismissed', this.onConsentClosed);
    this.isBiometricSupported = await this.checkBiometricSupported();
    this.isBiometricSupported && (await this.loadBiometric());
  }

  private onConsentClosed = async () => {
    if (Capacitor.isNativePlatform()) {
      this.startBiometricIfAllowed();
    }
  };

  private async checkBiometricSupported(): Promise<boolean> {
    try {
      const result = await firstValueFrom(this.appSettingsService.getSettingValue('biometric_support'));
      return JSON.parse(result);
    } catch (e) {
      console.warn('Error fetching biometric support setting:', e);
      return false;
    }
  }

  async loadBiometric() {
    try {
      const result = await this.safeIsAvailable();
      if (!result?.isAvailable || !result?.biometryType) return;

      const isCheckedBiometric = await this.storage.get('isCheckedBiometric');
      if (!isCheckedBiometric) return;

      const verified = await this.verifyBiometric('Verify to login');
      if (!verified) {
        this.isCheckedBiometric = true;
        return;
      }

      const creds = await NativeBiometric.getCredentials({ server: `${(window as any).TenantId}` });
      if (creds?.username && creds?.password) {
        this.loginForm.patchValue({
          userIdentifier: creds.username,
          password: creds.password,
        });
        this.isSubmitting = true;
        this.isCheckedBiometric = true;
        await this.login();
      } else {
        console.warn('No credentials found');
      }
    } catch (e) {
      console.warn('loadBiometric error:', e);
    }
  }

  async saveBiometric() {
    if (!this.isCheckedBiometric) {
      this.verifyBiometric('Check to open faceid/fingerid modal');
    }
    this.storage.remove('forceOpenBanner');
    try {
      this.storage.set('isCheckedBiometric', 'true');
      try {
        await NativeBiometric.deleteCredentials({ server: `${(window as any).TenantId}` });
      } catch {
        console.warn('No existing credentials to delete');
      }
      const payload = this.loginForm.value;
      await NativeBiometric.setCredentials({
        username: payload.userIdentifier,
        password: payload.password,
        server: `${(window as any).TenantId}`,
      });
    } catch (e) {
      console.warn('save Biometric error:', e);
    }
  }

  private async handleBiometricSave(): Promise<void> {
    try {
      const result = await this.safeIsAvailable();
      if (result?.isAvailable && result?.biometryType) {
        this.saveBiometric();
      }
    } catch (err) {
      console.warn('handle biometric save', err);
    }
  }

  private async safeIsAvailable(): Promise<{ isAvailable: boolean; biometryType?: any }> {
    try {
      return await NativeBiometric.isAvailable();
    } catch (e) {
      console.warn('Biometric isAvailable check failed:', e);
      return { isAvailable: false };
    }
  }

  private async verifyBiometric(reason = 'Verify your identity'): Promise<boolean> {
    try {
      await NativeBiometric.verifyIdentity({
        reason,
        title: 'Secure Login',
        description: 'Use your fingerprint to verify your identity',
        maxAttempts: 5,
      });
      return true;
    } catch (e) {
      console.warn('Biometric verification failed:', e);
      return false;
    }
  }
  // End Biometric pipeline

  get userAccount() {
    return this.loginForm.get('userIdentifier')?.value;
  }

  async checkUserOrEmailExists(authService, userIdentifier: string): Promise<boolean> {
    const input = userIdentifier?.trim();
    if (!input) return false;

    const isEmail = GlobalRegex?.EMAIL.test(input);

    const checkFn = isEmail ? authService.checkEmailExists : authService.checkUserExists;

    return await firstValueFrom(checkFn.call(authService, input));
  }

  // TODO
  async clearUser() {
    // clear  user when forge to sign in
    if (this.cre.currentUser) {
      await this.authService.logout();
    }
  }

  reset() {
    this.clearUser();
    this.loginForm.get('userIdentifier')?.reset();
    this.loginForm.get('password')?.reset();
    this.isUserAuthorized = false;
    this.permissionDenied = false;
    this.invalidUsernamePassword = false;
  }

  async authorizeUserIdentifier(userIdentifier: string) {
    try {
      const isExists = await this.checkUserOrEmailExists(this.authService, userIdentifier);
      if (isExists) {
        this.ngZone.run(() => {
          this.isUserAuthorized = true;
        });
      } else {
        if (this.isWeeklyAdsSupport) {
          this.subscriptionData = await firstValueFrom(this.subscriptionService.getSubsciptionByEmail(userIdentifier));
        }
        // navigate to signup with the email
        this.router.navigate(['/sign-up'], {
          state: { email: userIdentifier, subscriptionData: this.subscriptionData },
        });
      }
    } catch (err) {
      console.error('Error authorizing user identifier:', err);
    }
  }

  validateControl(controlName: string): boolean {
    const control = this.loginForm.get(controlName);
    if (control?.invalid) {
      control.markAsTouched();
      return false;
    }
    return true;
  }

  async validateUserIdentifier() {
    if (this.isSubmitting) return;

    this.isSubmitting = true;
    try {
      const isValid = this.validateControl('userIdentifier');
      if (isValid) {
        await this.authorizeUserIdentifier(this.userAccount);
      }
    } catch (error) {
      console.error('Error validating user identifier:', error);
    } finally {
      this.ngZone.run(() => {
        this.isSubmitting = false;
      });
    }
  }

  async validatePassword() {
    if (this.isSubmitting) return;

    this.isSubmitting = true;
    try {
      const isValid = this.validateControl('password');
      if (isValid) {
        await this.login();
      }
    } catch (error) {
      console.error('Error validating password:', error);
    } finally {
      this.ngZone.run(() => {
        this.isSubmitting = false;
      });
    }
  }

  async login() {
    this.resetLoginErrors();
    const payload = this.loginForm.value;
    try {
      const res = await firstValueFrom(this.authService.login(payload, false));
      if (!res?.FailCode) {
        await this.handlePostLogin(res);
      } else {
        if (this.isCheckedBiometric) this.isUserAuthorized = true;
        this.isSubmitting = false;
        this.cd.detectChanges();
        this.handlErrorMsg(res.FailCode);
      }
    } catch (err) {
      console.error('Login failed', err);
    }
  }

  exploreAsGuest() {
    this.navCtrl.navigateRoot('/tabs/home', { replaceUrl: true });
  }

  handlErrorMsg(failCode: string) {
    switch (failCode) {
      case ELoginFailCode.PERMISSION_DENIED:
        this.permissionDenied = true;
        break;

      case ELoginFailCode.INVALID_USERNAME_PASSWORD:
        this.invalidUsernamePassword = true;
        this.loginForm.get('password')?.setErrors({ hiddenError: true });
        this.loginForm.get('password')?.markAsTouched();
        break;

      case ELoginFailCode.MAX_INVALID_PASSWORD_ATTEMPTS:
        this.openConfirmResetPasswordModal();
        break;

      case ELoginFailCode.USER_NOT_ACTIVE:
      case ELoginFailCode.USER_LOCKED_OUT:
      case ELoginFailCode.USER_NOT_LOYALTY_CARD:
      case ELoginFailCode.SYSTEM_ERROR: {
        const config = SignInErrorMessages[failCode as ELoginFailCode];
        if (config) {
          this.systemAlertConfig.title = this.translate.instant(config.title);
          this.systemAlertConfig.message = this.translate.instant(config.message, { link: this.contactLink });
          this.systemAlertConfig.actionText = this.translate.instant('common.close');
          this.dialogComponent.openDialog();
        }
        break;
      }
    }
  }

  private resetLoginErrors() {
    this.invalidUsernamePassword = false;
    this.permissionDenied = false;
    this.loginForm.get('password')?.setErrors(null);
  }

  async openConfirmResetPasswordModal() {
    const modal = await this.modalCtrl.create({
      component: MagModalConfirmComponent,
      componentProps: {
        title: this.translate.instant('error.signIn.manyFailedAttempts.title'),
        description: this.translate.instant('error.signIn.manyFailedAttempts.message', { link: this.contactLink }),
        confirmTitle: this.translate.instant('login.forgotPassword'),
        cancelTitle: this.translate.instant('common.cancel'),
      },
      cssClass: 'mag-confirm-modal',
    });

    modal.onDidDismiss().then((result) => {
      if (result?.data) {
        this.router.navigate(['/forgot-password'], { state: { email: this.userAccount } });
      }
    });

    await modal.present();
  }

  //ToDo
  async handlePostLogin(user) {
    try {
      await firstValueFrom(this.authService._postLogin(of(user)));
      this.events.publishEvent(enumTrackAction.Login, user);
      this.eventTrackingLogin(user?.User?.UserId);
      this.events.publishEvent(enumTrackAction.TrackUserProperty, {
        name: 'MemberID',
        value: user && (user?.User?.LoyaltyCardId || user?.User?.CustomerCode || ''),
      });
      if (Capacitor.isNativePlatform() && this.isBiometricSupported) {
        this.handleBiometricSave();
      }
      this.isSubmitting = false;
      this.userService.setterEmail(null, null);
      this.close();

      firstValueFrom(this.authService.generateCookieConsentToken())
        .then((dataToken) => {
          window.postMessage({ action: 'MagInitCookieConsent', payload: { dataToken } }, window.location.origin);
        })
        .catch(() => {
          window.postMessage({ action: 'MagInitCookieConsent', payload: { dataToken: null } }, window.location.origin);
        });
    } catch (err) {
      console.error('Error handling post login:', err);
      this.isSubmitting = false;
    }
  }

  close() {
    if (this.returnRoute) {
      this.router.navigateByUrl(this.returnRoute);
    } else {
      this.navCtrl.navigateRoot('/tabs/home', { replaceUrl: true });
    }
  }

  eventTrackingLogin(userId) {
    this.googleTracking.gtagTrackLogin(this.loginForm.userIdentifier, userId);
  }

  forgotPassword() {
    this.router.navigate(['/forgot-password'], { state: { email: this.userAccount } });
  }

  closeAlert() {
    this.dialogComponent.closeDialog();
  }
}
