import { Component, Input, Output, EventEmitter, OnChanges } from '@angular/core';

@Component({
  selector: 'mag-account-email-options',
  templateUrl: './mag-account-email-options.html',
  styleUrls: ['./mag-account-email-options.scss'],
})
export class MagAccountEmailOptionsComponent implements OnChanges {
  @Input() emailProviders: string[] = [];
  @Input() selectedEmailProvider: string[] = [];
  @Input() title: string = '';

  @Output() selectionChange = new EventEmitter<string[]>();

  parentChecked: boolean = false;
  parentIndeterminate: boolean = false;

  ngOnChanges() {
    this.updateParentState();
  }

  // Called when the parent checkbox is toggled
  onParentChange(event: any) {
    this.parentChecked = event.detail.checked;

    if (this.parentChecked) {
      this.selectedEmailProvider = [...this.emailProviders]; // Select all providers
    } else {
      this.selectedEmailProvider = []; // Deselect all providers
    }

    this.updateParentState();
    this.selectionChange.emit(this.selectedEmailProvider); // Emit the updated list
  }

  // Called when any child checkbox is toggled
  onChildChange(provider: string, event: any) {
    const checked = event.detail.checked;
    if (checked) {
      if (!this.selectedEmailProvider.includes(provider)) {
        this.selectedEmailProvider.push(provider);
      }
    } else {
      this.selectedEmailProvider = this.selectedEmailProvider.filter((f) => f !== provider);
    }

    this.updateParentState();
    this.selectionChange.emit(this.selectedEmailProvider); // Emit the updated list
  }

  // Update the parent checkbox state (checked + indeterminate)
  updateParentState() {
    const total = this.emailProviders?.length;
    const selected = this.selectedEmailProvider?.length;

    this.parentChecked = selected === total; // If all are selected, parent is checked
    this.parentIndeterminate = selected > 0 && selected < total; // If some are selected, parent is indeterminate
  }
}
