import { Inject, Injectable } from '@angular/core';
import { BehaviorSubject, firstValueFrom, map, of } from 'rxjs';
import { IMagProduct, IMagProductRes } from '../../product/model/interface';
import { Credential } from '@rsApp/modules/auth-v2/providers/credential.service';
import { MagEComCoreApiHttpClient } from '@rsApp/modules/gateway/mag-ecom-core-api.service';
import { MAG_CART_V2_HTTP_CLIENT } from '../../utils/ecom-api-configs';
import { IMagShoppingList } from '@rsApp/modules/interfaces/shopping-list.interface';

@Injectable({ providedIn: 'root' })
export class ShoppingListService {
  private userId;
  private currentShoppingList: BehaviorSubject<IMagShoppingList | null> = new BehaviorSubject(null);
  private allShoppingLists: BehaviorSubject<IMagShoppingList[]> = new BehaviorSubject([]);

  constructor(
    private cre: Credential,
    @Inject(MAG_CART_V2_HTTP_CLIENT) private api: MagEComCoreApiHttpClient
  ) {
    this.userId = this.cre.currentUser?.UserId;
  }

  private fetchCurrentShoppingList() {
    return this.api.post('/shoppinglist/init', null).pipe(
      map((data: IMagShoppingList) => {
        return data;
      })
    );
  }

  private fetchShoppingListByUserId() {
    if (!this.userId) return of([]);
    return this.api.get(`/shoppinglist/users/${this.userId}`).pipe(
      map((data: IMagShoppingList[]) => {
        return data;
      })
    );
  }

  private async addItemToCurrentList(product: IMagProduct | IMagProductRes) {
    const shoppingListId = this.currentShoppingList.getValue()?.Id;
    if (!shoppingListId) return;
    return await firstValueFrom(
      this.api
        .post(`/shoppinglist/${shoppingListId}/items`, {
          productId: product.ProductId,
          optionSets: product?.OptionSets,
        })
        .pipe(
          map((data: number) => {
            return data;
          })
        )
    );
  }

  getCurrentShoppingList() {
    return this.currentShoppingList.asObservable();
  }

  public async initData() {
    const shoppinglist = await firstValueFrom(this.fetchCurrentShoppingList());
    this.currentShoppingList.next(shoppinglist);
  }

  async handleGetShoppingListByUserId() {
    if (!this.userId) return;
    const allLists = await firstValueFrom(this.fetchShoppingListByUserId());
    this.allShoppingLists.next(allLists);
    const shoppingListId = this.currentShoppingList.getValue()?.Id;
    const findList = allLists.find((list) => list.Id === shoppingListId);
    if (findList) this.currentShoppingList.next(findList);
  }

  async handleAddItemToCurrentShoppingList(product: IMagProduct | IMagProductRes) {
    try {
      await this.addItemToCurrentList(product);
      await this.handleGetShoppingListByUserId();
    } catch (error) {
      console.error(error);
    }
  }
}
