import { Component, Input, OnInit } from '@angular/core';
import { Credential } from '@rsApp/modules/auth-v2/providers/credential.service';
import { AccountManagementSettingKeys } from '@rsApp/modules/utils/models/app-settings.model';
import { AppSettings } from '@rsApp/modules/utils/providers/app-setting';
import { toBoolean } from '@rsApp/modules/utils/providers/utils';
import { firstValueFrom } from 'rxjs';
import { EnumAudienceType, ICampaign } from '../../model/interface';
import { SubscriptionService } from '../../providers/subscription.service';
import { AccountChoice } from '../../utils/enum';

@Component({
  selector: 'mag-account-accordion',
  templateUrl: './mag-account-accordion.html',
  styleUrls: ['./mag-account-accordion.scss'],
})
export class MagAccountAccordionComponent implements OnInit {
  isWeeklyAdsSupport: boolean = false;
  communicationSetting: boolean = false;
  activeIndex: number | null = null;
  isBusiness: boolean;
  user: any;

  public campaigns: ICampaign[];

  @Input() openPreferencesOnInit = false;

  toggle(index: number): void {
    this.activeIndex = this.activeIndex === index ? null : index;
  }
  constructor(
    public cre: Credential,
    public appSettingsService: AppSettings,
    public subscriptionSvc: SubscriptionService
  ) {
    Promise.all([this.loadSettingAM()]).then(([settings]) => {
      this.isWeeklyAdsSupport = toBoolean(settings?.primary_subscription_support);
      const commSetting = settings?.communication_setting;
      this.communicationSetting = !!(commSetting && commSetting.length > 0);
      this.shouldOpenPreferences();
    });
  }

  ngOnInit(): void {
    const { AccountType } = this.cre.currentUser || {};
    this.isBusiness = AccountType === AccountChoice.BUSINESS;
    this.initCampaigns();
  }

  private shouldOpenPreferences(): void {
    if (this.communicationSetting && this.openPreferencesOnInit) {
      this.activeIndex = 4;
    }
  }

  private async loadSettingAM(): Promise<Record<AccountManagementSettingKeys, string>> {
    try {
      const setting: Record<AccountManagementSettingKeys, string> = await firstValueFrom(
        this.appSettingsService.getSettingByPath('ACCOUNT MANAGEMENT')
      );
      return setting;
    } catch (error) {
      console.error(error);
    }
  }

  private async initCampaigns() {
    try {
      const audiencesRes = await firstValueFrom(
        this.subscriptionSvc.getAudiencesByType(EnumAudienceType.Subscription, '')
      );
      this.campaigns = audiencesRes.map((e) => {
        return {
          Id: e.Id,
          Name: e.Name,
          Checked: false,
        };
      });
    } catch (error) {
      console.error(error);
    }
  }
}
