import { Component, EventEmitter, Input, Output, ViewChild } from '@angular/core';
import { AbstractControl } from '@angular/forms';
import { Router } from '@angular/router';
import { MagOtpActionType } from '@rsApp/components/interface';
import { MagAppBottomSheetComponent } from '@rsApp/components/mag-app-bottom-sheet/mag-app-bottom-sheet';
import { IUpdateUserPayload } from '../../utils/enum';
import { EventBusService } from '@rsApp/modules/utils/providers/event-bus.service';
@Component({
  selector: 'mag-force-verify-phone',
  templateUrl: 'mag-force-verify-phone.html',
  styleUrls: ['./mag-force-verify-phone.scss'],
})
export class ForceVerifyPhoneComponent {
  bottomSheetView: 'enter' | 'verify' = 'enter';
  valuePhone: AbstractControl;

  @Input() phone: string = '';
  @Input() dataUser: any;
  @Input() actionType: MagOtpActionType = MagOtpActionType.VERIFY_PHONE_ACCOUNT;

  @Output() eventVerifySuccess: EventEmitter<boolean> = new EventEmitter();
  @Input() userPayload: IUpdateUserPayload;

  @Output() verifiedSuccess = new EventEmitter<{ type: MagOtpActionType; otp: string }>();

  @ViewChild('bottomSheet') bottomSheetComponent!: MagAppBottomSheetComponent;
  public methodSelected: string;

  constructor(
    public router: Router,
    private eventBus: EventBusService
  ) {}

  handleVerifiedSuccess() {
    this.verifiedSuccess.emit({ type: this.actionType, otp: '' });
  }

  openBottomSheet() {
    this.eventBus.emit('sms');
    this.bottomSheetComponent.openModal();
  }

  closeBottomSheet() {
    this.bottomSheetComponent.closeModal();
  }

  public onOtpRequested(value) {
    if (!value || !value.status) {
      this.closeBottomSheet();
      return;
    }
    this.methodSelected = value.methodSelected;
    this.bottomSheetView = 'verify';
  }

  handleVerified(event?) {
    if (event && Object.keys(event).length > 0) {
      this.eventVerifySuccess.emit(event);
    } else {
      this.bottomSheetComponent.closeModal();
    }
  }

  public onBottomSheetDismiss() {
    this.bottomSheetView = 'enter';
  }
}
