import { Component, Input, Output, EventEmitter } from '@angular/core';

@Component({
  selector: 'mag-app-button',
  templateUrl: './mag-app-button.html',
  styleUrls: ['./mag-app-button.scss'],
})
export class MagAppButtonComponent {
  @Input() title: string = '';
  @Input() loading: boolean = false;
  @Input() disabled: boolean = false;
  @Input() type: 'button' | 'submit' = 'button';
  @Input() variant: 'primary'; // TODO: add more variants
  @Input() size: 'medium' | 'small' = 'medium'; // TODO: add more sizes
  @Output() buttonClick = new EventEmitter<void>();

  onClick(): void {
    if (!this.loading && !this.disabled) {
      this.buttonClick.emit();
    }
  }
}
