import { Component, EventEmitter, Input, OnDestroy, OnInit } from '@angular/core';
import { ModalController } from '@ionic/angular';
import { DxpComponentService } from '@rsApp/modules/utils/providers/dxp.component.service';
import { LocationFulfillmentComponent } from '../location-fulfillment/location-fulfillment.component';
import { Subject, takeUntil } from 'rxjs';
import { RouteTrackerService } from '@rsApp/modules/utils/providers/route-tracker.service';

@Component({
  selector: 'app-location-bar',
  templateUrl: './location-bar.component.html',
  styleUrls: ['./location-bar.component.scss'],
})
export class LocationBarComponent implements OnInit, OnDestroy {
  @Input() isAdjustUI: boolean = false;
  public magFulfillmentManagement = '';
  public destroy$ = new Subject();

  constructor(
    private dxpComponentService: DxpComponentService,
    private modalCtrl: ModalController,
    private routeTracker: RouteTrackerService
  ) {}

  async ngOnInit() {
    await this.dxpComponentService.onConnected();
    this.routeTracker
      .getRenderType()
      .pipe(takeUntil(this.destroy$))
      .subscribe((value) => {
        this.magFulfillmentManagement = `<mag-fulfillment-management render-type="${value}"></mag-fulfillment-management>`;
      });
  }

  ngOnDestroy() {
    this.magFulfillmentManagement = '';
    this.destroy$.next(true);
  }

  async openModal() {
    const modal = await this.modalCtrl.create({
      component: LocationFulfillmentComponent,
      componentProps: {
        closeModal: new EventEmitter(),
      },
      cssClass: 'location-fulfillment',
    });
    await modal.present();
    await modal.componentProps.closeModal.subscribe(() => {
      modal.dismiss();
    });
    return modal;
  }
}
