import { Injectable } from '@angular/core';
import moment from 'moment';
import { BehaviorSubject } from 'rxjs';
import { CurrentStore } from '../store/store.module';
import { IMagCartInfo } from './product/model/interface';

@Injectable({
  providedIn: 'root',
})
export class EditOrderService {
  public cartInfor: BehaviorSubject<IMagCartInfo> = new BehaviorSubject({
    isEditOrderMode: false,
    editOrderId: '',
    editOrderExpiry: '',
    slotPicking: null,
  });
  constructor(private currentStore: CurrentStore) {}

  setCartInfo = (cartInfor: any) => {
    return this.cartInfor.next(cartInfor);
  };

  getEditCartInfor = () => {
    const cartInfor = this.cartInfor.getValue();
    return cartInfor;
  };

  cartObs = () => {
    return this.cartInfor.asObservable();
  };

  isEditMode = () => {
    const { isEditOrderMode } = this.getEditCartInfor();
    return isEditOrderMode;
  };

  getExpireTimeEditOrder = async () => {
    const { slotPicking } = this.getEditCartInfor();
    const currentStore = await this.currentStore.getStore();
    const { ZoneName } = currentStore || {};
    const now = moment.utc().tz(ZoneName);
    const minutes = moment.utc(slotPicking?.StartSlotTime).tz(ZoneName).diff(now, 'minutes');
    return minutes;
  };
}
