import { Injectable, NgZone } from '@angular/core';
import { Capacitor } from '@capacitor/core';
import {
  FirebaseMessaging,
  PermissionStatus,
  TokenReceivedEvent,
  NotificationReceivedEvent,
  NotificationActionPerformedEvent,
} from '@capacitor-firebase/messaging';
import { Router } from '@angular/router';
import { NavController, Platform } from '@ionic/angular';
import { NgxPubSubService } from '@pscoped/ngx-pub-sub';
import { Utils } from './utils';
import { Logger, LoggingService } from 'ionic-logging-service';
import { enumTrackAction } from '../enum/enum';
import { Subject } from 'rxjs';
import { LocalNotifications } from '@capacitor/local-notifications';
import { App } from '@capacitor/app';

interface NotificationData {
  tap?: string;
  deeplink?: string;
  data?: {
    originalLink?: string;
  };
  originalLink?: string;
  message_source?: string;
  order_id?: string;
  order_state?: string;
  customer_state?: string;
  aps?: {
    alert?: {
      title?: string;
      body?: string;
    };
  };
  title?: string;
  body?: string;
}

@Injectable({
  providedIn: 'root',
})
export class NotificationService {
  private logger: Logger;
  private notificationReceived$ = new Subject<any>();
  private permission: PermissionStatus;
  private initialized = false;
  private localIdToUrl = new Map<number, string>();

  constructor(
    private ngZone: NgZone,
    private router: Router,
    private navCtrl: NavController,
    private events: NgxPubSubService,
    private utils: Utils,
    private loggingService: LoggingService,
    private platform: Platform
  ) {
    this.logger = this.loggingService.getLogger('Notification');
  }

  /**
   * Initialize the notification service
   */
  async initialize(): Promise<void> {
    if (this.initialized) {
      return;
    }
    if (!Capacitor.isNativePlatform()) {
      this.logger.info('Not a native platform, skipping FCM initialization');
      return;
    }

    try {
      this.logger.info('Starting FCM initialization');
      await this.ensurePermissionsSystemOnly();
      await this.ensureAndroidChannel();
      await this.setupNotificationHandlers();
      await this.handleDeliveredNotifications();
      // Clear badges/delivered notifications on app open
      await this.clearAllBadges();
      // Clear again whenever app returns to foreground
      App.addListener('appStateChange', async ({ isActive }) => {
        if (isActive) {
          await this.clearAllBadges();
        }
      });
      this.initialized = true;
    } catch (error) {
      this.logger.error('Error initializing notification service:', error);
    }
  }

  private async ensurePermissionsSystemOnly(): Promise<void> {
    try {
      // Request Local Notifications permission first (this usually covers FCM too)
      const localCheck = await LocalNotifications.checkPermissions();
      if (localCheck?.display === 'prompt') {
        await LocalNotifications.requestPermissions();
      }

      // FCM permission is usually granted automatically when Local is granted
      const fcmCheck = await FirebaseMessaging.checkPermissions();
      this.permission = fcmCheck;

      if (fcmCheck.receive === 'denied') {
        this.logger.warn('Remote notification permission denied');
      }
    } catch (error) {
      this.logger.warn('ensurePermissionsSystemOnly error', error);
    }
  }

  /**
   * Clear all delivered notifications to reset launcher badges (Android) and best-effort on iOS
   */
  public async clearAllBadges(): Promise<void> {
    try {
      const lnAny: any = LocalNotifications as any;
      if (typeof lnAny?.removeAllDeliveredNotifications === 'function') {
        await lnAny.removeAllDeliveredNotifications();
      }
    } catch (e) {
      this.logger.warn('clearAllBadges failed', e);
    }
  }

  /**
   * Setup notification handlers and listeners
   */
  private async setupNotificationHandlers(): Promise<void> {
    this.logger.info('Setting up notification handlers');

    // Token received listener
    FirebaseMessaging.addListener('tokenReceived', (event: TokenReceivedEvent) => {
      this.logger.info('FCM token received:', event.token);
      this.publishTokenEvent(event.token);
    });

    // Notification received listener (foreground)
    FirebaseMessaging.addListener('notificationReceived', (event: NotificationReceivedEvent) => {
      this.logger.info('Notification received:', event);
      this.ngZone.run(async () => {
        this.notificationReceived$.next(event);
        const data = event.notification?.data as NotificationData;
        const raw = event.notification as any;
        const title = data?.title ?? data?.aps?.alert?.title ?? raw?.title ?? 'Notification';
        const body = data?.body ?? data?.aps?.alert?.body ?? raw?.body ?? '';
        const url = data?.deeplink || data?.data?.originalLink || data?.originalLink;

        try {
          const appState = await App.getState();
          const isForeground = appState?.isActive === true;

          // Show local banner only on Android; iOS uses presentationOptions in capacitor.config.ts
          if (isForeground && this.platform.is('android')) {
            await this.showPushNotification(title, body, url);
            return;
          }
        } catch (error) {
          console.warn('Error showing push notification:', error);
        }
      });
    });

    // Push notification tap (iOS/Android)
    FirebaseMessaging.addListener('notificationActionPerformed', (event: NotificationActionPerformedEvent) => {
      this.logger.info('Notification action performed:', event);
      this.ngZone.run(async () => {
        try {
          const data = event.notification.data as NotificationData;
          await this.navigateFromNotification(data);
        } catch (error) {
          this.logger.error('Error handling notification tap:', error);
        }
      });
    });

    // Local notification tap (Android foreground banner)
    LocalNotifications.addListener('localNotificationActionPerformed', (event: any) => {
      this.logger.info('Local notification action performed:', event);
      this.ngZone.run(async () => {
        const notif: any = event?.notification;
        const id: number = notif?.id;
        const url = notif?.extra?.deeplink || this.localIdToUrl.get(id);
        if (url) {
          await this.navigateFromNotification({ deeplink: url } as NotificationData);
        }
      });
    });
  }

  /**
   * Handle delivered notifications
   */
  private async handleDeliveredNotifications(): Promise<void> {
    try {
      const messagingAny = FirebaseMessaging as any;
      const initial = await messagingAny.getInitialNotification?.();
      if (initial?.notification?.data) {
        this.logger.info('Processing initial notification:', initial.notification.data);
        await this.navigateFromNotification(initial.notification.data as NotificationData);
      }
    } catch (error) {
      this.logger.error('Error handling delivered notifications:', error);
    }
  }

  /**
   * Unified navigation handler for all notification taps
   */
  private async navigateFromNotification(data: NotificationData): Promise<void> {
    const url = data.deeplink || data.data?.originalLink || data.originalLink;
    if (!url) return;
    try {
      // Handle custom app scheme first
      if (url.includes('app://')) {
        const internalUrl = url.replace('app://', '/');
        await this.router.navigateByUrl(internalUrl);
        return;
      }

      // Handle Firebase Dynamic Link style URLs to match app.component.ts logic
      // Example: https://bigy-links.mercatus.com/deeplink/?link=...&afl=...&ifl=...
      const parsed = new URL(url);
      const isDynamicLinkHost = parsed.pathname === '/deeplink/';
      if (isDynamicLinkHost) {
        const appDynamicLink =
          parsed.searchParams.get('afl') || parsed.searchParams.get('ifl') || parsed.searchParams.get('link');
        if (appDynamicLink) {
          try {
            const deepUrl = new URL(appDynamicLink);
            const appUrl = await this.utils.mappingDynamicLink(deepUrl.pathname, deepUrl.search);
            if (appUrl) {
              await this.router.navigateByUrl(appUrl);
              return;
            }
            // Fallback to opening the resolved deep link in system if mapping not found
            await this.utils.openInSystem(deepUrl.href);
            return;
          } catch (e) {
            console.warn('Failed to parse inner dynamic link URL', e);
          }
        }
      }

      // Default behavior: open in system (external browser)
      this.utils.openInSystem(url);
    } catch (err) {
      console.warn('navigateFromNotification failed, opening in system as fallback', err);
      this.utils.openInSystem(url);
    }
  }

  /**
   * Get FCM token for a user
   */
  async getFCMToken(user?: any): Promise<string | null> {
    if (!Capacitor.isNativePlatform()) {
      return null;
    }

    try {
      const { token } = await FirebaseMessaging.getToken();
      this.publishTokenEvent(token, user);
      return token;
    } catch (error) {
      this.logger.error('Error getting FCM token:', error);
      return null;
    }
  }

  /**
   * Publish token event
   */
  private publishTokenEvent(token: string, user?: any): void {
    this.events.publishEvent(enumTrackAction.SaveToken, {
      options: {
        DeviceToken: token,
        Notification: true,
        UserName: user?.Email || `guest-${token}`,
        CustomerCode: user?.CustomerCode,
        NotificationOptIn: this.permission.receive === 'granted',
      },
    });
  }

  /**
   * Subscribe to notification received events
   */
  onNotificationReceived() {
    return this.notificationReceived$.asObservable();
  }

  async showPushNotification(title, body, deeplinkUrl?: string) {
    try {
      // Ensure ID fits Android int (max 2,147,483,647) and is definitely an integer
      const safeId = Math.floor(Math.random() * 2000000000);

      const baseNotification: any = {
        title: title,
        body: body,
        id: safeId,
      };

      if (this.platform.is('android')) {
        baseNotification.channelId = 'default';
        // Use existing drawable resource for consistent icon
        baseNotification.smallIcon = 'ic_launcher';
      }

      if (deeplinkUrl) {
        // iOS uses extra; Android action event may expose data or use our in-memory map
        baseNotification.extra = { deeplink: deeplinkUrl };
      }

      await LocalNotifications.schedule({
        notifications: [baseNotification],
      });

      if (deeplinkUrl) {
        this.localIdToUrl.set(safeId, deeplinkUrl);
      }
    } catch (e) {
      console.error('Notification failed:', e);
    }
  }

  private async ensureAndroidChannel(): Promise<void> {
    try {
      if (!this.platform.is('android')) return;
      const createChannel = (LocalNotifications as any).createChannel;
      if (typeof createChannel !== 'function') return;
      await (LocalNotifications as any).createChannel({
        id: 'default',
        name: 'General',
        description: 'Default notifications',
        importance: 5,
        sound: 'default',
        visibility: 1,
        lights: true,
        vibration: true,
      });
    } catch (error) {
      this.logger.warn('Failed to create Android channel', error);
    }
  }

  /**
   * Clean up listeners when service is destroyed
   */
  async destroy(): Promise<void> {
    try {
      await FirebaseMessaging.removeAllListeners();
      this.notificationReceived$.complete();
    } catch (error) {
      this.logger.error('Error destroying notification service:', error);
    }
  }
}
