import { Injectable } from '@angular/core';
import { FirebaseAnalytics } from '@capacitor-firebase/analytics';
import type {
  ViewItemListParams,
  SelectItemParams,
  Ga4MappedEvent,
  ViewItemParams,
  ViewSearchResultsParams,
  AddToCartParams,
  RemoveFromCartParams,
  ViewCartParams,
  BeginCheckoutParams,
  PurchaseParams,
} from '../../../analytics/mappers/ga4.types';
import { mapStencilToGa4 } from '../../../analytics/mappers/mapStencilToGa4';

@Injectable({ providedIn: 'root' })
export class NativeAnalyticsService {
  private readonly handlers: Partial<Record<Ga4MappedEvent['name'], (params: any) => Promise<void>>> = {
    view_item_list: (params) => this.viewItemList(params),
    select_item: (params) => this.selectItem(params),
    view_item: (params) => this.viewItem(params),
    view_search_result: (params) => this.viewSearchResult(params),
    add_to_cart: (params) => this.addToCart(params),
    remove_from_cart: (params) => this.removeFromCart(params),
    view_cart: (params) => this.viewCart(params),
    begin_checkout: (params) => this.beginCheckout(params),
    purchase: (params) => this.purchase(params),
    // add_this_event: (params) => this.addThisEvent(params),
  };

  async handleGa4Native(eventName: string, payload: any) {
    try {
      const mapped = mapStencilToGa4(eventName, payload);
      if (!mapped) return;

      const handler = this.handlers[mapped.name];
      if (!handler) return;

      await handler(mapped.params);
    } catch (err) {
      console.error('[GA4 native] Failed to send', eventName, err);
    }
  }

  async viewItemList(params: ViewItemListParams) {
    await FirebaseAnalytics.logEvent({ name: 'view_item_list', params });
  }

  async selectItem(params: SelectItemParams) {
    await FirebaseAnalytics.logEvent({ name: 'select_item', params: params });
  }

  async viewItem(params: ViewItemParams) {
    await FirebaseAnalytics.logEvent({ name: 'view_item', params });
  }

  async viewSearchResult(params: ViewSearchResultsParams) {
    const mappedParams = { search_term: params };
    await FirebaseAnalytics.logEvent({ name: 'view_search_result', params: mappedParams });
  }

  async addToCart(params: AddToCartParams) {
    await FirebaseAnalytics.logEvent({ name: 'add_to_cart', params });
  }

  async removeFromCart(params: RemoveFromCartParams) {
    await FirebaseAnalytics.logEvent({ name: 'remove_from_cart', params });
  }

  async viewCart(params: ViewCartParams) {
    await FirebaseAnalytics.logEvent({ name: 'view_cart', params });
  }

  async beginCheckout(params: BeginCheckoutParams) {
    await FirebaseAnalytics.logEvent({ name: 'begin_checkout', params });
  }

  async purchase(params: PurchaseParams) {
    await FirebaseAnalytics.logEvent({ name: 'purchase', params });
  }
}
