import { HttpErrorResponse, HttpEvent, HttpHandler, HttpInterceptor, HttpRequest } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { Router } from '@angular/router';
import { Network } from '@capacitor/network';
import { from, Observable, of, Subject, throwError, timer } from 'rxjs';
import { catchError, finalize, mergeMap, retry, switchMap, timeout } from 'rxjs/operators';
import { AuthService } from '../auth-v2/providers/auth-v2.service';
import { Credential } from '../auth-v2/providers/credential.service';

@Injectable()
export class AuthInterceptor implements HttpInterceptor {
  private refreshTokenInProgress = false;
  private refreshTokenSubject: Subject<any> = new Subject<any>();
  private readonly MAX_RETRY_COUNT = 3;
  private readonly RETRY_DELAY = 1000; // 1 second delay between retries
  private readonly REFRESH_TIMEOUT = 30000; // 30 seconds timeout

  constructor(
    private auth: AuthService,
    private cre: Credential,
    public router: Router
  ) {}

  intercept(req: HttpRequest<any>, next: HttpHandler): Observable<HttpEvent<any>> {
    const url = req.url;
    if (url.includes('/tokens/refresh') || url.includes('/tokens/')) {
      return next.handle(req);
    }

    return next.handle(req).pipe(
      catchError((error: HttpErrorResponse) => {
        if (this.isTokenExpiryErr(error)) {
          return from(Network.getStatus()).pipe(
            mergeMap((status) => {
              if (status.connectionType === 'none') {
                return throwError(() => error);
              }
              return this.handleTokenRefresh(req, next);
            })
          );
        }
        return throwError(() => error);
      })
    );
  }

  private isTokenExpiryErr(error: HttpErrorResponse): boolean {
    return error.status === 401;
  }

  private handleTokenRefresh(req: HttpRequest<any>, next: HttpHandler): Observable<HttpEvent<any>> {
    // Create new subject if it's closed or if we're starting a new refresh cycle
    if (this.refreshTokenSubject.closed || !this.refreshTokenInProgress) {
      this.refreshTokenSubject = new Subject<any>();
    }

    if (!this.refreshTokenInProgress) {
      this.refreshTokenInProgress = true;

      this.attemptTokenRefresh()
        .pipe(
          timeout(this.REFRESH_TIMEOUT),
          finalize(() => {
            this.refreshTokenInProgress = false;
          })
        )
        .subscribe({
          next: async (res) => {
            if (!res) {
              await this.auth.logout();
              this.refreshTokenSubject.error('Failed to refresh token');
              this.refreshTokenSubject.complete();
              return;
            }

            await this.cre.setRsApiToken(res?.accessToken);
            await this.cre.setRefreshToken(res?.refreshToken);

            this.refreshTokenSubject.next(res);
            this.refreshTokenSubject.complete();
          },
          error: async (err) => {
            await this.auth.logout();
            this.refreshTokenSubject.error(err);
            this.refreshTokenSubject.complete();
            this.auth.backToSignIn();
          },
        });
    }

    // All requests (including the first one) wait for the result from refreshTokenSubject
    return this.refreshTokenSubject.pipe(
      switchMap((res) => {
        if (!res) {
          return throwError(() => 'Failed to refresh token');
        }
        // Use the new token from refresh response
        return next.handle(this.updateHeader(req, res.accessToken));
      }),
      catchError((error) => {
        // Only reset flag when there's an actual error, not when request succeeds
        if (error === 'Failed to refresh token' || error.name === 'TimeoutError') {
          this.refreshTokenInProgress = false;
        }
        return throwError(() => error);
      })
    );
  }

  private attemptTokenRefresh(): Observable<{ accessToken?: string; refreshToken?: string }> {
    // Get user directly from credential instead of authState
    const user = this.cre.currentUser;
    if (!user?.UserId) {
      // Guest mode - use requestAccessToken
      return this.auth.requestAccessToken().pipe(
        retry({
          count: this.MAX_RETRY_COUNT,
          delay: (error, retryCount) => {
            console.warn('Retry guest token request error: ', error);
            console.warn(`Guest token request failed, retry ${retryCount}/${this.MAX_RETRY_COUNT}`);
            return timer(this.RETRY_DELAY);
          },
          resetOnSuccess: true,
        }),
        switchMap((response: any) => {
          if (!response?.Token) {
            throw new Error('Failed to get access token in guest mode');
          }
          return of({
            accessToken: response?.Token,
            refreshToken: null,
          });
        })
      );
    } else {
      // User mode - use refreshToken with retry
      return this.auth.refreshToken().pipe(
        retry({
          count: this.MAX_RETRY_COUNT,
          delay: (error, retryCount) => {
            console.warn('Retry refresh token error: ', error);
            console.warn(`Refresh token failed, retry ${retryCount}/${this.MAX_RETRY_COUNT}`);
            return timer(this.RETRY_DELAY);
          },
          resetOnSuccess: true,
        })
      );
    }
  }

  private updateHeader(req: HttpRequest<any>, token?: string): HttpRequest<any> {
    const tokenToUse = token || this.cre.rsApiToken;
    if (!tokenToUse) {
      throw new Error('No token available');
    }
    return req.clone({
      headers: req.headers.set('Authorization', `Bearer ${tokenToUse}`),
    });
  }
}
