import { Directive, ElementRef, OnDestroy, AfterViewInit, Renderer2 } from '@angular/core';
import { IonContent } from '@ionic/angular';
import { Subject } from 'rxjs';
import { throttleTime, takeUntil } from 'rxjs/operators';
/**
 * Directive: BlurOnScrollOutOfViewDirective
 * -----------------------------------------
 * Automatically blurs an input element when it scrolls out of the visible
 * area of an Ionic `<ion-content>` container.
 *
 * How it works:
 * - Locates the first focusable <input> element within the directive host.
 * - Tracks focus/blur state of the input.
 * - Subscribes to IonContent scroll events (throttled for performance).
 * - On each scroll event, checks if the focused input is still visible
 *   within the scrollable viewport.
 * - If the input scrolls fully out of view, it is automatically blurred.
 *
 * Requirements:
 * - Must be used inside an Ionic <ion-content>.
 * - Host element must contain (or be) a native <input>.
 *
 * Use cases:
 * - Automatically close the mobile keyboard when scrolling away from inputs.
 * - Prevent the keyboard from obscuring content after the user scrolls.
 *
 * Cleanup:
 * - Unsubscribes from scroll events on destroy.
 * - Removes all event listeners to prevent memory leaks.
 *
 */

@Directive({
  selector: '[appBlurOnScrollOutOfView]',
})
export class BlurOnScrollOutOfViewDirective implements AfterViewInit, OnDestroy {
  private scrollElement?: HTMLElement;
  private inputElement?: HTMLInputElement;
  private isFocused = false;

  private _destroy$ = new Subject<void>();
  private focusListener?: () => void;
  private blurListener?: () => void;

  constructor(
    private el: ElementRef<HTMLElement>,
    private renderer: Renderer2,
    private ionContent: IonContent
  ) {}

  async ngAfterViewInit() {
    this.scrollElement = await this.ionContent.getScrollElement();
    this.inputElement = this.findFocusable(this.el.nativeElement);

    if (!this.ionContent.ionScroll) {
      console.warn(
        '[BlurOnScrollOutOfViewDirective] ionScroll is not available. Ensure scrollEvents="true" on ion-content.'
      );
      return;
    }

    if (!this.inputElement) {
      console.warn('[BlurOnScrollOutOfViewDirective] No focusable input found in host:', this.el.nativeElement);
      return;
    }

    this.ionContent.ionScroll
      .pipe(throttleTime(100), takeUntil(this._destroy$))
      .subscribe(() => this.checkVisibilityAndBlur());

    // Track focus/blur state on input element
    this.focusListener = this.renderer.listen(this.inputElement, 'focus', () => (this.isFocused = true));
    this.blurListener = this.renderer.listen(this.inputElement, 'blur', () => (this.isFocused = false));
  }

  private checkVisibilityAndBlur() {
    if (!this.isFocused || !this.inputElement || !this.scrollElement) return;

    const inputRect = this.inputElement.getBoundingClientRect();
    const scrollRect = this.scrollElement.getBoundingClientRect();

    // Determine if the input is completely out of the visible scroll area:
    // - true if the input is fully above the viewport (inputRect.bottom < scrollRect.top)
    // - true if the input is fully below the viewport (inputRect.top > scrollRect.bottom)
    const isOutOfView = inputRect.bottom < scrollRect.top || inputRect.top > scrollRect.bottom;

    if (isOutOfView) {
      this.inputElement.blur();
    }
  }

  private findFocusable(root: HTMLElement): HTMLInputElement | null {
    return root.tagName === 'INPUT' ? (root as HTMLInputElement) : null;
  }

  ngOnDestroy() {
    this._destroy$.next();
    this._destroy$.complete();
    this.focusListener?.();
    this.blurListener?.();
  }
}
