import { Component, OnDestroy, OnInit } from '@angular/core';
import { Subject, tap, firstValueFrom, takeUntil } from 'rxjs';
import { Credential } from '@rsApp/modules/auth-v2/providers/credential.service';
import { Router } from '@angular/router';
import { User } from '../../providers/user.service';
import { IUser } from '@rsApp/modules/interfaces/user.interface';
import { AuthService } from '@rsApp/modules/auth-v2/providers/auth-v2.service';

@Component({
  selector: 'my-account',
  templateUrl: './my-account.html',
  styleUrls: ['./my-account.scss'],
})
export class MyAccountComponent implements OnDestroy, OnInit {
  // Full display name of the user (e.g., "John Doe")
  userName: string;

  // Initials for avatar (e.g., "JD")
  avtName: string;

  // Flag to control whether Preferences accordion should auto-open
  openPreferencesOnInit = false;

  // Subject used to clean up subscriptions when component is destroyed
  private destroy$ = new Subject<boolean>();

  constructor(
    public cre: Credential,
    public router: Router,
    private userService: User,
    private authService: AuthService
  ) {}

  /**
   * Angular lifecycle hook - runs on component initialization
   */
  ngOnInit() {
    const nav = this.router.getCurrentNavigation();
    this.openPreferencesOnInit = !!nav?.extras?.state?.openPreferencesOnInit;
    this.loadCurrentUser();
    this.authService
      .getCurrentUser()
      .pipe(takeUntil(this.destroy$))
      .subscribe((user) => {
        if (!user || !user.UserId) {
          return;
        }
        this.setUserInfo(user);
      });
  }

  /**
   * Sets user display name and avatar initials
   */
  async setUserInfo(user?: IUser) {
    const { FirstName = '', LastName = '' } = user || {};
    this.userName = `${FirstName} ${LastName}`.trim();
    this.avtName = `${FirstName.charAt(0)}${LastName.charAt(0)}`.toUpperCase();
  }

  private async loadCurrentUser() {
    const getUser$ = this.userService.getUserById(this.cre.currentUser.UserId).pipe(
      tap((user: IUser) => {
        this.authService.setCurrentUser(user);
        this.cre.setCurrentUser(user);
      })
    );
    await firstValueFrom(getUser$);
  }

  /**
   * Cleanup logic when component is destroyed
   */
  ngOnDestroy(): void {
    this.destroy$.next(true);
    this.destroy$.complete();
  }

  backToHome(): void {
    this.router.navigate(['tabs/home']);
  }
}
