import { Component, Input, OnDestroy, OnInit, Output, ViewChild } from '@angular/core';
import { FormControl } from '@angular/forms';
import { MagAppBottomSheetComponent } from '@rsApp/components/mag-app-bottom-sheet/mag-app-bottom-sheet';
import { firstValueFrom, Subject, takeUntil } from 'rxjs';
import { EventEmitter } from '@angular/core';
import { Utils } from '@rsApp/modules/utils/providers/utils';
import { TenantSettingsStore } from '@rsApp/modules/utils/providers/tenant-settings.service';
import { IMagState } from '../interface';
import { ErrorMessagePipe } from '../input-error.service';
@Component({
  selector: 'mag-state-selector',
  templateUrl: 'mag-state-selector.html',
  styleUrls: ['./mag-state-selector.scss'],
  providers: [ErrorMessagePipe],
})
export class MagStateSelectorComponent implements OnInit, OnDestroy {
  @Input() label?: string = '';
  @Input() required?: boolean = false;
  @Input() control?: FormControl;
  @Input() controlName?: string;
  @Input() placeholder?: string = '';

  stateList: IMagState[] = [];
  searchStateList: any[] = [];
  displayValue: string = '';
  searchTerm: string = '';
  private destroy$ = new Subject<void>();

  @Output() stateSelected = new EventEmitter<string>();
  @ViewChild('bottomSheet') bottomSheetComponent!: MagAppBottomSheetComponent;

  constructor(
    private utils: Utils,
    public tenantSettingsStore: TenantSettingsStore,
    private errorPipe: ErrorMessagePipe
  ) {}

  async ngOnInit() {
    await this.loadState();
    if (this.control) {
      if (this.control.value) {
        this.setStateNameByCode(this.control.value);
      }
      this.control.valueChanges.pipe(takeUntil(this.destroy$)).subscribe((value) => this.setStateNameByCode(value));
    }
  }

  async loadState() {
    const tenantSetting = await this.tenantSettingsStore.getTenantSettings();
    const countryCode = tenantSetting?.country;
    const states = await firstValueFrom(this.utils.getStates(countryCode));
    if (states && states.length) {
      this.stateList = states;
      this.searchStateList = states;
    }
  }

  onDismissHandle() {
    this.searchTerm = '';
    this.searchStateList = this.stateList;
  }

  ngOnDestroy() {
    this.destroy$.next();
    this.destroy$.complete();
  }

  searchState(event: any) {
    this.searchTerm = event.target.value?.toLowerCase() || '';
    if (!this.searchTerm) {
      this.searchStateList = this.stateList;
      return;
    }
    this.searchStateList = this.stateList.filter((state) => state.StateName.toLowerCase().includes(this.searchTerm));
  }

  openPicker() {
    this.bottomSheetComponent.openModal();
  }

  selectState(state: any) {
    const selectedValue = state;
    this.setStateNameByCode(selectedValue?.StateId);
    this.stateSelected.emit(selectedValue);
    this.bottomSheetComponent.closeModal();
  }

  setStateNameByCode(code: string) {
    const state = this.stateList.find((s) => s.StateId === code);
    this.displayValue = state.StateName;
    return;
  }

  get errorMessage(): string | null {
    return this.control ? this.errorPipe.transform(this.control, this.controlName, this.label.toLowerCase()) : null;
  }

  get placeholderWithAsterisk(): string {
    if (this.required && this.placeholder && !this.placeholder.trim().endsWith('*')) {
      return `${this.placeholder.trim()} *`;
    }
    return this.placeholder || '';
  }
}
