import { BarcodeScanner, SupportedFormat } from '@capacitor-community/barcode-scanner';
import { Injectable } from '@angular/core';
import { Storage } from '@ionic/storage';

@Injectable({
  providedIn: 'root',
})
export class BarcodeScannerService {
  private isAskedPermission = false;

  constructor(private storage: Storage) {
    this.storage.get('isAskedPermission').then((isAskedPermission: boolean) => {
      this.isAskedPermission = isAskedPermission;
    });
  }

  /**
   * Check if the app has permission to use the camera
   * @returns Promise<boolean> - true if permission is granted, false otherwise
   */
  async checkPermission(): Promise<boolean> {
    try {
      const status = await BarcodeScanner.checkPermission({ force: false });

      if (status.granted) {
        // the user granted permission
        return true;
      }

      return false;
    } catch (error) {
      console.warn('Error checking permission:', error);
      return false;
    }
  }

  /**
   * Request camera permission if not already granted
   * @returns Promise<boolean> - true if permission is granted, false otherwise
   */
  async requestPermission(): Promise<boolean> {
    try {
      const status = await BarcodeScanner.checkPermission({ force: true });

      if (status.granted) {
        // the user granted permission
        return true;
      }

      return false;
    } catch (error) {
      console.warn('Error requesting permission:', error);
      return false;
    }
  }

  /**
   * Start the barcode scanner
   * @returns Promise<string> - the scanned barcode result
   */
  async startScan(format?: SupportedFormat): Promise<string> {
    try {
      // Check permission first
      const hasPermission = await this.checkPermission();
      if (!hasPermission) {
        if (!this.isAskedPermission) {
          this.storage.set('isAskedPermission', true);
          this.isAskedPermission = true;
          const granted = await this.requestPermission();
          if (!granted) {
            throw new Error('Camera permission denied');
          }
        } else {
          await BarcodeScanner.openAppSettings();
          return null;
        }
      }

      // Make background transparent to show camera preview
      document.querySelector('body')?.classList.add('scanner-active');

      // Add overlay scan
      this.addScanOverlay();

      // Start scanning
      const result = await BarcodeScanner.startScan({
        targetedFormats: format ? [format] : [],
      });

      return result.hasContent ? result.content : null;
    } catch (error) {
      console.error('Error starting scan:', error);
      throw error;
    }
  }

  /**
   * Stop the barcode scanner
   */
  async stopScan(): Promise<void> {
    try {
      await BarcodeScanner.stopScan();
      document.querySelector('body')?.classList.remove('scanner-active');
      this.removeScanOverlay();
    } catch (error) {
      console.error('Error stopping scan:', error);
      throw error;
    }
  }

  /**
   * Add overlay scan with frame and back button
   */
  private addScanOverlay() {
    if (document.getElementById('barcode-scan-overlay')) return;
    const overlay = document.createElement('div');
    overlay.id = 'barcode-scan-overlay';
    overlay.className = 'barcode-scan-overlay';
    overlay.innerHTML = `
      <ion-button id="barcode-back-btn" class="barcode-back-btn" fill="clear">
        <ion-icon slot="start" name="arrow-back-outline"></ion-icon>
        Stop Scan
      </ion-button>
      <div class="scan-frame"></div>
    `;
    // Ensure ion-button is rendered before assigning event
    setTimeout(() => {
      overlay.querySelector('#barcode-back-btn')?.addEventListener('click', () => this.stopScan());
    }, 0);
    document.body.appendChild(overlay);
  }

  /**
   * Remove overlay scan
   */
  private removeScanOverlay() {
    const overlay = document.getElementById('barcode-scan-overlay');
    if (overlay) overlay.remove();
  }
}
