import { Component, OnInit, ViewChild } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { ModalController, NavController } from '@ionic/angular';
import { MagModalConfirmComponent } from '@rsApp/components/mag-confirm-modal/mag-modal-confirm';
import { AccountChoice } from '@rsApp/modules/auth-v2/utils/enum';
import isEqual from 'lodash/isEqual';
import { AccountV2Service } from '../../providers/account-v2.service';
import { Credential } from '@rsApp/modules/auth-v2/providers/credential.service';
import { firstValueFrom, tap } from 'rxjs';
import { IUpdateUserPayload } from '../../utils/enum';
import { IMagToastOptions } from '@rsApp/components/interface';
import { ToastService } from '@rsApp/components/toast.service';
import { User } from '../../providers/user.service';
import { IUser } from '@rsApp/modules/interfaces/user.interface';
import { TranslateService } from '@ngx-translate/core';
import { GlobalRegex, POSTAL_CODE_LABEL, postalCodeMasks } from '@rsApp/modules/utils/enum/enum';
import { AuthService } from '@rsApp/modules/auth-v2/providers/auth-v2.service';
import { AppSettings } from '@rsApp/modules/utils/providers/app-setting';
import { PhoneValidator } from '@rsApp/modules/utils/validator/phone-validator-v2';
import { MaskitoOptions, maskitoTransform } from '@maskito/core';
import { phoneMasks } from '@rsApp/modules/utils/enum/enum';
import { TenantSettingsStore } from '@rsApp/modules/utils/providers/tenant-settings.service';
import { toUtcMonthStartIso } from '@rsApp/modules/utils/providers/date-utils';
import { ForceVerifyPhoneComponent } from '../../components/mag-force-verify-phone/mag-force-verify-phone';
@Component({
  selector: 'personal-information',
  templateUrl: 'personal-infomation.html',
  styleUrls: ['./personal-infomation.scss'],
})
export class PersonalInformationComponent implements OnInit {
  AccountChoice = AccountChoice;
  detailInfomation: FormGroup;
  isShowAllFields: boolean = true;
  isBusiness = false;
  originalFormValue: any;
  isNonProfit = false;
  isBusinessCheck = false;
  user: IUser;
  isBusinessAccount: boolean;
  isBusinessMobileNumber: boolean = false;
  isSubmitting: boolean = false;
  isCheckPhone: boolean = false;
  isLoyaltySupported: boolean = false;
  phoneMask: MaskitoOptions;
  countryRegion: string = 'us';
  postalCodeLabel = POSTAL_CODE_LABEL;
  valuePhone: string;
  userPayload: IUpdateUserPayload;
  isPhoneVerify: boolean = false;

  public SettingKeyAM = 'ACCOUNT MANAGEMENT';

  @ViewChild('forceVerifyPhonePopup') forceVerifyPhoneComponent!: ForceVerifyPhoneComponent;

  constructor(
    public router: Router,
    private fb: FormBuilder,
    private modalCtrl: ModalController,
    private accountService: AccountV2Service,
    private cre: Credential,
    private toastService: ToastService,
    private userService: User,
    private translate: TranslateService,
    private authService: AuthService,
    private appSettingsService: AppSettings,
    private navCtrl: NavController,
    private phoneValidator: PhoneValidator,
    private tenantSettingsStore: TenantSettingsStore
  ) {
    this.detailInfomation = this.fb.group({
      firstName: ['', [Validators.required, Validators.pattern(GlobalRegex.NAME)]],
      lastName: ['', [Validators.required, Validators.pattern(GlobalRegex.NAME)]],
      phone: [''],
      cellPhone: ['', Validators.required],
      birthday: [''],
      address: ['', [Validators.required, Validators.pattern(GlobalRegex.ADDRESS_US)]],
      city: ['', [Validators.required, Validators.pattern(GlobalRegex.CITY_US)]],
      state: ['', Validators.required],
      zipCode: ['', Validators.required],
    });

    this.preventBackNavigation();
  }

  preventBackNavigation() {
    const originalNavigateBack = this.navCtrl.navigateBack;

    this.navCtrl.navigateBack = (url: string | any[], options?: any): Promise<boolean> => {
      if (this.isFormChanged()) {
        this.openConfirmModal();
      } else {
        return originalNavigateBack.call(this.navCtrl, url, options);
      }
      return Promise.resolve(false);
    };
  }

  async ngOnInit() {
    this.user = await this.getUser();
    this.checkIsForceVerifyPhone();
    this.isBusinessAccount = this.user?.AccountType === AccountChoice.BUSINESS;
    const businessPhoneControl = this.detailInfomation.get('phone');

    if (this.isBusinessAccount) {
      businessPhoneControl?.setValidators([Validators.required]);
    }
    businessPhoneControl?.updateValueAndValidity();

    const tenantInfo = await this.tenantSettingsStore.getTenantSettings();
    this.countryRegion = tenantInfo?.country ? tenantInfo.country.toLowerCase() : 'us';
    const zipPattern = this.countryRegion === 'ca' ? GlobalRegex.ZIP_CODE_CA : GlobalRegex.ZIP_CODE_US;

    this.detailInfomation.get('zipCode')?.setValidators([Validators.required, Validators.pattern(zipPattern)]);
    this.phoneMask = phoneMasks[this.countryRegion];

    this.getForm();
    this.setOrganizationStatus();
    this.isLoyaltySupported = await this.initWBSettings();

    const phoneControl = this.detailInfomation.get('phone');
    const cellControl = this.detailInfomation.get('cellPhone');

    // Subscribe to phone and cellPhone value changes for validation
    phoneControl?.valueChanges.subscribe((value) => {
      this.handlePhoneValidation('phone', value);
    });

    cellControl?.valueChanges.subscribe((value) => {
      this.handlePhoneValidation('cellPhone', value);
    });
  }

  async getUser() {
    return await this.cre.getCurrentUser();
  }

  async initWBSettings() {
    try {
      const value = await firstValueFrom(this.appSettingsService.getSettingValue('loyalty_support'));
      if (!value) {
        console.warn('Loyalty support setting not found or empty');
      }
      return JSON.parse(value);
    } catch (err) {
      console.warn('Error fetching loyalty_support setting:', err);
      return false;
    }
  }

  async getForm() {
    if (!this.user) return;
    const maskedPhone = maskitoTransform(
      { value: this.user.Phone, selection: [this.user.Phone.length, this.user.Phone?.length] },
      this.phoneMask
    ).value;

    const maskedCellPhone = maskitoTransform(
      { value: this.user.CellPhone, selection: [this.user.CellPhone.length, this.user.CellPhone?.length] },
      this.phoneMask
    ).value;

    const maskedZip = maskitoTransform(
      { value: this.user.ZipCode, selection: [this.user.ZipCode.length, this.user.ZipCode.length] },
      postalCodeMasks[this.countryRegion]
    ).value;

    this.detailInfomation.patchValue({
      firstName: this.user.FirstName || '',
      lastName: this.user.LastName || '',
      phone: maskedPhone || '',
      birthday: toUtcMonthStartIso(this.user.BirthDay) || '',
      address: this.user.Address || '',
      city: this.user.City || '',
      state: this.user.State || '',
      zipCode: maskedZip || this.user.ZipCode || '',
      businessName: this.user.FirstName || '',
      contactName: this.user.LastName || '',
      cellPhone: maskedCellPhone || this.user.Phone || '',
    });
    if (this.isBusinessAccount && this.user.Phone === this.user.CellPhone) {
      this.isBusinessMobileNumber = true;
    }
    setTimeout(() => {
      this.originalFormValue = this.detailInfomation.getRawValue();
    }, 0);
  }

  private handlePhoneValidation(controlName: string, value: string) {
    this.isCheckPhone = true;
    const maskedPhone = maskitoTransform(
      { value: this.user.Phone, selection: [this.user.Phone.length, this.user.Phone?.length] },
      this.phoneMask
    ).value;

    const maskedCellPhone = maskitoTransform(
      { value: this.user.CellPhone, selection: [this.user.CellPhone.length, this.user.CellPhone?.length] },
      this.phoneMask
    ).value;
    const oldValue = controlName === 'phone' ? maskedPhone : maskedCellPhone;

    const control = this.detailInfomation.get(controlName);

    if (value === oldValue) {
      control?.clearValidators();
      control?.clearAsyncValidators();
    } else if (
      this.isBusinessAccount &&
      controlName === 'cellPhone' &&
      control?.value === this.detailInfomation.get('phone')?.value
    ) {
      control?.clearValidators();
      control?.clearAsyncValidators();
    } else {
      control?.setValidators([Validators.required]);
      control?.setAsyncValidators([this.phoneValidator.phoneValidator(this.user?.UserId)]);
    }
    control?.updateValueAndValidity({ emitEvent: false });
    this.isCheckPhone = false;
  }

  async getOrganizationStatus(): Promise<any> {
    return await firstValueFrom(this.accountService.getOrganizationStatus(this.user?.CustomerCode));
  }

  async UpdateUser() {
    const formValue = this.detailInfomation.getRawValue();
    const userId = this.user?.UserId;
    let CellPhone = formValue?.cellPhone?.replace(/\D/g, '');
    const Phone = formValue?.phone?.replace(/\D/g, '');
    if (!this.isBusinessAccount || (this.isBusinessAccount && this.isBusinessMobileNumber)) {
      CellPhone = Phone;
    }

    const userPayload: IUpdateUserPayload = {
      UserId: userId,
      FirstName: formValue?.firstName,
      LastName: formValue?.lastName,
      Address: formValue?.address,
      City: formValue?.city,
      State: formValue?.state,
      ZipCode: formValue?.zipCode,
      CellPhone: CellPhone,
      Phone: Phone,
      BirthDay: formValue?.birthday, // Not required for business
    };

    try {
      const res = await firstValueFrom(this.accountService.updateUser(userId, userPayload));

      return res ?? false;
    } catch {
      return false;
    }
  }

  private loadCurrentUser() {
    return this.userService.getUserById(this.user.UserId).pipe(
      tap((user: IUser) => {
        this.authService.setCurrentUser(user);
        this.cre.setCurrentUser(user);
        this.user = user;
        this.getForm();
      })
    );
  }

  toggleToast() {
    const toastRemoveAddressConfig: IMagToastOptions = {
      message: this.translate.instant('toast.personalUpdateSuccess'),
      type: 'success',
    };
    this.toastService.create(toastRemoveAddressConfig);
  }

  async setOrganizationStatus() {
    try {
      const { BusinessChecks, Nonprofit } = await this.getOrganizationStatus();
      this.isBusinessCheck = BusinessChecks;
      this.isNonProfit = Nonprofit;
    } catch (error) {
      console.error('Failed to fetch organization status:', error.message);
    }
  }

  onStateSelected(state: any) {
    this.detailInfomation.get('state')?.setValue(state.StateId);
  }

  isFormChanged(): boolean {
    const currentValue = this.detailInfomation.getRawValue();
    return !isEqual(currentValue, this.originalFormValue);
  }

  async openConfirmModal() {
    const modal = await this.modalCtrl.create({
      component: MagModalConfirmComponent,
      componentProps: {
        title: this.translate.instant('accountInfo.unsavedChanges'),
        description: this.translate.instant('accountInfo.description'),
        confirmTitle: this.translate.instant('common.leavePage'),
        cancelTitle: this.translate.instant('common.stay'),
        verticalButtons: false,
      },
      cssClass: 'mag-confirm-modal',
    });

    modal.onDidDismiss().then((result) => {
      if (result.data === false) {
        this.getForm();
        this.navigateToAccount();
      }
    });

    await modal.present();
  }

  // backCheck() {
  //   if (this.isFormChanged()) {
  //     this.openConfirmModal();
  //   } else {
  //     this.navigateToAccount();
  //   }
  // }

  private navigateToAccount() {
    this.router.navigate(['tabs/my-account']);
  }

  async updateOrganizationStatus() {
    const payload = {
      CustomerCode: this.user?.CustomerCode,
      BusinessChecks: this.isBusinessCheck,
      Nonprofit: this.isNonProfit,
    };

    try {
      const res = await firstValueFrom(this.accountService.updateOrganizationStatus(payload));
      return !!res;
    } catch {
      return false;
    }
  }

  async verifiedSuccess(data?) {
    if (data?.otp) {
      await firstValueFrom(this.loadCurrentUser());
      this.navigateToAccount();
    }
    this.forceVerifyPhoneComponent.closeBottomSheet();
    this.isSubmitting = false;
    this.toggleToast();
  }

  private async checkIsForceVerifyPhone() {
    this.isPhoneVerify = (await this.cre.getCurrentUser())?.IsForceVerifyPhone || false;
  }

  //TODO
  async saveForm() {
    if (this.detailInfomation.invalid || this.isCheckPhone) return;

    const originalPhone = this.user?.Phone || '';
    const formValue = this.detailInfomation.getRawValue();
    const currentPhone = String(formValue.phone ?? '').replace(/\D/g, '') || '';
    let currentCellPhone = String(formValue.cellPhone ?? '').replace(/\D/g, '') || '';
    const isChangePhone = originalPhone !== currentPhone;
    if (isChangePhone && this.isPhoneVerify) {
      this.valuePhone = String(formValue.phone ?? '');

      if (!this.isBusinessAccount || (this.isBusinessAccount && this.isBusinessMobileNumber)) {
        currentCellPhone = currentPhone;
      }
      this.userPayload = {
        UserId: this.user?.UserId,
        FirstName: formValue?.firstName,
        LastName: formValue?.lastName,
        Address: formValue?.address,
        City: formValue?.city,
        State: formValue?.state,
        ZipCode: formValue?.zipCode,
        CellPhone: currentCellPhone,
        Phone: currentPhone,
        BirthDay: formValue?.birthday,
      };
      this.forceVerifyPhoneComponent.openBottomSheet();
    } else {
      if (this.isSubmitting) return;

      if (this.detailInfomation.invalid) {
        this.detailInfomation.markAllAsTouched();
        this.isSubmitting = false;
        return;
      }
      this.isSubmitting = true;
      const updateUserSuccess = await this.UpdateUser();
      let updateOrganizeSuccess = true;
      if (this.isBusinessAccount && this.isLoyaltySupported) {
        updateOrganizeSuccess = await this.updateOrganizationStatus();
      }

      const isSuccess = updateUserSuccess && updateOrganizeSuccess;
      if (isSuccess) {
        await firstValueFrom(this.loadCurrentUser());
        this.navigateToAccount();
      }
      this.isSubmitting = false;
      this.toggleToast();
      this.originalFormValue = formValue;
    }
  }
}
