import { Component } from '@angular/core';
import { CacheService } from 'ionic-cache';
import { Router } from '@angular/router';
import { AlertController, ModalController } from '@ionic/angular';
import { AppSettings } from '@rsApp/modules/utils/providers/app-setting';
import { Utils } from '@rsApp/modules/utils/providers/utils';
import { Credential } from '@rsApp/modules/auth-v2/providers/credential.service';
import { CurrentStore } from '@rsApp/modules/store/providers/current-store.service';

@Component({
  selector: 'check-order-modal',
  templateUrl: 'check-order-modal.html',
  styleUrls: ['check-order-modal.scss'],
})
export class CheckOrderModalComponent {
  latestOnlineOrder: any;

  currentUser: any = {};
  currentStore: any;

  constructor(
    public cre: Credential,
    public cStore: CurrentStore,
    public cache: CacheService,
    public router: Router,
    public alertCtrl: AlertController,
    public appSettings: AppSettings,
    public utils: Utils,
    public modalCtrl: ModalController
  ) {}

  async viewOrderSummary() {
    await this.modalCtrl.dismiss();
    this.router.navigate(['/tabs/purchase/order-sumary', { orderId: this.latestOnlineOrder.OrderId }]);
  }
}
