import type { PurchaseParams, Ga4Item } from './ga4.types';

function pickLocalizedText(v: any): string | undefined {
  if (!v) return undefined;
  if (typeof v === 'string') return v;

  if (typeof v === 'object') {
    if (typeof v.en === 'string') return v.en;
    if (typeof v.En === 'string') return v.En;
    const first = Object.values(v).find((x) => typeof x === 'string');
    return first as string | undefined;
  }

  return undefined;
}

function toNumber(v: any): number | undefined {
  if (typeof v === 'number' && Number.isFinite(v)) return v;
  const n = Number(v);
  return Number.isFinite(n) ? n : undefined;
}

function mapCartItemToGa4Item(p: any, idx: number): Ga4Item {
  return {
    item_id: p?.ProductId ?? p?.Upc ?? p?.Gtin ?? p?.item_id,
    item_name: pickLocalizedText(p?.DisplayName) ?? pickLocalizedText(p?.Name) ?? p?.item_name,
    item_brand:
      pickLocalizedText(p?.Brand?.Name) ??
      p?.Brand?.Id ??
      p?.BrandName?.BrandName ??
      (Array.isArray(p?.Brands) ? p.Brands?.[0]?.BrandName : undefined) ??
      p?.item_brand,
    item_category: Array.isArray(p?.Categories)
      ? p?.Categories?.find((c: any) => c?.Level === 1)?.CategoryName
      : undefined,
    item_category2: Array.isArray(p?.Categories)
      ? p?.Categories?.find((c: any) => c?.Level === 2)?.CategoryName
      : undefined,
    item_category3: Array.isArray(p?.Categories)
      ? p?.Categories?.find((c: any) => c?.Level === 3)?.CategoryName
      : undefined,
    item_category4: Array.isArray(p?.Categories)
      ? p?.Categories?.find((c: any) => c?.Level === 4)?.CategoryName
      : undefined,
    item_category5: Array.isArray(p?.Categories)
      ? p?.Categories?.find((c: any) => c?.Level === 5)?.CategoryName
      : undefined,
    item_variant: p?.Unit ?? p?.item_variant,
    location_id: p?.StoreCode ?? p?.BranchId ?? p?.location_id,
    price: toNumber(p?.Price),
    quantity: toNumber(p?.Quantity),
    index: idx + 1, // keep consistent with your other mappers
  };
}

function sumCartValue(items: any[]): number | undefined {
  const values = items.map((x) => {
    const total = toNumber(x?.TotalPrice) ?? toNumber(x?.TotalPriceWithSavings);
    if (typeof total === 'number') return total;

    const price = toNumber(x?.Price);
    const qty = toNumber(x?.Quantity) ?? 1;
    if (typeof price === 'number') return price * qty;

    return 0;
  });

  const sum = values.reduce((a, b) => a + b, 0);
  return Number.isFinite(sum) ? sum : undefined;
}

export function mapPurchaseParams(payload: any): PurchaseParams | null {
  const itemsArray: any[] = Array.isArray(payload)
    ? payload
    : Array.isArray(payload?.items)
      ? payload.items
      : Array.isArray(payload?.cartItems)
        ? payload.cartItems
        : [];

  if (!itemsArray.length) return null;

  const currency = payload?.currency ?? itemsArray?.[0]?.Currency ?? itemsArray?.[0]?.currency ?? 'USD';

  const value = toNumber(payload?.value) ?? sumCartValue(itemsArray);

  return {
    currency,
    value,
    items: itemsArray.map(mapCartItemToGa4Item),
  };
}
