import { Injectable } from '@angular/core';
import { RelationshopCoreHttpClient } from '@rsApp/modules/gateway/rs-api-core.service';
import { Utils } from '@rsApp/modules/utils/providers/utils';
import { tap, map } from 'rxjs/operators';

@Injectable({ providedIn: 'root' })
export class WalletService {
  constructor(
    private api: RelationshopCoreHttpClient,
    public utils: Utils
  ) {}

  public getGoogleWallet(cardId: string) {
    return this.api.get(`/wallet/google-wallet/${cardId}`, { responseType: 'text' });
  }

  public saveGoogleWallet(cardId: string) {
    return this.getGoogleWallet(cardId).pipe(
      tap((url) => {
        this.utils.openInSystem(url);
      })
    );
  }

  public getAppleWallet(cardId: string) {
    return this.api.get(`/wallet/apple-wallet/${cardId}`, { responseType: 'blob' });
  }

  public saveAppleWallet(cardId: string) {
    return this.getAppleWallet(cardId).pipe(
      map((blob: Blob) => {
        // Convert blob to base64 data URI
        return new Promise<string>((resolve, reject) => {
          const reader = new FileReader();
          reader.onload = () => {
            resolve(reader.result as string);
          };
          reader.onerror = reject;
          reader.readAsDataURL(blob);
        });
      }),
      tap(async (dataPromise) => {
        const data = await dataPromise;
        this.addAppleWallet(data);
      })
    );
  }

  public addAppleWallet(data) {
    try {
      const w = window as any;
      if (!w.Passbook) {
        console.warn('Passbook is not available');
        return;
      }
      w.Passbook.available((isAvailable: boolean) => {
        if (!isAvailable) {
          console.warn('Passbook is not available');
          return;
        }
        w.Passbook.downloadPass(data);
      });
    } catch (error) {
      console.error('Error processing Apple Wallet data:', error);
    }
  }
}
