import { Animation, AnimationController } from '@ionic/angular';

export const iosSmooth = (baseEl: HTMLElement, opts?: any): Animation => {
  const animationCtrl = new AnimationController();
  const enteringEl = opts.enteringEl;
  const leavingEl = opts.leavingEl;

  const isBack = opts.direction === 'back';
  const easing = 'cubic-bezier(0.22, 1, 0.36, 1)';
  const duration = 320;
  const enterFromX = isBack ? '-25%' : '100%';
  const enterToX = '0%';

  const enterAnim = animationCtrl
    .create()
    .addElement(enteringEl)
    .beforeRemoveClass('ion-page-invisible')
    .duration(duration)
    .easing(easing)
    .fromTo('opacity', isBack ? 0.9 : 0.5, 1)
    .fromTo('transform', `translate3d(${enterFromX}, 0, 0)`, `translate3d(${enterToX}, 0, 0)`);

  const leaveToX = isBack ? '100%' : '-40%';

  const leaveAnim = animationCtrl
    .create()
    .addElement(leavingEl)
    .duration(duration)
    .easing('cubic-bezier(0.35, 0, 0.25, 1)')
    .fromTo('opacity', 1, isBack ? 0.9 : 0.5)
    .fromTo('transform', 'translate3d(0%, 0, 0)', `translate3d(${leaveToX}, 0, 0)`);

  return animationCtrl.create().addAnimation([enterAnim, leaveAnim]);
};
