import { Injectable } from '@angular/core';
import { cacheErrorHandle, strapiUrlAutoGenerate } from '@rsApp/modules/utils/providers/utils';
import { CacheService } from 'ionic-cache';
import { firstValueFrom, from } from 'rxjs';
import { map, switchMap } from 'rxjs/operators';
import { EnumAppSettings } from '../enum/enum';
import { RelationshopEComCoreHttpClient } from '@rsApp/modules/gateway/rs-ecom-core-api.service';
import { ITenantSettings, ITenantSettingsRes, IDXPSetting, IThemeConfigurations } from '../models/app-settings.model';
import { SettingKey } from '@rsApp/modules/auth-v2/utils/interface';
import { RelationshopSettingHttpClient } from '@rsApp/modules/gateway/rs-setting-api.service';
import { EnvironmentService } from '../../../../environments/environment.service';
import { Capacitor } from '@capacitor/core';
import { Router } from '@angular/router';

@Injectable({
  providedIn: 'root',
})
export class TenantSettingsStore {
  public ttl = 5 * 60; // 5 mins

  // Tenant settings
  public tenantSettingsCacheKey = EnumAppSettings.CacheKey;
  public tenantSettings: ITenantSettings = null;
  private loadingPromise: Promise<ITenantSettings | null> | null = null;

  // Guest mode setting
  public guestModeSetting: IDXPSetting = null;
  public guestModeSettingCacheKey = SettingKey.GuestMode;
  private loadingGuestPromise: Promise<IDXPSetting | null> | null = null;

  constructor(
    private coreApi: RelationshopEComCoreHttpClient,
    public settingApi: RelationshopSettingHttpClient,
    private cache: CacheService,
    private environmentService: EnvironmentService,
    public router: Router
  ) {}

  private async loadDynamicEnvironment() {
    try {
      await firstValueFrom(this.environmentService.getDynamicEnvironment());
    } catch (error) {
      console.warn('Failed to load dynamic environment in AppSettings service:', error);
    }
  }

  public async getTenantSettings(): Promise<ITenantSettings | null> {
    if (this.tenantSettings) {
      return this.tenantSettings;
    }

    if (this.loadingPromise) {
      return this.loadingPromise;
    }

    this.loadingPromise = (async () => {
      try {
        const cachedSettings = await this.cache.getItem(this.tenantSettingsCacheKey).catch(cacheErrorHandle);
        this.tenantSettings = cachedSettings || (await this.loadTenantSettings());
        return this.tenantSettings;
      } finally {
        this.loadingPromise = null;
      }
    })();

    return this.loadingPromise;
  }

  private async setTenantSettings(tenantSettings: ITenantSettings | null) {
    this.tenantSettings = tenantSettings;
    if (!tenantSettings) {
      await this.cache.removeItem(this.tenantSettingsCacheKey);
    } else {
      await this.cache.saveItem(this.tenantSettingsCacheKey, tenantSettings, null, this.ttl);
    }
  }

  private getTenantSettingsValue() {
    // Ensure dynamic environment is loaded before making request
    if (!(window as any).TenantId) {
      return from(this.loadDynamicEnvironment()).pipe(switchMap(() => this.makeTenantSettingsRequest()));
    }

    return this.makeTenantSettingsRequest();
  }

  private makeTenantSettingsRequest() {
    const tenantSettings = this.coreApi.get('/tenant/v1.0/api/TenantSetting/GetTenantSettingBySiteCode', {
      params: {
        name: EnumAppSettings.Name,
        tenantId: (window as any).TenantId,
        siteCode: (window as any).SiteCode,
        platform: EnumAppSettings.Platform,
      },
    });
    const observable = tenantSettings.pipe(
      map((tenantSettingsRes: ITenantSettingsRes) => {
        try {
          const siteSettings = tenantSettingsRes.SiteSettings ? JSON.parse(tenantSettingsRes.SiteSettings) : {};
          const envSettings = tenantSettingsRes.MobileEnvSettings
            ? JSON.parse(tenantSettingsRes.MobileEnvSettings)
            : {};
          const themeConfigurations: IThemeConfigurations = tenantSettingsRes.ThemeConfigurations
            ? JSON.parse(tenantSettingsRes.ThemeConfigurations)
            : { fonts: [], ':root': { ':root': {} } };
          const associatedWeSite = tenantSettingsRes.MobileLinkToWebDomain
            ? JSON.parse(tenantSettingsRes.MobileLinkToWebDomain)
            : null;

          const { SiteName, BannerId, BannerName, Country } = tenantSettingsRes;
          const { pages, languages, logoUrl, favicon, appInformations, maintenanceMode } = siteSettings;

          const { googleMaps, appBundle, firebase } = envSettings;
          const informations =
            Object.fromEntries(
              Object.entries(appInformations || {}).filter(
                ([, value]) => value !== undefined && value !== null && value !== ''
              )
            ) || {};

          const resultSettings: ITenantSettings = {
            appBundleId: Capacitor.getPlatform() === 'ios' ? appBundle?.ios : appBundle?.android,
            isPublish: tenantSettingsRes?.IsPublish,
            siteName: SiteName,
            appName: appInformations?.appName,
            tenantCode: (window as any).TenantCode,
            tenantId: (window as any).TenantId,
            siteCode: (window as any).SiteCode,
            trackingCode: appInformations?.trackingCode,
            bannerId: BannerId,
            bannerName: BannerName,
            pages,
            country: Country,
            themeConfigurations,
            languages,
            logoUrl,
            favicon,
            strapiUrl: strapiUrlAutoGenerate(),
            informations,
            googleMapKeys: {
              android: googleMaps?.android,
              ios: googleMaps?.ios,
              browser: googleMaps?.browser,
            },
            firebaseConfig: firebase ? JSON.parse(firebase) : {},
            associatedWebUrl: associatedWeSite?.Domain,
            maintenanceMode: maintenanceMode || false,
          };
          return resultSettings;
        } catch (error) {
          this.router.navigateByUrl('/maintenance');
          console.error('Failed to parse app settings:', error);
          return null;
        }
      })
    );
    return observable;
  }

  private async loadTenantSettings() {
    try {
      const tenantSettings = await firstValueFrom(this.getTenantSettingsValue());
      if (tenantSettings) {
        await this.setTenantSettings(tenantSettings);
      }
      return tenantSettings;
    } catch {
      this.router.navigateByUrl('/maintenance');
      return null;
    }
  }

  public async getGuestModeSetting(): Promise<IDXPSetting | null> {
    if (this.guestModeSetting) {
      return this.guestModeSetting;
    }

    if (this.loadingGuestPromise) {
      return this.loadingGuestPromise;
    }

    this.loadingGuestPromise = (async () => {
      try {
        const cached = (await this.cache
          .getItem(this.guestModeSettingCacheKey)
          .catch(cacheErrorHandle)) as IDXPSetting | null;
        if (cached) {
          this.guestModeSetting = cached;
          return this.guestModeSetting;
        }

        const fetchedSetting = (await firstValueFrom(
          this.settingApi.get(`/setting/by-name/${SettingKey.GuestMode}`)
        )) as IDXPSetting | null;
        if (fetchedSetting) {
          this.guestModeSetting = fetchedSetting;
          await this.cache.saveItem(this.guestModeSettingCacheKey, this.guestModeSetting, null, this.ttl);
        }
        return fetchedSetting || null;
      } finally {
        this.loadingGuestPromise = null;
      }
    })();

    return this.loadingGuestPromise;
  }
}
