import { Component, EventEmitter, Output, OnInit } from '@angular/core';
import { FormBuilder, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { AuthService } from '@rsApp/modules/auth-v2/providers/auth-v2.service';
import { Credential } from '@rsApp/modules/auth-v2/providers/credential.service';

import { firstValueFrom } from 'rxjs';

@Component({
  selector: 'mag-confirm-password',
  templateUrl: './mag-confirm-password.html',
  styleUrls: ['./mag-confirm-password.scss'],
})
export class MagConfirmPasswordComponent implements OnInit {
  confirmPasswordForm;
  userEmail: string;
  isLoading = false;

  @Output() confirmDelete = new EventEmitter<boolean>();

  constructor(
    private fb: FormBuilder,
    private authService: AuthService,
    private cre: Credential,
    private router: Router
  ) {
    // Initialize the form with validation
    this.confirmPasswordForm = this.fb.group({
      password: ['', [Validators.required]],
    });
  }

  async ngOnInit() {
    if (!this.cre.currentUser) {
      console.warn('No user found');
      this.router.navigate(['/tabs/my-account']);
      return;
    }
    this.userEmail = this.cre.currentUser?.Email;
  }

  /**
   * Calls login API to verify user password.
   * Emits the entered password for external use (e.g., logging or flow control).
   */
  async checkPassword(): Promise<boolean> {
    try {
      const isPwValid = await firstValueFrom(
        this.authService.validatePassword(this.confirmPasswordForm.value.password)
      );
      return isPwValid;
    } catch (error) {
      console.error('error', error);
      return false;
    }
  }

  /**
   * Triggered on form submit; verifies password and emits success
   */
  async onSubmit() {
    if (this.confirmPasswordForm.invalid) {
      this.confirmPasswordForm.markAllAsTouched();
      return;
    }
    this.isLoading = true;
    const isPwValid = await this.checkPassword();
    if (!isPwValid) {
      const control = this.confirmPasswordForm.get('password');
      control.setErrors({ failedAttempt: true });
      this.isLoading = false;
      return;
    }
    this.isLoading = false;
    return this.confirmDelete.emit(true);
  }
}
