import type { ViewCartParams, Ga4Item } from './ga4.types';

function pickLocalizedText(v: any): string | undefined {
  if (!v) return undefined;
  if (typeof v === 'string') return v;

  if (typeof v === 'object') {
    if (typeof v.En === 'string') return v.En;
    if (typeof v.en === 'string') return v.en;

    const first = Object.values(v).find((x) => typeof x === 'string');
    return first as string | undefined;
  }

  return undefined;
}

function toNumber(v: any): number | undefined {
  if (typeof v === 'number' && Number.isFinite(v)) return v;
  const n = Number(v);
  return Number.isFinite(n) ? n : undefined;
}

function mapCartItemToGa4Item(p: any, idx: number): Ga4Item {
  const categories: any[] = Array.isArray(p?.Categories) ? p.Categories : [];
  const byLevel = (level: number) => categories.find((c) => c?.Level === level)?.CategoryName;

  return {
    item_id: p?.ProductId ?? p?.Upc ?? p?.Gtin ?? p?.item_id,
    item_name: pickLocalizedText(p?.DisplayName) ?? pickLocalizedText(p?.Name) ?? p?.item_name,
    item_brand: p?.BrandName?.BrandName ?? p?.Brands?.[0]?.BrandName ?? p?.item_brand,

    item_category: byLevel(1),
    item_category2: byLevel(2),
    item_category3: byLevel(3),
    item_category4: byLevel(4),
    item_category5: byLevel(5),

    item_variant: p?.Unit ?? p?.item_variant,
    location_id: p?.BranchId ?? p?.Stores?.[0]?.StoreCode ?? p?.location_id,

    price: toNumber(p?.Price ?? p?.TotalPrice ?? p?.price),
    quantity: toNumber(p?.Quantity ?? p?.quantity),

    index: idx + 1,
  };
}

export function mapViewCartParams(payload: any): ViewCartParams | null {
  const itemsRaw: any[] = Array.isArray(payload) ? payload : payload?.items ?? payload?.data ?? [];
  if (!Array.isArray(itemsRaw) || itemsRaw.length === 0) return null;

  const currency = payload?.currency ?? payload?.Currency ?? itemsRaw[0]?.Currency ?? 'USD';

  const value =
    itemsRaw.reduce((sum, it) => sum + (toNumber(it?.TotalPriceWithSavings ?? it?.TotalPrice) ?? 0), 0) ||
    itemsRaw.reduce((sum, it) => sum + (toNumber(it?.Price) ?? 0) * (toNumber(it?.Quantity) ?? 1), 0);

  return {
    currency,
    value,
    items: itemsRaw.map(mapCartItemToGa4Item),
  };
}
