import { PerformanceLoggerService } from './modules/utils/providers/performance-logger.service';
import { WidgetPrerenderService } from './modules/utils/providers/widget-prerender.service';
import { CategoryService } from './modules/browse/provider/category.service';

import { NativeAnalyticsService } from './core/firebase/native-analytics.service';
register();

@Component({
  selector: 'app-root',
  templateUrl: 'app.component.html',
  animations: [
    trigger('routerTransition', [
      transition(':enter', [
        style({ opacity: 0, transform: 'translateX(100%)' }), // Starting state (from right)
        animate('300ms ease-in-out', style({ opacity: 1, transform: 'translateX(0)' })), // End state (in position)
      ]),
      transition(':leave', [
        style({ opacity: 1, transform: 'translateX(0)' }), // Starting state (in position)
        animate('300ms ease-in-out', style({ opacity: 0, transform: 'translateX(-100%)' })), // End state (slide out left)
      ]),
    ]),
    trigger('fadeAnimation', [
      state('void', style({ opacity: 1 })),
      state('*', style({ opacity: 1 })),
      transition(':leave', [animate('0.5s ease-out', style({ opacity: 0 }))]),
    ]),
  ],
})
export class AppComponent implements OnDestroy, OnInit {
  runOnce = false;
  banner = DEFAULT_BANNER_NAME;
  deviceMode = DEFAULT_DEVICE_MODE;
  state = null;
  isAppReady = false;
  appOpenedFromDeepLink = false;
  isMaintenanceMode = false;

  private _tenantSettings: ITenantSettings;
  private user: any;
  private _dxpComponentCustomMessages = {};
  private _destroy$: Subject<boolean> = new Subject();
  private _isFirstStoreLoad = true;

  private readonly UTM_STORAGE_KEY = 'ga_campaign_data';

  @ViewChild(IonRouterOutlet, { static: false }) routerOutlet: IonRouterOutlet;

  constructor(
    private platform: Platform,
    private cache: CacheService,
    private router: Router,
    private route: ActivatedRoute,
    private auth: AuthService,
    public tracker: RSTracker,
    public dxpTracker: DXPTracker,
    public utils: Utils,
    public modalCtrl: ModalController,
    private events: NgxPubSubService,
    public cStore: CurrentStore,
    private ngZone: NgZone,
    public cre: Credential,
    public appSettings: AppSettings,
    public tenantSettingsStore: TenantSettingsStore,
    public navCtrl: NavController,
    public dxpComponentService: DxpComponentService,
    public store: StoreService,
    public widgetLayoutService: WidgetLayoutService,
    public translate: TranslateService,
    private storage: Storage,
    private googleTracker: GoogleAnalyticTracker,
    private notificationService: NotificationService,
    public dynamicMenuSvc: DynamicMenu,
    private titleService: Title,
    private firebaseService: FirebaseService,
    private useKeyboard: UseKeyboard,
    private cacheVersioning: CacheVersioningService,
    private cookieConsentService: CookieConsentService,
    private shoppingCartService: EditOrderService,
    private perfLogger: PerformanceLoggerService,
    private widgetPrerenderService: WidgetPrerenderService,
    public categoryService: CategoryService,
    private nativeAnalyticsService: NativeAnalyticsService
  ) {
    this.perfLogger.mark('APP_COMPONENT_CONSTRUCTOR');
    this.initializeApp();
    this.useKeyboard.init();
    this.router.events.subscribe((event) => {
      if (event instanceof NavigationStart) {
        this.state = event.navigationTrigger === 'popstate' ? 'back' : 'forward';
        this.perfLogger.log(`🧭 Navigation Start: ${event.url}`);
      }
    });

    // This ensures the cookie banner state is reset for a fresh login flow.
    const isCookieOpen = this.storage.get('forceOpenBanner');
    isCookieOpen && this.storage.remove('forceOpenBanner');
  }

  async ngOnInit() {
    if (Capacitor.isNativePlatform()) {
      await this.initializeSafeAreaInsets();
    }
  }

  // ==================== LIFECYCLE METHODS ====================
  ngOnDestroy() {
    this._destroy$.next(true);
    this._destroy$.complete();
  }

  // ==================== MAIN INITIALIZATION ====================
  async initializeApp() {
    this.perfLogger.mark('INIT_APP_START');
    this.initializeCache();
    this.perfLogger.mark('CACHE_INITIALIZED');
    this.prefetchData(); // Do not await this function
    this.perfLogger.log('Data prefetch started');
    this.cacheVersioning.checkAndUpdate();
    await this.initializeAppSettings();
    this.perfLogger.mark('APP_SETTINGS_INITIALIZED');

    //Maintainance mode check
    if (this.isMaintenanceMode) {
      await this.setAppReady();
      return;
    }

    await this.initializePlatform();
    this.perfLogger.mark('PLATFORM_INITIALIZED');
    this.setupNavigationTracking();
    this.setupStoreSubscription();
    await this.setAppReady();
    this.perfLogger.mark('APP_READY');
    this.initializeNotifications(); // Do not await this function
    this.perfLogger.printSummary('INIT_APP_COMPLETE');
  }

  // ==================== CACHE INITIALIZATION ====================
  private initializeCache() {
    // Set TTL to 10 mins
    this.cache.setDefaultTTL(10 * 60 * 1);
    // Keep our cached results when device is offline!
    this.cache.setOfflineInvalidate(false);
  }

  // ==================== PREFETCH DATA ====================
  private async prefetchData() {
    const isStartApp = window.location.pathname === '/';
    if (isStartApp) {
      // Prefetch layout data for home page & cache it
      lastValueFrom(this.widgetLayoutService.getLayout('tabs/home', 'home', 'home')).then((layout) => {
        this.widgetPrerenderService.setLayoutConfig(layout);
        setTimeout(() => {
          this.widgetPrerenderService.preloadStencilComponent();
        }, 3000);
      });
    }
    firstValueFrom(this.store.getStoreSystemServices()).then();
    // Prefetch setting data
    const settingNames = ['DXP_COMPONENT_BUILD_NUMBER_APP'];
    this.appSettings.getSettingValues(settingNames).toPromise();
  }

  // ==================== APP SETTINGS INITIALIZATION ====================
  private async initializeAppSettings() {
    try {
      this.perfLogger.log('Fetching tenant settings...');
      this._tenantSettings = await this.tenantSettingsStore.getTenantSettings();
      this.perfLogger.mark('TENANT_SETTINGS_LOADED');
      this.handleMaintenanceMode();
      this.titleService.setTitle(this._tenantSettings?.siteName || 'ShopDot Supermarkets App');
      this.setFavicon(this._tenantSettings?.favicon);
      this.perfLogger.log('Initializing translations...');
      await this.initTranslation(this._tenantSettings?.languages);
      this.perfLogger.mark('TRANSLATIONS_INITIALIZED');
      const themeSvc = new ThemeService();
      themeSvc.initialize(this._tenantSettings?.themeConfigurations);
      this.appThemeBanner();
    } catch (error) {
      console.warn('Error initializing app settings:', error);
      this.perfLogger.log('❌ Error initializing app settings', error);
    }
  }

  private handleMaintenanceMode() {
    if (this._tenantSettings?.maintenanceMode) {
      this.isMaintenanceMode = true;
      this.router.navigateByUrl('/maintenance');
      return;
    }
  }

  async initTranslation(languages: ITenantLanguage[]) {
    let currentLocale = await this.storage.get(LOCAL_LOCALE_KEY);
    if (!currentLocale) {
      currentLocale = languages?.find((l) => l.IsDefault)?.Value;

      // Assign default locale if no current locale
      if (!currentLocale) {
        const defaultLocale = languages?.find((l) => l?.Value === DEFAULT_LOCALE);
        if (defaultLocale) {
          currentLocale = defaultLocale.Value;
        } else {
          currentLocale = languages?.[0]?.Value;
        }
      }
      await this.storage.set(LOCAL_LOCALE_KEY, currentLocale);
    }

    this._applyCustomMessages(currentLocale, languages);
  }

  setFavicon(faviconUrl: string) {
    const link: HTMLLinkElement | null = document.querySelector("link[rel*='icon']") || document.createElement('link');
    link.type = 'image/x-icon';
    link.rel = 'shortcut icon';
    link.href = faviconUrl || 'assets/icon/favicon.png';

    if (!document.head.contains(link)) {
      document.head.appendChild(link);
    }
  }

  appThemeBanner() {
    this.banner = this._tenantSettings?.bannerName || DEFAULT_BANNER_NAME;
    this.deviceMode = ENV.DeviceMode || DEFAULT_DEVICE_MODE;
  }

  // ==================== PLATFORM INITIALIZATION ====================
  private async initializePlatform() {
    this.perfLogger.log('Loading DXP component script...');
    this.dxpComponentService.loadScriptDxpComponent();
    this.perfLogger.mark('DXP_SCRIPT_LOADED');

    this.tracker.init();
    this.dxpTracker.init();
    this.googleTracker.init();
    this.perfLogger.mark('TRACKERS_INITIALIZED');

    this.perfLogger.log('Waiting for platform ready...');
    await this.platform.ready();
    this.perfLogger.mark('PLATFORM_READY');
    this.perfLogger.log('Getting store...');

    let store = await this.cStore.getStore();
    if (!store?.StoreCode) {
      store = await this.cStore.autoAssignStore();
      this.getCategoryAfterAssignStore(store);
    }
    this.perfLogger.mark('STORE_LOADED');

    this.onAuthChange();
    this.handleOnDynamicLink();
    this.handleOnTutorial(); // Do not await this function
    this.setupPlatformResumeHandler();
    this.cookieConsentService
      .listenForceUpdate()
      .pipe(take(1))
      .subscribe((rs) => {
        if (!rs) {
          this.initializeCookieConsent(localStorage.getItem('cookieConsentToken'));
        }
      });
    this.handleCurbsideOrderData();
  }

  getCategoryAfterAssignStore(store) {
    if (!store || !store.StoreCode) return;
    return Promise.all([this.categoryService.loadCategories(true), this.categoryService.loadDepartments(true)]);
  }

  private initializeCookieConsent(consentToken: string, forceOpenBanner?: boolean) {
    const trackingPageViewAfterInit = () => {
      const componentName = this.getComponentName();
      this.trackPageAnalytics(componentName, this.router.url); // Trigger tracking page view when change init
    };

    this.cookieConsentService.init(consentToken, trackingPageViewAfterInit, forceOpenBanner);
    this.cookieConsentService.refreshTokenCookieConsent(); // First time out refresh token
  }

  async initializeSafeAreaInsets() {
    try {
      // Set status bar style
      if (Capacitor.getPlatform() === 'ios') {
        StatusBar.setStyle({ style: Style.Default });
      }

      const data = await SafeArea.getSafeAreaInsets();
      const { insets } = data;

      // Set properties
      for (const [key, value] of Object.entries(insets)) {
        document.documentElement.style.setProperty(`--safe-area-inset-${key}`, `${value}px`);
      }
    } catch (error) {
      console.error('Error handling safe area insets:', error);
      // Set default values if everything fails
      document.documentElement.style.setProperty('--safe-area-inset-top', '32px');
      document.documentElement.style.setProperty('--safe-area-inset-bottom', '0px');
      document.documentElement.style.setProperty('--safe-area-inset-left', '0px');
      document.documentElement.style.setProperty('--safe-area-inset-right', '0px');
    }
  }

  private async handleCurbsideOrderData() {
    if (!Capacitor.isNativePlatform()) return;
    const currentCurbsideOrderData = await this.cache.getItem('curbside-order-data').catch(() => null);
    if (currentCurbsideOrderData?.orderId && !currentCurbsideOrderData?.isArrived) {
      this.dxpComponentService.doPostUserLocation(currentCurbsideOrderData?.orderId);
    }
  }

  // ==================== NOTIFICATIONS INITIALIZATION ====================
  private async initializeNotifications() {
    if (!Capacitor.isNativePlatform()) return;

    // Delay 3 seconds to ensure the app is ready
    await new Promise((resolve) => setTimeout(resolve, 1500));
    this.notificationService.initialize();
  }

  private setupPlatformResumeHandler() {
    this.platform.resume.subscribe(async () => {
      // cheat for extend time cache token
      await this.cacheVersioning.checkAndUpdate();
      this.auth.cre.setRsApiToken(this.auth.cre.rsApiToken);
      this.events.publishEvent('emmit-change-order');
      this.events.publishEvent('reload-timeslot');
      this.notificationService.getFCMToken(this.user);
    });
  }

  // ==================== NAVIGATION & ROUTING ====================

  private setupNavigationTracking() {
    this.setupNavigationLoading();
    this.setupNavigationAnalytics();
  }

  private setupNavigationLoading() {
    const navigationLoadingO = this.router.events.pipe(
      filter((event) => event instanceof NavigationEnd),
      tap(async (event: NavigationEnd) => {
        try {
          this.perfLogger.log(`📍 Navigation End: ${event.url}`);
          if (!this.runOnce) {
            this.runOnce = true;
            this.perfLogger.mark('SPLASH_SCREEN_HIDDEN');
            await SplashScreen.hide();
          }
          // track page Event
          let state = this.route.root;
          //Get Page name
          while (state.firstChild) {
            state = state.firstChild;
          }
        } catch (error) {
          console.error('Tracking page:', error); // Log to check when build prod
        }
      })
    );
    navigationLoadingO.subscribe();
  }

  private setupNavigationAnalytics() {
    const navigationO = this.router.events.pipe(
      filter((event) => event instanceof NavigationEnd),
      tap(async (event: any) => {
        try {
          if (!this.runOnce) {
            this.runOnce = true;
            await SplashScreen.hide();
          }

          const componentName = this.getComponentName();
          this.perfLogger.log(`📊 Tracking analytics for: ${componentName}`);
          this.trackPageAnalytics(componentName, event.url);
          this.restoreCampaignOnNavigation();
        } catch (error) {
          console.error('Tracking page:', error); // Log to check when build prod
        }
      })
    );
    navigationO.subscribe();
  }

  private getComponentName(): string {
    let state = this.route.root;
    while (state.firstChild) {
      state = state.firstChild;
    }

    return (
      (<any>state.component &&
        (<any>state.component).prototype &&
        (<any>state.component).prototype.getPageName &&
        (<any>state.component).prototype.getPageName()) ||
      (<any>state.component).prototype.constructor?.name
    );
  }

  private trackPageAnalytics(componentName: string, url: string) {
    this.tracker.trackPage(componentName || url, url);
    this.dxpTracker.trackPage(componentName || url, url);
    this.googleTracker.gtagTrackPageView(componentName || url, url);
  }

  private getLeaftActiveRoute(route) {
    if (route.firstChild) {
      return this.getLeaftActiveRoute(route.firstChild);
    }
    return route;
  }

  // ==================== AUTHENTICATION & USER MANAGEMENT ====================
  onAuthChange() {
    let o = this.auth.authState().pipe(
      switchMap((user: any) => {
        const lRoute = this.getLeaftActiveRoute(this.getLeaftActiveRoute(this.route));
        return lRoute.data.pipe(
          map((data) => {
            return { data, user };
          })
        );
      })
    );
    // anaylytics
    o = o.pipe(
      tap(async (res: any) => {
        this.events.publishEvent('emmit-change-order', { cleanUpData: !res.user }); // clean data if user logout
        this.events.publishEvent('emmit-list', { reload: true }); // must call befor return user null

        // Initialize dxp-component with Store & User data
        const currentStore = await this.cStore.getStore();
        if (currentStore && currentStore.StoreCode) {
          this.events.publishEvent(enumTrackAction.TrackUserProperty, {
            name: 'HomeStore',
            value: currentStore && currentStore.StoreCode,
          });
          this.initializeDxpComponent({ user: res.user, store: currentStore });
        } else {
          // if no store, wait for store to be loaded
          // subscribe store state only once and then destroy subscription
          this.cStore
            .storeState()
            .pipe(
              filter((store) => store && store.StoreCode),
              take(1),
              takeUntil(this._destroy$)
            )
            .subscribe((store) => {
              this.events.publishEvent(enumTrackAction.TrackUserProperty, {
                name: 'HomeStore',
                value: store && store.StoreCode,
              });
              this.initializeDxpComponent({ user: res.user, store });
            });
        }

        if (!res.user) {
          return;
        }
        // add set user id and user property
        const user = res.user;
        this.tracker.trackUser(user.UserId);
        this.events.publishEvent(enumTrackAction.TrackUserProperty, {
          name: 'MemberID',
          value: user && (user.LoyaltyCardId || user.CustomerCode || ''),
        });

        if (Capacitor.isNativePlatform()) {
          await FirebaseCrashlytics.setUserId({
            userId: user.UserId,
          });
        }
      })
    );

    o.subscribe((res: any) => {
      this.user = cloneDeep(res.user);
      this.notificationService.getFCMToken(res.user);
      if (res.user) {
        return;
      }
    });
  }

  // ==================== STORE MANAGEMENT ====================
  private setupStoreSubscription() {
    this.cStore.storeState().subscribe((store) => {
      if (!store) return;

      // Skip first time store change since onAuthChange already init dxp-component
      if (this._isFirstStoreLoad) {
        this._isFirstStoreLoad = false;
        return;
      }

      this.events.publishEvent(enumTrackAction.TrackUserProperty, { name: 'HomeStore', value: store.StoreCode });

      // From second time store change, init dxp-component
      this.dxpComponentService.onChangeStore(store, this.auth?.cre);
    });
  }

  // ==================== DXP COMPONENT MANAGEMENT ====================
  initializeDxpComponent({ user, store }: { user: IUser; store: IStore }) {
    this.dxpComponentService.initializeDxpComponent(
      {
        user,
        store,
        cre: this.auth.cre,
        currentShoppingList: null,
      },
      this._tenantSettings
    );
  }

  // ==================== DYNAMIC LINKS & DEEP LINKING ====================
  private handleOnDynamicLink() {
    App.addListener('appUrlOpen', (data: { url: string }) => {
      if (!data.url) {
        console.warn('No url found in deep link');
        return;
      }
      this.ngZone.run(() => {
        try {
          const baseUrl = new URL(data?.url);
          const part = baseUrl.toString().split('link=')[1];
          const innerLink = part.split(/&apn=|&afl=|&ifl=|&ibi=|&efr=/)[0];

          if (innerLink) {
            const innerUrl = new URL(innerLink);
            const utm = {
              source: innerUrl?.searchParams.get('utm_source'),
              medium: innerUrl?.searchParams.get('utm_medium'),
              campaign: innerUrl?.searchParams.get('utm_campaign'),
              id: innerUrl?.searchParams.get('utm_id'),
              term: innerUrl?.searchParams.get('utm_term'),
              content: innerUrl?.searchParams.get('utm_content'),
              timestamp: Date.now(),
            };

            localStorage.setItem(this.UTM_STORAGE_KEY, JSON.stringify(utm));
          }

          // Skip firebase pre-install link test
          if (baseUrl.searchParams.get('match_message') === 'No pre-install link matched for this device.') {
            return;
          }

          // Mark that the app was opened from a deep link
          this.appOpenedFromDeepLink = true;

          const { host, searchParams, origin } = baseUrl;
          // TODO: keys that should NEVER move into inner link
          const SYSTEM_KEYS = new Set(['link', 'afl', 'ifl', 'apn', 'ibi', 'isi', 'efr']);

          // Check if the deep link is for our app
          if (origin.includes(host)) {
            const appDynamicLink = searchParams.get('afl') || searchParams.get('ifl') || searchParams.get('link');
            if (appDynamicLink) {
              const _appDynamicLink = new URL(appDynamicLink);
              // TODO : move ALL dynamic params into inner link thant can not encode
              baseUrl.searchParams.forEach((value, key) => {
                if (!SYSTEM_KEYS.has(key)) {
                  _appDynamicLink.searchParams.set(key, value);
                }
              });
              this.handleNavigateFromDynamicLink(_appDynamicLink);
            } else {
              console.warn('No appDynamicLink found in deep link');
              this.router.navigateByUrl('/tabs/home');
            }
          } else {
            console.warn('Handle other URLs with existing logic');
            this.router.navigateByUrl('/tabs/home');
          }
        } catch (error) {
          console.warn('Error handling dynamic link navigation:', error);
          this.router.navigateByUrl('/tabs/home');
        }
      });
    });
  }

  async handleNavigateFromDynamicLink(hostUrl: URL): Promise<void> {
    try {
      const appUrl = await this.utils.mappingDynamicLink(hostUrl.pathname, hostUrl.search);
      if (appUrl) {
        await this.router.navigateByUrl(appUrl);
      } else {
        await this.utils.openInaAppBrowser(hostUrl.href);
      }
    } catch (error) {
      console.warn('Error handling dynamic link navigation:', error);
      this.router.navigateByUrl('/');
    }
  }

  // ==================== TUTORIAL HANDLING ====================
  private async handleOnTutorial() {
    try {
      const tutorialData = await firstValueFrom(this.appSettings.getSettingValue('tutorial_configurations'));
      if (!tutorialData) {
        console.warn('No tutorial data found');
        return;
      }
      const parsed = typeof tutorialData === 'string' ? JSON.parse(tutorialData) : [];
      const currentTutorialVersion = await this.storage.get('tutorial_version');
      const serverTutorialVersion = parsed.tutorial_version;
      const gotoTutorial =
        !currentTutorialVersion || parseInt(currentTutorialVersion) < parseInt(serverTutorialVersion);

      if (!gotoTutorial) return;

      // Ensure deep link page open before tutorial page
      if (this.appOpenedFromDeepLink) {
        await new Promise((resolve) => setTimeout(resolve, 3000));
        this.appOpenedFromDeepLink = false;
      }

      this.router.navigate(['/tutorial']);
    } catch (e) {
      console.warn('Error handling tutorial:', e);
    }
  }

  // ==================== TRANSLATION & LOCALIZATION ====================
  private async _applyCustomMessages(currentLocale: string, languages: ITenantLanguage[]) {
    // Early return if translations or languages are not provided
    if (!this.translate || !languages || !languages.length || !currentLocale) return;

    // Find the language object matching the current locale
    const lang = languages.find((l) => l.Value === currentLocale);

    // Flatten the custom messages and apply translations
    const platformMsgs = unflatten(lang.CustomMessages?.platform);
    takeUntil(this._destroy$);
    this.translate
      .getTranslation(currentLocale)
      .pipe(takeUntil(this._destroy$))
      .subscribe((existingTranslations) => {
        // Deep merge existing translations with custom ones
        const merged = merge({}, existingTranslations, platformMsgs);
        // Set the merged translations
        this.translate.setTranslation(currentLocale, merged, false); // false = replace existing
        // Set default and use language
        this.translate.setDefaultLang(currentLocale);
        this.translate.use(currentLocale);
      });
    // Store dxpComponent custom messages for future use
    this._dxpComponentCustomMessages = lang.CustomMessages?.dxpComponent;
    const normailizeDxpComponentCustomMessages = stripLocalePrefix(this._dxpComponentCustomMessages, currentLocale);

    // Send a message to update locale and custom messages
    await this._setLocaleAndSendMessage(currentLocale, normailizeDxpComponentCustomMessages);
  }

  private async _setLocaleAndSendMessage(locale: string, customMessages?: any) {
    // Wait until 'dxp-widget' is defined before posting the message
    await customElements.whenDefined('dxp-widget');

    // Post message to dxp component
    const payload = {
      action: ActionType.MagOnChangeLocale,
      data: {
        Locale: locale,
        CustomMessages: customMessages || {},
      },
    };
    window.postMessage({ ...payload }, window.location.origin);
  }

  // ==================== EVENT HANDLERS ====================
  @HostListener('window:message', ['$event'])
  async listenDxpComponent(event) {
    if (!event.data) return;

    switch (event.data.action) {
      case 'goSetting':
        this.utils.openAppSettings();
        break;
      case 'MagPushTrackingGA4Native': {
        const { eventName, payload } = event.data.payload;
        void this.nativeAnalyticsService.handleGa4Native(eventName, payload);
        break;
      }
      case 'MagPushTrackingFirebase': {
        const { eventName, payload } = event.data.payload;
        this.firebaseService.logEvent(eventName, { ...payload });
        break;
      }
      case 'MagPushTrackingMatomo': {
        const { eventName, payload } = event.data.payload;
        this.events.publishEvent(eventName, { ...payload });
        break;
      }
      case 'MagInitCookieConsent': {
        const { dataToken, forceOpenBanner } = event.data.payload;
        this.initializeCookieConsent(dataToken, forceOpenBanner);
        break;
      }
      case ActionType.MagEditOrderStatusChange: {
        const { data } = event.data;
        this.shoppingCartService.setCartInfo(data);
        break;
      }
      default:
        try {
          await this.dxpComponentService.listenDxpComponent(event);
        } catch (error) {
          console.error('error listenDxpComponent', error);
        }
        break;
    }
  }

  // ==================== UTILITY METHODS ====================
  /**
   * Waiting for the pre-rendering to complete
   * This prevent the layout shifting when the app is ready
   */
  private async setAppReady() {
    if (this.router.url.includes('/sign-in')) {
      this.isAppReady = true;
      return;
    }
    this.perfLogger.log('Setting app ready (waiting 500ms)...');
    await new Promise((resolve) => setTimeout(resolve, 1000));
    this.isAppReady = true;
    this.perfLogger.mark('APP_READY_COMPLETE');
  }

  restoreCampaignOnNavigation() {
    try {
      const storedCampaign = localStorage.getItem('ga_campaign_data');
      if (!storedCampaign) {
        return null;
      }

      const campaignParsed = JSON.parse(storedCampaign);
      const now = Date.now();
      const cacheTime = 30 * 60 * 1000;
      if (now - campaignParsed.timestamp < cacheTime) {
        return campaignParsed;
      } else {
        localStorage.removeItem('ga_campaign_data');
        return null;
      }
    } catch (error) {
      console.error('Error restoring campaign data:', error);
      return null;
    }
  }
}
