import { Injectable } from '@angular/core';
import { User } from '@rsApp/modules/account-v2/providers/user.service';
import { Credential } from '@rsApp/modules/auth-v2/providers/credential.service';
import { ProductService } from '@rsApp/modules/ecom-v2/product/providers/product.service';
import { firstValueFrom } from 'rxjs';
import { AppSettings } from './app-setting';

export interface ICacheModuleVersion {
  name: CacheVersionModule;
  version: number;
}

export interface ICacheVersionConfig {
  version: number;
  modules: ICacheModuleVersion[];
}

export enum CacheVersionModule {
  PPR_TAGS = 'PPRTags',
  USER_DATA = 'userData',
  SETTING = 'setting',
}

@Injectable({ providedIn: 'root' })
export class CacheVersioningService {
  constructor(
    private productService: ProductService,
    private appSettings: AppSettings,
    private cre: Credential,
    private userService: User
  ) {}

  cacheVersionConfigKey = 'app_client_cache_management';

  async checkAndUpdate(): Promise<void> {
    try {
      const serverConfig = await firstValueFrom(this.fetchServerCacheVersionConfig());
      const parseData: ICacheVersionConfig | null =
        typeof serverConfig === 'string' && serverConfig?.length > 0 ? JSON.parse(serverConfig) : null;

      // If no server config, don't do anything
      if (!parseData) {
        console.warn('No server config found');
        return;
      }

      const localConfig = this.getLocalCacheVersionConfig();

      // If no local config, save and run all module updaters
      if (!localConfig) {
        await this.updateModulesOnFirstSync(parseData);
        this.saveLocalCacheVersionConfig(parseData);
        return;
      }

      // If server cacheVersion is newer, update per-module and then persist
      if (Number(parseData.version) > Number(localConfig.version)) {
        await this.updateModulesByDiff(localConfig, parseData);
        this.saveLocalCacheVersionConfig(parseData);
      }
    } catch (error) {
      // Silent fail to avoid blocking app startup/resume
      console.warn('CacheVersioningService.checkAndUpdate error:', error);
    }
  }

  // ============== Fetch/Store ==============
  private fetchServerCacheVersionConfig() {
    try {
      return this.appSettings.getSettingValue(this.cacheVersionConfigKey, true);
    } catch (error) {
      console.warn('Fetch server cache version config failed:', error);
      return null;
    }
  }

  private getLocalCacheVersionConfig(): ICacheVersionConfig | null {
    try {
      const raw = localStorage.getItem(this.cacheVersionConfigKey);
      return raw ? (JSON.parse(raw) as ICacheVersionConfig) : null;
    } catch {
      return null;
    }
  }

  private saveLocalCacheVersionConfig(config: ICacheVersionConfig) {
    try {
      localStorage.setItem(this.cacheVersionConfigKey, JSON.stringify(config));
    } catch {
      console.warn('Save local cache version config failed');
    }
  }

  // ============== Module Update Logic ==============
  private async updateModulesOnFirstSync(config: ICacheVersionConfig): Promise<void> {
    const modules = config?.modules || [];

    // Run all module updates in parallel for better performance
    const updatePromises = modules.map((module) => this.runModuleUpdate(module.name));
    await Promise.all(updatePromises);
  }

  private async updateModulesByDiff(local: ICacheVersionConfig, server: ICacheVersionConfig): Promise<void> {
    const localMap = new Map<CacheVersionModule, number>((local.modules || []).map((m) => [m.name, Number(m.version)]));
    const serverModules = server?.modules || [];

    // Collect modules that need updates
    const modulesToUpdate: CacheVersionModule[] = [];
    for (const module of serverModules) {
      const prevVersion = localMap.get(module.name) ?? -1;
      const nextVersion = Number(module.version);
      if (nextVersion > prevVersion) {
        modulesToUpdate.push(module.name);
      }
    }

    // Run all updates in parallel for better performance
    if (modulesToUpdate.length > 0) {
      const updatePromises = modulesToUpdate.map((moduleName) => this.runModuleUpdate(moduleName));
      await Promise.all(updatePromises);
    }
  }

  public async runModuleUpdate(moduleName: CacheVersionModule): Promise<void> {
    switch (moduleName) {
      case CacheVersionModule.PPR_TAGS:
        await this.updatePprTags();
        break;
      case CacheVersionModule.USER_DATA:
        await this.updateUserData();
        break;
      case CacheVersionModule.SETTING:
        await this.updateSetting();
        break;
      default:
        console.warn('unimplemented module:', moduleName);
        break;
    }
  }

  // ============== PPRTags Updater ==============
  private async updatePprTags(): Promise<void> {
    try {
      const user = await this.cre.getCurrentUser();
      if (!user?.UserId) return;

      const pprTags = await firstValueFrom(this.productService.getProductRecommendation());

      if (pprTags) {
        localStorage.setItem(CacheVersionModule.PPR_TAGS, JSON.stringify(pprTags));
      } else {
        localStorage.removeItem(CacheVersionModule.PPR_TAGS);
      }
    } catch (error) {
      console.warn('updatePprTags failed', error);
    }
  }

  // ============== User Data Updater ==============
  private async updateUserData(): Promise<void> {
    try {
      const user = await this.cre.getCurrentUser();
      if (!user?.UserId) return;
      const newUser = await firstValueFrom(this.userService.getUserById(user.UserId, true));
      if (newUser) {
        // Set new user data to credential service
        await this.cre.setCurrentUser(newUser);

        // Refresh page to apply new user data
        window.location.reload();
      }
    } catch (error) {
      console.warn('updateUserData failed', error);
    }
  }

  // ============== Setting Updater ==============
  private async updateSetting(): Promise<void> {
    try {
      // TODO: Implement after review all setting
      console.log('TODO: updateSetting');
    } catch (error) {
      console.warn('updateSetting failed', error);
    }
  }
}
