import { Component, Input, OnDestroy, OnInit } from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { NavController } from '@ionic/angular';
import { ProductSearchService } from '@rsApp/modules/ecom-v2/product/providers/product-search.service';
import { DxpComponentService } from '@rsApp/modules/utils/providers/dxp.component.service';
import { Subject, takeUntil } from 'rxjs';

@Component({
  selector: 'app-header-product-search',
  templateUrl: './header-product-search.html',
})
export class HeaderProductSearchComponent implements OnInit, OnDestroy {
  private _destroy$: Subject<boolean> = new Subject();
  public keyword: string = '';
  @Input() isShowBackButton = false;

  constructor(
    public route: ActivatedRoute,
    public dxpComponentService: DxpComponentService,
    public productSearchService: ProductSearchService,
    public navController: NavController
  ) {}

  async ngOnInit() {
    await this.dxpComponentService.onConnected();
    this.listenGetCriteria();
  }

  listenGetCriteria() {
    this.productSearchService
      .getCriterias()
      .pipe(takeUntil(this._destroy$))
      .subscribe((criterias) => {
        this.keyword = criterias?.keyword ?? '';
      });
  }

  ngOnDestroy() {
    this._destroy$.next(true);
    this._destroy$.complete();
  }

  handleNavigateBack = () => {
    this.productSearchService.handleNavigateBack();
  };
}
