import { enableProdMode } from '@angular/core';
import { platformBrowserDynamic } from '@angular/platform-browser-dynamic';
import { provideAnimations } from '@angular/platform-browser/animations';
import { Capacitor } from '@capacitor/core';
import { AppModule } from './app/app.module';
import { ENV } from '@app/env';

import 'hammerjs'; // HAMMER TIME

// Performance logging
if (ENV.EnablePerformanceLogging) {
  console.log('[PERF] 🚀 Main.ts - Bootstrap starting', performance.now());
}

(window as any).IsApp = true;
(window as any).IsNativePlatform = Capacitor.isNativePlatform();
(window as any).IsWebLocalhost = window.location.hostname === 'localhost';

if ((window as any).IsNativePlatform || (window as any).IsWebLocalhost) {
  (window as any).TenantId = ENV.TenantId;
  (window as any).TenantCode = ENV.TenantCode;
  (window as any).SiteCode = ENV.SiteCode;
}

if (ENV.production) {
  enableProdMode();
}

const bootstrapStart = performance.now();
platformBrowserDynamic()
  .bootstrapModule(AppModule, {
    providers: [provideAnimations()],
  })
  .then(() => {
    if (ENV.EnablePerformanceLogging) {
      const bootstrapTime = performance.now() - bootstrapStart;
      console.log(`[PERF] ✅ AppModule bootstrapped - ${bootstrapTime.toFixed(2)}ms`);
    }
  })
  .catch((err) => console.error(err));
