import { CommonModule } from '@angular/common';
import { HttpHandler } from '@angular/common/http';
import { CUSTOM_ELEMENTS_SCHEMA, NgModule } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { RouterModule, Routes } from '@angular/router';
import { ENV } from '@app/env';
import { IonicModule } from '@ionic/angular';
import { Credential } from '@rsApp/modules/auth-v2/providers/credential.service';
import { RelationshopEComCoreHttpClientFactory } from '@rsApp/modules/gateway/rs-ecom-core-api.service';
import { EnvironmentService } from '../../../environments/environment.service';
import { UtilsModule } from '@rsApp/modules/utils/utils.module';
import { UserServiceModule } from '../account-v2/providers/user.service';
import { StoreListComponent } from './components/store-list/store-list';
import { StoreMapComponent } from './components/store-map/store-map';
import { DirectionsMapPageComponent } from './pages/direction/direction';
import { FindStorePageComponent } from './pages/find-store/find-store';
import { StoreInfoPageComponent } from './pages/info/info';
import { NearStorePageComponent } from './pages/near-store/near-store';
import { ResultFindStorePageComponent } from './pages/result-find-store/result-find-store';
import { StoreContextPageComponent } from './pages/store-context/store-context';
import { StoreServiceModule } from './providers/store.service';
import { STORE_API_URL, STORE_HTTP_CLIENT } from './store.config';
export { CurrentStore } from './providers/current-store.service';
export { StoreService } from './providers/store.service';
import { TranslateModule } from '@ngx-translate/core';
import { HeaderComponentModule } from '../header/header.component.module';

const baseRoute: Routes = [
  {
    path: '',
    // component: ResultFindStorePageComponent
    redirectTo: 'result-find',
    pathMatch: 'full',
  },
  {
    path: 'find',
    component: FindStorePageComponent,
    data: {
      hideTab: true,
    },
  },
  {
    path: 'near',
    component: StoreContextPageComponent,
    data: {
      hideTab: true,
    },
  },
  {
    path: 'context',
    component: StoreContextPageComponent,
    data: {
      hideTab: true,
    },
  },
  {
    path: 'info',
    component: StoreInfoPageComponent,
    data: {
      hideTab: true,
    },
  },
  {
    path: 'direction',
    component: DirectionsMapPageComponent,
    data: {
      hideTab: true,
    },
  },
  {
    path: 'result-find',
    component: ResultFindStorePageComponent,
    data: {
      hideTab: true,
    },
  },
];

const routes = baseRoute.map((route) => ({
  ...route,
  data: {
    ...route.data,
    hideTab: true,
  },
}));

@NgModule({
  imports: [
    RouterModule.forChild(routes),
    CommonModule,
    IonicModule,
    FormsModule,
    UserServiceModule,
    StoreServiceModule,
    UtilsModule,
    TranslateModule,
    HeaderComponentModule,
  ],
  declarations: [
    FindStorePageComponent,
    NearStorePageComponent,
    StoreContextPageComponent,
    StoreInfoPageComponent,
    DirectionsMapPageComponent,
    ResultFindStorePageComponent,
    StoreListComponent,
    StoreMapComponent,
  ],
  providers: [
    { provide: STORE_API_URL, useValue: ENV.EComStoreAPIURL },
    {
      provide: STORE_HTTP_CLIENT,
      useFactory: RelationshopEComCoreHttpClientFactory,
      deps: [HttpHandler, Credential, STORE_API_URL, EnvironmentService],
    },
  ],
  schemas: [CUSTOM_ELEMENTS_SCHEMA],
})
export class StoreModule {}
