import { Injectable } from '@angular/core';
import { ActivatedRouteSnapshot, CanActivate, Router, UrlTree } from '@angular/router';
import { Observable } from 'rxjs';
import { map, take } from 'rxjs/operators';
import { AuthService } from '../providers/auth-v2.service';

@Injectable({
  providedIn: 'root',
})
export class AuthGuardService implements CanActivate {
  constructor(
    public auth: AuthService,
    public router: Router
  ) {}
  canActivate(next: ActivatedRouteSnapshot): Observable<boolean | UrlTree> {
    return this.auth.getCurrentUser().pipe(
      take(1),
      map((user) => {
        if (user) {
          return true;
        }
        // not yet login, redirect to login page
        const backUrl = (<any>next)._routerState.url;
        return this.router.createUrlTree(['/sign-in', { returnRoute: backUrl }]);
      })
    );
  }
}
