import { Inject, Injectable } from '@angular/core';

import { Observable, of } from 'rxjs';
import { catchError, map } from 'rxjs/operators';

// import { Http, Response, Headers, RequestOptions, URLSearchParams } from '@angular/http';
import { RelationshopEComCoreHttpClient } from '@rsApp/modules/gateway/rs-ecom-core-api.service';
import { IMenu } from '@rsApp/modules/interfaces/menu.interface';
import { AppSettings } from '@rsApp/modules/utils/providers/app-setting';
import { refreshParam } from '@rsApp/modules/utils/providers/utils';
import { CMS_HTTP_CLIENT } from '@rsApp/modules/more/more.config';

@Injectable()
export class MenuService {
  groupCacheKey = 'CMS-MENU;';
  constructor(
    public appSetting: AppSettings,
    @Inject(CMS_HTTP_CLIENT) private apiCore: RelationshopEComCoreHttpClient
  ) {}
  public getMenu(menuCode: string, platform = 'Mobile', locale: string, refresher = true): Observable<IMenu | null> {
    const baseParams = { locale };
    const params = {
      ...baseParams,
      ...refreshParam(refresher, this.groupCacheKey),
    };

    return this.apiCore.get<any>(`/Menu/GetMenuByCode/${menuCode}/${platform}`, { params }).pipe(
      map((response) => (response && response.Data ? response.Data : null)),
      catchError((error) => {
        console.error('Failed to load menu:', error);
        return of(null);
      })
    );
  }
}
