import { Injectable, OnDestroy } from '@angular/core';
import { Subject, switchMap, takeUntil, timer, forkJoin } from 'rxjs';
import { AppSettings } from './app-setting';
import { CookieConsentProviderType } from '@rsApp/modules/cookie-consent/cookie-consent.type';
import { CookieConsentManager } from '@rsApp/modules/cookie-consent/cookie-consent.manager';
import { getCookieConsentTranslation } from '@rsApp/modules/cookie-consent/options/cookieconsent.option';
import { find } from 'lodash';
import { Platform } from '@ionic/angular';
import { TranslateService } from '@ngx-translate/core';
import { Credential } from '@rsApp/modules/auth-v2/providers/credential.service';
import { DxpComponentService } from './dxp.component.service';
import { AuthService } from '@rsApp/modules/auth-v2/providers/auth-v2.service';

@Injectable({ providedIn: 'root' })
export class CookieConsentService implements OnDestroy {
  public listenCookieConsentinItialized: Subject<boolean> = new Subject();
  private _destroy$: Subject<boolean> = new Subject();
  private _listenForceUpdate$: Subject<boolean> = new Subject();

  constructor(
    private platform: Platform,
    private appSettings: AppSettings,
    private translate: TranslateService,
    private cre: Credential,
    private auth: AuthService,
    private dxpComponentService: DxpComponentService
  ) {}

  listenForceUpdate() {
    return this._listenForceUpdate$.asObservable();
  }

  emitForce(value) {
    return this._listenForceUpdate$.next(value);
  }

  ngOnDestroy() {
    this._destroy$.next(true);
    this._destroy$.complete();
  }

  init(consentToken?: string, callback?: () => void, forceOpenBanner?: boolean) {
    const translator = (key: string) => {
      return this.translate.instant(key);
    };

    forkJoin([
      this.appSettings.getSettingsByPatch('GENERAL/Cookie Consent'),
      this.appSettings.getSettingValue('loyalty_support'),
    ])
      .pipe(takeUntil(this._destroy$))
      .subscribe(([settings, loyaltySupport]) => {
        try {
          let appId: string;

          const getSettingByName = (name: string) => find(settings, { SettingName: name })?.SettingValue;
          const provider: CookieConsentProviderType = getSettingByName('cookie_consent_provider') || 'none';

          if (this.platform.is('android')) {
            appId = getSettingByName('cookie_consent_android_key');
          } else if (this.platform.is('ios')) {
            appId = getSettingByName('cookie_consent_ios_key');
          }

          if (provider == 'onetrust' && !appId) return;

          // Wait for translation to be loaded. This is not the best way to do this.
          this.translate
            .get('cookieConsent.consentModal.title')
            .pipe(takeUntil(this._destroy$))
            .subscribe(() => {
              const cookieConsentManager = new CookieConsentManager(provider, {
                language: this.translate.currentLang,
                translation: getCookieConsentTranslation(translator, 5),
                identifier: loyaltySupport ? this.cre?.currentUser?.CustomerCode : this.cre?.currentUser?.UserName,
                appId: appId,
                cookieConsentToken: consentToken ? JSON.parse(consentToken)?.Token : null,
              });

              cookieConsentManager.initialize(async () => {
                const cookieConsent = CookieConsentManager.getInstance();

                this.listenCookieConsentinItialized.next(true);

                if (!cookieConsent.initialize || forceOpenBanner) cookieConsent.showPreferences();

                cookieConsent?.onConsentChange(() => {
                  cookieConsentManager.hasConsent('C0002', null, (hasConsent) => {
                    window.postMessage(
                      { action: 'DXPCookieConsentChange', data: { hasConsent } },
                      window.location.origin
                    );

                    if (hasConsent) {
                      callback();
                    }
                  });
                });

                await this.dxpComponentService.onConnected();

                cookieConsent.hasConsent('C0002', null, (hasConsent) => {
                  window.postMessage(
                    { action: 'DXPCookieConsentChange', data: { hasConsent } },
                    window.location.origin
                  );
                });
              });
            });
        } catch (err) {
          console.log(err);
        }
      });
  }

  refreshTokenCookieConsent() {
    if (!this.cre.currentUser) return;

    const expireTime = this.getTokenCookieConsentGap();

    timer(expireTime)
      .pipe(
        switchMap(() => this.auth.generateCookieConsentToken()),
        takeUntil(this._destroy$)
      )
      .subscribe((dataToken) => {
        window.postMessage({ action: 'MagInitCookieConsent', payload: { dataToken } }, window.location.origin);
      });
  }

  private getTokenCookieConsentGap(): number {
    const dataTokenJson = localStorage.getItem('cookieConsentToken');
    if (!dataTokenJson) return 0;

    try {
      const dataToken = JSON.parse(dataTokenJson);
      const createdDate = new Date(dataToken?.CreatedUtc?.toString());
      const expireTime = createdDate.getTime() + (dataToken?.ExpiresInSecond ?? 0) * 1000;
      const now = Date.now();

      const gapInSeconds = Math.floor(expireTime - now);

      return gapInSeconds > 0 ? gapInSeconds : 0;
    } catch {
      return 0;
    }
  }
}
